class Union {
  var rank: [Int] = []
  var parent: [Int] = []
  init(_ n: Int) {
    rank = .init(repeating: 0, count: n)
    parent = (0..<n).map { $0 }
  }
  func root(_ x: Int) -> Int {
    if parent[x] == x {
      return x
    }
    parent[x] = root(parent[x])
    return parent[x]
  }
  func merge(_ x: Int, _ y: Int) {
    if root(x) == root(y) {
      return
    }
    let px = root(x)
    let py = root(y)
    if rank[px] < rank[py] {
      parent[px] = py
    } else if rank[px] > rank[py] {
      parent[py] = px
    } else {
      rank[px] += 1
      parent[py] = px
    }
  }
  func uniqueCount() -> Int {
    return Set(parent).count
  }
}

