#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

struct UnionFind {
    vector<int> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2

    UnionFind(int N) : par(N) { //最初は全てが根であるとして初期化
        for(int i = 0; i < N; i++) par[i] = i;
    }

    int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) { // xとyの木を併合
        int rx = root(x); //xの根をrx
        int ry = root(y); //yの根をry
        if (rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま
        par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
    }

    bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }

    int num_root() { // 幾つの木があるかを出力
        set<int> s;
        for (auto it: par) {
            s.insert(root(it));
        }
        return s.size();
    }
};

int main() {
    int n, m;
    vector<int> a, b;
    cin >> n >> m;

    UnionFind tree(2 * n);
    for(int i = 0; i < m; ++i) {
        int x, y, z;
        cin >> x >> y >> z;
        if (z % 2 == 0) {
            tree.unite(x - 1, y - 1);
            tree.unite(x + n - 1, y + n - 1);
        } else {
            tree.unite(x - 1, y + n - 1);
            tree.unite(x + n - 1, y - 1);
        }
    }

    int res = tree.num_root() / 2;
    cout << res << endl;

    return 0;
}

