  {
    par.at(i) = i;
    rankt.at(i) = 0;
  }
}

int find(int x)
{
  if(par.at(x) == x)
  {
    return x;
  }
  else
  {
    return par.at(x) = find(par.at(x));
  }
}

void unite(int x, int y)
{
  x = find(x);
  y = find(y);
  if(x == y)return;

  if(rankt.at(x) < rankt.at(y))
  {
    par.at(x) = y;
  }
  else
  {
    par.at(y) = x;
    if(rankt.at(x) == rankt.at(y))rankt.at(x)++;
  }
}

bool same(int x, int y)
{
  return find(x) == find(y);
}

