struct union_find{
	int N;
	vector<int> parent;
	vector<int> siz;

	union_find(int N) : parent(N), siz(N, 1){
		for (int i = 0; i < N; i++) parent[i] = i;
	}

	int root(int x){
		if(parent[x] == x) return x;
		else return parent[x] = root(parent[x]);
	}

	void merge(int x, int y){
		x = root(x), y = root(y);
		if(x == y) return;
		if(siz[x] < siz[y]) swap(x, y);
		parent[y] = x;
		siz[x] += siz[y];
		siz[y] = 0;
	}

	bool are_same(int x, int y){
		return root(x) == root(y);
	}

	int size(int x){
		return siz[root(x)];
	}
};

int main(){
	int N, M, X, Y, Z, i;
	scanf("%d%d", &N, &M);
	union_find uf(N);
	for(i = 0; i < M; i++){
		scanf("%d%d%d", &X, &Y, &Z);
		uf.merge(X - 1, Y - 1);
	}
	int ans = 0;
	for(i = 0; i < N; i++){
		ans += i == uf.root(i);
	}
	printf("%d\n", ans);
	return 0;
}

