class UnionFind {
  vector<int> par, rank;
public:
  UnionFind(int n) {
    par.resize(n);
    for (int i = 0; i < n; i++)
      par[i] = i;
    rank.resize(n, 0);
  }
  int root(int x) {
    if (par[x] == x)
      return x;
    return par[x] = root(par[x]);
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
  bool unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y)
      return false;
    if (rank[x] >= rank[y]) {
      par[y] = x;
      if (rank[x] == rank[y])
        rank[x]++;
    } else
      par[x] = y;
    return true;
  }
};

