vector <long long> par;

long long root(long long v){
	if (par[v] < 0)
		return v;
	return par[v] = root(par[v]);
}

bool merge(long long v, long long u){
	v = root(v);
	u = root(u);
	if (v == u)
		return false;
	if (par[v] > par[u])
		swap(v, u);
	par[v] += par[u];
	par[u] = v;
	return true;
}

int main(){
