vector<vector<pair<int,int>>> graph;
vector<bool> know;

void solve(int i){
  for(auto p : graph.at(i)){
    if(know.at(p.first)&&!know.at(p.second)){
      know.at(p.second)=true;
      solve(p.second);
    }else if(!know.at(p.first)&&know.at(p.second)){
      know.at(p.first)=true;
      solve(p.first);
    }
  }
}

int main(){
  int N,M;
  cin>>N>>M;
  vector<int> X(M),Y(M),Z(M);
  graph.resize(N);
  for(int i=0;i<M;i++){
    vector<int> x(3);
    cin>>x.at(0)>>x.at(1)>>x.at(2);
    x.at(0)--;x.at(1)--;x.at(2)--;
    X.at(i)=x.at(0),Y.at(i)=x.at(1),Z.at(i)=x.at(2);
    sort(x.begin(),x.end());
    graph.at(x.at(0)).push_back(make_pair(x.at(1),x.at(2)));
    graph.at(x.at(1)).push_back(make_pair(x.at(0),x.at(2)));
    graph.at(x.at(2)).push_back(make_pair(x.at(0),x.at(1)));
  }

  int ans=0;
  know.resize(N,false);
  for(int i=0;i<N;i++){
    if(know.at(i)){
      continue;
    }
    if(graph.at(i).size()==0){
      know.at(i)=true;
      ans++;
    }else{
      bool flag=false;
      for(auto p :graph.at(i)){
        if(know.at(p.first)&&know.at(p.second)){
          know.at(i)=true;
          flag=true;
          break;
        }
      }
      if(!flag){
        know.at(i)=true;
        ans++;
      }
      solve(i);
    }
  }
  cout<<ans<<endl;
}

