int pre[maxn],n,m,x,y,z,vis[maxn];
int Find(int x){
	return pre[x] == x ? x : pre[x] = Find(pre[x]);
}
void mix(int x,int y){
	int fx = Find(x);
	int fy = Find(y);
	if(fx != fy) pre[fx] = fy;
}
