int ran[N_MAX], parent[N_MAX];

void initialize(int n) {
    for (int i = 0; i < n; i++) {
        ran[i] = 0;
        parent[i] = i;
    }
}

int find(int x) {
    if (x == parent[x])
        return x;
    return parent[x] = find(parent[x]);
}

void unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y)
        return;
    if (ran[x] > ran[y]) {
        parent[y] = x;
    } else {
        parent[x] = y;
        if (ran[x] == ran[y])
            ran[y]++;
    }
}

int main() {
