struct UnionFind
{
  int par[MAX_N];	//親
  int height[MAX_N];	//木の深さ
  int size[MAX_N];	//子の数

	//n要素で初期化
  void init (int n)
  {
    for (int i = 0; i < n; i++)
    {
      par[i] = i;
      height[i] = 0;
      size[i] = 1;
    }
  }

	//木の根を求める
  int find (int x)
  {
    if (par[x] == x)
    {
      return x;
    }
    else
    {
      return par[x] = find(par[x]);
    }
  }

	//xとyの属する集合を併合
  void unite (int x, int y)
  {
    x = find(x);
    y = find(y);
    if (x == y)
    {
      return;
    }

    if (height[x] < height[y])
    {
      par[x] = y;
      size[y] = size[x] + size[y];
    }
    else
    {
      par[y] = x;
      size[x] = size[x] + size[y];
      if (height[x] == height[y])
      {
        height[x]++;
      }
    }
  }

	//xとyが同じ集合に属するか否か
  bool same (int x, int y)
  {
    return find(x) == find(y);
  }
};

