        if(z % 2 == 0) unite(x-1, y-1);
        else {
            if(!known[x-1] && !known[y-1]) ++cnt;
            known[x-1] = true;
            known[y-1] = true;
        }
    }

    int res = 0;
    map<int,bool> P;
    for(int i=0; i<N; ++i) {
        if(!P[find(i)]) {
            P[find(i)] = true;
            ++res;
        }
    }
