struct DSU {
  std::vector<int> size;
  std::vector<int> parent;
  int connected;

  static DSU make_set(int n) {
    DSU dsu;
    int size[n], parent[n];
    for (int i = 0; i < n; i++) {
      dsu.parent.push_back(i);
      dsu.size.push_back(1);
    }
    dsu.connected = n;
    return dsu;
  }

  int find(int u) {
    if (parent[u] == u) {
      return u;
    }
    return parent[u] = find(parent[u]); // compression
  }

  int unite(int u, int v) {
    int up = find(u);
    int vp = find(v);
    if (up == vp) {
      return up;
    }

    parent[vp] = up;
    size[up] += size[vp];
    connected--;
    return up;
  }

  int getSize(int u) {
    return size[find(u)];
  }
};

