using namespace std;

void visit_dfs(vector<int> *c, vector<bool> &visit, int start = 0) {
  visit[start] = 0;
  stack<int> s;
  s.push(start);
  visit[start] = true;
  while (!s.empty()) {
    int current = s.top();
    s.pop();
    for (const auto &e : c[current])
      if (!visit[e]) {
        s.push(e);
        visit[e] = true;
      }
  }
}

int visitHasFalse(vector<bool> visit) {
  int ret = -1;
  for (int i = 0; i < visit.size(); i++) {
    if (!visit[i]) {
      ret = i;
      break;
    }
  }
  return ret;
}

int nomOfConnected(vector<int> *c, vector<bool> visit) {
  int counter = 0;
  int node;
  while ((node = visitHasFalse(visit)) != -1) {
    counter++;
    visit_dfs(c, visit, node);
  }
  return counter;
}

