// UnionFind
struct UnionFind {
    vector<int> par;
    UnionFind(int n) : par(n,-1) {}
    int root(int x) {
        if (par[x] < 0) return x;
        return par[x] = root(par[x]);
    }
    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (par[x] > par[y]) swap(x,y);
        par[x] += par[y]; par[y] = x;
        return true;
    }
    bool issame(int x, int y) {return root(x) == root(y);}
    int size(int x) {return -par[root(x)];}
};

signed main() {
    int n, m; cin >> n >> m;
    UnionFind uf(n);
    vector<int> a(m), b(m);
    int c;
    rep(i,m) {
        cin >> a[i] >> b[i] >> c;
        a[i]--; b[i]--;
        uf.merge(a[i],b[i]);
    }
    set<int> v;
    rep(i,n) v.insert(uf.root(i));
    cout << v.size() << endl;
    return 0;
}

