vector<int> adj[100'000];
int subgraph[100'000];

void fill(int node_id, int sub_id)
{
    if (subgraph[node_id] != -1)
    {
        return;
    }

    subgraph[node_id] = sub_id;
    for (auto to = adj[node_id].begin(); to != adj[node_id].end(); to++)
    {
        fill(*to, sub_id);
    }
}

int main()
{
