// ============union_find_tree===============
vector<ll> par;//MAX_N == num of node
vector<ll> tree_rank;

void init(ll n)
{
  par = vector<ll>(n);
  tree_rank = vector<ll>(n, 0);
  for (ll i = 0; i < n; ++i)
  {
    par.at(i) = i;
  }
}

ll find(ll x)
{
  if (par.at(x) == x)
  {
    return x;
  }
  else
  {
    return par.at(x) = find(par.at(x));
  }
}

void unite(ll x, ll y)
{
  x = find(x);
  y = find(y);
  if (x == y)
  {
    return;
  }
  if (tree_rank.at(x) < tree_rank.at(y))
  {
    par.at(x) = y;
  }
  else
  {
    par.at(y) = x;
    if (tree_rank.at(x) == tree_rank.at(y))
    {
      tree_rank.at(x)++;
    }
  }
}

bool same(ll x, ll y)
{
  return find(x) == find(y);
}
// =======================================

int main()
{
  ll N, M;
  cin >> N >> M;
  init(N);
  for (ll i = 0; i < M; ++i)
  {
    ll x, y, z;
    cin >> x >> y >> z;
    unite(x - 1, y - 1);
  }
  vector<bool> p(N, false);
  ll ans = 0;
  for (ll i = 0; i < N; ++i)
  {
    find(i);
    if (p.at(par.at(i)))
    {
      continue;
    }
    p.at(par.at(i)) = true;
    ans += 1;
  }
  cout << ans << endl;
}

