class DisjointSet {
public:
  vector<int> p, rank, size;
  DisjointSet(int n) {
    p.assign(n, 0);
    rank.assign(n, 0);
    size.assign(n, 0);
    for (int i = 0; i < n; i++) {
      make_set(i);
    }
  }

  void make_set(int x) {
    p[x] = x;
    rank[x] = 0;
    size[x] = 1;
  }

  bool same(int x, int y) {
    return find_set(x) == find_set(y);;
  }

  int find_set(int x) {
    if (x != p[x]) {
      p[x] = find_set(p[x]);
    }
    return p[x];
  }

  int union_size(int x) {
    if (x != p[x]) {
      size[x] = union_size(find_set(x));
    }
    return size[x];
  }

  void link(int x, int y) {
    if(rank[x]  > rank[y]) {
        p[y] = x;
        size[x] = size[x] + size[y];
    }else if(rank[x] < rank[y]){
        p[x] = y;
        size[y] = size[x] + size[y];
    }else if(x != y) {
      p[y] = x;
      rank[x]++;
      size[x] = size[x] + size[y];
    }
  }

  void unite(int x, int y) {
    link(find_set(x), find_set(y));
  }
};

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  int N, M;
  cin >> N >> M;
  int X[M], Y[M], Z[M];
  int odd[N]{};
  int even[N]{};
  DisjointSet ds(N);
  for (int i = 0; i < M; i++) {
    cin >> X[i] >> Y[i] >> Z[i];
    X[i]--;
    Y[i]--;
    if (Z[i] % 2 == 0) {
      even[X[i]] = 1;
      even[Y[i]] = 1;
    } else {
      odd[X[i]] = 1;
      odd[Y[i]] = 1;
    }
    ds.unite(X[i], Y[i]);
  }
  int p[N]{};
  for (int i = 0; i < N; i++) {
    if (even[i] * odd[i] == 1 ) {
      p[ds.find_set(i)] = 1;
    }
  }
  set<int> s;
  for (int i = 0; i < N; i++) {
    s.insert(ds.find_set(i));
  }
  cout << s.size() << "\n";

  return 0;
}

