struct UnionFind {
  vector<int> parent, rank;
  UnionFind(int N = 1) {
    init(N);
  }
  void init(int N = 1) {
    parent.resize(N);
    rank.resize(N);
    for (int i = 0; i < N; i++) {
      parent.at(i) = i;
      rank.at(i) = 0;
    }
  }
  int root(int x) {
    if (parent.at(x) == x) return x;
    else {
      int r = root(parent.at(x));
      parent.at(x) = r;
      return r;
    }
  }
  bool issame(int x, int y) {
    return root(x) == root(y);
  }
  void merge(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) return;
    if (rank.at(x) < rank.at(y)) swap(x, y);
    if (rank.at(x) == rank.at(y)) rank.at(x)++;
    parent.at(y) = x;
  }
};

