class DisjointSet {
public:
    vector<int> rank, p;

    DisjointSet() {}
    DisjointSet(int size) {
        rank.resize(size, 0);
        p.resize(size, 0);
        for(int i=0; i<size; i++) makeSet(i);
    }

    void makeSet(int x) {
        p.at(x) = x;
        rank.at(x) = 0;
    }

    bool same(int x, int y) {
        return findSet(x) == findSet(y);
    }

    void unite(int x, int y) {
        link(findSet(x), findSet(y));
    }

    void link(int x, int y) {
        if(rank.at(x)>rank.at(y)) {
            p.at(y)=x;
        }
        else {
            p.at(x)=y;
            if (rank.at(x)==rank.at(y)) {
                rank.at(y)++;
            }
        }
    }

    int findSet(int x) {
        if (x!=p.at(x)) {
            p.at(x) = findSet(p.at(x));
        }
        return p.at(x);
    }
};

