class UnionFind {
    vector<int> par;
    vector<int> myrank;
    vector<int> size;

public:
     UnionFind(int n) {
         par.resize(n);
         myrank.resize(n);
         size.resize(n);
         for(int i = 0; i < n; i++){
             par[i] = i;
             myrank[i] = 0;
             size[i] = 1;
         }
    }

    //木の根を求める
    int find(int x) {
        if (par[x] == x) {
            return x;
        } else {
            return par[x] = find(par[x]);
        }
    }

    // xとyの属する集合を併合
    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return;

        if (myrank[x] < myrank[y]) {
            par[x] = y;
            size[y] += size[x];
        } else {
            par[y] = x;
            size[x] += size[y];
            if (myrank[x] == myrank[y]) myrank[x]++;
        }
    }

    //xとyが同じ集合に属するかどうか
    bool same(int x, int y) {
        return find(x) == find(y);
    }

    // xが属する集合の大きさを返す
    int getSize(int x){
        return size[find(x)];
    }
};


int main(){
    int n, m;   cin >> n >> m;
    UnionFind uf(n);

    for(int i = 0; i < m; i++){
        int x, y, z;    cin >> x >> y >> z;
        x--; y--;
        uf.unite(x, y);
    }

    vector<bool> res(n, false);
    int count = 0;
