#include <bits/stdc++.h>

#define REP(i, n) for (int i = 0; i < n; i++)
#define FOR(i, n, m) for (int i = n; i < m; i++)
#define ll long long int

using namespace std;

struct UnionFind
{
  vector<int> par;   // par[i]が親を表す
  vector<int> _size; // _size[i]でそのノードの属しているサイズを返す

  // コンストラクタ
  UnionFind(int n)
  {
    _size = vector<int>(n);
    par = vector<int>(n);
    for (int i = 0; i < n; i++)
    {
      par[i] = i;
      _size[i] = 1;
    }
  }

  // データxの根を求める
  int root(int x)
  {
    if (par[x] == x)
      return x;
    return par[x] = root(par[x]); // 木構造の縮約を行っている
  }

  // xとyの親が違うとき、マージする。そのときyの根がxの根の子になる
  void merge(int x, int y)
  {
    int rootx = root(x);
    int rooty = root(y);
    if (rootx == rooty)
      return;
    par[rooty] = rootx;
    int s = _size[rooty] + _size[rootx];
    _size[rooty] = s;
    _size[rootx] = s;
  }

  // xの属している集団のサイズ
  int size(int x)
  {
    return _size[x];
  }

  // 同じグループに属しているか
  bool isSame(int x, int y)
  {
    return root(x) == root(y);
  }
};

int main()
{
  int n, m;
  cin >> n >> m;
  UnionFind uf = UnionFind(n);

  REP(i, m)
  {
    int x, y, z;
    cin >> x >> y >> z;
    uf.merge(x - 1, y - 1);
  }

  list<int> s;

  REP(i, n)
  {
    s.push_back(uf.root(i));
  }

  s.sort();
  s.unique();
  cout << s.size() << endl;
}

