ll root(ll X,ll par[]){
    if(X==par[X]){
        return X;
    }else{
        par[X]=root(par[X],par);
        return par[X];
    }
}
void merge(ll X,ll Y,ll par[]){
    if(root(X,par)!=root(Y,par))par[root(Y,par)]=root(X,par);
    return;
}

int main(){
    ll N,M;
    cin >> N >> M;
    ll par[N];
    ll i;
    for(i=0;i<N;i++){
