     vector<int> par;
     UnionFind(int n) : par(n, -1) { } //初期化
     // メンバ関数
     void init(int n) { par.assign(n, -1); } //途中で初期化したいときに使う。
     int root(int x) {
         if (par[x] < 0) return x;
         else return par[x] = root(par[x]);
     }
