struct MedianManager{
    ll sz = 0, median = 0;
    priority_queue<ll> lower;
    priority_queue<ll, vl, greater<ll>> upper;
    vl in, out;
    ll ini;

    MedianManager(ll _ini = -INF){
        ini = _ini;
        in = out = vl(2, _ini);
    }

    void update(ll v){
        sz++;
        if (sz == 1) median = v, in[0] = in[1] = out[0] = out[1] = ini;
        else if (sz % 2 == 0){
            if (v < median) lower.push(v), upper.push(median), in[0] = v, in[1] = median, out[0] = out[1] = ini;
            else lower.push(median), upper.push(v), in[0] = median, in[1] = v, out[0] = out[1] = ini;
        }else if (sz % 2){
            ll lower_top = lower.top(), upper_bottom = upper.top();
            if (v < lower_top) median = lower_top, lower.pop(), lower.push(v), in[0] = v, out[0] = median, in[1] = out[1] = ini;
            else if (v > upper_bottom) median = upper_bottom, upper.pop(), upper.push(v), in[1] = v, out[1] = median, in[0] = out[0] = ini;
            else median = v, in[0] = out[0] = in[1] = out[1] = ini;
        }
    }

    ll size(){return sz;}
    pl medians(){return sz % 2 ? mp(median, median) : mp(lower.top(), upper.top());}
};

struct RangeTypeQuery{
    ll n, cur, Q;
    vl types, most_right, ans;
    vtp3 queries;
    BinaryIndexedTree bit;

    RangeTypeQuery(ll _n, ll _Q, BinaryIndexedTree _bit): bit(_bit){
        n = _n, Q = _Q, cur = 0;
        queries.resize(Q); ans.resize(Q);
        types.resize(n); most_right = vl(n, -1);
    }

    void get_queries(ll offset=-1){
        rep(i, Q){
            ll l, r; in2(l, r);
            l += offset, r += offset;
            queries[i] = {r, l, i};
        }
        sort(all(queries));
    }

    void get_sequence(ll offset=-1){
        rep(i, n){
            in1(types[i]);
            types[i] += offset;
            // type num must be less than n.
            assert(types[i] <= n - 1);
        }
    }

    void update(ll nxt){
        while (cur <= nxt){
            if (most_right[types[cur]] != -1)
                bit.update(most_right[types[cur]], -1);
            most_right[types[cur]] = cur;
            bit.update(most_right[types[cur]], 1);
            cur++;
        }
    }

    void process_queries(){
        rep(i, Q){
            ll l, r, v, idx;
            tie(r, l, idx) = queries[i];
            update(r);
            v = bit.query(l, r);
            ans[idx] = v;
        }
    }
};

ll gcd(ll m, ll n){
    ll a = max(m, n);
    ll b = min(m, n);
    while(b != 1 && b != 0){ a %= b; swap(a, b);}
    return b == 1 ? 1 : a;
}

ll lcm(ll m, ll n){ return m / gcd(m, n) * n;}

ll power_normal(ll a, ll power){
    ll value = 1;
    while(power != 0){
        if(power & 1) value = value * a;
        a = a * a;
        power = power >> 1;
    }
    return value;
}

ll power_mod(ll a, ll power, ll mod){
    __int128_t value = 1;
    __int128_t b = a;
    while(power != 0){
        if (power & 1) value = (value * b) % mod;
        b = (b * b) % mod;
        power = power >> 1;
    }
    return value % mod;
}

ll modinv(ll a, ll mod){
    return power_mod(a, mod - 2, mod);
}

ll combination(ll n, ll r, ll mod){
    if (n == r && n == 0) return 1;
    else if (n <= 0 || r < 0 || r > n) return 0;
    ll numerator = 1;
    ll denomenator = 1;
    for(ll i = 0; i < r ; i++){
        ll num = (n - i) % mod, den = (i + 1) % mod;
        (numerator *= num) %= mod;
        (denomenator *= modinv(den, mod)) %= mod;
    }

    return (numerator * denomenator) % mod;
}

vl2 pascal_triangle(ll n){
    /*
    Complexity: O(n^2)
    The upper bound of n is nearly 50.

    Parameters
    ----------
    n; the size of returned vector

    Returns
    -------
    comb[i][j]: combination(i, j). 0 <= i <= n, 0 <= j <= i
    */

    vl2 comb(n + 1, vl(n + 1));
    comb[0][0] = 1;
    For(i, 1, n + 1) rep(j, i + 1){
        comb[i][j] += comb[i - 1][j];
        if (j > 0) comb[i][j] += comb[i - 1][j - 1];
    }

    return comb;
}

ld log_combination(ll n, ll r){
    if (n == r && n == 0) return 0;
    else if (n <= 0 || r < 0 || r > n) return -INF;
    ld val = 0;
    for(ll i = 0; i < r ; i++){
        val += log(n - i);
        val -= log(i + 1);
    }

    return val;
}

string bin_expression(ll n, ll dig){
    string s = "";
    rep(i, dig){
        s += to_string(n % 2);
        n /= 2;
    }
    reverse(all(s));
    return s;
}

bool is_prime(ll n){
    if (n <= 1) return false;
    for(ll i = 2; i * i <= n; i++){
        if (n % i == 0) return false;
    }
    return true;
}

vl eratosthenes(ll n, vl& div){
    // return the list of prime number up to n
    div = vl(n + 1, 0); vl ps;
    rep(i, n + 1) div[i] = i;
    For(i, 2, n + 1){
        if(div[i] == i){
            for(ll j = 2 * i; j <= n; j += i)
                chmin(div[j], i);
            ps.pb(i);
        }
    }
    return ps;
}

map<ll, ll> quick_prime_factorization(vl& div, ll n){
    // ABC177E using the div from eratosthenes
    map<ll, ll> table;
    while (n != 1){
        table[div[n]]++;
        n /= div[n];
    }
    return table;
}

map<ll, ll> prime_factorization(ll n){
    ll i = 2;
    map<ll, ll> table;
    while(i * i <= n){
        while(n % i == 0){
            table[i]++;
            n /= i;
        }
        i++;
    }
    if (n > 1) table[n] = 1;
    return table;
}

vl divisor_table(ll n, bool asc = true){
    vl table;
    ll i = 1;
    while(i * i <= n){
        if (n % i == 0){
            table.pb(i);
            if (i * i != n) table.pb(n / i);
        }
        i++;
    }

    if (asc) sort(all(table));
    else sort(rall(table));

    return table;
}

ll euler_function(ll x){
    // the number of coprime numbers for x (including 1)
    vl dt = divisor_table(x, false);
    ll ret = x; map<ll, ll> cnt;

    for (ll d: dt){
        if (d == 1) continue;
        cnt[d] = x / d;
        for (auto& c: cnt)
            if (c.e1 != d && c.e1 % d == 0)
                cnt[d] -= c.e2;
        ret -= cnt[d];
    }
    return ret;
}

vl base_converter(ll num, ll base, ll sz){
    vl coefs(sz); ll cur = 0;
    while (num){
        ll val = num % base;
        assert(cur < sz);
        coefs[cur++] = val;
        num -= val, num /= base;
    }
    while (cur < sz) coefs[cur++] = 0;
    return coefs;
}

string indexed_alphabet(ll leng, ll idx){
    // 0-indexed
    // returns the string whose order is the-idx-th in the set of strings of the given length.
    string ret = "";
    if (idx >= power_normal(26, leng))
        return ret;

    vl cs = base_converter(idx, 26, leng);
    reverse(all(cs));
    rep(i, cs.size()) ret += char('a' + cs[i]);

    return ret;
}

ll alphabetical_index(string s){
    // including the strings whose length is less than that of s.
    // excluding the empty string.
    ll leng = s.length();
    ll ret = 0, p = 1;
    rep(i, leng){
        ll b = s[leng - 1 - i] - 'a';
        ret += p + p * b, p *= 26;
    }
    return ret;
}

// just change the input if you want to change the target.
// If you want to check the common sequences in two strings,
// combine them. e.g. ABC150F
template<typename T>
vl z_algorithm(T& s, ll n){
    /*
    Paramters
    ---------
    T: the string or list of interest
    n: the size of string or list

    Returns
    -------
    res[i] is the maximum number of K which satisfies
    s[:K] == s[i:i + K]
    for each i = 0, 1, 2, ..., n - 1.
    */
    vl res(n);
    res[0] = n;
    ll i1 = 1, i2 = 0;

    while(i1 < n){
        /*
        i1: the starting point
        i2: the length of substring
        */
        while (i1 + i2 < n && s[i2] == s[i1 + i2]) ++i2;
        res[i1] = i2; if (i2 == 0){++i1; continue;}
        ll i3 = 1;

        // update the already seen points
        while (i1 + i3 < n && i3 + res[i3] < i2){res[i1 + i3] = res[i3]; ++i3;}
        // update up to i1 + i3 and the next possible minimum length is i2 - i3 (= res[i3])
        i1 += i3, i2 -= i3;
    }
    return res;
}

ll string_to_ll(string s){
    ll l = s.length(); ll idx = 0;
    ll val = 0; ll tenth = 1;
    while (idx < l){
        ll m = s[l - 1 - idx] - '0';
        val += (m * tenth);
        tenth *= 10; idx++;
    }

    return val;
}

string reflected_string(string s){
    string t, u; ll n = s.length();
    t = s; reverse(all(t));
    u = substring(t, 0, n - 2) + s + substring(t, 1, n - 1);
    return u;
}

ld distance_between_point_line(point l_begin, point l_end, point p){
    ll xl1 = l_begin.x, yl1 = l_begin.y;
    ll xl2 = l_end.x, yl2 = l_end.y;
    ll xp = p.x, yp = p.y;
    ll a = yl2 - yl1;
    ll b = - xl2 + xl1;
    ll c = - a * xl2 - b * yl2;
    return abs(ld(a * xp + b * yp + c)) / ld(sqrt(a * a + b * b));
}

bool is_cross(point l1_begin, point l1_end, point l2_begin, point l2_end){
    ll x1 = l1_begin.x, y1 = l1_begin.y;
    ll x2 = l1_end.x, y2 = l1_end.y;
    ll x3 = l2_begin.x, y3 = l2_begin.y;
    ll x4 = l2_end.x, y4 = l2_end.y;
    ll val1 = (x1 - x2) * (y3 - y1) + (y1 - y2) * (x1 - x3);
    ll val2 = (x1 - x2) * (y4 - y1) + (y1 - y2) * (x1 - x4);
    ll val3 = (x3 - x4) * (y1 - y3) + (y3 - y4) * (x3 - x1);
    ll val4 = (x3 - x4) * (y2 - y3) + (y3 - y4) * (x3 - x2);

    return val1 * val2 < 0 && val3 * val4 < 0;
}

template<typename T>
bool isColinear(T p1, T p2, T p3){
    T v1 = p2 - p1, v2 = p3 - p1;
    return v1.x * v2.y == v1.y * v2.x;
}

template<typename T>
T PerpendicularBisector(T p1, T p2){
    T vec = p2 - p1;
    assert(!vec.is_zero());
    T ret = {vec.y, -vec.x};

    return ret;
}

template<typename T>
ld Distance2DPoints(T p1, T p2){
    T vec = (p1 - p2) * (p1 - p2);
    return sqrt(vec.x + vec.y);
}

ll SquaredDistance2DPoints(point p1, point p2){
    point vec = (p1 - p2) * (p1 - p2);
    return vec.x + vec.y;
}

ld space_of_triangle(point p1, point p2, point p3){
    ll x1 = p1.x, y1 = p1.y;
    ll x2 = p2.x, y2 = p2.y;
    ll x3 = p3.x, y3 = p3.y;
    ll v1 = x2 - x1; ll u1 = y2 - y1;
    ll v2 = x3 - x1; ll u2 = y3 - y1;
    ld s = ld(v1 * u2 - u1 * v2) / ld(2);
    return abs(s);
}

pair<point, ll> OuterCenter(point p1, point p2, point p3){
    // the center of circle on the given three points
    // return the determinant value and the product of center points and 2 * determinant value
    point ret;

    if (isColinear(p1, p2, p3)){
        ll d1 = SquaredDistance2DPoints(p1, p2);
        ll d2 = SquaredDistance2DPoints(p2, p3);
        ll d3 = SquaredDistance2DPoints(p3, p1);
        if (d1 >= d2 && d1 >= d3) {ret = p1 + p2; return mp(ret, 2);}
        else if (d2 >= d1 && d2 >= d3) {ret = p2 + p3; return mp(ret, 2);}
        else {ret = p3 + p1; return mp(ret, 2);}
    }

    point pv1 = PerpendicularBisector(p1, p2);
    point pv2 = PerpendicularBisector(p1, p3);
    point cv1_2x = p1 + p2, cv2_2x = p1 + p3;
    // cv1 + k pv1 == cv2 + m pv2
    // (pv1x -pv2x) (k) = (cv2x - cv1x)
    // (pv1y -pv2y) (m) = (cv2y - cv1y)
    ll det_inv = - pv1.x * pv2.y + pv1.y * pv2.x;
    ll x1_2x = cv2_2x.x - cv1_2x.x, x2_2x = cv2_2x.y - cv1_2x.y;
    pl c_2x_det = {-pv2.y * x1_2x + pv2.x * x2_2x, -pv1.y * x1_2x + pv1.x * x2_2x};

    // ret.x = ld(cv1_2x.x * det_inv + pv1.x * c_2x_det.e1) / ld(2 * det_inv);
    // ret.y = ld(cv1_2x.y * det_inv + pv1.y * c_2x_det.e1) / ld(2 * det_inv);
    ret.x = cv1_2x.x * det_inv + pv1.x * c_2x_det.e1;
    ret.y = cv1_2x.y * det_inv + pv1.y * c_2x_det.e1;

    ll jacobian = 2 * det_inv;
    return mp(ret, jacobian);
}

ll inversion_number(vl a, ll a_max){
    /*
    Paramters
    ---------
    a: vector<ll>
        All the elements must be non-negative.
        Prefably the elements are compressed to reduce the computational cost.
    a_max: ll
        The maximum value of the vector a or the value bigger than the value stated previously.
    */

    BinaryIndexedTree bit(a_max + 1); ll val = 0;
    rep(i, a.size()){
        // i is the number of elements that have lower index than a[i].
        // call the number of elements that have lower value than a[i]
        // by subtracting these two, the residual number is the number of elements that have larger value.
        val += i - bit.query(a[i] - 1);// cumulative sum from 0 to a[i] - 1
        bit.update(a[i], 1);
    }
    return val;
}

ld bin_search(ld left, ld right, bool lb, function<bool(ld)> judge){
    ld mid;
    while(right - left > EPS * 5){
        mid = (right + left) / 2;
        if (lb){
            if (judge(mid)) right = mid;
            else left = mid + EPS;
        }else{
            if (judge(mid)) left = mid;
            else right = mid - EPS;
        }
    }
    return right;
}

ll bin_search(ll left, ll right, bool lb, function<bool(ll)> judge){
    ll mid;
    while(right > left){
        if (lb){
            // if true (satisfies the condition), range shifts smaller direction
            mid = (right + left) / 2;
            if (judge(mid)) right = mid;
            else left = mid + 1;
        }else{
            // if true (satisfies the condition), range shitfs larger direction
            mid = (right + left + 1) / 2;
            if (judge(mid)) left = mid;
            else right = mid - 1;
        }
    }
    return right;
}

ld trinary_search(ld left, ld right, function<ld(ld)> func){
    // Care the value EPS!!! Compare to the condition
    while(abs(right - left) > EPS){
        ld left2 = (2.0 * left + right) / 3.0;
        ld right2 = (left + 2.0 * right) / 3.0;
        ld f1 = func(left2);
        ld f2 = func(right2);
        if (f1 <= f2) right = right2;
        else if (f2 <= f1) left = left2;
    }

    return right;
}

template<typename T>
vector<T> compress(vector<T> v){
    // sort and remove all the duplicated values
    sort(all(v));
    v.erase(unique(all(v)), v.end());
    return v;
}

template<typename T>
map<T, ll> dict(const vector<T> &v){
    map<T, ll> d;
    rep(i, v.size()) d[v[i]] = i;
    return d;
}

points compress2D(vl xs, vl ys){
    /*
    NOTE
    ----
    Add the corner points if required
    */

    ll n = xs.size();
    vl xcs = compress(xs), ycs = compress(ys);
    map<ll, ll> xd = dict(xcs), yd = dict(ycs);
    points ps(n);

    rep(i, n)
        xs[i] = xd[xs[i]], ys[i] = yd[ys[i]];

    rep(i, n)
        ps[i] = {xs[i], ys[i]};

    sort(all(ps));

    return ps;
}

ll kruskal(vector<undirected_edge>& es, ll n_vertex){
    // O(ElogE)
    sort(all(es));
    UnionFind uf(n_vertex);

    ll min_cost = 0;

    rep(i, es.size()){
        undirected_edge& e = es[i];
        if (!uf.is_same(e.from, e.to)){
            min_cost += e.cost;
            uf.unite(e.from, e.to);
        }
    }
    return min_cost;
}

ll LongestIncreasedSequence(vl& v){
    ll n = v.size();
    vl dp(n, INF);
    rep(i, n)
        *lower_bound(all(dp), v[i]) = v[i];
    return lower_bound(all(dp), INF) - dp.begin();
}

void dijkstra(ll start, Graph& graph, vl& dist,
              vl& vertex_pre, bool trace = false){
    priority_queue<pl, vpl, greater<pl>> q;
    ll n = graph.size(); dist = vl(n, INF); dist[start] = 0;
    if (trace) vertex_pre = vl(n, -1);
    q.push(pl(0, start));

    while (!q.empty()){
        ll idx, cost;
        tie(cost, idx) = q.top(); q.pop();
        if (dist[idx] < cost) continue;

        for (auto& e: graph[idx]) 
            if (chmin(dist[e.to], dist[idx] + e.cost)){
                if (trace) vertex_pre[e.to] = idx;
                q.push(pl(dist[e.to], e.to));
            }
    }
}

vl get_predecessor(ll g, vl& vertex_pre){
    vl path;
    for (; g != -1; g = vertex_pre[g]) path.pb(g);

    reverse(all(path));
    return path;
}

void warshall_floyd(vl2& dist){
    ll n = dist.size();
    // Dont forget the initialization
    // rep(i, n) rep(j, n) dist[i][j] = INF * (i != j);
    rep(k, n) rep(i, n) rep(j, n) dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
}

void update_warshall_floyd(vl2& dist, ll v1, ll v2, ll cost){
    ll n = dist.size();
    if (!chmin(dist[v1][v2], cost)) return;
    dist[v2][v1] = dist[v1][v2];
    rep(i, n) rep(j, n) dist[i][j] = min(dist[i][j], dist[i][v1] + dist[v1][j]);
    rep(i, n) rep(j, n) dist[i][j] = min(dist[i][j], dist[i][v2] + dist[v2][j]);
}

// ABC061D, 137E
bool find_negative_cycle(ll n, ll goal, Graph& graph, vl& dist){
    rep(i, n) rep(v, n) rep(k, graph[v].size()){
        edge e = graph[v][k];
        if (dist[e.to] != INF && dist[e.to] > dist[v] + e.cost){
            dist[e.to] = -INF;
            if (goal == -1) return true;
            else if (goal == e.to) return true;
        }
    }
    return false;
}

bool bellman_ford(ll start, ll goal, Graph& graph, vl& dist){
    // if there is a closed circuit, it returns false. (when goal == -1)
    // if the distance to goal cannot be obtained, it returns false (when goal != -1)
    ll n = graph.size();
    dist = vl(n, INF);
    dist[start] = 0;
    rep(i, n) rep(v, n) rep(k, graph[v].size()){
        edge e = graph[v][k];
        if (dist[v] != INF && dist[e.to] > dist[v] + e.cost)
            dist[e.to] = dist[v] + e.cost;
    }

    if (find_negative_cycle(n, goal, graph, dist)) return false;
    return true;
}

void Euler_Tour(Graph& tree, vl& euler_tour, vl& in, vl& out, ll anc = 0){
    // record only when we first reach a node and leave the node.
    ll n = tree.size();
    vb visited(n, false);
    in = out = vl(n);

    auto dfs = [&](auto dfs, ll source) -> void{
        visited[source] = true;
        in[source] = euler_tour.size();
        euler_tour.pb(source);

        bool is_leaf = true;
        for (auto& e: tree[source]){
            ll target = e.to;
            if (visited[target]) continue;
            else is_leaf = false;
            dfs(dfs, target);
        }

        euler_tour.pb(- source);
        out[source] = euler_tour.size() - 1;
    };

    dfs(dfs, anc);
}

void Euler_Tour2(Graph& tree, vl& euler_tour, vl& in, vl& out, ll anc = 0){
    // record everytime we reach a node
    ll n = tree.size();
    vb visited(n, false);
    in = out = vl(n);

    auto dfs = [&](auto dfs, ll source) -> void{
        visited[source] = true;
        in[source] = euler_tour.size();
        euler_tour.pb(source);

        bool is_leaf = true;
        for (auto& e: tree[source]){
            ll target = e.to;
            if (visited[target]) continue;
            else is_leaf = false;
            dfs(dfs, target);
            euler_tour.pb(source);
        }

        out[source] = euler_tour.size() - 1;
    };

    dfs(dfs, anc);
}

std::mt19937 create_rand_engine(){
    std::random_device rnd;
    std::vector<std::uint_least32_t> v(10);
    std::generate(v.begin(), v.end(), std::ref(rnd));
    std::seed_seq seed(v.begin(), v.end());
    return std::mt19937(seed);
}

vl generate_unique_array(const size_t sz, ll vm, ll vM){
    const size_t range = static_cast<size_t>(vM - vm + 1);
    const size_t num = static_cast<size_t>(sz * 1.2);
    assert(vm <= vM);
    assert(sz <= range);

    vl ret;
    auto engine = create_rand_engine();
    std::uniform_int_distribution<ll> distribution(vm, vM);

    while (ret.size() < sz){
        while (ret.size() < num) ret.pb(distribution(engine));
        sort(all(ret));

        auto unique_end = unique(all(ret));
        if (sz < distance(ret.begin(), unique_end)) 
            unique_end = next(ret.begin(), sz);

        ret.erase(unique_end, ret.end());
    }

    return ret;
}

vl generate_array(const size_t sz, ll vm, ll vM){
    const size_t range = static_cast<size_t>(vM - vm + 1);
    assert(vm <= vM);

    vl ret;
    auto engine = create_rand_engine();
    std::uniform_int_distribution<ll> distribution(vm, vM);

    while (ret.size() < sz)
        ret.pb(distribution(engine));

    return ret;
}

template<typename T>
void read_vector(ll n, vector<T>& v, ll offset = 0){
    v.resize(n);
    rep(i, n){
        in1(v[i]);
        if (offset) v[i] += offset;
    }
}

template<typename T>
void read_vector(ll n, vector<T>& v1, vector<T>& v2, ll offset1 = 0, ll offset2 = 0){
    v1.resize(n); v2.resize(n);
    rep(i, n){
        in2(v1[i], v2[i]);
        if (offset1) v1[i] += offset1;
        if (offset2) v2[i] += offset2;
    }
}

void read_points(ll n, points& ps, ll offset = 0){
    ps.resize(n);
    rep(i, n){
        ll x, y; in2(x, y);
        ps[i] = {x, y};
        ps[i] += offset;
    }
}

void read_2DMap(ll w, ll h, vb2& block, char b){
    block = vb2(w, vb(h, false));
    string s;
    rep(y, h){
        in1(s);
        rep(x, w) block[x][y] = (s[x] == b);
    }
}

ll diameter_of_tree(Graph& tree){
    ll dM = 0, vM = 0, v1, v2;

    auto dfs = [&](auto dfs, ll src, ll par, ll d) -> void{
        if (chmax(dM, d)) vM = src;
        for (auto& e: tree[src]){
            if (e.to == par) continue;
            dfs(dfs, e.to, src, d + 1);
        }
    };
    dfs(dfs, 0, -1, 0); v1 = vM;
    dfs(dfs, vM, -1, 0); v2 = vM;
    return dM;
}

void trit_search(ll n, function<void(ll, ll)> func){
    rep(bit, 1LL << n){
        ll sub = bit;
        do{
            func(bit, sub);
            sub = (sub - 1) & bit;
        }while (sub != bit);
    }
}

ll convert_string_to_int(string s, ll n_below_decimal){
    // return double(s) * coef
    ll ret = 0, comma = s.length(), n10 = 1, coef = power_normal(10, n_below_decimal);
    rep(i, s.length()) if (s[i] == '.') comma = i;
    revrep(i, comma){
        ll num = s[i] - '0';
        ret += n10 * num;
        n10 *= 10;
    }
    ret *= coef; n10 = coef / 10;
    For(i, comma + 1, s.length()){
        ll num = s[i] - '0';
        ret += n10 * num;
        n10 /= 10;
    }
    return ret;
}

void iter_combination(ll n, ll k, function<void(ll)> func){
    /*
        sub & -sub: the binary which shares the last digit whose value is 1 in sub
        sub + x   : carry up the last digit
            ~y    : the binary whose digits are 1 if y's digit is 0.
    (sub & ~y) / x: reduce the same number of 0s after first 1 in x from (sub & ~y).
    */

    auto next_combination = [&](ll sub) -> ll{
        ll x = sub & -sub, y = sub + x;
        if (x != 0) return (((sub & ~y) / x) >> 1) | y;
        else return INF;
    };

    ll M = 1LL << n;
    for (ll bit = (1LL << k) - 1; bit < M; bit = next_combination(bit))
        func(bit);
}

ll count_in_sorted_seq(vl& as, ll val){
    ll lb = lower_bound(all(as), val) - as.begin();
    ll ub = upper_bound(all(as), val) - as.begin();
    return ub - lb;
}

bool win_first_player(vl& grundy_nums){
    ll x = 0;
    for (ll& gn: grundy_nums) x ^= gn;
    return x != 0;
}

ll create1001001(ll num, ll m, ll num_of_1, ll nb = 31){
    // e.g. 1001001001 -> num = 3
    // e.g. 111111 -> num = 1 (REPUNIT)
    // Calculate the modulo m of 100..100...100..1 (the length of each 00... is num - 1. The # of 1 is 2^i.)
    // Then calculate the modulo m of 100...100...100...1 (The # of 1 is num_of_1 using the memo.)
    vl memo(nb, 1); ll v = 0, tot = 1, coef = power_mod(10, num, m);
    rep(j, nb){
        ll c10 = power_mod(coef, 1LL << j, m);
        memo[j + 1] = ((memo[j] * c10) % m + memo[j]) % m;
        if (num_of_1 >> j & 1){
            (v += (memo[j] * tot) % m) %= m;
            (tot *= power_mod(coef, 1LL << j, m)) %= m;
        }
    }
    return v;
}

ll GaussJordanBitVector(vl &bs){
    ll n = bs.size();
    ll rank = 0; ll j = 0;
    revrep(i, N_DIGITS){
        for(j = rank; j < n; j++) if (bs[j] & (1LL << i)) break;
        if (j == n) continue;
        if (j > rank) bs[rank] ^= bs[j];
        for (j = 0; j < n; j++) if (j != rank) bs[j] = min(bs[j], bs[j] ^ bs[rank]);
        rank++;
    }
    return rank;
}

ll GaussJordan(vl2& A, ll mod, bool is_extended = false, bool det = false){
    /*
    Ax = b

    Parameters
    ----------
    A: m x n matrix
        The matrix of interest

    is_extended: bool
        if A includes the term of b (e.g. when solving linear equation), true
        otherwise false.

    Property: The product of diagonal elements of upper triangle matrix is equal to the determinant of this matrix.
    */

    ll rank = 0, m = A.size(), n = A[0].size();
    rep(r, m) rep(c, n) A[r][c] = modf(A[r][c], mod);

    ll pivot, inv, ret = 1; vl tmp;
    if (det) tmp = vl(n);
    rep(c, n){
        if (is_extended && c == n - 1) break;
        pivot = -1;
        For(r, rank, m) if (A[r][c] != 0) {pivot = r; break;}
        if (pivot == -1){
            if (det) return 0;
            continue;
        }

        swap(A[pivot], A[rank]);
        ret = modf(ret * A[rank][c], mod), inv =  modinv(A[rank][c], mod);
        vl& ax = det ? tmp : A[rank];
        rep(c2, n) ax[c2] = A[rank][c2] * inv % mod;

        rep(r, m) if (r != rank && A[r][c]){
            ll base = A[r][c];
            rep(c2, n)
                A[r][c2] = modf(A[r][c2] - ax[c2] * base, mod);
        }
        ++rank;
    }

    return det ? ret : rank;
}

ll linear_equation(vl2 A, vl b, vl &res){
    ll m = A.size(), n = A[0].size();
    vl2 M(m, vl(n + 1));
    rep(r, m){
        rep(c, n) M[r][c] = A[r][c];
        M[r][n] = b[r];
    }

    ll rank = GaussJordan(M, true);
    For(r, rank, m) if (M[r][n]) return -1;

    res.assign(n, 0);
    rep(i, rank) res[i] = M[i][n];
    return rank;
}

ll determinant(vl2& A, ll mod){return GaussJordan(A, mod, false, true);};

