class Union_find {
	const int _size;
	std::vector<int> _array;
public:
	Union_find(const int size) :_size{ size }, _array(size, -1) {};
	int find(int a) {
		if (_array[a] < 0) return a;
		else return _array[a] = find(_array[a]);
	}
	bool is_same(const int a, const int b) {
		return find(a) == find(b);
	}
	void merge(const int a, const int b) {
		auto ar = find(a);
		auto br = find(b);
		if (ar != br) {
			if (_array[ar] < _array[br]) {
				_array[ar] += _array[br];
				_array[br] = ar;
			}
			else {
				_array[br] += _array[ar];
				_array[ar] = br;
			}
		}
	}
};
