typedef long long ll;

const int MAX = 100001;

struct UnionFind {
  int par[MAX];
  int rank[MAX];
  UnionFind() {
    for (int x = 0; x < MAX; ++x) {
      par[x] = x;
      rank[x] = 0;
    }
  }

  int find(int x) {
    if (par[x] != x) {
      par[x] = find(par[x]);
    }
    return par[x];
  }

  void unite(int x, int y) {
    int px = find(x);
    int py = find(y);
    if (px != py) {
      if (rank[px] > rank[py]) {
        par[py] = px;
      }
      par[px] = py;
      if (rank[px] == rank[py]) {
        ++rank[px];
      }
    }
  }
};


int main() {
  UnionFind uf;
  int n, m;
  cin >> n >> m;
  for (int i = 0; i < m; ++i) {
    int x, y, z;
    cin >> x >> y >> z;
    uf.unite(x, y);
  }
  int ans = 0;
  set<int> group;
  for (int i = 1; i <= n; ++i) {
    int id = uf.find(i);
    if (group.find(id) == group.end()) {
      ++ans;
      group.insert(id);
    }
  }
  cout << ans << endl;
}

/*
知らなかったこと

「Ax + Ay + Zi は偶数であること」を
「各カードの値が偶数なのか奇数なのかだけわかれば良い」
と言いかえられなかった.

こういうときは, 本質的に知りたいことは「偶奇」だけである
だから, mod 2をとることでparityに着目する

Ax + Ay mod2が表す意味がわからなかった
・・・「一方の偶奇がわかれば他方の偶奇」もわかる
２つの関係式があったら？？
・・・一つでも偶奇がわかれば他の２つについても偶奇がわかる
・・・ノード x とノード y との間に辺を張ったグラフを用意することで処理できる

・・・そう考えることで
「グラフの各連結成分について、どれか 1 個でも偶奇がわかれば、
連結成分内のすべてのノードの偶奇がわかる」ことになる


・・・よって求める試行回数は, 「グラフの連結成分の個数」である

・・・グラフの連結成分の個数を求めるためには
UnionFindにより「root」の個数が何通りあるか？調べれば良い

重複を許さず, 集合の要素がいくつ存在するかを知りたいときは
要素を全てstd::setへ入れ込んで, .size()によりsetの大きさを求めれば良い

*/


#include <iostream>
#include <vector>
#include <algorithm>
#include <set>

using namespace std;

class UnionFind{
public:

    //親の番号を格納する. Parentだった場合は−(the size)とする
    vector<int> Parent;

    //作るときはParentの値を全て-1にする
    //こうすると, すべての頂点が根となる
    UnionFind(int N){
        Parent = vector<int>(N, -1);
    }

    //Aがどのグループに属しているか調べる
    int root(int A){
        if (Parent[A] < 0) return A; //自分のグループにいる
        return Parent[A] = root(Parent[A]); //親をつなぎ替える
    }

    //size関数を作る
    //自分の所属するグループの頂点数を調べる
    long long size(int A){
        return -Parent[root(A)]; //親をとりたい
    }

    //AとBをくっつける
    bool connect(int A, int B){
        //AとBを直接繋がない
        //root(A) に root(B)をくっつける　
        //リーダー同士をくっつける

        A = root(A);
        B = root(B);

        if (A == B){
            return false; //すでにくっついてる
        }

        //大きい方に小さい方をくっつけたい
        //大小が逆だったらひっくり返す

        if(size(A) < size(B)) swap(A, B);

        //Aのサイズを更新する
        Parent[A] += Parent[B];

        //BのParentをAに変更する
        Parent[B] = A;

        return true; //くっついた
    }

};

int main(void){

    int n, m;
    cin >> n >> m;

    UnionFind uni(n);

    for (int i = 0; i < m; i++){
        int x, y, z;
        cin >> x >> y >> z;
        x--, y--;

        uni.connect(x,y);
    }

    set<int> st;

    for (int i = 0; i < n; i++){
        st.insert(uni.root(i));
    }

    cout << st.size() << endl;
}

