const int MAX_N = 100000+10;
class UF {
    private:
        int par[MAX_N];
        int rank[MAX_N];

    public:
        UF(int n) {
            for(int i = 1;i <= n;i++) {
                par[i] = i;
                rank[i] = 1;
            }
        }

        int root(int x) {
            return x == par[x] ? x : root(par[x]);
        }

        bool same(int x,int y) {
            return root(x) == root(y);
        }

        void merge(int x, int y) {
            x = root(x);
            y = root(y);
            if(x == y)
                return;

            if(rank[x] < rank[y]) {
                par[x] = y;
            } else {
                par[y] = x;
                if(rank[x] == rank[y])
                    rank[y]++;
            }
        }

        int connect(int n) {
            int sum = 0;
            for(int i = 1;i <= n;i++) {
                if(i == par[i])
                    sum++;
            }

            return sum;
        }
};

