class DisjointSet {
    public:
        DisjointSet(int n) : pars(n, -1), N(n), sz(n) {
        }
        int find(int x) {
            return pars[x] < 0 ? x : (pars[x] = find(pars[x]));
        }
        bool unite(int x, int y) {
            x = find(x);
            y = find(y);
            if (x == y) {
                return false;
            }
            if (pars[x] < pars[y]) {
                swap(x, y);
            }
            pars[y] += pars[x];
            pars[x] = y;
            --sz;
            return true;
        }

        int size() { return sz; }
    private:
        int N;
        int sz;
        vector<int> pars;
};


class Solution {
public:
    int solve(int n, vector<int>& X, vector<int>& Y, vector<int>& Z) {
        DisjointSet ds(n);

        int m = X.size();
        for (int i = 0; i < m; ++i) {
            if ((Z[i] & 1) == 0) {
                int u = X[i], v = Y[i];
                ds.unite(u, v);
            }
        }

        map<int,int> MP;
        int idx = 0;
        vector<int> indices(n, -1);
        for (int i = 0; i < n; ++i) {
            int s = ds.find(i);
            if (MP.count(s) == 0) {
                MP[s] = idx;
                indices[i] = idx;
                ++idx;
            } else {
                indices[i] = MP[s];
            }
        }

        int N = idx;
        DisjointSet ds2(N);
        for (int i = 0; i < m; ++i) {
            if (Z[i] & 1) {
                int u = X[i], v = Y[i];
                u = indices[u], v = indices[v];
                assert(u != v);
                ds2.unite(u, v);
            }
        }

        return ds2.size();                
    }
};

int main(int argc, char** argv) {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, m;
    cin >> n >> m;
    vector<int> X(m);
    vector<int> Y(m);
    vector<int> Z(m);
    for (int i = 0; i < m; ++i) {
        cin >> X[i] >> Y[i] >> Z[i];
        --X[i], --Y[i];
    }
    Solution sol;
    cout << sol.solve(n, X, Y, Z) << "\n";

    return 0;
}

