void visit(vector<vector<int> > &adj, int u, int flag[]) {
	flag[u] = 1;

	for (int i = 0; i < (int) adj[u].size(); ++i) {
		if(!flag[adj[u][i]]) {
			visit(adj, adj[u][i], flag);
		}
	}

	return;
}

int dfs(vector<vector<int> > &adj) {
	int flag[(int) adj.size()] = {0};
	int scc = 0;

	for (int i = 0; i < (int) adj.size(); ++i) {
		if(!flag[i]) {
			scc++;
			visit(adj, i, flag);
		}
	}

	return scc;
}

