using namespace std;

class unionfind {
  vector<int> v;

  int size(int n) {
    return -v[root(n)];
  }

  int parent(int n) {
    return v[n] < 0 ? n : v[n];
  }

  int root(int n) {
    return parent(n) == n ? n : v[n] = root(parent(n));
  }

public:
  int component_count;

  unionfind(int n) {
    v.resize(n, -1);
    component_count = n;
  }

  int unite(int a, int b) {
    int ra = root(a);
    int rb = root(b);
    if (ra == rb) return -1;
    component_count--;
    if (size(ra) < size(rb)) swap(ra, rb);
    v[ra] += v[rb];
    v[rb] = ra;
    return size(ra);
  }
};

