using namespace std;

struct union_find_t {
  vector<int> parents;

  union_find_t() {}

  explicit union_find_t(int n) : parents(n) {
    for (int i = 0; i < n; i++) {
      parents[i] = i;
    }
  }

  void resize(int n) {
    parents.resize(n);
    for (int i = 0; i < n; i++) {
      parents[i] = i;
    }
  }

  int root(int x) {
    if (parents[x] == x) {
      return x;
    }
    auto const ret = root(parents[x]);
    parents[x] = ret;
    return ret;
  }

  void unite(int x, int y) {
    int const rx = root(x);
    int const ry = root(y);
    if (rx == ry) {
      return;
    }
    parents[rx] = ry;
  }

  bool same(int x, int y) { return root(x) == root(y); }
};

static union_find_t unionFind;

int main() {
  std::cin.tie(nullptr);
  std::ios::sync_with_stdio(false);
  int n;
  std::cin >> n;
  unionFind.resize(n);
  int64_t m;
  std::cin >> m;
  for (int i = 0; i < m; i++) {
    int x;
    int y;
    int z;
    std::cin >> x >> y >> z;
    unionFind.unite(x - 1, y - 1);
  }
  std::unordered_set<int> roots;
  for (int i = 0; i < n; i++) {
    roots.insert(unionFind.root(i));
  }
  std::cout << roots.size() << std::endl;
  return 0;
}

