LL modpow(LL a, LL n, LL _MOD = MOD) {
	LL re = 1;
	while (n > 0) {
		if (n & 1)re = re * a % _MOD;
		a = a * a % _MOD; n >>= 1;
	}
	return re;
}
LL modinv(LL n, LL _MOD = MOD) {
	return modpow(n, _MOD - 2, _MOD);
}
