// Nはグラフの頂点数
struct UnionFind {
    vector<int> parent, rank;

    UnionFind(int N) {
        parent.resize(N+1);
        rank.resize(N+1);
        /*
        // 0 origin
        for(int i=0; i<N; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
        */
        // 1 origin
        for(int i=1; i<=N; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    int root(int x) {
        if(parent[x] == x) {
            return x;
        } else {
            return parent[x] = root(parent[x]);
        }
    }

    bool unite(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) {
            return false;
        }

        if (rank[rx] < rank[ry]) {
            parent[rx] = ry;
        } else {
            parent[ry] = rx;
            if (rank[rx] == rank[ry]) {
                rank[rx]++;
            }
        }
        return true;
    }

    bool isSame(int x, int y) {
        return root(x) == root(y);
    }
};

