		if (par[x] == x)return x;
		return par[x] = root(par[x]);
	}
	bool same(ll x, ll y) {
		return root(x) == root(y);
	}
	void unite(ll x, ll y) {
		if (same(x, y))return;
		Size[root(x)] += Size[root(y)];
		par[root(y)] = root(x);
	}
};

int main(){
    ll n,m;
    cin>>n>>m;
    struct union_find U(n);
    while(m){
        ll a,b,z;
        cin>>a>>b>>z;
        a--; b--;
        U.unite(a,b);
        m--;
    }
    ll ans=0;
    vector<bool> f(n,true);
    for(int i=0;i<n;i++){
        if(f[U.root(i)]){
            ans++;
            f[U.root(i)]=false;
        }
    }
    cout<<ans<<endl;

}

