template<class T> struct UF{
    vector<T> par,sz;

    UF(T n){
        par.resize(n);
        sz.resize(n);
        for (int i = 0; i < n; ++i) {
            par[i]=i;
            sz[i]=1;
        }
    }

    T find(T x){
        if(par[x]==x) return x;
        return par[x]=find(par[x]);
    }

    bool unit(T x,T y){
        x=find(x);
        y=find(y);
        if(x==y) return false;
        if(sz[x]>sz[y]){
            par[y]=x;
            sz[x]+=sz[y];
        }
        else{
            par[x]=y;
            sz[y]+=sz[x];
        }
        return true;
    }

    bool same(T x,T y){return find(x)==find(y);}
};

int main(){
    ll n,m,ans=0;
    cin>>n>>m;
    bool vis[100010]={};
    int x,y,z;
    UF<ll> uf(n);
    fr(i,m){
        cin>>x>>y>>z;
        uf.unit(x-1,y-1);
    }
    fr(i,n){
        ll j=uf.find(i);
        if(vis[j]) continue;
        vis[j]=1;
        ans++;
    }
    cout<<ans<<endl;
}

