bool issue = false;

void dfs(int s, vector<int> &visited, int label) {
  visited[s] = label;

  for(auto &pi : g[s]) {
    if(visited[pi.first] != -1) {
      if((visited[s] + pi.second + visited[pi.first]) % 2) {
        issue = true;
      }
    } else {
      dfs(pi.first, visited, (visited[s] + pi.second) % 2);
    }
  }
}

