  }

  int ans = 0;
  for(int i = 1;i <= N;i++) {
    if(visited_1[i] == -1) {
      dfs(i, visited_1, 1);
      bool i1 = issue;
      issue = false;
      dfs(i, visited_2, 0);
      bool i2 = issue;
      issue = false;
      if(i1 + i2 == 0) ans++;
      // cout << i1+i2 << endl;
    }
  }

  cout << ans << endl;

  return 0;
}

