  int cmps; vi s;
  uf (int n) : cmps(n), s(n, -1) {}
  bool conn(int i, int j) {
    return find(i) == find(j);
  }
  int find(int i) {
    return s[i] < 0 ? i : (s[i] = find(s[i]));
  }
  void join(int i, int j) {
    i = find(i), j = find(j);
