int root(int x){
  if(par[x] == x){
    return x;
  }else{
    return par[x] = root(par[x]);
  }
}

bool same(int a, int b){
  return root(a) == root(b);
}

void unite(int a, int b){
  a = root(a);
  b = root(b);
  if(a == b)return;
  par[a] = b;
}

