int ans[101010];
int X[101010], Y[101010], Z[101010];

vector<int> g[101010];
void solve(int u) {
    for (int v : g[u]) {
        if (ans[v] != -1) continue;
        ans[v] = 2;
        solve(v);
    }
}

int main() {
    int N, M;
    cin >> N >> M;
    fill(ans, ans+N, -1);
    map<int, int> used;
    rep(i, M) {
        cin >> X[i] >> Y[i] >> Z[i];
        X[i]--; Y[i]--;
        used[X[i]]++;
        used[Y[i]]++;
        if (Z[i]%2 == 0) {
            ans[X[i]] = ans[Y[i]] = 1;
        }
        g[X[i]].push_back(Y[i]);
        g[Y[i]].push_back(X[i]);
    }

    vector<pair<int, int>> tmp;
    rep(i, N) {
        tmp.emplace_back(used[i], i);
    }
    sort(tmp.rbegin(), tmp.rend());

    rep(i, 20) {
        rep(j, M) {
            if (Z[j]%2) {
                if (ans[X[j]] == -1 and ans[Y[j]] == -1) continue;
                else if (ans[X[j]] != -1 and ans[Y[j]] == -1) {
                    if (ans[X[j]] == 0) {
                        ans[Y[j]] = 1;
                    }
                }
                else if (ans[X[j]] == -1 and ans[Y[j]] != -1) {
                    if (ans[Y[j]] == 0) {
                        ans[X[j]] = 1;
                    }
                }
            }
        }
    }

    int ret = 0;
    rep(i, N) {
        int v = tmp[i].second;
        if (ans[v] == -1) {
            ret++;
            ans[v] = 2;
            solve(v);
        }
    }

    cout << ret << endl;

}

