	vector<Int> seen(N);//決まっていれば1
	Int x, y,z;
	for (Int i = 0; i < M; i++) {
		cin >> x >> y>>z;
		x--;
		y--;
		f.unite(x, y);
	}

	Int cnt = 0;
	Int temp;
	for (Int i = 0; i < N; i++) {
		temp = f.root(i);
		if (seen[temp]) {
			seen[i] = 1;
			continue;
		}
		else {
			seen[temp] = 1;
			seen[i] = 1;
			cnt++;
		}
	}

	cout << cnt << "\n";

}

