int parent[100000];

void init(int N){
    for(int i = 0; i < N; i++){
        parent[i] = i;
    }
}

int find(int node){
    int temp = parent[node];
    if(temp == node){
        return temp;
    }
    else{
        int newParent = find(temp);
        parent[node] = newParent;
        return newParent;
    }
}

void unite(int i, int j){
    int pi = find(i);
    int pj = find(j);

    if(pi != pj){
        parent[i] = pj;
    }
}

