class UnionFind {

public :
    int* par;
    // 自分のグループに何人属しているかを管理
    int* depth;
    UnionFind(int n);
    virtual ~UnionFind();
    // 同じグループにいるかどうか
    bool same(int x, int y);
    // 同じグループに所属させる
    void unite(int x,int y);
    // どのグループに属しているかを見つける
    int find(int x);
};

UnionFind::UnionFind(int n)
{
    par = new int[n];
    depth = new int[n];
    for (int i = 0; i < n; i++) {
        par[i] = i;
        depth[i] = 1;
    }
}

UnionFind::~UnionFind()
{
    delete[] par;
    delete[] depth;
}

int UnionFind::find(int x)
{
    if (par[x] == x) {
        return x;
    } else {
        par[x] = find(par[x]);
        return par[x];
    }
}

void UnionFind::unite(int x,int y) 
{
    int rootX, rootY;
    rootX = find(x);
    rootY = find(y);
    if (rootX == rootY) {
        return;
    }

    if (depth[rootX] < depth[rootY]) {
        par[rootX] = rootY;
        depth[rootY] += depth[rootX];
    } else {
        par[rootY] = rootX;
        depth[rootX] += depth[rootY];
    }
}

bool UnionFind::same(int x, int y)
{
    return find(x) == find(y);
}

