template<int SZ> struct DSU {
    int parent[SZ], size[SZ], count[SZ];

    DSU() {
        F0R(i, SZ) parent[i] = i, size[i] = 0, count[i] = 1;
    }

    int get(int x) {
        if (parent[x] != x) parent[x] = get(parent[x]);
        return parent[x];
    }

    void unify(int x, int y) {
        x = get(x); y = get(y);
        if (x == y) return;
        if (size[x] < size[y]) swap(x, y);
        if (size[x] == size[y]) size[x]++;
        parent[y] = x;
        count[x] += count[y];

    }
};

