		par.resize(n);
		rank.resize(n);
		for (int i = 0; i < n; ++i) {
			par[i] = i;
			rank[i] = 0;
		}
	}

	//木の根を探す
	int find(int s) {
		if (par[s] == s) {
			return s;
		}
		return par[s] = find(par[s]);
	}

