	void unite(int x, int y) {
		int a = find(x), b = find(y);
		if (a == b) {
			return;
		}
		if (rank[a] < rank[b]) {
			par[a] = b;
		}
		else {
			par[a] = b;
			if (rank[a] == rank[b]) {
				++rank[b];
			}
		}
	}

	//二つの数の根が同じかどうか
	bool same(int x, int y) {
		return find(x) == find(y);
