#include <bits/stdc++.h>

using namespace std;
using ii = pair<int, int>;

class UFDS
{
private:
    std::vector<int> size, ps;
    int count;

public:
    UFDS(int N) : size(N + 1, 1), ps(N + 1), count(N)
    {
        std::iota(ps.begin(), ps.end(), 0);
    }

    int find_set(int x) 
    {
        return x == ps[x] ? x : (ps[x] = find_set(ps[x]));
    }

    bool same_set(int x, int y)
    {
        return find_set(x) == find_set(y);        
    }

    void union_set(int x, int y)
    {
        if (same_set(x, y))
            return;

        int p = find_set(x);
        int q = find_set(y);

        if (size[p] < size[q])
            std::swap(p, q);

        ps[q] = p;
        size[p] += size[q];
        --count;
    }

    int get_count() const { return count; }
};

int solve(int N, const vector<ii>& es)
{
    UFDS ufds(N);

    for (auto p : es)
    {
        auto x = p.first, y = p.second;

        ufds.union_set(x, y);
    }

    return ufds.get_count();
}

int main()
{
    ios::sync_with_stdio(false);

    int N, M;
    cin >> N >> M;

    vector<ii> es(M);

    for (int i = 0; i < M; ++i)
    {
        int x, y, z;
        cin >> x >> y >> z;

        es.push_back(ii(x, y));
    }

    cout << solve(N, es) << endl;

    return 0;
}

