class UF{
private:
	vector<int> root;

public:
	UF(int n){
		root = vector<int>(n, -1);
	}

	int getRoot(int x){
		if(root[x] == -1) return x;
		else return root[x] = getRoot(root[x]);
	}

	void update(int x, int y){
		x = getRoot(x);
		y = getRoot(y);
		if(x == y) return;
		if(x > y) swap(x, y);
		root[y] = x;
	}

};

int main()
{
	int n, m;
	cin >> n >> m;
	UF uf(n);
	for(int i = 0; i < m; i++){
		int x, y, z;
		cin >> x >> y >> z;
		x--;
		y--;
		uf.update(x, y);
	}
	int ans = 0;
	for(int i = 0; i < n; i++){
		if(i == uf.getRoot(i)){
			ans++;
		}
	}
	cout << ans << endl;
}

