int main() {
    int N; // the number of vertices
    int M; // the number of edges
    std::cin >> N >> M;
    assert(2 <= N && N <= 100'000);
    assert(1 <= M && M <= 100'000);

    // Getting edges in adjacency list
    std::vector<int> A[N]; // A_i: the adjacency list of the vertex i

    for (int i=0; i<M; i++) {
        int x, y, z;
        std::cin >> x >> y >> z;
        assert(1 <= x && x <= N);
        assert(1 <= y && y <= N);
        assert(x < y);
        assert(1 <= z && z <= 100);
        A[x-1].push_back(y-1);
        A[y-1].push_back(x-1);
    }

    // Deciding the number of the connected components
    int cc = 0; // the number of the connected components
    bool visited[N];

    std::function<void(int)> DFS;
    DFS = [&](int v) {
        if (visited[v]) return;
        visited[v] = true;
        for (int i=0; i<A[v].size(); i++) DFS(A[v].at(i));
    };

    for (int i=0; i<N; i++) visited[i] = false;
    for (int i=0; i<N; i++) {
        if (visited[i]) continue;
        DFS(i);
        cc++;
    }

    std::cout << cc << std::endl;

    return 0;
}

