    for(int i=0;i<n;++i)
    {
        if(!visited[i])
        {
            res++;
            deque<int> q;
            q.push_back(i);
            visited[i] = true;
            while(!q.empty())
            {
                int src = q.front();
                q.pop_front();
                for(int dst: edges[src])
                {
                    if(!visited[dst])
                    {
                        visited[dst] = true;
                        q.push_back(dst);
                    }
                }
            }
        }
    }
    cout << res << endl;

}

