void bfs(int i, int color[], vector<int> adj[]) {
  queue<int> que;
  que.push(i);

  while (que.size() > 0) {
    int cur = que.front();
    que.pop();
    for (auto a = adj[cur].begin(); a != adj[cur].end(); a++) {
      if (color[*a] == 0) {
        color[*a] = 1;
        que.push(*a);
      }
    }
  }
}

int main() {
  int N, M;
  cin >> N >> M;

  vector<int> adj[N + 1];

  for (int i = 0; i < M; i++) {
    int x, y, z;
    cin >> x >> y >> z;
    adj[x].push_back(y);
    adj[y].push_back(x);
  }

  int color[N + 1];
  for (int i = 1; i <= N; i++) {
    color[i] = 0;
  }

  int count = 0;
  for (int i = 1; i <= N; i++) {
    if (color[i] == 0) {
      color[i] = 1;
      bfs(i, color, adj);
      count += 1;
    }
  }

  cout << count << endl;

  return 0;
}

