namespace NyaGadget
{
	struct UnionFindVertex
	{	// 頂点を表現する構造体
		ll self = 0; // 自分自身のインデックス
		ll root = 0; // 根のインデックス
		ll size = 0; // 自分が属している木のサイズ
	};

	struct UnionFind
	{
		vt<UnionFindVertex> v;

		/**
		@brief コンストラクタ
		@param max データ最大値
		@note
		 max+1の素集合データ構造を作成する
		**/
		UnionFind(ll max)
		{	// [0-max]のデータ構造にするため、max+1でリサイズ
			v.resize(max+1);
			each(i, e, v)
			{	// 各頂点の根を自分自身で初期化、木サイズは1
				e.self = i;
				e.root = i;
				e.size = 1;
			}
		}
		/**
		@brief 根を検索する関数
		@param i 根を検索する頂点インデックス
		@note
		 引数で指定された頂点の根を返す。
		**/
		ll Find(ll i)
		{
			if (i == v[i].root) return i;

			// 根の探索をすると同時に次からO(1)で根を参照できるようにする(経路圧縮)
			v[i].root = Find(v[i].root);
			return v[i].root;
		}
		/**
		@brief 頂点を併合する関数
		@param i1 併合する頂点1
		@param i2 併合する頂点2
		@note
		 頂点i1を含む木と頂点i2を含む木を「サイズ優先で」併合する。
		 ただし、i1とi2が既に同じ木に属しているときは何もしない。
		 併合したときtrue、何もしなかったときfalseを返す。
		 サイズによる工夫により、計算量はアッカーマンの逆関数になる。
		**/
		bool Union(ll i1, ll i2)
		{
			ll root1 = Find(i1);
			ll root2 = Find(i2);

			// 既に同じ木に属しているときは何もしない
			if (root1 == root2) return false;

			// サイズの小さい木の根をサイズの大きい木の根に繋いで併合する
			if (v[root1].size < v[root2].size)
			{
				v[root1].root = root2;
				v[root2].size += v[root1].size;
			}
			else
			{
				v[root2].root = root1;
				v[root1].size += v[root2].size;
			}
			return true;
		}

		/**
		@brief 頂点を併合する関数
		@param i1 併合する頂点1
		@param i2 併合する頂点2
		@param parent 親ノード
		@note
		 頂点i1を含む木と頂点i2を含む木を「parentを親として」併合する。
		 通常、parentにはi1かi2のどちらかを渡す。
		 ただし、i1とi2が既に同じ木に属しているときは何もしない。
		 併合したときtrue、何もしなかったときfalseを返す。
		 計算量はO(logN)になり、アッカーマンの逆関数に比べて若干遅くなる。
		**/
		bool Union(ll i1, ll i2, ll parent)
		{
			ll root1 = Find(i1);
			ll root2 = Find(i2);

			// 既に同じ木に属しているときは何もしない
			if (root1 == root2) return false;

			// 子の木を親の木へ併合する
			if (parent == i1)
			{
				v[root2].root = root1;
				v[root1].size += v[root2].size;
			}
			else
			{
				v[root1].root = root2;
				v[root2].size += v[root1].size;
			}
			return true;
		}
	};
}

using namespace NyaGadget;

const ll MAX = Nya(5);

int main(void)
{
	ll N, M; cin >> N >> M;
	vt<ll> X(M), Y(M), Z(M); // x[0, N-1] y[0, N-1]
	rep(i, 0, M)
	{
		cin >> X[i] >> Y[i] >> Z[i];
		X[i]--; Y[i]--; Z[i]--;
	}

	vt<ll> xycount(N);
	rep(i, 0, M)
	{
		xycount[X[i]]++;
		xycount[Y[i]]++;
	}

	ll ans = 0;
	vt<bool> unk(N, true);
	UnionFind uf(MAX);
	rep(i, 0, M)
	{
		if (xycount[Y[i]] <= xycount[X[i]]) uf.Union(X[i], Y[i], X[i]);
		else uf.Union(X[i], Y[i], Y[i]);
	}

	rep(i, 0, M)
	{
		unk[X[i]] = (uf.Find(X[i]) == X[i]) ? true : false;
		unk[Y[i]] = (uf.Find(Y[i]) == Y[i]) ? true : false;
	}

	rep(i, 0, N) if (unk[i]) ans++;
	cout << ans;
	return 0;
}

