        x--; y--;
        Union(x,y);
        know[x] = true; know[y] = true;
    }
    int ans = 1;

    sort(par.begin(),par.end());
    rep(i,n-1){
        if(par[i] != par[i+1]) ans++;
    }

    cout << ans << endl;
}

