struct UF{
  vector<int>par,rank;
  UF(int n){
    par.resize(n);
    rank.resize(n,0);
    for(int i=0;i<n;i++)par[i]=i;
  }
  int root(int x){
    if(par[x]==x)return x;
    return par[x]=root(par[x]);
  }
  void unite(int x,int y){
    x=root(x);
    y=root(y);
    if(rank[x]<rank[y]){
      par[y]=x;
    }
    else{
      par[x]=y;
      if(rank[x]==rank[y]){
        rank[x]++;
      }
    }
  }
  bool isSame(int x,int y){
    return root(x)==root(y);
  }
};

