#include <iostream>
#include <vector>
#include <stack>

template<class T>
class UnionFindTree{
public:
    UnionFindTree(const T N){
        tree = std::vector<T>(N);
        for(T i=0; i<N; ++i){
            tree[i] = i;
        }
    }

    T root(const T idx){
        T tmp = idx;
        std::stack<T> stack;
        while(tree[tmp] != tmp){
            stack.push(tmp);
            tmp = tree[tmp];
        }
        while(!stack.empty()){
            tree[stack.top()] = tmp;
            stack.pop();
        }
        return tmp;
    }

    void merge(const T idx1, const T idx2){
        tree[root(idx1)] = root(idx2);
    }

    bool same(const T idx1, const T idx2){
        return root(idx1) == root(idx2);
    }

private:
    std::vector<T> tree;
};



int main(int argc, char *argv[]){
