struct UnionFind{
    vector<ll> d;
    UnionFind(ll n): d(n,-1){}

    ll root (ll x){
        if(d[x] < 0) return x; // 自分が根
        return d[x] = root(d[x]);
    }

    bool unite(ll x, ll y){
        x = root(x); y = root(y);
        if(x == y)return false;
        if(d[x]>d[y])swap(x,y);
        d[x] += d[y];
        d[y] = x;
        return true;
    }

    bool same(ll x, ll y){ //同じグループか判定
        return root(x) == root(y);
    }

    ll size(ll x){
        return -d[root(x)];
    }
};

