        for (int i = 0; i < n; i++) {
            pars[i] = i;
        }
    }

    int get_root(int i) {
        if (pars[i] == i) {
            return i;
        } else {
            pars[i] = get_root(pars[i]);
            return pars[i];
        }
    }
    bool is_same(int i, int j) {
        return get_root(i) == get_root(j);
    }
    void unite(int i, int j) {
        if (is_same(i, j) == false) {
            pars[get_root(j)] = get_root(i);
        }
    }
};

