        if (parent[x] == x) return x;
        return parent[x] = root(parent[x]);
    }

    void unite(int x, int y) {
        int rootX = root(x);
        int rootY = root(y);
        if (rootX == rootY) return;
        parent[x] = rootY;
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

