struct Union_Find
{
	vector<int> par;
	int n;
	Union_Find(int a) {init(a);}
	void init(int a) {
		n = a;
		par.resize(n, -1);
	}
	int root(int x) {
		return par[x] < 0 ? x : par[x] = root(par[x]);
	}
	bool same(int x, int y) {
		return root(x) == root(y);
	}
	bool unite(int x, int y) {
		x = root(x);
		y = root(y);
		if (x == y) return false;
		if (size(x) < size(y)) swap(x, y);
		par[x] += par[y];
		par[y] = x;
		return true;
	}
	int size(int x) {
		x = root(x);
		return -par[x];
	}
};

