T peak_and_pop(std::queue<T>& q)
{
    assert(!q.empty());
    T t = move(q.front());
    q.pop();
    return t;
}

struct edge_t {
    edge_t(int n, int d):next(n),distance(d){}
    int next = 0;
    int distance = 0;
};

constexpr int unknown = 0;

struct node_t {
    int num = unknown;
    vector<int> same_node;
    vector<int> different_node;
};

void solution()
{
    int n,m;
    cin >> n >> m;
    vector<node_t> nodes(n);

    const auto connect = [&](int u, int v, int w){
        if(w % 2 == 0){
            nodes[u].same_node.push_back(v);
            nodes[v].same_node.push_back(u);
        }else{
            nodes[u].different_node.push_back(v);
            nodes[v].different_node.push_back(u);
        }
    };

    rep(i,m){
        int x,y,z;
        cin >> x >> y >> z;
        connect(x-1, y-1, z);
    }

    int cost = 0;
    queue<int> visit_queue;
    rep(i,n){
        if(nodes[i].num == unknown){
            nodes[i].num = 1;
            visit_queue.push(i);
            cost += 1;
        }
        while(!visit_queue.empty()){
            auto& node = nodes.at(peak_and_pop(visit_queue));
            assert(node.num != unknown);
            for(auto& j : node.same_node){
                if(nodes[j].num == unknown){
                    nodes[j].num = node.num;
                    visit_queue.push(j);
                }
            }
            for(auto& j : node.different_node){
                if(nodes[j].num == unknown){
                    nodes[j].num = node.num == 2 ? 1 : 2;
                    visit_queue.push(j);
                }
            }
        }
    }
    cout << cost << '\n';
}

