struct UnionFind {
	struct Node {
		Node*	parent = nullptr;
		int		count = 1;

		Node* Root() {
			if (parent == nullptr) {
				return this;
			}
			return parent = parent->Root();
		}
	};
	vector<Node> nodes;

	UnionFind(int count) {
		nodes.resize(count);
	}

	void Join(int a, int b) {
		Node* rootA = nodes[a].Root();
		Node* rootB = nodes[b].Root();
		if (rootA == rootB) {
			return;
		}

		if (rootA->count > rootB->count) {
			swap(rootA, rootB);
		}

		rootB->count += rootA->count;
		rootA->parent = rootB;
		rootA->count = 0;
	}

	bool IsReachable(int a, int b) {
		Node* rootA = nodes[a].Root();
		Node* rootB = nodes[b].Root();
		return rootA == rootB;
	}

	int Count(int a) {
		return nodes[a].Root()->count;
	}
};

struct MyMain {
	int N = in;
	int M = in;

	void Run() {
		UnionFind uf(N);
		REP(i, M) {
			int X = in(-1);
			int Y = in(-1);
			int Z = in;
			uf.Join(X, Y);
		}

		set<UnionFind::Node*> nodes;
		REP(i, N) {
			nodes.insert(uf.nodes[i].Root());
		}

		out << nodes.size();
	}
};

