const int MAX = 100000;

int parent[MAX], tree_rank[MAX];

void init(int n) {
  // n:要素数
  for (int i = 0; i < n; i++) {
    parent[i] = i;
    tree_rank[i] = 0;
  }
}

int find(int x) {
  // xの根を求める
  if (parent[x] == x) {
    return x;
  } else {
    return parent[x] = find(parent[x]);
    // 繋ぎ変え
  }
}

void unite(int x, int y) {
  // xが入っている集合とyが入っている集合をくっつける
  int rx = find(x);
  int ry = find(y);
  if (rx == ry) {
    // もし同じ集合なら
    return;
  }
  if (tree_rank[rx] < tree_rank[ry]) {
    parent[rx] = ry;
  } else {
    parent[ry] = rx;
    if (tree_rank[rx] == tree_rank[ry]) {
      tree_rank[rx]++;
    }
  }
}

bool issame(int x, int y) { return find(x) == find(y); }

