class disjointset{

  public:

    vector<int>rank,parent,sz;

    disjointset(int size){
        rank=parent=sz=vector<int>(size+1);
        for(int i=0;i<=size;i++)rank[i]=0,parent[i]=i,sz[i]=1;
    }

    int root(int n){return (parent[n]==n?n:parent[n]=root(parent[n]));}

    void unite(int x,int y){
        x=root(x);y=root(y);
        if(x==y)return;
        (rank[x]>rank[y])?parent[y]=x,sz[x]+=sz[y]:parent[x]=y,sz[y]+=sz[x];
        rank[root(x)]+=(rank[x]==rank[y]);
    }
};

