ll N, M, i, X[100001], Y[100001], Z[100001];

struct UnionFind {
    vector<ll> par; // par[i]:iの親の番号  (例) par[3] = 2 : 3の親が2
    vector<ll> rank; // 木の深さ
    vector<ll> siz; // 集合のサイズを表す配列

    UnionFind(ll N) : par(N), rank(N), siz(N) { //最初は全てが根であるとして初期化
        for(ll i = 0; i < N; i++){
            par[i] = i;
            rank[i] = 0;
            siz[i] = 1;
        }
    }

    ll root(ll x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(ll x, ll y) { // xとyの木を併合
        x = root(x);
        y = root(y);
        if (x == y) return; //xとyの根が同じ(=同じ木にある)時はそのまま

        if(siz[x] < siz[y]){
            swap(x, y);
        }

        siz[x] += siz[y];
        par[y] = x;
        if(rank[x] == rank[y]) rank[x]++;
    }

    bool same(ll x, ll y) { // 2つのデータx, yが属する木が同じならtrueを返す
        ll rx = root(x);
        ll ry = root(y);
        return rx == ry;
    }

    ll size(ll x){ // xが属する集合の要素数
        return siz[root(x)];
    }
};

