	public:
		UnionFind(int N) { 
			rank.assign(N, 0);
			t.assign(N, 1);
			p.assign(N, 0); 
			for (int i = 0; i < N; i++) 
				p[i] = i;
		}
		int findSet(int i) { 
			return (p[i] == i) ? i : (p[i] = findSet(p[i])); 
		}
		bool isSameSet(int i, int j) { 
			return findSet(i) == findSet(j);
		}
		void unionSet(int i, int j) {
			if (!isSameSet(i, j)) {
				int x = findSet(i), y = findSet(j);
				if (rank[x] > rank[y]) {
					p[y] = x;
					t[x] += t[y];
				} else {
					p[x] = y;
					t[y] += t[x];
					if (rank[x] == rank[y])
						rank[y]++;
				}
			}
		}
		int totalSet(int i) {
			return t[findSet(i)];
		}
};

