      par.resize(N);
      rank.resize(N);
      for(ll i=0; i<N; ++i){
        par[i] = i;
        rank[i] = 0;
      }
      return;
    };

    ~Union_Find(void){
      return;
    };

    //search the root
    ll find(ll x){
      if(par[x] == x){
        return x;
      }else{
        return par[x] = find(par[x]);
      }
    };

    //merge the sets x or y belong
    void unite(ll x, ll y){
      x = find(x);
      y = find(y);
      if(x == y) return;

      if(rank[x] < rank[y]){
        par[x] = y;
      }else{
        par[y] = x;
        if(rank[x] == rank[y]){
          rank[x]++;
        }
      }
      return;
    };

    //judge x and y belong the same set or not
    bool same(ll x, ll y){
      return find(x) == find(y);
    };
};

