struct Unionfind {
    vector<int> par, rank;

    Unionfind(int n) {
        par.resize(n);
        fill(par.begin(), par.end(), -1);
        rank.resize(n);
    }

    int root(int x) {
        int r = x;
        while (!(par[r]<0)) r = par[r];
        int t = x;

        while (t!=r) {
            int tmp = t;
            t = par[t];
            par[tmp] = r;
        }

        return r;
    }

    void unite(int x, int y) {
        int rx = root(x);
        int ry = root(y);

        if (rx==ry) return;

        if (rank[rx]<=rank[ry]) {
            par[ry] += par[rx];
            par[rx] = ry;

            if (rank[rx]==rank[ry]) rank[ry]++;
        }
        else {
            par[rx] += par[ry];
            par[ry] = rx;
        }
    }

    bool is_same(int x, int y) {
        return root(x)==root(y);
    }

    int count(int x) {
        return -par[root(x)];
    }
};

