    ll n, m; cin >> n >> m;
    UnionFind tree(n);
    rep(i,m) {
        ll u,v,z; cin >> u >> v >> z;
        u--; v--;
        tree.merge(u,v);
    }
    cout << tree.allsize() << endl;

    return 0;
}

