struct UnionFind
{
    vector<int> par;
    vector<int> sizes;
    vector<int> rnk;
    UnionFind(){}
    UnionFind(int n){
        par.resize(n);rnk.resize(n,0);
        sizes.resize(n, 1);
        REP(i,n) par[i] = i;
    }

    int find(int x) {
        if (x == par[x]) return x;
        return par[x] = find(par[x]);
    }

    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if(x==y)return;
        if(rnk[x]<rnk[y]){
            par[x]=y;
            sizes[y]+=sizes[x];
        }else{
            par[y]=x;
            sizes[x]+=sizes[y];
            if(rnk[x]==rnk[y])rnk[x]++;
        }
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }
    int size(int x) {
        return sizes[find(x)];
    }
};

