int parent(int x, vector<int> &par){
  if(par.at(x) == x) return x;
  return par.at(x) = parent(par.at(x), par);
}

void join(int u, int v, vector<int> &par){
  int pu = parent(u, par);
  int pv = parent(v, par);
  if(pu == pv) return;
  par.at(pu) = pv;
}

