	cin >> N >> M;
	UnionFind uf(N);
	REP(i, M) {
		ll X, Y, Z;
		cin >> X >> Y >> Z;
		X--; Y--;
		uf.merge(X, Y);
	}
	set<ll> se;
	REP(i, N) {
		se.insert(uf.root(i));
	}
	PRINT(se.size());
	return 0;
}

