using namespace std;
class dsu {
public:
  vector<int> rank, p, size;
  dsu(){};
  dsu(int n) {
    rank.assign(n, 0);
    size.assign(n, 1);
    p.resize(n);
    for (int i = 0; i < n; ++i) p[i] = i;
  }

  int getSize(int x) {
    return size[findRep(x)];
  }

  void unite(int x, int y) {
    int p1 = findRep(x), p2 = findRep(y);
    if (p1 == p2) return;
    if (rank[p1] < rank[p2]) swap(p1, p2);

    if (rank[p1] == rank[p2]) rank[p1]++;
    p[p2] = p1;
    size[p1] += size[p2];
  }

  int findRep(int x) {
    if ( x != p[x] ) {
      p[x] = findRep(p[x]);
    }
    return p[x];
  }
};

int main() {
