struct UnionFind {
    vector<int> par;

    UnionFind(int N) : par(N) {
        //初めは全部の頂点が根になる
        for (int i = 0; i < N; i++) par[i] = i;
    }

    int root(int x) { //木の根を求める
        if (par[x] == x) { //根の判定
            return x;
        }
        else {
            return (par[x] = root(par[x])); //経路圧縮
        }
    }

