VI parent;   // 各要素の親の要素

int root(int x) {   // 根に到達するまで親を辿る
    if (parent[x] == x) {   // 根は親==自分
        return x;
    } else {   // 経路圧縮(木の深さを緩和するために辿った要素を全て根に直結させる)
        return parent[x] = root(parent[x]);
    }
}

bool same(int x, int y) {   // 根が同じなら同じ集合に属する
    return root(x) == root(y);
}

void unite(int x, int y) {   // 同値関係x~yを追加(xが属する集合とyが属する集合をマージ)、ランクは考慮しない実装だがO(logN)程度
    x = root(x);
    y = root(y);
    if (x == y) return;   // すでに同じ集合
    parent[x] = y;
}


