class UnionFind
{
public:
	explicit UnionFind(int size)
		: mParent(size, -1)
		, mRank(size, 0)
        , mData(size, 0)
		, mSize(size)
		{}
	bool unionSet(int x, int y)
	{
		if ((x = root(x)) == (y = root(y)))
			return false;
		if( mRank[x] < mRank[y] )
		{
			mParent[y] += mParent[x];
			mParent[x] = y;
            unionData( mData[y], mData[x] );
		}
		else
		{
			mParent[x] += mParent[y];
			mParent[y] = x;
			if( mRank[x] == mRank[y] ) ++mRank[x];
            unionData( mData[x], mData[y] );
		}
		--mSize;
		return true;
	}
	bool isEqualSet(int x, int y)
	{
		return root(x) == root(y);
	}
	int root(int x)
	{
		return mParent[x] < 0 ? x : mParent[x] = root(mParent[x]);
	}
	int unionSize(int x)
	{
		return -mParent[root(x)];
	}
	int size() const
	{
		return mSize;		
	}

	void unionData( int& parent, int& child )
	{
		parent += child;
	}
	void setData( int x, int data )
	{
		mData[root(x)] = data;
	}
	int getData( int x )
	{
		return mData[root(x)];
	}

private:
	vector<int> mParent; // = mUnionSize
	vector<int> mRank;
	vector<int> mData;
	int mSize;
};

