        cin >> x[i] >> y[i] >> z[i];
        --x[i], --y[i];
        exists[x[i]] = exists[y[i]] = true;
        vec[x[i]].push_back(y[i]);
    }

    bool decided[n];
    fill(decided, decided + n, false);
    int res = 0;
    for (int i = 0; i < n; i++) {
        if (!exists[i]) {
