int main() {
	int N, M;
	cin >> N >> M;
	vector<vector<int> > G(N);
	for (int i = 0; i < M; ++i) {
		int a, b, c;
		cin >> a >> b >> c; --a, --b;
		G[a].push_back(b);
		G[b].push_back(a);
	}
	int cnt = 0;
	vector<long long> dist(N, -1);
	for (int i = 0; i < N; ++i) {
		if (dist[i] != -1) continue;
		++cnt;
		dist[i] = 0;
		queue<int> que;
		que.push(i);
		while (!que.empty()) {
			int u = que.front(); que.pop();
			for (int e : G[u]) {
				if (dist[e] == -1) {
					dist[e] = dist[u] + 1;
					que.push(e);
				}
			}
		}
	}
	cout << cnt << endl;
	return 0;
}

