void dfs(vector<int> &exception, vector<vector<int>> &group, int curr) {
    exception[curr] = 1;
    for (auto next : group[curr]) {
        if (exception[next] == -1) {
            dfs(exception, group, next);
        }
    }
}

int main() {
    int N, M;
    cin >> N >> M;
    int x, y, z;
