    vector<vector<int>> group(N + 1);
    for (int i = 0; i < M; i++) {
        cin >> x >> y >> z;
        exception[x] = -1;
        exception[y] = -1;
        group[x].push_back(y);
        group[y].push_back(x);
    }
    int ans = 0;
    for (int i = 1; i <= N; i++) {
        if (exception[i] == -2)
            ans += 1;
        else if (exception[i] == -1) {
            ans += 1;
            dfs(exception, group, i);
        }
    }

    cout << ans << endl;
    return 0;
}

