struct Unionfind{
    vector<int> par;
    vector<int> rank;

    Unionfind(int n){
        init(n);
    }

    void init(int n=1){
        par.resize(n),rank.resize(n);
        rep(i,n) par[i]=i,rank[i]=0;
    }

    int root(int x){
        if (par[x]==x) {
        return x;
        } else {
            int r=par[x];
            return par[x]=r; //親が帰ってくる？？
        }
    }

    bool issame(int x,int y) {
        return root(x)==root(y);
    }

    bool merge(int x,int y) {
        x=root(x); y=root(y);
        if (x==y) return false;
        if (rank[x]<rank[y]) swap(x, y);
        if (rank[x]==rank[y]) ++rank[x];
        par[y]=x;
        return true;
    }

};


