	int N, M;
	cin >> N >> M;
	init(N);
	ans = N;
	for(int i=0; i<M; i++){
		int x, y, z;
		cin >> x >> y >> z;
		x--; y--;
		unite(x, y);
	}
	cout << ans << endl;
	return 0;
}

