template <typename T = ll> struct TreeBFS {
    vector<T> dist;
    vector<vector<pair<int, T>>> edges;
    TreeBFS(int n) : dist(n, -1), edges(n) {}
    void addEdge(int f, int t, T w) {
        edges[f].emplace_back(t, w);
        edges[t].emplace_back(f, w);
    }
    void bfs(int start) {
        dist[start] = 0;
        deque<int> node;
        node.push_back(start);
        while (node.size() != 0) {
            int n = node.front();
            node.pop_front();
            for (auto e : edges[n]) {
                if (dist[e.first] == -1) {
                    dist[e.first] = dist[n] + e.second;
                    node.push_back(e.first);
                }
            }
        }
    }
};

