        return (x == p[x] ? x : p[x] = find(p[x]));
    }
    bool same(int x, int y){
        return find(x) == find(y);
    }
    void unite(int x, int y){
        x = find(x), y = find(y);
        if(x == y) return;
        if(r[x] < r[y]) swap(x, y);
        r[x] += r[y];
        p[y] = x;
        s[x] += s[y];
        num--;
    }
    int rank(int x){
        return r[find(x)];
    }
    int count() const{
        return num;
    }
    int size(int x){
        return s[find(x)];
    }
};


