#include <bits/stdc++.h>
using namespace std;

class UnionFind
{
    vector<int> par;
    int groupCount;

public:
    // UnionFind uf(n)でn要素のUF木uf
    UnionFind(int n = 0)
    {
        init(n);
    }

    // n要素で初期化
    void init(int n = 0)
    {
        par.resize(n);
        fill(par.begin(), par.end(), -1);
        groupCount = n;
        return;
    }

    // xが属する集合の根を求める
    int root(int x)
    {
        if (par[x] < 0)
        {
            return x;
        }
        return par[x] = root(par[x]);
    }

    // xとyが同じ集合に属するか調べる
    bool same(int x, int y)
    {
        return root(x) == root(y);
    }

    // xが属する集合の大きさを調べる
    int size(int x)
    {
        return -par[root(x)];
    }

    // xが属する集合とyが属する集合を繋ぐ
    // 既に繋がっていたらfalseが返る
    bool unite(int x, int y)
    {
        x = root(x);
        y = root(y);
        if (x == y)
        {
            return false;
        }
        if (par[y] < par[x])
        {
            swap(x, y);
        }
        par[x] += par[y];
        par[y] = x;
        --groupCount;
        return true;
    }

    // UF内にある集合の個数を調べる
    int size(void)
    {
        return groupCount;
    }
};

