typedef struct UnionFind
{
	vector<int> par;

	UnionFind(int N)
	{
		par.resize(N);
		for(int i=0; i<N; i++)
		{
			par[i] = i;
		}
	}

	int root(int x)
	{
		if(par[x]==x)
		{
			return x;
		}
		else
		{
			return par[x] = root(par[x]);
		}
	}

	void unite(int x, int y)
	{
		int rx = root(x);
		int ry = root(y);
		if(rx==ry)
		{
			return;
		}
		par[rx] = ry;
	}

	bool same(int x, int y)
	{
		return root(x) == root(y);
	}
}UnionFind;

int main()
{
	int N,M;
	cin>>N>>M;

	UnionFind tree(N);

	for(int i=0; i<M; i++)
	{
		int x,y,z;
		cin>>x>>y>>z;
		x--;
		y--;
		tree.unite(x,y);
	}

	set<int> s;

	for(int i=0; i<N; i++)
	{
		s.insert(tree.root(i));
	}

	cout<<s.size()<<endl;

	return 0;
}

