#include <bits/stdc++.h>
using namespace std;


struct UnionFind {
    vector<int> par;

    explicit UnionFind(int n) : par(n, -1) { }
    void init(int n) { par.assign(n, -1); }

    int find_root(int x) {
        if (par[x] < 0) return x;
        else return par[x] = find_root(par[x]);
    }

    bool is_same(int x, int y) {
        return find_root(x) == find_root(y);
    }

    bool unite(int x, int y) {
        int root_x = find_root(x);
        int root_y = find_root(y);
        if (root_x == root_y) return false;
        if (par[root_x] > par[root_y]) swap(root_x, root_y); // unite technique
        par[root_x] += par[root_y];
        par[root_y] = root_x;
        return true;
    }

    int size(int x) {
        return -par[find_root(x)];
    }
};

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int N, M;
    cin >> N >> M;
    UnionFind uf(N + 1);
    for (int i = 0; i < M; ++i) {
        int x, y, z;
        cin >> x >> y >> z;
        if (z % 2 == 0) {
            uf.unite(x, y);
        }
    }

    int count = 1;
    for (int i = 1; i <= N; ++i) {
        count += uf.size(i) == 1;
    }

    cout << min(N - 1, count) << '\n';


    return 0;
}

