vector<bool> is_filled;

void fill(int s, int d, Graph& g) {
	is_filled[d] = true;
	for (const auto &p_e : g.vertices[d]->edges) {
		int nd = p_e->p_dst->id;
		if (is_filled[nd])
			continue;
		fill(d, nd, g);
	}
}

