   int find(int x){
      while(x != parent[x]){
         parent[x] = parent[parent[x]];
         x = parent[x];
      }
      return x;
   }

   bool unite(int x, int y){
      x = find(x), y = find(y);
      if(x == y)
         return false;
      if(size[x] < size[y])swap(x, y);
      size[x] += size[y];
      parent[y] = x;
      return true;
   } 

   int getSize(int x){
      x = find(x);
      return size[x];
   }
};

