    UnionFind(int N) //par(N)を全て根として初期化
    : par(N), rank(N), size(N)
    {
        rep(i,0,N){
            par[i] = i;
            rank[i] = 0;
            size[i] = 1;
        }
    }
    int root(int x) 
    {
        if(par[x] == x) return x;
        return par[x] = root(par[x]);
    }
    bool unite(int x, int y)
    {
        int rx = root(x);
        int ry = root(y);
        if(rx == ry) return false;
        //rxが常に根に来るようにする。
        if(rank[rx] < rank[ry]) swap(rx,ry);
        if(rank[rx] == rank[ry]) rank[rx]++;
        par[ry] = rx;
        return true;
    }
    bool isSame(int x, int y){
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};

