constexpr int mint_len = 1400001;
vi fac, finv, inv;
vi p2;
void setmod() {
//    p2.resize(mint_len);p[0] = 1; for (int i = 1; i < mint_len; ++i) p2[i] = p2[i - 1] * 2 % MOD;
    fac.resize(mint_len);
    finv.resize(mint_len);
    inv.resize(mint_len);
    inv[1] = fac[0] = finv[0] = 1;
    for (int i = 2; i < mint_len; ++i) inv[i] = inv[MOD % i] * (MOD - MOD / i) % MOD;
    for (int i = 1; i < mint_len; ++i) fac[i] = fac[i - 1] * i % MOD, finv[i] = finv[i - 1] * inv[i] % MOD;
}
