// n要素で初期化(親が自分自身で、高さ0)
void init_uf(int n){
    for(int i=1; i<=n; i++){
        par[i] = i;
        height[i] = 0;
    }
}

// 親を見つける(再帰的)(記録して返す)
int find_par(int x){
    if(par[x] == x){
        return x;
    }
    else{
        return par[x] = find_par(par[x]);
    }
}

// 併合(根を共有させる)(heightに注意)
// 集合の情報は根っこにもたせてると考えてok
void unite(int x, int y){
    x = find_par(x);
    y = find_par(y);
    if(x == y) return;

    if(height[x] < height[y]){
        par[x] = y; // 高い方にいく
    }
    else{
        par[y] = x;
        // 高さ一緒だったら x の方が一段高くなる
        if(height[x] == height[y]) height[x]++;
    }
}

// 同グループかどうかの判定(根が等しいか)
bool same(int x, int y){
    return find_par(x) == find_par(y);
}

int main(void){
    int n,m;
    cin >> n >> m;

    // union find tree の初期化
    // 0 は除外してる
    init_uf(n);

    for(int i=0; i<m; i++){
        int x,y,z;
        cin >> x >> y >> z;
        unite(x,y);
    }

    // 異なるグループの数を数える
    // それが答え
    int ans = 0;
    set<int> a;
    for(int i=1; i<=n; i++){
        if(a.find(par[i]) == a.end()){
            ans += 1;
            a.insert(par[i]);
        }
    }

    cout << ans;

    return 0;
}

