#include <bits/stdc++.h>
using namespace std;

vector<int> par;
vector<int> rnk;

void makeSets(int n) {
    par.resize(n);
    rnk.resize(n);
    for(int i=0; i<n; i++) {
        par[i] = i;
        rnk[i] = 0;
    }
}

int find(int x) {
    if(x != par[x]) par[x] = find(par[x]);
    return par[x];
}

void unite(int xp, int yp) {
    int x = find(xp);
    int y = find(yp);
    if(x == y) return;
    if(rnk[x] > rnk[y]) {
        par[y] = x;
    } else {
        par[x] = y;
        if(rnk[x] == rnk[y]) rnk[y]++;
    }
}

int main() {
    int N, M;
    cin >> N >> M;
    makeSets(N);

    vector<int> X(M), Y(M), Z(M);
    for(int i=0; i<M; ++i) {
        cin >> X[i] >> Y[i] >> Z[i];
        --X[i]; --Y[i];
        if(Z[i] % 2 == 0) unite(X[i], Y[i]);
    }

    map<int, bool> K;
    int res = 0;
    for(int i=0; i<M; ++i) {
        if(Z[i] % 2) {
            if(!K[find(X[i])] && !K[find(Y[i])]) ++res;
            K[find(X[i])] = true;
            K[find(Y[i])] = true;
        }
    }

    for(int i=0; i<N; ++i) {
        if(!K[find(i)]) {
            ++res;
            K[find(i)] = true;
        }
    }
    cout << res << endl;
}

