struct UnionFind{
    std::vector<int> data;

    UnionFind(int size):
        data(size, -1){}

    void init() {
        fill(data.begin(), data.end(), -1);
    }

    int root(int x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    bool unite(int x, int y) {
        x = root(x);
        y = root(y);
        if(x == y) return false;

        if(data[y] < data[x]) std::swap(x, y); // yの方が気が深いなら交換
        data[x] += data[y];
        data[y] = x;

        return true;
    }

    int size(int x) {
        return -data[root(x)];
    }
};

int main(){
    int N, M;
    cin >> N >> M;
    vector<int> X(M), Y(M), Z(M);
    for(int i = 0; i < M; i++) {
        cin >> X[i] >> Y[i] >> Z[i];
        X[i]--, Y[i]--;
    }

    UnionFind uf(N);
    for(int i = 0; i < M; i++) {
        uf.unite(X[i], Y[i]);
    }

    set<int> s;
    for(int i = 0; i < N; i++) {
        s.insert(uf.root(i));
    }

    cout << s.size() << endl;

    return 0;
}

