struct E{
	int u,v,w;

	E() = default;
	E(int u_, int v_, int w_):u(u_),v(v_),w(w_){}

	E rev(){return E(v, u, w);}

	bool operator<(const E& rhs)const{
		return w == rhs.w ? u == rhs.u ? v < rhs.v : u < rhs.u : w < rhs.w;
	}
};

struct UF{
	vector<int> par;
	UF(size_t n): par(n,-1){}
	bool unite(int x, int y){
		x = root(x), y = root(y);
		if(x != y){
			if(par[y] < par[x]) swap(x,y);
			par[x] += par[y]; par[y] = x;
		}
		return x != y;
	}
	bool isSame(int x, int y){
		return root(x) == root(y);
	}

	int root(int x){
		if(par[x] < 0)return x;
		par[x] = root(par[x]);
		return par[x];
	}
	int size(int x){
		return -par[root(x)];
	}
	int rootnum(){
		int ret = 0;
		for(auto e : par){
			if(e < 0)ret += 1;
		}
		return ret;
	}
	void print(){
		for(auto e : par)cerr << e << " ";
		cerr << endl;
	}
};

