typedef long long int64;

class UnionFind {
public:
    vector<int> par, rank;
    UnionFind(int n);
    int root(int a);
    bool isConnect(int a, int b);
    void connect(int a, int b);
};

inline UnionFind::UnionFind(int n) {
    par.resize(n);
    rank.resize(n);
    for(int i = 0; i < n; ++i) {
        par[i] = i;
    }
}

inline int UnionFind::root(int a) {
    if(par[a] == a) return a;
    else return par[a] = root(par[a]);
}

inline bool UnionFind::isConnect(int a, int b) {
    return root(a) == root(b);
}

inline void UnionFind::connect(int a, int b) {
    a = root(a);
    b = root(b);
    if(a == b) return;
    if(rank[a] < rank[b]) {
        par[a] = b;
    } else {
        par[b] = a;
        if(rank[a] == rank[b]) rank[a]++;
    }
}

void solve() {
    int N, M;
    cin >> N >> M;
    UnionFind uf(N);
    rep(i, M) {
        int a, b, c;
        cin >> a >> b >> c;
        --a, --b;
        uf.connect(a, b);
    }
    set<int> st;
    rep(i, N) st.insert(uf.root(i));
    cout << st.size() << '\n';
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    solve();
    return 0;
}

