namespace UnionTree {
template <typename T>
int root(vector<T> &u, int x) {
    if (x < 0 || u.size() <= x) return -1;
    if (u[x].parent == -1)
        return x;
    else
        return u[x].parent = root(u, u[x].parent);
}
template <typename T>
bool connect(vector<T> &u, int a, int b) {
    a = root(u, a), b = root(u, b);
    if (a == b || a < 0 || b < 0) return false;
    u[b].parent = a;
    return true;
}
// O(u.size())
template <typename T>
void count(vector<T> &u, map<int, int> &ret) {
    for (int i = 0; i < u.size(); i++) {
        int tmp = u[i].parent;
        if (tmp == -1) tmp = i;
        if (!ret.count(tmp)) {
            ret[tmp] = 0;
        }
        ret[tmp]++;
    }
}
};  // namespace UnionTree

