struct UnionFind {
  vll rank, par, data;

  UnionFind(ll x = MAX) {
    rank.resize(x + 1, 0);
    par.resize(x + 1, 0);
    data.resize(x + 1, 1);
    rep(i, x + 1) par[i] = i;
  }

  ll root(ll x) {
    if (x != par[x]) par[x] = root(par[x]);
    return par[x];
  }

  ll size(ll x) {
    return data[root(x)];
  }

  void unite(ll a, ll b) {
    ll x = root(a);
    ll y = root(b);
    if (x == y) return;
    if (rank[x] > rank[y]) {
      par[y] = x;
      data[x] += data[y];
    }
    else {
      par[x] = y;
      data[y] += data[x];
      if (rank[x] == rank[y]) rank[y]++;
    }
  }

  bool same(ll a, ll b) {
    return root(a) == root(b);
  }
};



