	vector<int> p(N+1, 0);
	vector<int> grp(N+1, 0);
	vector<int> grp_depth(N+1, 0);
	for (int i=1; i<=N; i++) {
		grp.at(i)=i;
	}
	for (int i=0; i<M; i++) {
		int x=A.at(i).at(0);
		int y=A.at(i).at(1);
		x=get_g(x, grp);
		y=get_g(y, grp);
		if (x==y)
			continue;
		if (grp_depth.at(x)==grp_depth.at(y)) {
			grp.at(max(x, y))=get_g(min(x, y), grp);
			grp_depth.at(min(x, y))++;
		} else if (grp_depth.at(x)>grp_depth.at(y))
			grp.at(y)=x;
		else
			grp.at(x)=y;
		N--;
	}
	cout <<N <<endl;
	return 0;
}

