	UnionFind Uni(n + 1);
	rep(i, m) {
		x[i]--; y[i]--;
		Uni.connect(x[i], y[i]);
	}
	set<int> st;
	rep(i, n) {
		int a = Uni.root(i);
		st.insert(a);
	}
	dunk(st.size());
	return 0;
}

