class Problem {
 public:
  int N, M, x, y, z;
  vector<int> adj[100002];
  vector<int> visit;

  Problem() {
    scanf("%d%d", &N, &M);
    visit = vector<int>(N+10);
    for(int i = 0; i < M; i++) {
      scanf("%d%d%d", &x, &y, &z);
      adj[x].push_back(y);
    }
  }

  int dfs(int n) {
    if (visit[n]) return 0;
    visit[n] = 1;
    for(int d: adj[n])
      dfs(d);
    return 1;
  }

  void solve() {
    int ans = 0;
    for(int i = 1; i <= N; i++)
      ans += dfs(i);
    printf("%d", ans);
  }
};

int main() {
  Problem().solve();
}

