	vector<int> par, sze;

	void init(int N)
	{
		n = N;
		par.resize(n);
		sze.resize(n);
		for (int i = 0; i != n; ++i)
			par[i] = i, sze[i] = 1;
	}

	int find(int x)
	{
		if (par[x] == x) return x;
		return par[x] = find(par[x]);
	}

	void join(int x, int y)
	{
		x = find(x);
		y = find(y);

		if (x == y) return;

		if (sze[x] < sze[y]) swap(x, y);

		--n;
		par[y] = x;
		sze[x] += sze[y];
	}
};

int main()
{
	DSU unionfind;
	int n, m;
	scanf("%d %d", &n, &m);
	unionfind.init(n);
	for (int i = 0; i != m; ++i)
	{
		int x, y, z;
		scanf("%d %d %d", &x, &y, &z);
		unionfind.join(x - 1, y - 1);
	}
	cout << unionfind.n << endl;
	return 0;
}

