template<class Abel> struct UnionFind {
  vector<int> par;
  vector<int> rank;
  vector<Abel> diff_weight;

  UnionFind(int n = 1, Abel SUM_UNITY = 0) {
    init(n, SUM_UNITY);
  }

  void init(int n = 1, Abel SUM_UNITY = 0) {
    par.resize(n); rank.resize(n); diff_weight.resize(n);
    for (int i = 0; i < n; i++) {
      par[i] = i;
      rank[i] = 0;
      diff_weight[i] = SUM_UNITY;
    }
  }

  int root(int x) {
    if (par[x] == x) {
      return x;
    } else {
      int r = root(par[x]);
      diff_weight[x] += diff_weight[par[x]];
      return par[x] = r;
    }
  }

  int count_root() {
    set<int> parents;
    for (int i = 0; i < par.size(); i++) {
      parents.insert(par[i]);
    }
    return parents.size();
  }

  Abel weight(int x) {
    root(x);
    return diff_weight[x];
  }

  bool issame(int x, int y) {
    return root(x) == root(y);
  }

  // root(y) と root(x) を merge する
  // その際に weight(y) - weight(x) = w を満たすようにする.
  bool merge(int x, int y, int w) {
    w += weight(x); w -= weight(y);
    x = root(x); y = root(y);

    if (x == y) return false;
    if (rank[x] < rank[y]) swap(x, y), w = -w;
    par[y] = x;
    diff_weight[y] = w;
    return true;
  }

  Abel diff(int x, int y) {
    return weight(y) - weight(x);
  }
};

int main() {
  int N, M; cin >> N >> M;
  UnionFind<int> Tree(N, 0);

  for (int i = 0; i < M; i++) {
    int x, y, z; cin >> x >> y >> z;
    x--; y--;
    if (!Tree.issame(x, y)) {
      Tree.merge(x, y, z % 2);
    } else {
      if (Tree.diff(x, y) != (z % 2)) {
        assert(false);
      }
    }
  }

  int x = Tree.count_root();
  cout << x << endl;
}

