struct UF {
	vector<int> p;
	UF() = default;
	explicit UF(int n) : p(n + 1, -1) { p.back() = n; }
	bool unite(int x, int y) {
		x = find(x); y = find(y);
		if (x == y) return false;
		if (p[x] > p[y]) swap(x, y);
		p[x] += p[y];
		p[y] = x;
