    VI sizes;

public:
    UnionFind(int n) : par(n), sizes(n, 1) {
        REP(i, n) par[i] = i;
    }

    int root(int x) {
        if(par[x] == x) return x;
        else return par[x] = this->root(par[x]);
    }

    void unite(int x, int y) {
        x = root(x);
        y = root(y);

