struct DSU {
    vector<int> parent, set_size;
    set<int> roots;
    DSU(int n) {
        parent.resize(n);
        set_size.resize(n);
        iota(parent.begin(), parent.end(), 0);
        roots.insert(parent.begin(), parent.end());
        fill(set_size.begin(), set_size.end(), 1);
    }

    int root(int x) {
        vector<int> v;

        while (x != parent[x]) {
            v.emplace_back(x);
            x = parent[x];
        }

        for (int e : v)
            parent[e] = x;

        return x;
    }

    bool join(int a, int b) {
        a = root(a), b = root(b);
        if (a == b) return false;
        if (set_size[a] < set_size[b])
            swap(a, b);
        roots.erase(b);
        set_size[a] += set_size[b];
        parent[b] = a;
        return true;
    }

    bool check(int a, int b) {
        return root(a) == root(b);
    }
};

