struct UnionFind {
  vector< int > data;
 //全要素を-1で初期化
  UnionFind(int sz) {
    data.assign(sz, -1);
  }


  bool unite(int x, int y) {
    x = find(x), y = find(y);
    if(x == y) return (false);
    if(data[x] > data[y]) swap(x, y);
    data[x] += data[y]; //date[x] = -(rank)
    data[y] = x;
    return (true);
  }

  int find(int k) {
    if(data[k] < 0) return (k);
    return (data[k] = find(data[k]));
  }

  int size(int k) {
    return (-data[find(k)]);
  }
};

