//UnionFind 
struct UnionFind
{
    std::vector<ll> uni;
    ll num;
    UnionFind(ll s) : uni(s, -1),num(s) {}

    //頂点aが所属するグループ
    ll root(ll a)
    {
        if (uni[a] < 0)
        {
            return a;
        }
        return uni[a] = root(uni[a]);
    }

    //a,bをつなげる
    bool connect(ll a, ll b)
    {
        a = root(a);
        b = root(b);
        if (a == b)
        {
            return false;
        }

        if (uni[a] > uni[b])
        {
            std::swap(a, b);
        }

        uni[a] += uni[b];
        uni[b] = a;
        return true;
    }

    //a,bが同グループか確認
    bool isConnect(ll a, ll b)
    {
        return root(a) == root(b);
    }

    //aが属するグループの要素数
    ll size(ll a)
    {
        return -uni[root(a)];
    }

    //グループ数を返す
    ll groups(){
        std::set<ll> b;
        for(ll i=0;i<num;i++){
            b.insert(root(i));
        }
        return b.size();
    }
};

