template<int SZ> struct UF{
	int p[SZ+1],sz[SZ+1];
	UF(){I(SZ);}
	void I(int n){for(int i=0;i<=n;i++)	sz[p[i]=i]=1;}
	int F(int x){return x==p[x]?x:p[x]=F(p[x]);}
	bool U(int x,int y){
		x=F(x),y=F(y);
		if(x==y)	return false;
		if(sz[x]<sz[y])	swap(x,y);
		return p[y]=x,sz[x]+=sz[y],true;
	}
};
