using namespace std;

const int MAX_N = 100005;

/* UNION FIND木 */
int par[MAX_N]; //親
int ranks[MAX_N]; //子

// n要素で初期化
void init(int n){
  for(int i=0; i<n; i++){
    par[i] = i;
    ranks[i] = 0;
  }
}

// 木の根を求める
int find(int x){
  if(par[x] == x){
    return x;
  } else {
    return par[x] = find(par[x]);
  }
}

// xとyの属する集合を併合
void unite(int x, int y){
  x = find(x);
  y = find(y);
  if(x == y) {
    return;
  }
  if(ranks[x] < ranks[y]){
    par[x] = y;
  } else {
    par[y] = x;
    if(ranks[x] == ranks[y]){
      ranks[x]++;
    }
  }
}

// xとyが同じ集合に属するか否か
bool same(int x, int y){
  return find(x) == find(y);
}


