//O(ElogV)のdijkstra
long long INF=1000000000; // コストの影響のでない十分な値10^10;
struct edge {long long to,cost;};//操作始点sから各場所へのコスト表示法
int V;//頂点の数
vector <edge> G[2000010];//各頂点(0~V-1)からのびる辺
long long d[2000010];//sを始点とする最短経路

void dijkstra(int s){
    //小さい順に取り出せるpriority_queue
    priority_queue < P, vector<P>, greater<P> > que;
    fill(d,d+V,INF);
    d[s]=0;
    que.push(P(0,s));

    while(!que.empty()){
        P p=que.top(); que.pop();
        int v=p.second;
        if(d[v]<p.first) continue;//下を読まずに次へ。
        for(int i=0;i<G[v].size();i++){
            edge e=G[v][i];
            if(d[e.to]>d[v]+e.cost){
                d[e.to]=d[v]+e.cost;
                que.push(P(d[e.to],e.to));
            }
        }
    }
}

