struct UnionFind {
    vector<int> par,siz;

    UnionFind(int n) { init(++n); }

    void init(int n) {
        par.resize(n);
        siz.assign(n,1);
        for(int i = 0; i < n; ++i) par[i] = i;
    }

    int find(int x) {
        if(par[x] == x) return x;
        int r = find(par[x]);
        return par[x] = r;
    }

    int size(int x) { return siz[find(x)]; }

    bool is_same(int x, int y) { return find(x) == find(y); }

    bool unite(int x, int y) {
        x = find(x);
        y = find(y);
        if(x == y) return false;
        if(siz[x] < siz[y]) swap(x,y);
        siz[x] += siz[y];
        par[y] = x;
        return true;
    }
};


