using namespace std;

class Edge{
public:
    int from, to, cost;
};

vector < vector < Edge > > edge;
vector <bool> visited;

void dfs(int now){
	int l=edge[now].size();
    for(int i=0; i<l; i++){
        if(!visited[edge[now][i].to]){
            visited[edge[now][i].to]=true;
            dfs(edge[now][i].to);
        }
    }
}

int main(){
    int N, M;
    int from, to, cost;

    cin>>N>>M;
    edge.resize(N);
    for(int i=0; i<M; ++i){
        cin>>from>>to>>cost;
        edge[from-1].push_back((Edge){from-1, to-1, cost%2});
        edge[to-1].push_back((Edge){to-1, from-1, cost%2});
    }

    visited.resize(N);
    for(int i=0; i<N; ++i){
        visited[i]=false;
    }

    int ans=0;
    for(int i=0; i<N; ++i){
        if(visited[i] == false){
            visited[i]=true;
            dfs(i);
            ans++;
        }
    }
    cout<<ans<<endl;

    return 0;
}

