void init(int n) {
	rep(i, n) {
		par[i] = i;
		ranked[i] = 0;
		sizeth[i] = 1;
	}
}

int root(int x) {
	if (par[x] == x) return x;
	return par[x] = root(par[x]);
}

bool same(int x, int y) {
	return root(x) == root(y);
}

void unite(int x, int y) {
	x = root(x);
	y = root(y);
	if (x == y) return;
	if (ranked[x] < ranked[y]) {
		par[x] = y;
		sizeth[y] += sizeth[x];
	}
	else {
		par[y] = x;
		if (ranked[x] == ranked[y]) ranked[x]++;
		sizeth[x] += sizeth[y];
	}
}
