const int N = (int)1e5;

class UFDS {
    int n;
    int par[N+5];
    //
    int findPar(int a) {
        return par[a] = (par[a] == a ? a : findPar(par[a]));
    }
public:
    int reset(int _n){
        for (int i=0; i<_n+3; i++) {
            par[i] = i;
        }
        return n = _n;
    }
    int unionDS(int a, int b) {
        a = findPar(a);
        b = findPar(b);
        return par[a] = b;
    }
    int solve() {
        int res = 0;

        for (int i=1; i<=n; i++) {
            res += (par[i] == i);
        }

        return res;
    }
};

UFDS ds;

int main() {
