int par[100001], rnk[100001];

void un(int a, int b) {
    if (par[a] == par[b]) {
        return;
    }

    if (rnk[par[a]] >= rnk[par[b]]) {
        par[par[b]] = par[a];
        rnk[par[a]] = rnk[par[a]] == rnk[par[b]] ? rnk[par[a]] + 1 : rnk[par[a]];
    }

    else {
        par[par[a]] = par[b];
    }
}

int fnd(int a) {
    if (par[a] == a) {
        return a;
    }

    par[a] = fnd(par[a]);
    return par[a];
}

