      continue;
    }
    stack.push(j);
    while(!stack.empty()){
      int state=stack.top();
      seen[state]=true;
      stack.pop();
      for(int i:Graph[state]){
        if(seen[i]==true){
          continue;
        }
        seen[i]=true;
        stack.push(i);
      }
    }
