const int INF = 0x3f3f3f3f;
const LL INFL = 0x3f3f3f3f3f3f3f3fLL;
const double EPS = 1e-9;

const int DX[]={1,0,-1,0},DY[]={0,-1,0,1};

struct UnionFind {
    vector<LL> data;
    UnionFind(LL size) : data(size, -1) { }

    // xとyをmergeする
    bool unionSet(LL x, LL y) {
    x = root(x); y = root(y);
    if (x != y) {
        if (data[y] < data[x]) swap(x, y);
        data[x] += data[y]; data[y] = x;
    }
    return x != y;
    }

    // xとyが同一のグループかを判定する
    bool findSet(LL x, LL y) {
        return root(x) == root(y);
    }

    // xのrootノードの番号を返す
    LL root(LL x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }

    // xのノードが含まれる木のサイズを返す
    LL size(LL x) {
        return -data[root(x)];
    }

    // グループの数を返す O(N)
    LL tree_count() {
        LL cnt = 0;
        REP(i, data.size()) cnt += (root(i) == i);
        return cnt;
    }
};

void solve(long long N, long long M, std::vector<long long> X, std::vector<long long> Y, std::vector<long long> Z){
    UnionFind uf(N);
    REP(i, M) uf.unionSet(X[i], Y[i]);

    cout << uf.tree_count() << endl;
}

