#include <bits/stdc++.h>
using namespace std;
int getComp(vector<int>& comp,int i){
  int c = i;
  while(comp[c] != c) c = comp[c];
  comp[i] = c;
  return c;
}
void merge(vector<int>& comp,int a,int b){
  int ca = getComp(comp,a), cb = getComp(comp,b);
  if(ca != cb){
    comp[ca] = cb;
    comp[a] = cb;
  }
}
int main(){
  ios::sync_with_stdio(0);
  cin.tie(0);
  int n,m,x,y,z;
  cin >> n >> m;
  vector<int> comp(n+1);
  iota(begin(comp),end(comp),0);
  while(m--){
    cin >> x >> y >> z;
    merge(comp,x,y);
  }
  set<int> st;
  for(int i = 1; i <= n; ++i) st.insert(getComp(comp,i));
  cout << st.size();
  return 0;
}

