        int x, y, z; cin >> x >> y >> z;
        G[x].push_back(y);
        G[y].push_back(x);
    }

    queue<int> q;

    bool used[N+1];
    fill(used, used + N + 1, false);

    int count = 0;
    for (int i = 1; i <= N; i++){
        if (used[i]) continue;
        q.push(i);
        while(q.size()){
            int x = q.front(); q.pop();
            used[x] = true;
