    int x, y, z;
    int ans = N;
    rep (i, M)
    {
        cin >> x >> y >> z;
        if (z % 2 == 0)
        {
            if (!uf1.same(x, y))
            {
                --ans;
            }
            uf1.unite(x, y);
        }
        else
        {
            if (!uf2.same(uf1.findSet(x), uf1.findSet(y)))
            {
                --ans;
            }
            uf2.unite(uf1.findSet(x), uf1.findSet(y));
        }
    }

    cout << ans << "\n";
    return 0;
}

