struct UnionFind {
  vector<int> par; // 親ノード
  vector<int> rank; // ランク

  UnionFind(int n = 1) {
    init(n);
  }

  void init(int n = 1) {
    par.resize(n);
    rank.resize(n);
    for (int i = 0; i < n; i++) {
      par[i] = i;
      rank[i] = 0;
    }
  }

  int root(int x) {
    if (par[x] == x) {
      return x;
    } else {
      int r = root(par[x]);
      return par[x] = r;
    }
  }

  bool issame(int x, int y) {
    return root(x) == root(y);
  }

  bool merge(int x, int y) {
    x = root(x); y = root(y);
    if (x == y) return false;
    if (rank[x] < rank[y]) swap(x, y); // y is smaller, x is bigger
    if (rank[x] == rank[y]) rank[x]++;
    par[y] = x; // parent of y is x
    return true;
  }

};


signed main() {
  int N, M; cin >> N >> M;
  UnionFind Tree(N);

  for (int i = 0; i < M; i++) {
    int x, y, z; cin >> x >> y >> z;
    x--; y--;
    if (!Tree.issame(x, y)) {
      Tree.merge(x, y);
    } 
  }

  for (int i = 0; i < N; i++) {
    Parents.insert(Tree.root(i));
  }

  cout << Parents.size() <<  endl;
}

