// find checks whether both a and b belong to the same set. If not, it creates an edge between them.
int find (int x)
{
    if (x == ufd[x])
        {
            return x;        
        }
    return ufd[x] = find(ufd[x]);
}


void Union (int a, int b)
{
    ufd[find(a)] = find(b):
}

// Initially, all n elements are disjoint but as we get new inputs, we are able to create sets for them. if i != ufd[i], implies (i, ufd[i]) have an edge between them.

int main() 
{
    int n, m;
    scanf("%d%d", &n, &m);

    for (int i = 1; i <= n; i++)
        {
            ufd[i] = i;        
        }

    for (int i = 0; i < m; i++)
        {
            int x, y;
            scanf("%d%d%*d", &x, &y);

            // Perform disjoint set union of the two inputs
            Union(x, y);         
        }

    int ans = 0;
    for (int i = 1; i <= n; i++)
        {
            if (i == find(i))
                {
                    ++ans;
                }        
        }    
    printf("%d\n", ans);

