		rtnflg -= flg[i];
	return rtnflg;
}

vector<int> flgoperation(int select ,vector<int> X, vector<int> Y, vector<int> flg){
	for(int i = 0; i < N; i++){
		if(X[i] == select && flg[Y[i]-1] == 0){
			flg[Y[i]-1] = 1;
			flg = flgoperation(Y[i], X, Y, flg);
		}

		if(Y[i] == select && flg[X[i]-1] == 0){
			flg[X[i]-1] = 1;
			flg = flgoperation(X[i], X, Y, flg);
		}
	}
	//showflg(flg);
	return flg;
}

