class UnionFindTree{
private:
    vector<int> parent;
    vector<int> rank;
public:
    int n;
    UnionFindTree(int n);
    int root(int x);
    void unite(int x, int y);
    bool isSame(int x, int y);
};

UnionFindTree::UnionFindTree(int n_): parent(n_), rank(n_, 0){
    n = n_;
    // 初期化:すべてのノードの親を自分にする
    REP(i, n) parent[i] = i;
}

int UnionFindTree::root(int x){
    // 経路圧縮を行う
    if (parent[x] == x) return x;
    else return parent[x] = root(parent[x]);
}

void UnionFindTree::unite(int x, int y){
    // 木の結合:高さが低い木を高い木の下にぶら下げる
    int rx = root(x);
    int ry = root(y);
    if (rx == ry) return;
    else {
        if (rank[rx] < rank[ry]){
            parent[rx] = ry;
        }else{
            parent[ry] = rx;
            if (rank[rx] == rank[ry]) rank[rx]++;
        }
    }
}

bool UnionFindTree::isSame(int x, int y){
    return root(x) == root(y);
}

