// Union-Find
struct UnionFind {
    vector<int> par;
    vector<int> scale1;
    vector<int> rank;
    int size1;
    // par[i]はiの親の番号
    // scale[i]はiが親の時にのみ意味を持ち, その木の要素の数
    // rank[i]はiが親の時にのみ意味を持ち, その木のrank(union操作に使う)
    // 実はrankを導入してもほとんど速度変わらない
    // sizeは木の数
    // scaleとsizeはオプションなので必要なら消してもいい

    //最初は全てが根であるとして初期化
    UnionFind(int N) : par(N), scale1(N,1), rank(N,0){
        for(int i = 0; i < N; i++) par[i] = i;
        size1 = N;
    }

    // データxが属する木の根を再帰で得る
    int root(int x){
        if (par[x] == x) return x;
        par[x] = root(par[x]); // 親を根にする付け替えによって次回以降の参照を高速化
        return par[x];
    }

    // xとyの木を併合(rankの大きい方の根を小さい方の根の親にする)
    void unite(int x, int y){
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return;
        if(rank[rx] > rank[ry]){
            par[ry] = rx;
            scale1[rx] += scale1[ry];
        }else if(rank[rx] < rank[ry]){
            par[rx] = ry;
            scale1[ry] += scale1[rx];
        }else{
            // 同じならxを根に
            par[ry] = rx;
            scale1[rx] += scale1[ry];
            rank[rx]++;
        }
        size1--;
    }

    // 2つのデータx, yが属する木が同じならtrueを返す関数
    bool same(int x, int y){
        return root(x) == root(y);
    }

    // xの属する木の要素の数を返す関数
    int scale(int x){
        return scale1[root(x)];
    }

    // 木の数を返す関数
    int size(){
        return size1;
    }
};

int main() {
    int N,M;
    cin >> N >> M;
    vector<int>X(M);
    vector<int>Y(M);
    vector<int>Z(M);
    for (int i = 0; i < M; ++i) {
      cin >> X[i] >> Y[i] >> Z[i];
    }

    UnionFind tree(N);
    for(int i=0; i<M; i++){
        tree.unite(X[i]-1, Y[i]-1);
    }
    int ans = tree.size();
    cout << ans;
    return 0;
}

