struct union_find {
  int n, count;
  vector<int> par, rank, sz;
  union_find(int _n): n(_n), count(_n), par(_n), rank(_n), sz(_n) {
    iota(all(par), 0);
    fill(all(sz), 1);
  }
  int root(int x) {
    return par[x] == x ? x : par[x] = root(par[x]);
  }
  void merge(int x, int y) {
    x = root(x); y = root(y);
    if (x == y) return;
    if (rank[x] < rank[y]) swap(x, y);
    par[y] = x;
    if (rank[x] == rank[y]) rank[x]++;
    sz[x] += sz[y];
    count--;
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
  int size(int x) {
    return sz[root(x)];
  }
};

int main() {
  int n = IN, m = IN;
  union_find uf(n);
  rep(m) {
    int x = IN1, y = IN1, z = IN1;
    uf.merge(x, y);
  }
  OUT(uf.count);
}

#include<bits/stdc++.h>
using namespace std;

class UF {
    public:
        vector<int> p;
        UF(size_t n) : p(n) {
            for(size_t i=0; i<n; i++)
                p[i] = i;
        };
        int find(int x) {
            if(p[x] == x) return x;
            return p[x] = find(p[x]);
        };
        void unite(int x, int y) {
            x = find(x);
            y = find(y);
            p[x] = y;
        };
};

int main(void) {
    int n,m;
    cin >> n >> m;

    UF uf(n);
    for(int i=0; i<m; i++) {
        int x, y, z;
        cin >> x >> y >> z;
        x--, y--;
        uf.unite(x, y);
    }
    bitset<100000> bs;

    long res = 0;
    for(int i=0; i<n; i++) {
        res += bs[uf.find(i)] == 0;
        bs[uf.find(i)] = 1;
    }
    cout << res << endl;
}

