using namespace std;

class Graph {
public:
    const int N;
    std::vector<std::vector<int>> graph;
    Graph(int N) : N(N) {
        this->graph.resize(N);
    }

    void add_undirected_edge(const int u, const int v) {
        this->graph.at(u).emplace_back(v);
        this->graph.at(v).emplace_back(u);
    }

    void add_directed_edge(const int from, const int to) {
        this->graph.at(from).emplace_back(to);
    }
};


void dfs(int u, const int no, vector<int> &used, const Graph &graph) {
    used[u] = no;
    for (int v : graph.graph[u]) {
        if (used[v] == -1) {
            dfs(v, no, used, graph);
        }
    }
}

int num_connected(const Graph &graph) {
    vector<int> used(graph.N, -1);

    int no = 0;
    for (int u = 0; u < graph.N; ++u) {
        if (used[u] == -1) {
            dfs(u, no, used, graph);
            no++;
        }
    }

    return no;
}

