struct UnionFind {
    vector <int> par; 
    vector <int> siz; 
    UnionFind(int sz): par(sz), siz(sz, 1LL) {
        rep(i, sz) par[i] = i; 
    }
    int root(int x) { 
        while (par[x] != x) x = par[x] = par[par[x]]; 
        return x;
    }
    bool merge(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return false;
        if (siz[x] < siz[y]) swap(x, y);
        siz[x] += siz[y];
        par[y] = x;
        return true;
    }
    bool issame(int x, int y) { 
        return root(x) == root(y);
    }
    int size(int x) { 
        return siz[root(x)];
    }
};
