class UnionFind {
    private:
        int par[N_MAX];
        int rank[N_MAX];
    public:
        UnionFind(int n) {
            for(int i = 0;i < n;i++) {
                par[i] = i;
                rank[i] = 0;
            }
        }

        int root(int x) {
            return x == par[x] ? par[x] : par[x] = root(par[x]);
        }

        bool same(int x,int y) {
            return par[x] == par[y];
        }

        void merge(int x,int y) {
            x = root(x);
            y = root(y);
            if(par[x] == par[y])
                return;

            if(rank[x] < rank[y]) {
                par[x] = y;
            } else {
                par[y] = x;
                if(rank[x] == rank[y])
                    rank[y]++;
            }

            return;
        }

        int num_cls(int n) {
            map<int,bool> dic;

            for(int i = 0;i < n;i++) {
                dic[par[i]] = true;
            }

            return dic.size();
        }
};

