class UnionFind {
    private: 
        vector<int> par;
        vector<int> rank;
        vector<int> cnt;

    public:
        UnionFind(int n);
        int find(int x);
        void unite(int x, int y);
        bool same(int x, int y);
        int count(int x);
        void printStatus();
};

UnionFind::UnionFind(int n) {
    for (int i = 0; i < n; i++) {
        par.push_back(i);
        rank.push_back(0);
        cnt.push_back(1);
    }
}
int UnionFind::find(int x) {
    if (par[x] == x) return x;
    else return par[x] = find(par[x]);
}
void UnionFind::unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (rank[x] < rank[y]) {
        cnt[y] += cnt[x];
        par[x] = y;
    } else {
        cnt[x] += cnt[y];
        par[y] = x;
        if (rank[x] == rank[y]) rank[x]++;
    }
}
bool UnionFind::same(int x, int y) {
    return find(x) == find(y);
}
int UnionFind::count(int x) {
    return cnt[find(x)];
}

int main() {
    int N, M;
    cin >> N >> M;
    vector<int> X, Y, Z;
    bool isparent[N];
    UnionFind tree(N);
    for (int i = 0; i < N; i++) {
        isparent[i] = false;
    }
    int count = 0;
    for (int i = 0; i < M; i++) {
        int xt, yt, zt;
        scanf("%d %d %d", &xt, &yt, &zt);
        X.push_back(xt - 1);
        Y.push_back(yt - 1);
        Z.push_back(zt);
        if (zt % 2 == 0) {
            tree.unite(xt - 1, yt - 1);
        } else {
            count--;
        }
    }
    for (int i = 0; i < N; i++) {
        isparent[tree.find(i)] = true;
    }
    for (int i = 0; i < N; i++) {
        if (isparent[i]) count++;
    }
    cout << count - 1 << endl;
    return 0;
}

