static int count_graph(const std::vector< std::vector<int> > &edges, int n) {
    int c = 0;
    std::set<int> unvisited;
    for (int i = 0; i < n; i++) {
        unvisited.insert(i);
    }

    while (!unvisited.empty()) {
        int f = *unvisited.begin();
        unvisited.erase(f);
        std::deque<int> q;
        q.push_back(f);

        c++;

        while (!q.empty()) {
            int u = q.front();
            q.pop_front();

            for (std::vector<int>::const_iterator it = edges[u].begin(); it != edges[u].end(); ++it) {
                if (unvisited.count(*it) != 0) {
                    q.push_back(*it);
                    unvisited.erase(*it);
                }
            }
        }
    }

    return c;
}

