template <class T> class UnionFind {

  private:
    struct subset  {
      T parent;
      T rank;
      T diff_weight;
      T sizes;
    };
    std::vector<subset> subsets;

  public:
    UnionFind (T N) {
      subsets.reserve(N);
      for(T i=0; i<N; i++){
        subsets.push_back( { i, 0, 0, 1 } );
      }
    }

    T Find (T x) {
      if (subsets[x].parent == x) return x;
      subsets[x].diff_weight += subsets[subsets[x].parent].diff_weight;
      return subsets[x].parent = Find(subsets[x].parent);
    }

    T weight(T x) {
      Find(x);
      return subsets[x].diff_weight;
    }

    bool Same (T x, T y) {
        return Find(x) == Find(y);
    }

    bool Union (T x, T y, T w) {
      w += weight(x); w -= weight(y);

      T xroot = Find(x);
      T yroot = Find(y);
      if ( xroot == yroot ) return false;

      if (subsets[xroot].rank < subsets[yroot].rank) {
        subsets[xroot].parent = yroot;
        w = -w;
        subsets[yroot].sizes += subsets[xroot].sizes;
      }
      else if (subsets[xroot].rank > subsets[yroot].rank) {
        subsets[yroot].parent = xroot;
        subsets[xroot].sizes += subsets[yroot].sizes;
      }
      else {
        subsets[yroot].parent = xroot;
        subsets[xroot].rank++;
        subsets[xroot].sizes += subsets[yroot].sizes;
      }
      subsets[yroot].diff_weight = w;
      return true;
    }

    T diff(T x, T y) {
      return weight(y) - weight(x);
    }

    T size (T x) {
      return subsets[Find(x)].sizes;
    }
};


int main (void) {

  int N, M;
  std::cin >> N >> M;

  UnionFind<int> uf(N);

  for(int i=0; i<M; i++){
    int x, y, z;
    std::cin >> x >> y >> z;
    uf.Union(x-1, y-1, 0.);
  }

  std::set<int> s;
  for(int i=0; i<N; i++) s.insert(uf.Find(i));
  std::cout << s.size() << std::endl;

  return 0;
}

