    ll cost = 0;

    // shift
    for(int i=0; i < M; i++){
        X.at(i)--;
        Y.at(i)--;
    }

    // 下準備
    // derivesをつくる
    for(int i=0; i < M; i++){
        derives.at(X.at(i)).push_back(Y.at(i));
        derives.at(Y.at(i)).push_back(X.at(i));
        covered.at(X.at(i))++;
        covered.at(Y.at(i))++;
