  }

  bool unite(long x, long y) {
    x = find(x), y = find(y);
    if(x == y) return (false);
    if(data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return (true);
  }

  long find(long k) {
    if(data[k] < 0) return (k);
    return (data[k] = find(data[k]));
  }

  long size(long k) {
    return (-data[find(k)]);
  }
};

