using namespace std;

#define MAX_N 100000

class union_find
{
private:
    int par[MAX_N];
    int tree_rank[MAX_N];
    int set_num;
public:
    union_find(int n); // const
    int find(int x);
    void unite(int x, int y);
    bool same(int x, int y);
    int get_number_of_cluster();
    int* get_par();
    int* get_tree_rank();
};

union_find::union_find(int n){
    set_num = n;
    for (int i = 0 ; i < n ; i++){
        par[i] = i;
        tree_rank[i] = 0;
    }
}

int union_find::find(int x){
    if (par[x] == x){
        return x;
    }else{
        return par[x] = find(par[x]);
    }
}

void union_find::unite(int x, int y){
    x = find(x);
    y = find(y);
    if (x==y) return;

    if(tree_rank[x] < tree_rank[y]){
        par[x] = y;
    }else{
        par[y] = x;
        if (tree_rank[x] == tree_rank[y]) tree_rank[x] ++;
    }
}

bool union_find::same(int x, int y){
    return find(x) == find(y);
}

int union_find::get_number_of_cluster(){
    int *memo = (int*)malloc(set_num * sizeof(int));
    memset(memo, 0, set_num * sizeof(int));
    int ret = 0;
    for (int i = 0; i < set_num; i++){
        if (memo[par[i]] == 0){
            ret++;
            memo[par[i]] = 1;
        }
    }
    free(memo);
    return ret;
}

int* union_find::get_par(){
    return par;
}

int* union_find::get_tree_rank(){
    return tree_rank;
}

int main(){
    int N,M, x,y,z;
    scanf("%d %d", &N, &M);
    union_find number_set(N);
    for (int i=0; i<M; i++){
        scanf("%d %d %d", &x, &y, &z);
        number_set.unite(x-1, y-1);
    }
    printf("%d\r\n", number_set.get_number_of_cluster());
}

