using namespace std;

void dfs(vector<int> *aList, vector<bool> visit, int node) {
  stack<int> s;
  s.push(node);
  visit[node] = true;

  while (!s.empty()) {
    int current = s.top();
    s.pop();
    for (const auto &e : aList[current])
      if (!visit[e]) {
        s.push(e);
        visit[e] = true;
      }
  }
}

int visitHasFalse(vector<bool> visit) {
  int ret = -1;
  for (const auto &e : visit)
    if (!e) {
      ret = e;
      break;
    }

  return ret;
}

int nomOfConnected(vector<int> *aList, vector<bool> visit) {
  int counter = 0;
  int n;
  while ((n = visitHasFalse(visit) != -1)) {
    counter++;
    dfs(aList, visit, n);
  }

  return counter;
}

