    int x, y, z;
    cin >> x >> y >> z;
    x--;
    y--;
    aList[x].push_back(y);
    aList[y].push_back(x);
  }

  int ans = nomOfConnected(aList, visit);
  cout << ans << endl;

  delete[] aList;
  return 0;
}

