struct UnionFind{
    std::vector<int> data;
    UnionFind(int size):data(size,-1){}
    bool unite(int x,int y) {
        x=root(x);y=root(y);
        if(x!=y){
            if(data[y]<data[x])std::swap(x,y);
            data[x]+=data[y];data[y]=x;
        }
        return x!=y;
    }
    bool find(int x,int y) {
        return root(x)==root(y);
    }
    int root(int x) {
        return data[x]<0?x:data[x]=root(data[x]);
    }
    int size(int x) {
        return -data[root(x)];
    }
    // added by QCFium
    bool united() {
        int comroot = -1;
        FOR(i,data.size()) {
            if (comroot != -1 && root(i) != comroot) return false;
            comroot = root(i);
        }
        return true;
    }
};


int main() {
	int n = ri();
	int m = ri();
	UnionFind uni(n);
	FOR(i,m) {
		int a = ri() - 1;
		int b = ri() - 1;
		ri();
		uni.unite(a, b);
	}
	std::set<int> res;
	FOR(i,n) res.insert(uni.root(i));
	std::cout << res.size() << std::endl;

	return 0;
}

