struct Forest_Uni{
private:
	vector<int> arr;
	int numTrees;
public:
	Forest_Uni():numTrees(0){}
	int add(){
		int p = arr.size();
		arr.push_back(p);
		numTrees++;
		return p;
	}
	int root(int tg){
		int buf = tg;
		while(buf != arr[buf]){
			buf = arr[buf];
		}
		arr[tg] = buf;
		return buf;
	}
	void unite(int a, int b){
		if(root(a) == root(b)) return;
		arr[root(a)] = root(b);
		numTrees--;
	}
	bool same(int a, int b){
		return root(a) == root(b);
	}
	int nTrees(){ return numTrees; }
};



int main(){

	int n, m;
	cin >> n >> m;
	Forest_Uni g;

	for(int i = 0; i< n; i++){
		g.add();
	}

	int x, y, z;
	for(int i = 0; i < m; i++){
		cin >> x >> y >> z;
		g.unite(x-1, y-1);
	}

	cout << g.nTrees() << endl;

	return 0;
}

