using namespace std;

class UnionFind {
public:
    int set_size;       // 集合の個数
private:
    vector<int> parent;	// 親の番号(親だった場合は-(その集合のサイズ))

public:
    UnionFind(int size) : parent(size, -1), set_size(size) {}

    // xとyが同じ集合に属するか
    bool is_same_set(int x, int y) {
        return find_root(x) == find_root(y);
    }

    // xとyの属する集合を併合
    void union_set(int x, int y) {
        x = find_root(x);
        y = find_root(y);
        if (x == y) {
            return;
        }
        if (parent[x] > parent[y]) {
            swap(x, y);
        }

		// 小さい方(x)に大きい方(y)をくっつける
		// 両方ともrootなので-(集合のサイズ)が入っている
        parent[x] += parent[y];
        // yの親をxにする
        parent[y] = x;
        set_size--;
    }

    // xの属する集合の要素数
    int size(int x) {
        return (-parent[find_root(x)]);
    }

    // 木の根を求める
    int find_root(int x) {
        if (parent[x] < 0) {
            return x;
        }
        else {
            return parent[x] = find_root(parent[x]);
        }
    }
};


LL count(vector<tuple<int, int, int>> &g, int N) {
    LL ans = 0;
    auto find = make_v<bool>(N);
    FOE(t, g) {
        int X, Y, Z;
        tie(X, Y, Z) = t;

        int num = 3;
        if (X == Z or Y == Z) {
            num--;
        }

        int kaku = find[X] + find[Y] + find[Z];
        if (kaku == 0) {
            if (num == 3) {
                ans += 2;
            }
            else if (num == 2) {
                ans += 1;
            }
        }
        else if (kaku == 1) {
            if (num == 3) {
                ans += 1;
            }
        }
        find[X] = true;
        find[Y] = true;
        find[Z] = true;
    }

    return ans;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N, M;
    cin >> N >> M;

