    auto v = make_v<tuple<int, int, int>>(M);
    FOR(i, 0, M) {
        int X, Y, Z;
        cin >> X >> Y >> Z;
        X--; Y--; Z--;
        v[i] = make_tuple(X, Y, Z);
        uf.union_set(X, Y);
        uf.union_set(X, Z);
    }


    unordered_map<int, vector<tuple<int, int, int>>> group;
    FOE(t, v) {
        int X, Y, Z;
        tie(X, Y, Z) = t;
        group[uf.find_root(X)].emplace_back(t);
    }

    LL ans = 0;
    FOE(p, group) {
        ans += count(p.second, N);
    }

    FOR(i, 0, N) {
        if (uf.size(i) == 1) {
            ans++;
        }
    }
    print(ans);

    return 0;
}

