struct UF{
    int par[MAX_N];
    int sizes[MAX_N];
    void init (int n){
        for (int i=0;i<n;i++){
            par[i]=i;
            sizes[i]=1;
        }
    }
    int find (int x){
        if (par[x]==x){
            return x;
        }
        else{
            return par[x] = find(par[x]);
