const int mxN = 1e5 + 7;
bool visited[mxN];
vector<int> adj[mxN];

void dfs(int i){
	if(!visited[i]){
		visited[i] = 1;
		for(int neigh : adj[i]) dfs(neigh);
	}
}

void solve(){
	int n,m; cin >> n >> m;
	map<int,int> mp;
	FOR(m){
		int x,y,z; cin >> x >> y >> z;
		--x,--y;
		++mp[x];
		++mp[y];
		adj[x].pb(y);
		adj[y].pb(x);
	}
	set<pair<int,int>> s;
	FOR(n){
		s.insert({mp[i],i});
	}
	auto itr = s.end();
	int ans = 0;
	while(itr != s.begin()){
		--itr;
		if(!visited[(*itr).second]){
			++ans;
			dfs((*itr).second);
		}
	}
	cout << ans;
}

