using namespace std;

struct cond
{
	int xi;
	int yi;
	int zi;
	bool solve;
};
int main(int argc, char const *argv[])
{
	int n,m,x,y,z;
	while(~scanf("%d %d",&n,&m)){
		vector<cond> v;
		int times[n+1],ans_cnt=0,cost=0;
		bool ans[n+1];
		for (int i = 0; i < n+1; ++i)
		{
			times[i]=0;
		}
		for (int i = 0; i < m; ++i)
		{
			cond te;
			scanf("%d %d %d",&te.xi,&te.yi,&te.zi);
			te.solve=false;
			v.push_back(te);
			times[te.xi]++,times[te.yi]++;
		}

		for (int i = 1; i < n+1; ++i)
			{
				//printf("times=%d\n",times[i]);
				if (times[i]==0)
				{
					cost++;
				}
			}

		while(ans_cnt<n){
			int maxn=0,pos=-1;
			for (int i = 1; i < n+1; ++i)
			{
				//printf("times=%d\n",times[i]);
				if (times[i]>0)
				{
					if (maxn<times[i])
					{
						pos=i;
						maxn=times[i];
					}
				}
			}
			if (maxn==0||pos==-1)
			{
				break;
			}
			ans[pos]=true;
			times[pos]=0;
			int vs= v.size();
			for (int i = 0; i < vs; ++i)
			{
				if (v[i].solve==false)
				{
					if (v[i].xi==pos)
					{
						v[i].solve=true;
						if (ans [ v[i].yi ]==false)
						{
							ans [ v[i].yi ]=true;
							times[ v[i].yi ]=-1;
							ans_cnt++;
						}

					}
					if (v[i].yi==pos)
					{
						v[i].solve=true;
						if (ans [ v[i].xi ]==false)
						{
							ans [ v[i].xi ]=true;
							times[ v[i].xi ]=-1;
							ans_cnt++;
						}
					}
				}

			}
			ans_cnt++;
			cost++;
			//printf("ans_cnt==%d\n",ans_cnt);
			if (ans_cnt==n)
			{
				break;
			}
		}
		printf("%d\n",cost );
	}
	return 0;
}

