int main (void) {
  int N, M;
  cin >> N >> M;
  // A[i]がわかったとき，かつそのときに限りA[j]がわかる
  vector<vector<int>> graph(N, vector<int>());
  vector<bool> known(N, false);
  for (int i = 0; i < M; i++) {
    int x, y, z;
    cin >> x >> y >> z;
    x--; y--;
    graph[x].push_back(y);
    graph[y].push_back(x);
  }
  // transitive closureを求める
  for (int u = 0; u < N; u++) {
    stack<int> st;
    vector<bool> visited(N, false);
    while (!st.empty()) {
      const int v = st.top(); st.pop();
      for (const auto w : graph[v]) {
        if (!visited[w]) {
          visited[w] = true;
          graph[u].push_back(w);
        }
      }
    }
  }
  // 魔法を使うといっぱいわかるところを先に塗っていく
  vector<int> indices(N);
  iota(indices.begin(), indices.end(), 0);
  sort(indices.begin(), indices.end(),
      [&](int a, int b) {
        return graph[b].size() < graph[a].size();
      });
  for (const auto u : indices) {
    for (const auto v : graph[u]) {
      if (v < u) continue;
      known[v] = true;
    }
  }
  int ans = 0;
  for (const auto b : known) {
    if (!b) ans++;
  }
  cout << ans << endl;
  return 0;
}

