    int N,M,res = 0;
    cin>>N>>M;
    Graph G(N);//0-ind
    vector<int> X(M),Y(M),Z(M);
    rep(i,M){
        cin>>X[i]>>Y[i]>>Z[i];
        G[X[i]-1].push_back(Y[i]-1);
        G[Y[i]-1].push_back(X[i]-1);
    }
    vector<int> dist(N,-1);
    rep(i,N){
        if(dist[i]!=-1)continue;
        res++;
        queue<int> Q;
        Q.push(i);
        dist[i] = 0;
        while(!Q.empty()){
            int v = Q.front(); Q.pop();
            for(auto nv: G[v]){
                if(dist[nv]!=-1)continue;
                dist[nv] = dist[v] + 1;
                Q.push(nv);
            }
        }
    }
    cout<<res<<endl;
}

