    cin >> x >> y >> z;
    x--, y--;
    uf.unite(x, y);
  }
  int cnt = 0;
  for (int i = 0; i < n; ++i)
  {
    if (uf.data[i] < 0)
      cnt++;
  }
  cout << cnt << endl;

  return 0;
}

