const int INF = 1e9;
const int MOD = 1e9+7;
const ll LINF = 1e18;

class UnionFind{
  public:
  // 親の番号を格納する．親の場合は-(その集合のサイズ)
  vector<int> Parent; 

  // 全て-1
  UnionFind(int N){
    Parent = vector<int>(N, -1);
  }

  // Aがどのグループに属しているか
  int root(int A){
    if(Parent[A] < 0) return A;
    return Parent[A] = root(Parent[A]); // return前に自分の親を更新することで高速化
  }

  // 自分のいるグループの頂点数を調べる
  int size(int A){
    return -Parent[root(A)]; 
  }

  // AとBをくっつける
  bool connect(int A, int B){
    // AとBを直接つなぐのではなく、root(A)にroot(B)をくっつける
    A = root(A);
    B = root(B);
    if(A == B){
      // すでにくっついているからくっつけない
      return false;
    }

    // グループのサイズが大きい方(A)に小さい方(B)をくっつけたい
    // 大小が逆ならひっくり返す
    if(size(A) < size(B)) swap(A, B);

    // Aのサイズを更新する
    Parent[A] += Parent[B];
    // Bの親をAに変更する
    Parent[B] = A;

    return true;
  }
};

signed main()
{
  cin.tie( 0 ); ios::sync_with_stdio( false );
  int n,m; cin>>n>>m;
  vi X(m), Y(m), Z(m);
  rep(i,m) {
    cin>>X[i]>>Y[i]>>Z[i];
    X[i]--; Y[i]--; Z[i]--;
  }
  auto uf = UnionFind(n);
  rep(i,m){
    uf.connect(X[i],Y[i]);
  }
  map<int, int> ma;
  int ans=0;
  rep(i,n){
    int p=uf.root(i);
    if(ma[p]==0){
      ma[p]++;
      ans++;
    }
  }
  cout<<ans<<endl;
  return 0;
}

