    UnionFind uf(N);
    for( int i = 0; i < M; ++i ){
        int X, Y, Z;
        cin >> X >> Y >> Z;
        --X, --Y;
        uf.unite(X, Y);
    }
    cout << uf.size() << endl;

    return 0;
}

