class UnionFind {
public:
    std::vector<int> par, num;

    int find(int v) {
        return (par[v] == v) ? v : (par[v] = find(par[v]));
    }

    explicit UnionFind(int N) : par(N), num(N, 1) {
        std::iota(par.begin(), par.end(), 0);
    }

    void unite(int u, int v) {
        u = find(u), v = find(v);
        if (u == v) return;

        if (num[u] < num[v]) std::swap(u, v);
        num[u] += num[v];
        par[v] = u;
    }

    bool same(int u, int v) { return find(u) == find(v); }
    bool ispar(int v) { return v == find(v); }
    int size(int v) { return num[find(v)]; }
};

using namespace std;

int main() {
    int N, M;
    cin >> N >> M;

    // 情報に基づいて頂点を繋ぐ
    UnionFind uf(N);
    for (int i = 0; i < M; ++i) {
        int u, v, z;
        cin >> u >> v >> z;
        --u, --v;
        uf.unite(u, v);
    }

    // 親の値の集合を取れば、その大きさが連結成分の数になる
    set<int> par;
    for (int v = 0; v < N; ++v) {
        par.insert(uf.find(v));
    }
    cout << par.size() << endl;
    return 0;
}

