int find(int x) {
  if (parent[x] == x) return x;
  return parent[x] = find(parent[x]);
}
void unite(int x, int y) {
  x = find(x);
  y = find(y);
  if (x == y) return;

  if (rnk[x] < rnk[y]) {
    parent[x] = y;
  } else {
    parent[y] = x;
    if (rnk[x] == rnk[y]) rnk[x]++;
  }
}
