Node* makeSet(lli data){
    Node* node = new Node();
    node->data = data;
    node->parent = node;
    node->rank = 1;
    node->inSubset = false;
    m[data] =node;
    return node;
}
Node* findSet(Node* node){
    if(node->parent == node)return node;
    node->parent = findSet(node->parent);
}
