    ran.resize(n, 0);
    m_size.resize(n, 1);
    rep(i,n) par[i] = i;
};

ll union_find::find(ll x) {
    if (par[x] == x) return x;
    else return par[x] = find(par[x]);
};

void union_find::unite(ll x, ll y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    ll t = size(x)+size(y);
    m_size[x] = m_size[y] = t;
    if (ran[x] < ran[y]) {
        par[x] = y;
        //size[y] += size[x];
    } else {
        par[y] = x;
        //ize[x] += size[y];
        if (ran[x]==ran[y]) ran[x]++;
    }
};

ll union_find::size(ll x) {
    if (par[x] == x) return m_size[x];
    return size(par[x] = find(par[x]));
}

bool union_find::same(ll x, ll y) {
    return (find(x) == find(y));
};

int main(int argc, char const *argv[]) {
    int n,m; cin>>n>>m;
    vector<T> a;
    a.reserve(n);
    union_find uf(n);
    rep(i,m) {
        int x,y,z; cin>>x>>y>>z;
        z %= 2;
        uf.unite(x-1,y-1);
        a.emplace_back(x,y,z);
    }
    set<int> ans;
    rep(i,n) ans.insert(uf.find(i));
    cout << ans.size() << '\n';
    return 0;
}

