// 隣接リストを用いた幅優先探索 O(|V|+|E|)
int n;
vector<int> G[100000], d(100000, 100000000); // 始点sから頂点iまでの最短距離をd[i]に記録
/*
* main関数からこれらを削除すること
* 隣接リストGの頂点数と最短距離dの要素数はnの最大値を整数で入力すること
*/

void bfs(int s) {
  queue<int> q;
  q.push(s);
  d[s] = 0;
  while(!q.empty()){
    int u = q.front();
    q.pop();
    for(int v = 0; v < G[u].size(); v++){
    if(d[G[u][v]] == 100000000){
        d[G[u][v]] = d[u] + 1;
        q.push(G[u][v]);
      }
    }
  }
}

