        exists.insert(X[i]);
        exists.insert(Y[i]);
    }
    set<ll> st;
    rep(i, M) {
        st.insert(uf.root(i));
    }

    ll not_exists = N - exists.size();

    cout << st.size() + not_exists << endl;
}

