struct UnionFind{
    vl p;
    vl rank;
    ll cnt;

    UnionFind(ll n){
        rank.resize(n,0);
        p.resize(n,0);
        rep(i,n){
            p[i] = i;
            rank[i] = 0;
        }
        cnt = n;
    }

    int find(int x){
        if(x != p[x]) p[x] = find(p[x]);
        return p[x];
    }

    void unite(ll x, ll y){
        x = find(x);
        y = find(y);
        if(x == y) return;
        cnt--;
        if(rank[x] > rank[y]){
            p[y] = x; 
        }else{
            p[x] = y;
            if(rank[x] == rank[y]) rank[y]++;
        }
    }

    ll getcnt(){
        return cnt;
    }
};

