struct UnionFind
{
    vector<int> par, rank;
    vector<int> last;

    UnionFind(int n){
        par.resize(n);
        rank.resize(n);
        for(int i = 0; i < n; i++){
            par[i] = i;
            rank[i] = 0;
        }
    }

    int find(int i){
        if(i == par[i]) return i;
        return find(par[i]);
    }

    bool same(int i, int j){
        return find(i) == find(j);
    }

    void unite(int i, int j){
        i = find(i), j = find(j);
        if(i == j) return;
        if(rank[i] < rank[j]){
            par[i] = j;
            last.push_back(i);
        }
        else{
            par[j] = i;
            if(rank[i] == rank[j]) rank[i]++;
            last.push_back(j);
        }
    }

    void undo(){
        if((int)last.size() == 0) return;
        int i = *(--last.end());
        par[i] = i;
        last.pop_back();
    }
};

