  int n, m;
  scanf("%d%d", &n, &m);
  UF uf(n);
  REP(i, m) {
    int a, b, z;
    scanf("%d%d%d", &a, &b, &z);
    --a;
    --b;
    uf.unify(a, b);
  }
  printf("%d\n", uf.size());
  return 0;
}

