struct UnionFind {
  vector<int> par;

  UnionFind(int n){ par.resize(n+1, -1); }
  void init(int n){ par.assign(n+1, -1); }

  int root(int x){
    if(par[x] < 0) return x;
    else return (par[x] = root(par[x]));  //根ノードを記録
  }

  bool is_same(int x, int y){
    return (root(x) == root(y));
  }

  bool merge(int x, int y){
    x = root(x); y = root(y);  //xとyの根を取得
    if(x == y) return false;  //結合の必要なし
    if(par[x] < par[y]) swap(x, y);   //基本的にはxの方を大きい木とする
    par[x] += par[y]; //サイズの合計(結合するので)
    par[y] = x; //par[y]はxを根とするようになる
    return true;
  }

  int size(int x){
    return -par[root(x)]; //サイズは負の値で記録されているので...
  }

};


