class UnionFind{
public:

    vector<int> parent;
    vector<int> sizev;
    vector<int> rankv;

    UnionFind();

    UnionFind(int n){
        rep(i,n + 1){
            parent.pback(i);
            sizev.pback(1);
            rankv.pback(1);
        }
    }

    int find(int n){

        vector<int> updatev;

        while(n != parent[n]){
            updatev.pback(n);
            n = parent[n];
        }

        rep(i, updatev.size()){
            parent[updatev[i]] = n;
        }

        return n;

    }

    int size(int n){
        return sizev[find(n)];
    }

    void merge(int a, int b){

        a = find(a);
        b = find(b);

        if(rankv[a] < rankv[b]){
            parent[a] = b;
            sizev[a] = sizev[a] + sizev[b];
        }else{
            parent[b] = a;
            sizev[b] = sizev[b] + sizev[a];

            if(rankv[a] == rankv[b]){
                rankv[a]++;
            }
        }
    }

};

