class UnionFind {
public:
    UnionFind(int size) : data_(size, -1) {
    }
    virtual ~UnionFind() {
    }
    bool unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x != y) {
            if (data_[x] > data_[y]) {
                // 少ない方を下に
                std::swap(x,y);
            }
            data_[x] += data_[y];
            data_[y] = x;
        }
        return x != y;
    }
    // x, yが同じ集合なら1
    bool find(int x, int y) {
        return root(x) == root(y);
    }
    // xの根を探す。同じ集合なら同じ根が帰る
    int root(int x) {
        if (data_[x] < 0) {
            return x;
        } else {
            return data_[x] = root(data_[x]);
        }
    }
    // xが含まれる集合の大きさを返す
    int size(int x) {
        return -data_[root(x)];
    }
    // 分離されている集合の数を返す
    int setNum(void) {
    }
    // O(n)
    // 集合ごとに全部の要素を出力
    void print(void) {
        std::map<int, std::set<int>> c;
        for (int i = 0; i < data_.size(); i++) {
            c[root(i)].insert(i);
        }

        for (auto& x : c) {
            std::cout << x.first << ": ";
            for (auto& y : x.second) 
                std::cout << y << " ";
            std::cout << std::endl;
        }
    }
    ll value(void) {
        std::map<int, int> c;
        for (int i = 0; i < data_.size(); i++) {
            c[root(i)] += 1;
        }
        return c.size();
    }
protected:
    std::vector<int> data_;
};

