#include<bits/stdc++.h>
using namespace std;
#define endl "\n"

class dsu{
	vector<int> parent,rnk;
	int component;
	public:
	void init(int n){
		parent.assign(n + 1,-1);
		rnk.assign(n + 1,0);
		component = n;
	}

	void make_set(int x){
		parent[x] = x;
	}

	int find_set(int x){
		if(x != parent[x]){
			return (parent[x] = find_set(parent[x]));
		}
		return parent[x];
	}

	void unite(int x,int y){
		int a = find_set(x);
		int b = find_set(y);
		if(a != b){
			component--;
			if(rnk[a] < rnk[b]){
				parent[a] = b;
				rnk[b]++;
			}
			else{
				parent[b] = a;
				rnk[a]++;
			}
		}
	}

	int getRank(int i){
		return rnk[i];
	}

	int getComp(){
		return component;
	}
};

dsu md;

