class Union_Find_size{
public:
	vector<int> Parent;

	//コンストラクタ
	Union_Find_size(int N){
		Parent=vector<int>(N,-1);
	}

	//木の根を求める
	int root(int x){
		//x（自分）が親ならxを返す
		if(Parent.at(x)<0)	return x;
		//経路圧縮しながら return する
		return Parent.at(x)=root(Parent.at(x));
	}

	//xの属する木の要素数を調べる
	int size(int x){
		return -Parent.at(root(x));
	}

	//xとyが同じ集合に属するかを判定する
	bool same(int x,int y){
		return root(x)==root(y);
	}

	//xとyの属する集合を併合する
	void unite(int x,int y){
		x=root(x);
		y=root(y);
		if(x==y)	return;

		if(size(x)<size(y))	swap(x,y);
		Parent.at(x)+=Parent.at(y);
		Parent.at(y)=x;
	}
};

int main(){
	int N,M;
	cin >> N >> M;
	vector<int> X(M),Y(M),Z(M);
	for(int i=0;i<M;i++){
		cin >> X.at(i) >> Y.at(i) >> Z.at(i);
		X.at(i)--;
		Y.at(i)--;
	}

	Union_Find_size Uni(N);
	for(int i=0;i<M;i++){
		if(!Uni.same(X.at(i),Y.at(i))){
			Uni.unite(X.at(i),Y.at(i));
		}
	}

	int ans=0;
	for(int i=0;i<N;i++){
		if(Uni.Parent.at(i)<0)	ans++;
	}
	cout << ans << endl;

	return 0;
}

