struct DJSet {
  int n;
  std::vector<int> upper;

  DJSet(int n) : upper(n, -1){}

  int root(int x) {
    return upper[x] < 0 ? x : (upper[x] = root(upper[x]));
  }

  bool equiv(int x, int y){
    return root(x) == root(y);
  }

  void setUnion(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) return;
    if (upper[x] < upper[y]){
      x ^= y;
      y ^= x;
      x ^= y;
    }
    upper[y] += upper[x];
    upper[x] = y;
  }

};

int main() {
  int N, M;
  std::cin >> N >> M;
  std::vector<int> X(M), Y(M), Z(M);
  std::vector<int> exist(N, 0);
  DJSet ds(N);
  for (int i = 0; i < M; ++i) {
    std::cin >> X[i] >> Y[i] >> Z[i];
    Z[i] %= 2;
    --X[i];
    --Y[i];
    ds.setUnion(X[i], Y[i]);
    exist[X[i]] = 1;
    exist[Y[i]] = 1;
  }
  int ans = 0;
  for (int i = 0; i < M; ++i) {
    if (exist[ds.root(X[i])] != 1) continue;
    ++ans;
    exist[ds.root(X[i])] = 2;
  }
  for (int i = 0; i < N; ++i) {
    if (exist[i] == 0)  ++ans;
  }

  std::cout << ans << std::endl;

  return 0;
}

