class UnionFind
{
public:
	UnionFind(int sz)
	{
		data.assign(sz, -1);
	}

	bool same(int x, int y)
	{
		x = find(x);
		y = find(y);

		return x != y;
	}

	bool unite(int x, int y)
	{
		x = find(x);
		y = find(y);

		if (x == y) return false;
		if (data[x] > data[y]) swap(x, y);
		data[x] += data[y];
		data[y] = x;

		return true;
	}

	vector <int> allParents()
	{
		vector <int> ret(SZ(data));

		for (int i = 0; i < SZ(data); ++i)
		{
			ret[i] = find(i);
		}

		return ret;
	}

	map <int, vector <int> > allUnions()
	{
		vector <int> parents = allParents();

		map <int, vector <int> > ret;
		for (int i = 0; i < SZ(data); ++i)
		{
			ret[parents[i]].push_back(i);
		}

		return ret;
	}

	int size(int k)
	{
		return(-data[find(k)]);
	}

private:

	int find(int k)
	{
		if (data[k] < 0) return(k);
		return(data[k] = find(data[k]));
	}

	// データが負のときは、所属集合のサイズ
	// データが0か正のときは、所属集合の代表ノード
	vector< int > data;

};

