struct DSU {
	vector<int> s, p;
	DSU(int n) {
		s.resize(n);
		p.resize(n);
		for (int i = 0; i < n; i++) {
			s[i] = 1;
			p[i] = i;
		}
	}

	int find(int x) {
		if (x == p[x]) return x;
		return p[x] = find(p[x]);
	}

	bool unite(int a, int b) {
		a = find(a);
		b = find(b);

		if (a == b) return false;
		if (s[a] < s[b]) swap(a, b);

		s[a] += s[b];
		p[b] = a;
		return true;
	}
};

void solve() {
	int n, m;
	cin >> n >> m;
	DSU dsu(n);
	int ans = n;
	for (int i = 0; i < m; i++) {
