long long Find(vector<long long> &f, long long n)
{
	if (f[n] == n) // ! not a root
	{
		return n;
	}
	else // ! using recursion to find root
	{
		return f[n] = Find(f, f[n]);
	}
	// return (f[n]==n) ? n : Find(f[n]);
}

void Union(vector<long long> &f, long long x, long long y)
{
	long long xset = Find(f, x);
	long long yset = Find(f, y);
	if (xset != yset)
	{
		f[max(xset, yset)] = min(xset, yset);
	}
}

