vector<int> parent(100100, -1);

void init(int n)
{
  for (int i = 0; i < n; i++)
  {
    parent.at(i) = -1;
  }
}

int root(int X)
{
  if (parent.at(X) < 0) return X;
  return parent.at(X) = root(parent.at(X));
}

int size(int X)
{
  return -parent.at(root(X));
}

void unite(int X, int Y)
{
  int x = root(X);
  int y = root(Y);
  if (x == y) return;

  if (size(x) < size(y)) swap(x, y);
  parent.at(x) += parent.at(y);
  parent.at(y) = x;
}

