    UnionFind(int n): t(n,-1) { }

    int root(int x) {
        if(t[x]<0) return x;
        else return t[x]=root(t[x]);
    }

    void merge(int x, int y) {
        x = root(x); y = root(y);
        if(t[x]>t[y]) swap(x,y);
        t[y] = x;
    }
};


int main(int argc, char const *argv[])
{
    int n, m; cin >> n >> m;
    UnionFind uF(n);

    int x,y,z;
    for(int i=0;i<m;++i) {
        cin >> x >> y >> z;
        uF.merge(x, y);
    }
    int c=0;
    for(int i=1;i<=n;++i) {
        if(uF.root(i)==i) ++c;
    }
    cout << c << endl;

    return 0;
}

