// UnionFind
struct UnionFind {
    vector<int> d;
    UnionFind(int n=0) : d(n, -1) {} // 各ルートノードはサイズのマイナスを値にもつ
    int find(int x) {
        if (d[x] < 0) return x;
        return d[x] = find(d[x]);
    }
    bool unite(int x, int y) {
        x = find(x); y = find(y);
        if (x == y) return false;
        if (-d[x] < -d[y]) swap(x,y); // Xの方がサイズが大きくなるように
        d[x] += d[y];                   // サイズを更新
        d[y] = x;                       // 大きいツリーに小さいツリーを足す
        return true;
    }
    bool same(int x, int y) {return find(x) == find(y);}
    int size(int x) {return -d[find(x)];}
    int component() {
        set<int> S;
        rep(x,d.size()) S.insert(find(x));
        return S.size();
    }
};

int main()
{
    int n, m;
    cin >> n >> m;
    UnionFind U(n);
    set<int> S;
    rep(i,m) {
        int x, y, z;
        cin >> x >> y >> z;
        x--;y--;
        U.unite(x, y);
        S.insert(x);
        S.insert(y);
    }

    int ans = 0;
    ans += U.component();

    cout << ans << endl;




    return 0;
}

