        Parent = vector<ll>(N, -1);
    }

    //Aがどのグループに属しているか調べる
    ll root(ll A) {
        if (Parent[A] < 0) return A;
        return Parent[A] = root(Parent[A]);
    }

    //自分のいるグループの頂点数を調べる
    ll size(ll A) {
        return -Parent[root(A)];//親をとってきたい]
    }

    //AとBをくっ付ける
    bool connect(ll A, ll B) {
        //AとBを直接つなぐのではなく、root(A)にroot(B)をくっつける
        A = root(A);
        B = root(B);
        if (A == B) {
            //すでにくっついてるからくっ付けない
            return false;
        }

        //大きい方(A)に小さいほう(B)をくっ付けたい
        //大小が逆だったらひっくり返しちゃう。
        if (size(A) < size(B)) swap(A, B);

        //Aのサイズを更新する
        Parent[A] += Parent[B];
        //Bの親をAに変更する
        Parent[B] = A;

        return true;
    }
};

ll solve()
{
    ll ans = 0;
    ll N,M;
    cin >> N >> M;
    UnionFind uni(N);
    for1(i,M) {
        ll X,Y,Z;
        cin >> X >> Y >> Z;
        --X;
        --Y;
        uni.connect(X,Y);
    }

    set<ll> parents;
    for1(i,N) {
        ll pa = uni.root(i);
        parents.insert(pa);
    }

    return parents.size();
}

