int main(){
    int n, m;
    scanf("%d %d", &n, &m);
    vector<vector<int> > nn;
    nn.resize(n);
    for(int i = 0; i < m; ++i){
        int x, y, z;
        scanf("%d %d %d", &x, &y, &z);
        nn.at(x-1).push_back(y-1);
        nn.at(y-1).push_back(x-1);
    }

    vector<bool> visited(n, false);
    int ans = 0;
    stack<int> s;
    for(int i = 0; i < n; ++i){
        if(visited.at(i)){ continue; }
        visited.at(i) = true;
        s.push(i);
        ans++;
        while(!s.empty()){
            int x = s.top(); s.pop();
            for(int y : nn.at(x)){
                if(visited.at(y)){ continue; }
                visited.at(y) = true;
                s.push(y);
            }
        }
    }

    printf("%d\n", ans);
    return 0;
}

