struct UnionFind{
    vector<int> par;

    UnionFind(int n) : par(n, -1) { }
    void init(int n) { par.assign(n, -1); }

    int root(int x) {
        if (par[x] < 0) return x;
        else return par[x] = root(par[x]);
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (par[x] > par[y]) swap(x, y);
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    int size(int x) {
        return -par[root(x)];
    }
};

int main(void){
    int N, M;
    cin >> N >> M;
    UnionFind uf(N);
    bool isroot[N];
    for(int i = 0; i < M; i++){
        int X, Y , Z;
        cin >> X >> Y >> Z;
        uf.merge(X - 1, Y - 1);
        isroot[i] = false;
    }

    int ans = 0;

    for(int i = 0; i < N; i++){
        isroot[uf.root(i)] = true;
    }

    for(int i = 0; i < N; i++){
        if(isroot[i]) ans++;
    }

    cout << ans << "\n";
    return 0;
}

