class UnionFind {
private:
  ll unionSize;
  vector<long long> vec;

private:
  long long FindRoot(long long ipt) {
    if (vec[ipt] == ipt) {
      return ipt;
    } else {
      vec[ipt] = FindRoot(vec[ipt]);
      return vec[ipt];
    }
  }

public:
  UnionFind() = delete;
  UnionFind(const UnionFind &another) = delete;
  UnionFind(long long size) : unionSize(size) {
    vec.resize(size);
    for (long long i = 0; i < size; ++i) {
      vec[i] = i;
    }
  }

  ll GetUnionSize() {
    return unionSize;
  }

  bool Same(long long a, long long b) {
    return FindRoot(a) == FindRoot(b);
  }

  void Union(long long a, long long b) {
    long long x = FindRoot(a);
    long long y = FindRoot(b);

    //改造部
    if (x != y) {
      --unionSize;
    }

    vec[y] = x;
  }
};

