class UnionFind {
private:
	vector<int> par, ran;

public:
	UnionFind(int n) {
		par = decltype(par)(n + 4, -1);
		ran = decltype(ran)(n + 4, 0);
	}

public:
	int find(int x) {
		if (par[x] < 0) {
			return x;
		}
		else {
			return par[x] = find(par[x]);
		}
	}

public:
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return;

		if (ran[x] < ran[y]) {
			par[find(y)] += par[find(x)];
			par[x] = y;
		}
		else {
			par[find(x)] += par[find(y)];
			par[y] = x;
			if (ran[x] == ran[y]) ran[x]++;
		}
	}

	int size(int x) {
		return -par[find(x)];
	}

	bool same(int x, int y) {
		return find(x) == find(y);
	}
};

