struct UnionFind {
    ll _groupcount; // グループ数
    vc<ll> parent;  // 各要素の直接の親リスト，親がいないときは自分自身を指す
    vc<ll> gsize; // 各要素が根である場合，その要素が属するグループの要素数 (root 要素のみ有効な値を持つ)

    // コンストラクタ
    UnionFind() {}
    // コンストラクタ，要素数 n の UnionFind 木を構築する
    UnionFind(ll n) : _groupcount(n), gsize(n, 1), parent(n, 0) { iota(ALL(parent), 0LL); }

    // x の属する部分木の根要素を返す
    ll find(ll x) { return x == parent[x] ? x : parent[x] = find(parent[x]); }

    // x と y が同じグループかどうか判定する
    bool same(ll x, ll y) { return find(x) == find(y); }

    // x と y を同じグループにする
    void unite(ll x, ll y) {
        ll rx = find(x); // x の属するグループの根
        ll ry = find(y); // y の属するグループの根
        if (rx == ry)    // unite 済
            return;
        // assert(x != y)
        if (gsize[rx] < gsize[ry]) swap(rx, ry);
        // assert(gsize[x] > gsize[y]); // x 側の木の方が大きい

        gsize[rx] += gsize[ry]; // x を根とする1つのグループに統合
        parent[ry] = rx;        // ry 以下の木を rx 配下に接続する
        _groupcount--;
    }

    // x が属するグループの要素数を返す
    ll size(ll x) { return gsize[find(x)]; }

    // 全体のグループ数を返す
    ll count() const { return _groupcount; }
};

/* #endregion */

// Problem
void solve() {
    ll n, m;
    cin >> n >> m;

    vll x(m), y(m), z(m);
    REP(i, 0, m) {
        cin >> x[i] >> y[i] >> z[i];
        --x[i], --y[i];
        z[i] %= 2;
    }
    // z[i] == 0 のとき，a[x[i]] + a[y[i]] は偶数 -> 偶奇が一致する
    // z[i] == 1 のとき，a[x[i]] + a[y[i]] は奇数 -> 偶奇が一致しない
    // 1回は1枚の偶奇を確定させる必要がある
    // それ以外は，グループ2つのどちらに属するか確定させるのに必要な回数だけカードを裏返す必要がある
    UnionFind uf(n);
    REP(i, 0, m) if (z[i] == 0) uf.unite(x[i], y[i]);

    // set<pll> pairs;
    // REP(i, 0, m) if (z[i] == 1) {
    //     ll parx = uf.find(x[i]), pary = uf.find(y[i]);
    //     pairs.emplace(min(parx, pary), max(parx, pary));
    // }

    Graph graph(n);
    REP(i, 0, m) if (z[i] == 1) {
        ll parx = uf.find(x[i]), pary = uf.find(y[i]);
        add_edge(graph, parx, pary);
    }
    ll cnt = 0;

    vll groupnums(n, -1);
    ll num = 0;
    REP(i, 0, n) {
        ll start = uf.find(i);
        if (groupnums[start] != -1) continue;
        stack<ll> stk;
        stk.push(start);
        groupnums[start] = num;
        while (!stk.empty()) {
            ll cur = stk.top();
            stk.pop();
            for (Edge &e : graph[cur])
                if (groupnums[e.dst] == -1) groupnums[e.dst] = num, stk.push(e.dst), ++cnt;
        }
        ++num;
    }
    // dump(uf.count(), cnt, groupnums);

    cout << (uf.count() - cnt) << endl;
}

// entry point
int main() {
    solve();
    return 0;
}

