class UnionFind {
public:
    UnionFind(int n) : parent(n, -1), rank(n) {}

    int find(int x) {
        if (parent[x] < 0) {
            return x;
        } else {
            return parent[x] = find(parent[x]);
        }
    }

    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return;

        if (rank[x] < rank[y]) {
            parent[y] += parent[x];
            parent[x] = y;
        } else {
            parent[x] += parent[y];
            parent[y] = x;
            if (rank[x] == rank[y]) rank[x]++;
        }
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }

    int size(int x) {
        return -parent[find(x)];
    }

private:
    vector<int> parent;
    vector<int> rank;
};

int main() {
    int n, m;
    cin >> n >> m;
    UnionFind uf(n);
    for (int i = 0; i < m; ++i) {
        int x, y, z;
        cin >> x >> y >> z;
        --x; --y;
        uf.unite(x, y);
    }

    int ans = 0;
    for (int i = 0; i < n; ++i) {
        if (uf.find(i) == i) ++ans;
    }

    cout << ans << endl;

    return 0;
}

