struct Query {
  int x;
  int y;
  int z;

  Query(int x, int y, int z) {
    this->x = x;
    this->y = y;
    this->z = z;
  }
};

int main() {
  int N, M;
  cin >> N >> M;
  init(N + 1);
  vector<Query> query;

  for (int i = 0; i < M; ++i) {
    int x, y, z;
    cin >> x >> y >> z;

    query.push_back(Query(x, y, z));
  }

  for (int i = 0; i < M; ++i) {
    Query q = query[i];

    if (q.x == q.z || q.y == q.z) {
      unite(q.x, q.y);
    }
  }

  int ans = 0;

  bool checked[N + 1];
  memset(checked, false, sizeof(checked));

  for (int i = 1; i <= N; ++i) {
    int parent = find(i);
    if (checked[parent]) {
      checked[i] = true;
      continue;
    }

    int s = getSize(parent);
    if (s <= 1) continue;
    checked[parent] = true;

    ++ans;
  }

  for (int n = 2; n >= 0; --n) {
    for (int i = 0; i < M; ++i) {
      Query q = query[i];

      int cnt = 0;
      if (checked[q.x]) ++cnt;
      if (checked[q.y]) ++cnt;
      if (checked[q.z]) ++cnt;
      if (cnt != n) continue;

      ans += 2 - cnt;

      checked[q.x] = true;
      checked[q.y] = true;
      checked[q.z] = true;
    }
  }

  for (int i = 1; i <= N; ++i) {
    if (!checked[i]) {
      ++ans;
    }
  }

  cout << ans << endl;

  return 0;
}

