		for (int i = 1; i <= N; ++i) {
			if (maxPair < pairs[i].size()) {
				maxPair = i;
			}
		}

		if (maxPair == 0) {
			break;
		}

		vector<int> knouwnPairs;
		knouwnPairs.push_back(maxPair);

		while (!knouwnPairs.empty()) {
			vector<int> newKnouwnPairs;
			for (int j = 0; j < knouwnPairs.size(); ++j) {
				int sizeOfMaxPair = pairs[knouwnPairs[j]].size();
				int index;
				for (int i = 0; i < sizeOfMaxPair; ++i) {
					index = pairs[knouwnPairs[j]][i];
					newKnouwnPairs.push_back(index);
				}
				pairs[knouwnPairs[j]].clear();
			}
			knouwnPairs.swap(newKnouwnPairs);
		}

		++result;
	}

	cout << result << endl;

	return 0;
}

