//Aには1か2が書かれている
//i番目に伏せられているカードをA[i]とする

// 以下の情報がM個与えられる
// A[Xi] + A[Yi] + Ziは偶数である

//Mの情報を使用しても特定できないカードは何個あるか
//(一つわかれば片方は自明、などもあるかもしれないことに注意する)

//Aの情報をまとめたい
//i 番目は i+1番目の反対、など
//UnionFindでいいのでは??

struct UnionFind {

    vector <ll> par;

    // new
    UnionFind(ll n):par(n, -1){}

    //初期化
    void init(ll n){par.assign(n, -1); } 


    ll root(ll x)
    {
        if(par[x] < 0)return x;
        else return par[x] = root(par[x]);//親の番号を返す(親が子になっていたら困るので取り込まれてたら代入も行う)
    }

    //同じグループに属するか
    bool issame(ll x, ll y)
    {
        //rootが同じであるか
        return root(x) == root(y);
    }

    //併合
    bool merge(ll x, ll y)
    {

        x = root(x);
        y = root(y);
        if(x == y)return false;
        if(par[x] > par[y])swap(x, y);
        //多い方に足し合わせる
        par[x] += par[y];
        //従属(ここで0以上となる)
        par[y] = x;
        return true;
    }

    ll size(ll x)
    {
        return -par[root(x)];
    }

};

