class UnionFind{
  public:
    vector<ll> par;
    vector<ll> rank;
    vector<ll> size;
    UnionFind(ll n): par(n+1, 0),rank(n+1, 0),size(n+1, 1) { iota(par.begin(), par.end(), 0); }

    ll find(ll x){
        if(par[x] == x) return x;
        else return par[x] = find(par[x]);
    }

    void unite(ll x, ll y){
        x = find(x);
        y = find(y);
        if(x == y) return;
        if(rank[x] < rank[y]){
            par[x] = y;
            size[y] += size[x];
        }else{
            par[y] = x;
            size[x] += size[y];
            if(rank[x] == rank[y]) rank[x]++;
        }
    }

    bool same(ll x, ll y){
        return find(x) == find(y);
    }

    ll getsize(ll x){
        return size[find(x)];
    }
};


