void init(){
  for (int i=0; i<100005; i++){
    parent[i]=i;
    length[i]=1;
  }
  return;
}

int getroot(int n){
  while(parent[n]!=n){
    n=parent[n];
  }
  return n;
}

bool samegroup(int n, int m){
  int nroot=getroot(n);
  int mroot=getroot(m);
  return nroot==mroot;
}

bool unite(int n, int m){
  if (samegroup(n, m)){
    return false;
  } else {
    int nroot=getroot(n);
    int mroot=getroot(m);
    if (length[nroot]==length[mroot]){
      parent[nroot]=mroot;
      length[mroot]++;
    } else if (length[nroot]>length[mroot]){
      parent[mroot]=nroot;
      length[nroot]++;
    } else {
      parent[nroot]=mroot;
      length[mroot]++;
    }
    return true;
  }
}

