void dfs(int v, int p) {
  for (pii P : G[v]) {
    int nv = P.F, cost = P.S;
    if (nv == p) continue;
    if (d[nv] == -1) {
      (d[nv] = d[v] + cost) %= 2;
      dfs(nv, v);
    }
    else {
      int D = (d[v] + cost) % 2;
      if (D != d[nv]) {
        cout << -1 << endl;
        exit(0);
      } else {
        d[nv] = D;
      }
    }
  }
}

