#include <bits/stdc++.h>
using namespace std;

const int N = 1e5 + 5;
int n,m;

class dsu {
public:
    vector<int> p;
    int n;

    dsu(int _n) : n(_n) {
        p.resize(n);//n nodes, 0 ~ n-1
        iota(p.begin(), p.end(), 0);
    }

    inline void re_init(){
        iota(p.begin(), p.end(), 0);
    }

    inline int findset(int x) {
        return (x == p[x] ? x : (p[x] = findset(p[x])));
    }

    inline bool unite(int x, int y) {
        x = findset(x);
        y = findset(y);
        if (x != y) {
            p[x] = y;
            return true;
        }
        return false;
    }
    int num_of_component(){
        int ans = 0;
        for (int i = 0; i < n; i++){
            if(i == findset(i)) ans++;
        }
