template<class T>using p_queue = std::priority_queue<T, std::vector<T>, std::greater<>>;
struct union_find
{
	std::vector<int> upper, rank;
	std::size_t dsize;
	union_find(std::size_t size) :upper(size, -1), rank(size, 0), dsize(size)
	{
	}

	int group(int index)
	{
		if (upper[index] == -1)
		{
			return index;
		}
		else
		{
			return upper[index] = group(upper[index]);
		}
	}

	bool merge(int x, int y)
	{
		auto gx = group(x);
		auto gy = group(y);
		if (gx != gy)
		{
			--dsize;
			if (rank[gx] < rank[gy])
			{
				upper[gx] = gy;
			}
			else if (rank[gx] > rank[gy])
			{
				upper[gy] = gx;
			}
			else
			{
				upper[gx] = gy;
				++rank[gx];
			}
			return true;
		}
		return false;
	}

	auto get()
	{
		std::map<int, std::set<int>> ret;
		for (int i = 0; i < upper.size(); ++i)
		{
			ret[group(i)].emplace(i);
		}
		return ret;
	}

	auto tops()
	{
		std::set<int> ret;
		for (int i = 0; i < upper.size(); ++i)
		{
			ret.emplace(group(i));
		}
		return ret;
	}

	bool is_same_group(int x, int y)
	{
		return group(x) == group(y);
	}

	std::size_t size()
	{
		return dsize;
	}
};

