int N, M;
vector<int> par;
set<int> S;

void init_union_find(int n) {
	par.resize(n, -1);
}

int find(int x) {
	if (par[x] < 0) return x;
	return par[x] = find(par[x]);
}

bool same(int x, int y) {
	return find(x) == find(y);
}

int get_size(int x) {
	return -par[find(x)];
}

bool unite(int x, int y) {
	x = find(x); y = find(y);
	if (x == y) return false;
	if (get_size(x) < get_size(y)) swap(x, y);
	par[x] += par[y];
	par[y] = x;
	return true;
}

void input_init(void) {
	cin >> N >> M;
	init_union_find(N);
	int x, y, z;
	for (int i = 0; i < M; ++i) {
		cin >> x >> y >> z;
		--x;
		--y;
		unite(x, y);
	}
}

int solve(void) {
	int cnt_1 = 0;
	for (int i = 0; i < N; ++i) {
		if (par[i] == -1)
			++cnt_1;
		else if (par[i] >= 0)
			S.insert(par[i]);
	}
	int cnt_2 = S.size();
	return cnt_1 + cnt_2;
}

int main(void) {
	input_init();
	int ans = solve();

	cout << ans << '\n';
	return 0;
}

