class UnionFind {
    std::vector<int> p;

public:
    UnionFind(int n) : p(n, -1) {}

    int root(int x) { return p[x] < 0 ? x : p[x] = root(p[x]); }

    bool same(int x, int y) { return root(x) == root(y); }

    bool unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return false;
        if (p[y] < p[x]) std::swap(x, y);
        if (p[x] == p[y]) --p[x];
        p[y] = x;
        return true;
    }
};

void solve(long long N, long long M, std::vector<long long> X,
           std::vector<long long> Y, std::vector<long long> Z) {
    UnionFind uf(N);
    for (int i = 0; i < M; i++) {
        uf.unite(X[i] - 1, Y[i] - 1);
    }
    int ans = 0;
    for(int i = 0 ; i < N ; i++){
        ans += uf.root(i) == i;
    }
    cout << ans << endl;
}

