  UnWeightedGraph buff;
  scc.build(buff);
  map<int, bool> sel;
  int ans = 0;
  for(int i=0;i<n;++i) {
    if(!sel[scc[i]]) {
      ans++;
      sel[scc[i]] = true;
    }
  }
  cout << ans << endl;
}

