struct UnionFind {
    vector<int> par;

    UnionFind(int N) : par(N) {
        for(int i = 0; i < N; i++) par[i] = i;
    }

    int root(int x) {
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) { 
        int rx = root(x); 
        int ry = root(y); 
        if (rx == ry) return;
        par[ry] = rx; 
    }

    int solve() { 
        int ans = 0;
		map<int,int> c;
        for(int u:par){
			if(c[u]==0){
				c[u]++;
				ans++;
			}
		}
        return ans;
    }
};

