  vector<Query> query;

  for (int i = 0; i < M; ++i) {
    int x, y, z;
    cin >> x >> y >> z;

    query.push_back(Query(x, y, z));
  }

  for (int i = 0; i < M; ++i) {
    Query q = query[i];

    if (q.x == q.z || q.y == q.z) {
      unite(q.x, q.y);
    }
  }

  int ans = 0;

  bool checked[N + 1];
  memset(checked, false, sizeof(checked));

  for (int i = 1; i <= N; ++i) {
    int parent = find(i);
    if (checked[parent]) {
      checked[i] = true;
      continue;
    }

    int s = getSize(parent);
    if (s <= 1) continue;
    checked[parent] = true;

    ++ans;
  }

  for (int i = 0; i < M; ++i) {
    Query q = query[i];

    int cnt = 0;
    if (checked[q.x]) ++cnt;
    if (checked[q.y]) ++cnt;
    if (checked[q.z]) ++cnt;
    if (cnt != 2) continue;

    checked[q.x] = true;
    checked[q.y] = true;
    checked[q.z] = true;
  }

  while (true) {
    bool update = false;

    map<int, int> counter;
    int maxD = 0;
    int maxV = -1;

    for (int i = 0; i < M; ++i) {
      Query q = query[i];
      int cnt = 0;

      if (!checked[q.x]) {
        counter[q.x]++;
      } else {
        ++cnt;
      }
      if (!checked[q.y]) {
        counter[q.y]++;
      } else {
        ++cnt;
      }
      if (!checked[q.z]) {
        counter[q.z]++;
      } else {
        ++cnt;
      }

      if (cnt == 2) {
        checked[q.x] = true;
        checked[q.y] = true;
        checked[q.z] = true;
        continue;
      }

      if (maxD < counter[q.x]) {
        maxD = counter[q.x];
        maxV = q.x;
      }
      if (maxD < counter[q.y]) {
        maxD = counter[q.y];
        maxV = q.y;
      }
      if (maxD < counter[q.z]) {
        maxD = counter[q.z];
        maxV = q.z;
      }
    }

    if (maxV != -1) {
      ++ans;
      checked[maxV] = true;
      update = true;
    }

    if (!update) {
      break;
    }
  }

  for (int i = 1; i <= N; ++i) {
    if (!checked[i]) {
      ++ans;
    }
  }

  cout << ans << endl;

  return 0;
}

