#include <bits/stdc++.h>

typedef long long ll;
using namespace std;

struct union_find {
    vector<int> parent; // parent. if the element itself is the parent, return -(the size of the group)

    union_find(int N) : parent(N) {
        parent = vector<int>(N, -1);
    }

    int root(int n) {
        return (parent[n] < 0) ? n : parent[n] = root(parent[n]);
    }

    void unite(int x, int y) {
        // unite small one to big one
        int rx = root(x);
        int ry = root(y);
        if (rx == ry)
            return;
        if (size_of(rx) < size_of(ry))
            swap(ry, rx);
        parent[rx] += parent[ry];
        parent[ry] = rx;
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    int size_of(int n) {
        return -parent[root(n)];
    }
};

int main() {
    int n, m;
    cin >> n >> m;
    union_find tree(n);
    for (int i = 0; i < m; i++) {
        int x, y, z;
