struct union_find {
    std::vector<int> data;
    std::vector<int> rank;
    int num_union;

    union_find(int size) : data(size+1, 0), rank(size+1, 0), num_union(size) {
        init();
    }

    void init() {
        for (int i=1; i<data.size(); ++i) {
            data[i] = i;
            rank[i] = 0;
        }
    }

    int find_root(int x) {
        if (data[x] == x) {
            return x;
        } else {
            return data[x] = find_root(data[x]);
        }
    }

    void unite(int x, int y) {
        x = find_root(x);
        y = find_root(y);
        if (x == y) return;

        if (rank[x] < rank[y]) {
            data[x] = y;
        } else {
            data[y] = x;
            if (rank[x] == rank[y]) ++rank[x];
        }
        --num_union;
    }

    bool same(int x, int y) {
        return find_root(x) == find_root(y);
    }
};


int main(int argc, char** argv) {
