struct UnionFind {
	vector<int>data;

	UnionFind(int n) :data(n) { for (auto&& x : data)x = -1; }

	int find(int k) {
		if (data[k] < 0)return k;
		return data[k] = find(data[k]);
	}

	bool unite(int x, int y) {
		x = find(x), y = find(y);
		if (x == y)return false;
		if (data[x] > data[y])swap(x, y);
		data[x] += data[y];
		data[y] = x;
		return true;
	}

	int size(int k) {
		return -data[find(k)];
	}
};

