int fnd(int a) {
    if (par[a] == a) {
        return a;
    }

    par[a] = fnd(par[a]);
    return par[a];
}

void un(int a, int b) {
    int paa = fnd(a);
    int pab = fnd(b);
    if (paa == pab) {
        return;
    }

    if (rnk[paa] >= rnk[pab]) {
        par[pab] = paa;
        rnk[paa] = (rnk[paa] == rnk[pab] ? rnk[paa] + 1 : rnk[paa]);
    }

