using namespace std;

class unionfind {
public:
  vector<int> v;

  unionfind(int n) {
    v = vector<int>(n, -1);
  }

  int size(int n) {
    return -v[root(n)];
  }

  int parent(int n) {
    return v[n] < 0 ? n : v[n];
  }

  int root(int n) {
    return parent(n) == n ? n : v[n] = root(parent(n));
  }

  int unite(int a, int b) {
    int ra = root(a);
    int rb = root(b);
    if (ra == rb) return size(ra);
    if (size(ra) >= size(rb)) {
      v[ra] += v[rb];
      v[rb] = ra;
      return size(ra);
    } else {
      v[rb] += v[ra];
      v[ra] = rb;
      return size(rb);
    }
  }
};

