typedef long long ll;

struct union_find{
    vector<ll> par;
    vector<ll> chs;
    union_find(int N){
        par.resize(N);
        chs.resize(N);
        for(int i=0;i<N;i++) par[i] = i;
        for(int i=0;i<N;i++) chs[i] = 1;
    }
    ll root(ll x){
        if(par[x] == x) return x;
        return par[x] = root(par[x]);
    }
    void unite(ll x,ll y){
        ll rx = root(x);
        ll ry = root(y);
        if(rx == ry) return;
        par[rx] = ry;
        chs[ry] += chs[rx];
    }
    bool same(ll x,ll y){
        return root(x) == root(y);
    }
    ll size(ll x){
        return chs[root(x)];
    }
};

int main(){
