void dfs(vector<vll> &G, vb &checked, ll u){
    if(checked[u]){
        return;
    }
    checked[u] = true;
    for(auto v: G[u]){
        dfs(G, checked, v);
    }
    return;
}

void solve(long long N, long long M, std::vector<long long> X, std::vector<long long> Y, std::vector<long long> Z){
    ll V = 2*N;
    vector<vll> G(V);
    REP(m, M){
        if(Z[m]){ //* X[m], Y[m] different
            G[X[m]*2].push_back(Y[m]*2+1);
            G[Y[m]*2+1].push_back(X[m]*2);
            G[X[m]*2+1].push_back(Y[m]*2);
            G[Y[m]*2].push_back(X[m]*2+1);
        }
        else{//* X[m], Y[m] same
            G[X[m]*2].push_back(Y[m]*2);
            G[Y[m]*2].push_back(X[m]*2);
            G[X[m]*2+1].push_back(Y[m]*2+1);
            G[Y[m]*2+1].push_back(X[m]*2+1);
        }
    }
    REP(i, N){
        G[i*2].push_back(i*2+1);
        G[i*2+1].push_back(i*2);
    }
    ll cnt = 0;
    vb checked(V, false);
    REP(v, V){
        if(!checked[v]){
            cnt++;
            dfs(G, checked, v);
        }
    }
    cout<<cnt<<endl;

}

