class DisjointSet{
  public:
    vector<int> rank,p,sz;

    DisjointSet(){}

    //初期化
    DisjointSet(int size){
      rank.resize(size,0);
      p.resize(size,0);
      sz.resize(size,1);
      rep(i,size){
        makeSet(i);
      }
    }        
    void makeSet(int x){
      p[x]=x;
      rank[x]=0;
    }

    bool same(int x,int y){
      return findSet(x)==findSet(y);
    }

    void unite(int x,int y){
      if(!same(x,y)) link(findSet(x),findSet(y));
    }

    int size(int key){
      return sz[findSet(key)];
    }

    void link(int x,int y){
      if(rank[x]>rank[y]){
        p[y]=x;
        sz[x]+=sz[y];
      }
      else{
        p[x]=y;
        sz[y]+=sz[x];
        if(rank[x]==rank[y]){
            rank[y]++;
        }
      }
    }

    int findSet(int x){
      if(x!=p[x]){
        p[x]=findSet(p[x]);
      }
      return  p[x];
    }
};

