        a--; b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    // BFS のためのデータ構造
    vector<int> dist(N, -1); // 全頂点を「未訪問」に初期化
    queue<int> que;
    rep(i,N){
    if(dist[i]!=-1) continue;
    else{
    //cout << i << endl;
    ca++;
    // 初期条件 (頂点 0 を初期ノードとする)
    dist[i] = 0;
