struct UnionFind {
private:
  int N;
  // parは親要素、rancは階層、cntはそのTree内に含まれる要素数
  vector<int> par,ranc,cnt;

public:
  UnionFind(int N) : N(N),par(N),ranc(N,0),cnt(N,1) { REP(i,N) par[i]=i; }

  int memsiz(int s) { return cnt[root(s)]; }
  int root(int s) { return (par[s]==s) ? s : root(par[s]); }
  bool same(int x, int y) { return root(x)==root(y); }

  bool connected() {
    int base = root(0);
    REP(i,N) if (root(i)!=base) return false;
    return true;
  }

  void merge(int x, int y) {
    x = root(x);
    y = root(y);
    if (x==y) return;
    if (ranc[x]>ranc[y]) {
      par[y] = x;
      cnt[x] += cnt[y];
    } else {
      par[x] = y;
      cnt[y] += cnt[x];
      if (ranc[x]==ranc[y]) ranc[y]++;
    }
  }
};

