// union_find {{{
class union_find {
  private:
    vector<Z> parent, rank, size;
  public:
    union_find(Z n): parent(n), rank(n, 1), size(n, 1) {
      for (auto i = 0; i < n; i++)
        parent[i] = i;
    }

    Z root(Z x) {
      Z& par = ix(parent, x);
      if (par == x) return x;
      return par = root(par);
    }

    void unite(Z x, Z y) {
      x = root(x);
      y = root(y);
      if (x == y) return;
      if (ix(rank, x) > ix(rank, y))
        swap(x, y);
      ix(parent, x) = y;
      ix(size, y) += ix(size, x);
      if (ix(rank, x) == ix(rank, y))
        ix(rank, y)++;
    }

    bool is_same(Z x, Z y) {
      return root(x) == root(y);
    }

    Z group_size(Z x) {
      return ix(size, root(x));
    }
};
// }}}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
