	void solve(std::istream& in, std::ostream& out) {
	    int n, m;
	    in >> n >> m;
	    UnionFind uf(n);
	    vi x(m), y(m), z(m);

	    ll res = 0;
	    map<int, int> mp;
	    for(int i=0; i<m; i++){
	        in >> x[i] >> y[i] >> z[i];
	        --x[i]; --y[i]; --z[i];
	        mp[x[i]]++; mp[y[i]]++; mp[z[i]]++;
	    }
	    for(int i=0; i<n; i++){
	        if(!mp.count(i)) res++;
	    }

	    vi v(n);
	    vi seen(m);
	    for(int i=0; i<m; i++){
	        if(v[x[i]] + v[y[i]] + v[z[i]] >= 2) {
                v[x[i]] = 1;
                v[y[i]] = 1;
                v[z[i]] = 1;
                seen[i] = 1;
	            continue;
	        }
            if(x[i] == z[i]){
                v[x[i]] = 1;
                v[y[i]] = 1;
                res++;
                seen[i] = 1;
            }
            if(y[i] == z[i]){
                v[x[i]] = 1;
                v[y[i]] = 1;
                res++;
                seen[i] = 1;
            }
	    }

	    for(int i=0; i<m; i++){
            if(seen[i]) continue;
            if(v[x[i]] + v[y[i]] + v[z[i]] >= 2) continue;
            else{
                res+=2;
            }
	    }

	    out << res << enl;
	}
};


int main() {
    cin.tie(nullptr);
    ios_base::sync_with_stdio(false);
	E1Or2 solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	return 0;
}

