vector<int> edge[100001]; 
bool visited[100001];

int dfs(int x, int y) {
    if(visited[x]) return 0;
    visited[x] = true;
    REP(i, edge[x].size()) {
        if(edge[x][i] == y) continue;
        dfs(edge[x][i], x);
    }

    return 0;
}

