struct UnionFind {
    vector<int> par;

    UnionFind(int N): par(N) {
        for(int i=0; i < N; i++) par[i] = i;
    }

    int root(int x) {
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if(rx == ry) return;
        par[rx] = ry;
    }
};

int main() {
    int N, M;
    cin >> N >> M;
    UnionFind tree(N);

    int X, Y, Z;
    for(int i=0; i<M; i++) {
        cin >> X >> Y>>Z;
        tree.unite(X-1,Y-1);
    }

    vector<int> vec = tree.par;
    sort(vec.begin(),vec.end());
    vec.erase(unique(vec.begin(),vec.end()),vec.end());

    cout << vec.size() << endl;
    return 0;
}

