class UnionFind {
private:
	int num_unions;
	vector<int> par;
	vector<int> rank;
public:
	UnionFind(int N);
	int root(int node);
	void marge(int node_a, int node_b);
	int count_unions();
};

int main() {
	int N, M;
	cin >> N >> M;

	UnionFind uf(N);
	for (int i = 0; i < M; i++) {
		int X, Y, Z;
		cin >> X >> Y >> Z;
		uf.marge(X - 1, Y - 1);
	}
	cout << uf.count_unions() << endl;
}

//各ノードの初期値はそれ自身（自身がノードの根）
UnionFind::UnionFind(int N) : par(N), num_unions(N),rank(N,0) {
	for (int i = 0; i < N; i++) {
		par[i] = i;
	}
}

int UnionFind::root(int node) {
	if (par[node] == node) return node;
	else {
		return par[node] = root(par[node]);//経路圧縮
	}
}

void UnionFind::marge(int node_a, int node_b) {
	int root_a = root(node_a);
	int root_b = root(node_b);
	if (root_a == root_b) return;
	else {
		if (rank[root_a] < rank[root_b]) {
			par[root_a] = root_b;
		}
		else {
			par[root_b] = root_a;
			if (rank[root_a] == rank[root_b]) rank[root_a]++;
		}
	} 
}

int UnionFind::count_unions() {
	int ret = 0;
	for (int i = 0; i < num_unions; i++) {
		if (par[i] == i) ret++;
	}
	return ret;
}

