class UnionFind {
    // can be slow !!!! -- if you need components only, consider bfs/dfs
    public:
      set<int> roots;
      int total_n;
      DirectedGraph<int> gr;     // value stores rank

      UnionFind(int n) : total_n(n)  { 
          for (int i = 0; i < n; ++i) {  roots.insert(i); gr.AddVertex(1); }
      }

      int Find(int i)   {
          gr.dfs_init(i);
          int root = i;
          while (!gr.dfs_iterator.end()) {  root = *gr.dfs_iterator;  ++gr.dfs_iterator;  }
          if (root != i) {
              if (*gr.neighbors[i].begin() != root) {
                gr.RemoveEdge(i, *gr.neighbors[i].begin());
                gr.AddEdge(i, root);
              }
          }
          return root;
      }

      void Union(int i, int j) {
          int root_i = Find(i), root_j = Find(j);
          if (root_i == root_j) {  return;  }

          if (gr[root_i] < gr[root_j])  {
              gr.AddEdge(root_i, root_j); roots.erase(root_i);
          } else if ( gr[root_i] > gr[root_j] ) {
              gr.AddEdge(root_j, root_i); roots.erase(root_j);
          }  else  {
              gr.AddEdge(root_i, root_j); roots.erase(root_i); ++gr[root_j];
          } 
      }

      void print_() {
          for (auto x : roots) {
          cout << x << " : ";
          for (int i = 0; i < total_n; ++i) {
            if (Find(i) == x) {   cout << i << " ";  }
          }
          cout << endl;
        }
      }


};


