i64 rank__[MAX_N];

void init(i64 n) {
    REP(i, n) {
        parent[i] = i;
        rank__[i] = 0;
    }
}

i64 find(i64 x) {
    if (parent[x] == x) {
        return x;
    } else {
        return parent[x] = find(parent[x]);
    }
}

void unite(i64 x, i64 y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (rank__[x] < rank__[y]) {
        parent[x] = y;
    } else {
        parent[y] = x;
        if (rank__[x] == rank__[y]) {
            rank__[x]++;
        }
    }
}

bool same(i64 x, i64 y) {
    return find(x) == find(y);
}

