struct UnionFind{
    vector<int> par;
    UnionFind(int N) : par(N){
        for(int i=0;i<N;i++){
            par[i] = i;
        }
    }
    int root(int x){
        if(par[x]==x)return x;
        return par[x] = root(par[x]);
    }
    void unite(int x,int y){
        int rx = root(x);
        int ry = root(y);
        if(rx==ry) return;
        par[rx] = ry;
    }
    bool same(int x,int y){
        int rx = root(x);
        int ry = root(y);
        return rx==ry;
    }
    int parent(int x){
        return root(x);
    }
};
int main(){
    int N,M;
    cin >> N >> M;
    UnionFind tree(N+5);
    int X,Y,Z;
    vector<int> check(N+5,0);
    for(int i=0;i<M;i++){
        cin >> X >> Y >> Z;
        X--; Y--;
        tree.unite(X,Y);
        if(Z%2==0){
            check[X] = 1;
            check[Y] = 1;
        }else{
            check[X] = 2;
            check[Y] = 2;
        }
    }
    int ans = 0;
    for(int i=0;i<N;i++){
        if(check[tree.parent(i)]==1){
            ans += 1;
            check[tree.parent(i)]=3;
        }else if(check[tree.parent(i)]==2){
            ans += 1;
            check[tree.parent(i)]=3;
        }else if(check[tree.parent(i)]==0){
            ans += 1;
            check[tree.parent(i)]=3;
        }
    }
