//unionfind
typedef pair<int, int> P;
const int MAX_N = 100010;
int m, n;
int par[MAX_N];    //親
int deapth[MAX_N]; //木の深さ
int cnt[MAX_N];
int num;

vector<int> vec[MAX_N];
//n要素で初期化
void init(int n)
{
    for (int i = 0; i < n; i++)
    {
        par[i] = i;
        deapth[i] = 0;
        cnt[i] = 1;
    }
}
//木の根を求める
int find(int x)
{
    if (par[x] == x)
    {
        return x;
    }
    else
    {
        return par[x] = find(par[x]);
    }
}

//xとyの属する集合を併合
void unite(int x, int y)
{
    x = find(x);
    y = find(y);
    if (x == y)
        return;
    if (deapth[x] < deapth[y])
    {
        par[x] = y;
        cnt[y] += cnt[x];
    }
    else
    {
        par[y] = x;
        cnt[x] += cnt[y];
        if (deapth[x] == deapth[y])
            deapth[x]++;
    }
}

bool same(int x, int y)
{
    return find(x) == find(y);
}

int main()
{
    cin >> n >> m;
    init(MAX_N);
    vector<P> v;
    for (int i = 0; i < m; i++)
    {
        int x, y, z;
        cin >> x >> y >> z;
        if (z % 2 == 0)
        {
            unite(x, y);
        }
        else
        {
            v.push_back(P(x, y));
            v.push_back(P(y, x));
        }
    }
    for (int i = 0; i < v.size(); i++)
    {
        vec[find(v[i].first)].push_back(find(v[i].second));
    }
    vector<bool> fl(n + 1, false);
    vector<P> u;

    for (int i = 1; i <= n; i++)
    {
        if (fl[find(i)])
            continue;
        fl[find(i)] = true;
        u.push_back(P(cnt[find(i)], find(i)));
    }

    sort(u.begin(), u.end(), greater<P>());

    vector<bool> f(n + 1, false);
    int ans = 0;
    for (int i = 0; i < u.size(); i++)
    {
        if (f[find(u[i].second)])
            continue;
        ans++;
        f[u[i].second] = true;
        for (int i = 0; i < vec[u[i].second].size(); i++)
        {
            int x = vec[u[i].second][i];
            f[find(x)] = true;
        }
    }
    for (int i = 1; i <= n; i++)
    {
        if (!f[find(i)])
            ans++;
    }
    cout << ans << endl;
}

#include<bits/stdc++.h>
using namespace std;
#define rep(i,n) for(int i = 0; i < (n); i++)

//unionfind
//init: union_find name(size)

class union_find{
private:
    //根にはグループの要素数に―1をかけたもの、それ以外には根の値
    //初期値は-1
    vector<int> uni;
public:
    //Constructer
    //uniを必要なサイズで初期化する、初期値は―1
    union_find(int unisize) : uni(unisize,-1){}

    //引数aの根を求める、なければaを根として返す
    int root(int a){
        if(uni[a] < 0) return a;
        return uni[a] = root(uni[a]);  
    }

    //頂点aとbを繋ぐ関数unite
    //戻り値：
    //  元々同じグループであればfalse
    //  連結に成功すればtrue
    bool unite(int a, int b){
        //a, bにそれぞれが属するグループの根を入れる
        //uni[a], uni[b]がa, bがそれぞれが属するグループのサイズになる
        a = root(a);
        b = root(b);
        if(a == b) return false;
        if(uni[a] > uni[b]) swap(a,b); //bの方を大きいものにする
        uni[a] += uni[b];
        uni[b] = a; //大きい方のグループに属するものの親を小さいものの根にする(rootが高速で動くようになる)
        return true;
    }
    //頂点aとbが同じグループかを調べる
    bool isConnected(int a, int b){
        return root(a) == root(b);
    }
    //頂点aを含むグループの頂点数を調べる
    int unisize(int a){
        return -uni[root(a)];
    }
};

int main(){
    int n,m; cin >> n >> m;
    union_find graph(n+1);
    int x,y,z;
    int ans1 = 0;
    rep(i,m){
        cin >> x >> y >> z;
        if(graph.isConnected(x,y)) continue;
        else{
            if(graph.unisize(x) == 1 && graph.unisize(y) == 1){
                graph.unite(x,y);
                ans1++;
            }else{
                graph.unite(x,y);
            }
        }
    }
    int ans2 = 0;
    rep(i,n) if(graph.unisize(i+1) == 1) ans2++;
    cout << ans1 + ans2 << endl;
}

