typedef pair<long long int, long long int> P;
typedef pair<long long int, P> Q;

int main() {
    long long int n, m;
    cin >> n >> m;
    long long int x, y, z;
    vector< vector<P> > mp(n);
    for (long long int i = 0; i < m; i++) {
        cin >> x >> y >> z;
        if (z % 2 == 0) {
            mp[x-1].push_back(P(y-1, 0));
            mp[y-1].push_back(P(x-1, 0));
        } else {
            mp[x-1].push_back(P(y-1, 1));
            mp[y-1].push_back(P(x-1, 1));
        }
    }
    vector<long long int> ans(n, 0);
    long long int count = 0;

    priority_queue<P, vector<P>, less<P> > pq;

    for (long long int i = 0; i < n; i++) {
        long long int sz = mp[i].size();
        pq.push(P(sz, i));
    }
    while (!pq.empty()) {
        P p = pq.top();
        pq.pop();
        if (ans[p.second] == 0) {
            count++;
            ans[p.second] = 2;
            queue<long long int> q;
            q.push(p.second);
            while (!q.empty()) {
                long long int qq = q.front();
                q.pop();
                for (long long int i = 0; i < mp[qq].size(); i++) {
                    P pp = mp[qq][i];
                    if (ans[pp.first] == 0) {
                        if (pp.second == 1) {
                            ans[pp.first] = 3 - ans[qq];
                        } else {
                            ans[pp.first] = ans[qq];
                        }
                        q.push(pp.first);
                    }
                } 
            }
        }
        //cout << ans[0] << ' ' << ans[1] << ' ' << ans[2] << endl;
    }
    cout << count << endl;
    return 0;
}

