class UnionFind {
  public:  
    vi Parent;
    UnionFind(int N) {
      Parent = vi(N,-1);
    }

      int root(int A) {
      if(Parent[A] < 0) return A;
      return Parent[A] = root(Parent[A]);
    }

      int size(int A) {
      return -Parent[root(A)];
    }

      bool connect(int A,int B) {
      A = root(A);
      B = root(B);
      if(A == B) return false;
      if(size(A) < size(B)) swap(A,B);
      Parent[A] += Parent[B];
      Parent[B] = A;
      return true;
    }
};


int main() {
  int N,M;
  cin >> N >> M;
  UnionFind tree = UnionFind(N);
  rep(i,M) {
    int a,b,c;
    cin >> a >> b >> c;
    tree.connect(a-1,b-1);
  }
  vi roots;
  rep(i,N) {
    int x = tree.root(i);
    roots.push_back(x);
  }
  sort(rng(roots));
  roots.erase(unique(rng(roots)),roots.end());
  cout << sz(roots) << endl;
  return 0;
}

