vector<int> tamanho, parent;

int root (int x) {
  while (x != parent[x]) x = parent[x];
  return x;
}

void join (int a, int b) {
  a = root(a);
  b = root(b);
  if (a == b) return;
  if (tamanho[a] < tamanho[b]) swap(a, b);
  tamanho[a] += tamanho[b];
  parent[b] = a;
}

int main () {
  int n, m;
  cin >> n >> m;
  tamanho = parent = vector<int> (n + 1);
  for (int i = 0; i <= n; i++) {
    parent[i] = i;
    tamanho[i] = 1;
  }

  while (m--) {
    int s, e, foo;
    cin >> s >> e >> foo;
    join (s, e);
  }
  unordered_set<int> ans;
  for (int i = 1; i <= n; i++) {
    ans.insert(root(i));
  }
  cout << ans.size() << '\n';
