class UnionFind
{
public:
	UnionFind(ll size) : parent(size), rank(size) {
		for (ll i = 0; i < size; i++) {
			parent[i] = i;
			rank[i] = 0;
		}
	};

	ll root(ll x) {
		if (parent[x] == x) {
			return x;
		}
		else {
			return parent[x] = root(parent[x]);
		}
	}

	bool same(ll x, ll y) {
		return root(x) == root(y);
	}

	void unite(ll x, ll y) {
		x = root(x);
		y = root(y);
		if (x == y) return;

		if (rank[x] < rank[y]) {
			parent[x] = y;
		}
		else {
			parent[y] = x;
			if (rank[x] == rank[y]) rank[x]++;
		}
	}

private:
	//parent[i]==j  : iの親がj
	vector<ll> parent;
	vector<ll> rank;

};

//解法
void solve() {

	ll N, M;
	cin >> N >> M;

	UnionFind UF(N);

	rep(i, M) {
		ll X, Y, Z;
		cin >> X >> Y >> Z;
		X--; Y--;

		UF.unite(X, Y);
	}

	vector<bool> vec(N,false);
	ll ans = 0;

	rep(i, N) {
		ll top = UF.root(i);
		if (vec[top] == false) {
			vec[top] = true;
			ans++;
		}
	}

	cout << ans;
}

