struct unionfind {
    vector<int> par;
    vector<int> sizes;

    unionfind(int n) : par(n),sizes(n,1){
        rep(i,0,n) par[i] = i;
    }

    int root(int x){
        if(par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x,int y){
        x = root(x);
        y = root(y);

        if(x == y) return;

        if(sizes[x] < sizes[y] ) swap(x,y);

        par[y] = x;
        sizes[x] += sizes[y];
        sizes[y] = 0;

        return;
    }

    bool same(int x,int y){
        return root(x) == root(y);
    }

    int size(int x){
        return sizes[root(x)];
    }
};

int main(){
    ll n,m;
    cin >> n >> m;
    unionfind uf(n);

    rep(i,0,m){
        ll x,y,z;
        cin >> x >> y >> z;
        uf.unite(x-1,y-1);
    }

    map<ll,bool> mapp;

    ll ans = 0;
    rep(i,0,n){
        if(mapp.count(uf.root(i)) == 0){
            ans++;
            mapp[uf.root(i)] = 1;
        }
    }
    cout << ans << endl;
    return 0;
}

