struct uf {
private:
	vector<int> par, ran;
public:
	void init(int n) {
		par.resize(n, 0);
		ran.resize(n, 0);
		rep(i, n) {
			par[i] = i;
		}
	}
	int find(int x) {
		if (par[x] == x)return x;
		else return par[x] = find(par[x]);
	}
	void unite(int x, int y) {
		x = find(x), y = find(y);
		if (x == y)return;
		if (ran[x] < ran[y]) {
			par[x] = y;
		}
		else {
			par[y] = x;
			if (ran[x] == ran[y])ran[x]++;
		}
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
};
void solve() {
	int n, m; cin >> n >> m;
	uf u; u.init(n+1);
	rep(i, m) {
		int x, y, z; cin >> x >> y >> z; x--; y--;
		u.unite(x, y);
	}
	int ans = 0;
	rep(i, n) {
		if (!u.same(n, i))ans++;
		u.unite(n, i);
	}
	cout << ans << endl;
}

