// find(i) = iの親, size(i) = iの属する集合の要素数
struct uf_tree {
    vector<int> parent;
    int internal_size;
    uf_tree(int size_) : parent(size_, -1), internal_size(size_) {}
    void unite(int x, int y) {
        if ((x = find(x)) != (y = find(y))) {
            if (parent[y] < parent[x]) swap(x, y);
            parent[x] += parent[y];
            parent[y] = x;
            internal_size--;
        }
    }
    bool is_same(int x, int y) { return find(x) == find(y); }
    int find(int x) { return parent[x] < 0 ? x : parent[x] = find(parent[x]); }
    int size(int x) { return -parent[find(x)]; }
    int size() { return internal_size; }
};

int main(void) {
    int n, m;
    cin >> n >> m;
    uf_tree uf(n);
    rep (m) {
        int a, b, c;
        cin >> a >> b >> c;
        --a; --b;
        uf.unite(a, b);
    }
    set<int> s;
    repeat (i, n) {
        s.insert(uf.find(i));
    }
    cout << s.size() << endl;
}

