struct UnionFind{
    vector<int> parent;

    UnionFind(int n){
        parent.resize(n);
        for(int i = 0; i < n; i++) parent[i] = i;
    }

    int root(int node){
        if(parent[node] == node){
            return node;
        } else {
            return parent[node] = root(parent[node]);
        }
    }

    void unite(int x, int y){
        int rootx = root(x);
        int rooty = root(y);
        if(rootx == rooty) return;
        parent[rootx] = rooty;
    }

    bool isSame(int x, int y){
        return root(x) == root(y);
    }
};
int main(void){
    int n, m;
    cin >> n >> m;

    UnionFind uf(n);

    for(int i = 0; i < m; i++){
