int main() {
  int N, M;
  std::cin >> N >> M;
  std::vector<std::vector<int>> hint(N);
  std::vector<int> lut(N);

  for (int i = 0; i < M; ++i) {
    int x, y, z;
    std::cin >> x >> y >> z;
    hint[x - 1].push_back(y - 1);
    hint[y - 1].push_back(x - 1);
  }

  std::vector<int> chain;
  int num = 0;

  for (int i = 0; i < N; ++i) {
    int table;
    if (lut[i] == 0) {
      ++num;
      table = num;
      lut[i] = table;
    } else {
      continue;
    }

    for (auto &h : hint[i]) {
      lut[h] = table;
      chain.push_back(h);
    }
    hint[i].clear();

    for (auto &c : chain) {
      for (auto &h : hint[c]) {
        if (lut[h] == 0) {
          lut[h] = table;
          chain.push_back(h);
        }
      }
      hint[c].clear();
    }
  }

  int result = num;

  std::cout << result << std::endl;

  return 0;
}

