				int k = p.top();
				p.pop();
				x = d[k].size();
				rep(i, x) {
					if (used[d[k][i]]) {
						used[d[k][i]] = false;
						p.push(d[k][i]);
					}
				}
				PB(ans, k);
			}
			j = ans.size();
			z -= (j - 1);
		}
	}

	cout << z;

	return 0;
}

