void operation(int start) {
	int i = start;
	for (int j = 0; j < connect[i].size(); j++) {
		if (color[connect[i][j]] == -1) {
			color[connect[i][j]] = 0;
			operation(connect[i][j]);
		}
	}
};

int main() {
	cin >> n >> m;

	for (int i = 0; i < n; i++) {
		degree[i] = 0;
		color[i] = -1;
		vertex.push_back(i);
	}

	for (int i = 0; i < m; i++) {
		int x, y, z;
		cin >> x >> y >> z;

		degree[x - 1]++;
		degree[y - 1]++;
		connect[x - 1].push_back(y - 1);
		connect[y - 1].push_back(x - 1);
	}

	int count = 0;
	bool check = true;

	while (true) {
		if (vertex.empty()) { break; }
		check = false;
		int start;
		while (true) {
			if (color[vertex[vertex.size() - 1]] == -1) {
				start = vertex[vertex.size() - 1];
				vertex.pop_back();
				check = true;
				break;
			}
			vertex.pop_back();

			if (vertex.empty()) { break; }
		}
		if (check == false) { break; }

		color[start] = 0;
		operation(start);
		count++;
	}



	cout << count << endl;
}

