template<typename T>
class UnionFind
{
	public:
	vector<T> parent;

	UnionFind(T n):parent(n)
	{
		for(int i=0;i<n;i++)
			parent[i]=i;
	}

	void unite(T a,T b)
	{
		a=root(a);
		b=root(b);
		if(a==b)return;
		if(a>b)swap(a,b);
		parent[b]=a;
		return;
	}

	T root(T n)
	{
		if(parent[n]==n)
			return n;
		else
		{
			T ret=root(parent[n]);
			parent[n]=ret;
			return ret;
		}
	}
};

