struct Query {
  int x;
  int y;
  int z;

  Query(int x, int y, int z) {
    this->x = x;
    this->y = y;
    this->z = z;
  }
};

int main() {
  int N, M;
  cin >> N >> M;
  init(N + 1);
  vector<Query> query;

  for (int i = 0; i < M; ++i) {
    int x, y, z;
    cin >> x >> y >> z;

    query.push_back(Query(x, y, z));
  }

  for (int i = 0; i < M; ++i) {
    Query q = query[i];

    unite(q.x, q.y);
  }

  int ans = 0;

  bool checked[N + 1];
  memset(checked, false, sizeof(checked));

  for (int i = 0; i < M; ++i) {
    Query q = query[i];

    if (!checked[par[q.x]]) {
      ++ans;
      checked[par[q.x]] = true;
    }

    if (!checked[par[q.y]]) {
      ++ans;
      checked[par[q.y]] = true;
    }
  }

  for (int i = 1; i <= N; ++i) {
    if (checked[par[i]]) continue;
    checked[par[i]] = true;
    ++ans;
  }

  cout << ans << endl;

  return 0;
}

