class UnionFind {
  vector<int> parent;
  vector<int> size;
  vector<int> rank;
  int num_group;

public:
  UnionFind(int n) {
    parent.assign(n, 0);
    size.assign(n, 1);
    rank.assign(n, 0);
    num_group = n;
    for (int i = 0; i < n; i++) {
      parent[i] = i;
    }
  }

  int find_root(int x) {
    return parent[x] == x ? x : parent[x] = find_root(parent[x]);
  }

  void unite(int x, int y) {
    int rx = find_root(x);
    int ry = find_root(y);
    if (rx == ry)
      return;
    if (rank[rx] > rank[ry]) {
      parent[ry] = rx;
      size[rx] += size[ry];
    } else if (rank[rx] < rank[ry]) {
      parent[rx] = ry;
      size[ry] += size[rx];
    } else {
      parent[ry] = rx;
      rank[rx]++;
      size[rx] += size[ry];
    }
    num_group--;
  }

  bool is_same_group(int x, int y) { return find_root(x) == find_root(y); }

  int get_group_size(int x) { return size[find_root(x)]; }

  int get_num_of_groups() { return num_group; }
};

int main() {
  int n, m;
  cin >> n >> m;
  auto uf = UnionFind(n);
  int x, y, z;
  for (int i = 0; i < m; i++) {
    cin >> x >> y >> z;
    x--;
    y--;
    uf.unite(x, y);
  }
  cout << uf.get_num_of_groups() << endl;
}

