	ios::sync_with_stdio(false);

	int N, M; cin >> N >> M;

	UF T(N);

	for (int i = 0; i < M; i++) {
		int tmp1, tmp2, tmp3; cin >> tmp1 >> tmp2 >> tmp3;
		T.unite(tmp1, tmp2);
	}

	set<int> S;
	for (int i = 1; i <= N; i++) {
		int pa = T.parent[i];
		S.insert(pa);
	}

	cout << S.size() << endl;

	return 0;
}

