  }

  UnionFind uf(N);
  uf.init(N);

  for(int i = 0; i < M; i++){
    if(uf.is_same(X[i], Y[i])) continue;
    if(uf.merge(X[i], Y[i])) cn--;
  }

  cout << cn << endl; 
  return 0;
}

