void dfs(vector<int> adj[], bool visited[], int start, int n){
	stack<int> s;
	visited[start]=true;
	s.push(start);
	while(!s.empty()){
		int temp=s.top();
		s.pop();
		vector<int>::iterator i;
		for(i=adj[temp].begin();i!=adj[temp].end();i++){
			if(!visited[*i]){
				s.push(*i);
				visited[*i]=true;
			}
		}
	}
}
