	if (x == y) return;
	if (ranked[x] < ranked[y]) {
		par[x] = y;
		sizeth[y] += sizeth[x];
	}
	else {
		par[y] = x;
		if (ranked[x] == ranked[y]) ranked[x]++;
		sizeth[x] += sizeth[y];
	}
}
