struct UnionFind{
    // par[i] >= 0 --> 親
    // par[i] < 0  --> size
    // rank --> 深さ
    vector<int> par, rank;
    UnionFind(int n){
        par.resize(n,-1);
        rank.resize(n,0);
    }

    int root(int x){
        if(par[x]<0) return x;
        else return par[x]=root(par[x]);
    }

    bool same(int x,int y){
        return root(x) == root(y);
    }

    int size(int x){
        return -par[root(x)];
    }

    void merge(int x,int y){
        x = root(x);
        y = root(y);
        if(x==y) return;
        if(rank[x] < rank[y]) swap(x,y);

        // x <-- y
        par[x]+=par[y]; // fix size
        par[y]=x;
        rank[x]+=(rank[x]==rank[y]);
    }
};

int main(){
    int n,m; cin >> n >> m;
    vector<int> x(m),y(m),z(m);
    UnionFind uf(n);
    rep(i,m){
        cin >> x[i] >> y[i] >> z[i];
        x[i]--; y[i]--;
        z[i] %= 2;
        uf.merge(x[i],y[i]);
    }

    set<int> st;
    rep(i,n){
        st.insert(uf.root(i));
    }
    cout << st.size() << endl;
}

