class UnionFind {
  private:
    std::vector<int> par;
    std::vector<int> sizes;
    std::vector<int> rank;
    int group;

  public:
    UnionFind(int n) : par(n), sizes(n, 1), rank(n, 0), group(n) {
      for(int i = 0; i < n; ++i) par[i] = i;
    }

    int find(int x) {
      if(x == par[x]) return x;
      return par[x] = find(par[x]);
    }

