      x = find(x);
      y = find(y);

      if(x == y) return;

      if(rank[x] < rank[y]) std::swap(x, y);
      par[y] = x;
      sizes[x] += sizes[y];
      if(rank[x] == rank[y]) rank[x]++;
      group--;
    }

    bool same(int x, int y) {
      return find(x) == find(y);
    }

    int size(int x) {
      return sizes[find(x)];
    }

    int groupSize() {
      return group;
    }
};

