    X[i]--;Y[i]--;
    UF.connect(X[i],Y[i]);
    //cout << X[i] << Y[i] << endl;
  }
  int ans = 0;
  rep(i,N){
    if(!check[UF.root(i)]){
      ans++;
      check[UF.root(i)]=1;
    }
  }
  cout << ans << endl;
}

