class UnionFind {
  public:

  //par[i]:parent of i. rank[i]:rank(depth) of the group with i.
  vector<int> par, rank; 

  UnionFind(int n) {
    par = vector<int>(n, -1);
    rank = vector<int>(n, 0);
  }

  int root(int x) {               //root(x):root of x
    return (par[x] < 0) ? x : par[x] = root(par[x]);
  }

  int size(int x) {               //the number of edge of the group with x
    return -par[root(x)];
  }

  bool same(int x, int y) {       //judge whether x & y is in the same group.
    return root(x) == root(y);
  }

  void unite(int x, int y) {      //unite group with x & group with y.
    x = root(x);
    y = root(y);
    if (x == y) return;

    if (rank[x] < rank[y]) swap(x, y);
    par[x] += par[y];
    par[y] = x;
    if (rank[x] == rank[y]) rank[x]++;
  }
};

