struct Xorshift {
  uint64_t x = 88172645463325252LL;
  unsigned next_int() {
    x = x ^ (x << 7);
    return x = x ^ (x >> 9);
  }
  unsigned next_int(unsigned mod) {
    x = x ^ (x << 7);
    x = x ^ (x >> 9);
    return x % mod;
  }
  unsigned next_int(unsigned l, unsigned r) {
    x = x ^ (x << 7);
    x = x ^ (x >> 9);
    return x % (r - l + 1) + l;
  }
  double next_double() {
    return double(next_int()) / UINT_MAX;
  }
} rnd;

template<typename T>
void shuffle_vector(vector<T>& v, Xorshift& rnd) {
  int n = v.size();
  for (int i = n - 1; i >= 1; i--) {
    int r = rnd.next_int(i);
    swap(v[i], v[r]);
  }
}



class DisjointSet {
private:
	vector<unsigned> par;
	vector<unsigned> rank;
	vector<unsigned> sz;	// 要素の個数
	size_t set_sz;			// 集合の個数

public:

	DisjointSet() : set_sz(0) {}

	DisjointSet(size_t n) :
		par(n), rank(n, 0), sz(n, 1), set_sz(n) {
		for (size_t i = 0; i < n; i++) par[i] = i;
	}

	size_t set_size() { return set_sz; }
	size_t size(size_t v) { return sz[find(v)]; }

	void makeset() {
		par.push_back(par.size());
		rank.push_back(0);
		sz.push_back(1);
		set_sz++;
	}
	void makeset(size_t n) {
		for (size_t i = 0; i < n; i++) makeset();
	}

	size_t find(size_t x) {
		if (par[x] == x)
			return x;
		else
			return par[x] = find(par[x]);
	}

	void unite(size_t x, size_t y) {
		x = find(x);
		y = find(y);
		if (x == y) return;

		if (rank[x] < rank[y])
			par[x] = y;
		else {
			par[y] = x;
			if (rank[x] == rank[y]) rank[x]++;
		}
		sz[x] += sz[y];
		sz[y] = sz[x];
		set_sz--;
	}

	bool same(size_t x, size_t y) {
		return find(x) == find(y);
	}

	friend ostream& operator<<(ostream& ostr, const DisjointSet& ds) {
		ostr << endl << "parent : " << ds.par << endl << "rank : " << ds.rank << endl << "size : " << ds.sz << endl << "size of set : " << ds.set_sz << endl;
		return ostr;
	}
};



int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

	int N, M;
	cin >> N >> M;
	DisjointSet ds(N);
	REP(i, M) {
		int x, y, z;
		cin >> x >> y >> z;
		x--; y--;
		ds.unite(x, y);
	}

	cout << ds.set_size() << endl;

  return 0;
}

