const int max_n = 100000+10;

class UnionFind {
    private:
        int par[max_n];
        int rank[max_n];
    public:
        UnionFind(int n) {
            for(int i = 1;i <= n;i++) {
                par[i] = i;
                rank[i] = 1;
            }
        }

        int root(int x) {
            return x == par[x] ? par[x] : par[x] = root(par[x]);
        }

        bool same(int x, int y) {
            return par[x] == par[y];
        }

        void merge(int x,int y) {
            x = root(x);
            y = root(y);
            if(same(x,y))
                return;
            if(rank[x] < rank[y]) {
                par[x] = y;
                rank[x]++;
            } else {
                par[y] = x;
                if(rank[x] == rank[y])
                    rank[y]++;
            }

            return;
        }

        int connect(int n) {
            int c = 0;
            for(int i = 1;i <= n;i++)
                if(par[i] == i)
                    c++;

            return c;
        }
};
