lli ans = 0;
struct Node{
    lli data;
    bool inSubset;
    Node* parent;
    lli rank;
};
map <lli, Node*> m;
void makeSet(lli data){
    Node* node = new Node();
    node->data = data;
    node->parent = node;
    node->rank = 0;
    node->inSubset = false;
    m[data] =node;
    //return node;
}
Node* findSet(Node* node){
    if(node->parent == node)return node;
    node->parent = findSet(node->parent);
}
void unionSet(lli a, lli b){
    Node *node1 = m[a];
    Node *node2 = m[b];
    if (node1 == node2)return;
    if(!node1->inSubset && !node2->inSubset){
        ans++;
    }
    Node *parent1 = findSet(node1);
    Node *parent2 = findSet(node2);
    if(parent1->data == parent2->data){
        return;
    }
    if(parent1->rank>=parent2->rank){
        parent1->rank = (parent1->rank == parent2->rank)?parent1->rank+1:parent1->rank;
        parent2->parent = parent1;

    }else{
        parent1->parent = parent2;
    }
    node1->inSubset = true;
    node2->inSubset = true;
}
