struct UnionFind{
    vector<int> rank, p;
    UnionFind(int N){
            rank.resize(N, 0);
            p.resize(N, 0);
            for(int i=0; i < N; i++) makeSet(i);
    }
    void makeSet(int x){
            p[x] = x;
            rank[x] = 0;
    }
    bool same(int x, int y){
            return findSet(x) == findSet(y);
    }
    void unite(int x, int y){
            link(findSet(x), findSet(y));
    }
    void link(int x, int y){
            if(rank[x] > rank[y]){
                    p[y] = x;
