                    p[x] = y;
                    if(rank[x] == rank[y]){
                            rank[y]++;
                    }
            }
    }
    int findSet(int x){
            if(x != p[x]){
                    p[x] = findSet(p[x]);
            }
            return p[x];
    }
};

