class DisjointSets {
    class Node {
        public: 
        int parent = -1;
        int rank = 0;
        int degree = 1;
    };

private:
    Node *nodes;

    void make_set(int x) {
        nodes[x].parent = x;
        nodes[x].rank = 0;
        nodes[x].degree = 1;
    }

public:
    int find_set(int x) {
        if(nodes[x].parent == x)
            return x;

        //経路圧縮
        nodes[x].rank = 0;
        return nodes[x].parent = find_set(nodes[x].parent);
    }

    int count = 0;

    DisjointSets(){}
    DisjointSets(int length) {
        nodes = (Node *)malloc(sizeof(Node) * length);
        count = length;

        for(int i = 0; i < length; ++i)
            make_set(i);
    }

    ~DisjointSets() {
        free(nodes);
    }

    int degree(int x) {
        return nodes[find_set(x)].degree;
    }

    void unite(int x, int y) {
        int set_x = find_set(x);
        int set_y = find_set(y);
        if(set_x == set_y) return;
        --count;

        if(nodes[x].rank < nodes[y].rank) {
            nodes[set_x].parent = set_y;
            nodes[y].degree += nodes[x].degree;
        } else if(nodes[x].rank > nodes[y].rank) {
            nodes[set_y].parent = set_x;
            nodes[x].degree += nodes[y].degree;
        } else {
            nodes[set_y].parent = set_x;
            nodes[x].rank++;
            nodes[x].degree += nodes[y].degree;
        }
    }

    bool same(int x, int y) {
        int set_x = find_set(x);
        int set_y = find_set(y);
        return set_x == set_y;
    }
};

int N, M;
int main(int argc, char **argv) {
    cin >> N >> M;

    DisjointSets *sets = new DisjointSets(N * 2);
    /*
        A_iについて
            偶数である事象...2 * i
            奇数である事象...2 * i + 1
    */

    for(int i = 0; i < M; ++i) {
        int X, Y, Z;
        cin >> X >> Y >> Z;
        X--;
        Y--;
        if(Z % 2 == 0) {
            sets->unite(2 * X, 2 * Y);
            sets->unite(2 * X + 1, 2 * Y + 1);
        } else {
            sets->unite(2 * X + 1, 2 * Y);
            sets->unite(2 * X, 2 * Y + 1);
        }
    }

    int groups = 0;
    set<int> new_num;
    for(int i = 0; i < 2 * N; ++i) {
        int root = sets->find_set(i);
        if(new_num.find(root) == new_num.end()) {
            new_num.insert(root);
            ++groups;
        }
    }

    delete sets;
    cout << (groups + 1) / 2 << endl;
}

