// 連結成分の番号を振る関数
void dfs(int n, int comp[], vector<int> G[]) {
    int i, j, vertex, neighbor, color[N] ,inst[N];
  stack<int> S;
  // 初期状態
    for (i = 0; i < n; i++) {
        color[i] = WHITE;
        inst[i]=WHITE;
    }

  for (i = 0; i < n; i++) {
    if (color[i] == WHITE) {
      // dfs
      S.push(i);
      while (!S.empty()) {
        vertex = S.top();
        S.pop();
        color[vertex] = BLACK;  // 訪問済みにする
        comp[vertex] = i;  // 連結成分の番号を振る
          if(inst[vertex]==WHITE){
              component[i]+=1;
              inst[vertex]=BLACK;
          }
          //cout << component[i] << endl;
        for (j = 0; j < (int) G[vertex].size(); j++) {
          neighbor = G[vertex][j]; // 隣接している頂点：友人
            if (color[neighbor] == WHITE) {
                S.push(neighbor);

            }
        }
      }
    }
  }
}

