using namespace std;
using ll = long long;
using p = pair<int, ll>;

class UnionFind
{
    vector<p> data;
public:
    UnionFind(int N)
    {
        data.resize(N+1);
        lpn(i, N+1) data[i] = {i, 1};
    }
    int root(int i)
    {
        if (data[i].first == i) return i;
        auto r = root(data[i].first);
        data[i] = {r, data[r].second};
        return r;
    }
    ll size(int i)
    {
        return data[root(data[i].first)].second;
    }
    void unite(int i, int j)
    {
        auto ri = root(i), rj = root(j);
        if (ri == rj) return;
        data[ri] = data[rj] = data[i] = data[j] = {min(ri, rj), size(i) + size(j)};
    }
};

int main(void)
{
    int N, M;
    cin >> N >> M;
    UnionFind uf(N);
    int X, Y, Z;
    while(M--)
    {
        cin >> X >> Y >> Z;
        uf.unite(X, Y);
    }
    int ans = 0;
    lpn(i, N) if (i+1 == uf.root(i+1)) ans++;
    cout << ans << endl;
    return 0;
}

