const int MAXN = 1e5 + 5;
int father[MAXN]; int sz[MAXN];

int grs;
void init(int n) {

    for (int i = 0; i <= n; ++i) {
        father[i] = i;
        sz[i] = 1;
    }
}

int find(int u) {

    return father[u] == u ? u : father[u] = find(father[u]);
}

void join(int u, int v) {

    int fatheru = find(u);
    int fatherv = find(v);
    if (fatheru == fatherv) return;
    father[fatheru] = fatherv;
    sz[fatheru] += sz[fatherv];
    sz[fatherv] = fatheru;
    grs--;
   // std::cout << grs;
}

int main(){
    int n,m;
    std::cin >> n >> m;
    grs = n;
    init(n + 1);
    int x,y,z;
    for(int i = 1; i <= m; ++ i){
        std::cin >> x >> y >> z;
        join(x,y);
    }
    std::cout << grs;
}

