class UnionFind {
public:
	UnionFind( int n )
	{
		par.resize( n );
		siz.resize( n );

		rep( i, n )
		{
			par[i] = i;
			siz[i] = 1;
		}
	}

	int find( int x )
	{
		if ( x == par[x] ) return ( x );
		else return ( par[x] = find( par[x] ) );
	}

	void unite( int x, int y )
	{
		int pX = find( x );
		int pY = find( y );
		if ( pX == pY ) return;

		if ( siz[pX] < siz[pY] )
		{
			par[pY] = pX;
			siz[pX] += siz[pY];
		}
		else
		{
			par[pX] = pY;
			siz[pY] += siz[pX];
		}
	}

private:
	vector<int> par;
	vector<int> siz;
};

