void initialize(){
    for(int i = 1; i <= 100000; i++){
        parent[i] = i;
        size[i] = 1;
    }
}

int fparent(int x){
    if(parent[x]!=x){
        parent[x] = fparent(parent[x]);
    }
    return parent[x];
}

void uni(int a , int b){
    pa = fparent(a);
    pb = fparent(b);
    if(pa == pb){
        return;
    }
    else{
      if(size[pa] > size[pb]){
          size[pa] = size[pa]+size[pb];
          parent[pb]=parent[pa];
      }
      else{
          size[pb] = size[pa]+size[pb];
          parent[pa]=parent[pb];
      }
    }
}

