    UnionFind tree(n);
    while(m--){
        ll x,y,z; cin >> x >> y >> z;
        x--; y--;
        tree.unite(x,y);        
    }
    ll cnt = 0;
    rep(i,n){
        if(tree.par[i]==i) cnt++;
    }
