template <typename T> struct DisjointSet {
    vector<T> rank, p;
    void link(T x, T y) {
        if (rank[x] > rank[y]) {
            p[y] = x;
        } else {
            p[x] = y;
            if (rank[x] == rank[y]) { rank[y]++; }
        }
    }
    DisjointSet() {}
    DisjointSet(const DisjointSet& tree) : rank(tree.rank), p(tree.p) {}
    DisjointSet(T size) : rank(size, 0), p(size, 0) {
        rep(i, 0, size) { make_set(i); }
    }
    void make_set(T x) {
        p[x] = x;
        rank[x] = 0;
    }
    bool same(T x, T y) { return find_set(x) == find_set(y); }
    void unite(T x, T y) { link(find_set(x), find_set(y)); }
    T find_set(T x) {
        if (x != p[x]) {
            p[x] = find_set(p[x]);
            rank[x] = 1;
        }
        return p[x];
    }
    int get_size() {
        set<int> s;
        for (int i : p) { s.insert(find_set(i)); }
        return s.size();
    }
};

