	vector<card>a(m);
	for (int i = 0; i < m; i++) {
		int e;
		cin >> a[i].x >> a[i].y >> e;
		a[i].x--;
		a[i].y--;
	}
	sort(a.begin(), a.end(), cmp);
	vector<int>d(n, -1);
	for (int i = m-1; i >= 0; i){
		bool check = 0;
		int id = -1;
		int j = i;
		for (; j >= 0 && a[j].x == a[i].x; j--){
			if (d[a[i].y] != -1)
