typedef long long ll;
const int MAX_N = 100001;
int par[MAX_N], uniteRank[MAX_N];

void uniteInit(int n){
    for (int i = 0; i < n; i++) {
        par[i] = i;
        uniteRank[i] = 0;
    }
}

int root(int x){
    return par[x] == x ? x : par[x] = root(par[x]);
}

bool same(int x, int y){
    return root(x) == root(y);
}

void unite(int x, int y){
    x = root(x);
    y = root(y);
    if(x == y) return;
    if(uniteRank[x] < uniteRank[y]){
        par[x] = y;
    } else {
        par[y] = x;
        if(uniteRank[x] == uniteRank[y]){
            uniteRank[x]++;
        }
    }
}

int main()
{
    int N, M;
    cin >> N >> M;
    uniteInit(N + 1);
    for(int i = 0; i < M; i++)
    {
        int x, y, z;
        cin >> x >> y >> z;
        unite(x, y);
    }
    int answer = 0;
    for(int i = 1; i <= N; i++)
    {
        if(par[i] == i)
        {
            answer++;
        }
    }
    cout << answer << endl;
    return 0;
}

