const ll MAX = 100000 + nya;

int main(void)
{
	ll N, M; cin >> N >> M;
	vt<ll> X(M), Y(M), Z(M); // x[0, N-1] y[0, N-1]
	rep(i, 0, M)
	{
		cin >> X[i] >> Y[i] >> Z[i];
		X[i]--; Y[i]--; Z[i]--;
	}

	vt<ll> xycount(N);
	rep(i, 0, M)
	{
		xycount[X[i]]++;
		xycount[Y[i]]++;
	}

	ll ans = 0;
	vt<bool> unk(N, true);
	UnionFind uf(MAX);
	rep(i, 0, M)
	{
		if (xycount[Y[i]] <= xycount[X[i]]) uf.Union(X[i], Y[i], X[i]);
		else uf.Union(X[i], Y[i], Y[i]);
	}

	rep(i, 0, M)
	{
		unk[X[i]] = (uf.Find(X[i]) == X[i]) ? true : false;
		unk[Y[i]] = (uf.Find(Y[i]) == Y[i]) ? true : false;
	}

	rep(i, 0, N) if (unk[i]) ans++;
	cout << ans;
	return 0;
}

