    bool unionSet(int x, int y) {   //併合
        x = root(x); y = root(y);
        if (x != y) {
            if (data[y] < data[x]) swap(x, y);
            data[x] += data[y]; data[y] = x;    //統合後のroot(data[x])さえ更新すれば，findSetで後々更新できる
        }
        return x != y;
    }
