	for (int i = 1; i <= n; ++i) f[i] = i;
	int ans = 0;
	sort(e + 1, e + cnt + 1, cmp);
	for (int i = 1; i <= cnt; ++i) {
		int x = find(e[i].u), y = find(e[i].v);
		if (x != y) {
			ans += e[i].w;
			f[y] = x;
		}
	}
	printf("%d\n", ans);

	return 0;
}

