# define MAX_N 1000010 // 10^6 + 10
class UnionFind{
    private:
        int par_[MAX_N];
        int rank_[MAX_N];
        int groups_;

    public:
        void init(int n){ // initializes the tree 
            for(int i=0; i<n; i++){
                par_[i] = i;
                rank_[i] = 0;
            }
            groups_ = n;
        } 
        int rootOf(int x){ // returns the root of x 
            if(par_[x] == x){
                return x;
            }
            else{
                return par_[x] = rootOf(par_[x]);
            }
        } 
        void unite(int x, int y){ // unites x and y 
            x = rootOf(x);
            y = rootOf(y);
            if(x == y) return;
            if(rank_[x] < rank_[y]){
                par_[x] = y;
                groups_--;
            }
            else{
                par_[y] = x;
                groups_--;
                if(rank_[x] == rank_[y]) rank_[x]++;
            }
        }
        bool isSameGroupe(int x, int y){ // whether x and y are united
            return rootOf(x) == rootOf(y);
        }
        int countGroups(){ // returns the number of groups
            return groups_;
        }
};

int main(void){
    int n, m;
    cin >> n >> m;

    UnionFind tree;
    tree.init(n);

    vector<int> x(m), y(m), z(m);
    for(int i=0; i<m; i++){
        cin >> x[i] >> y[i] >> z[i];
        tree.unite(x[i], y[i]);
    }

    int ans = tree.countGroups();
    cout << ans << endl;
    return 0;
}

