class UnionFind {
  using ll = long long;
  vector<ll> info;
  // 親、もしくは根の場合はそのsize*-1
  int num_group;

public:
  UnionFind(int n) {
    info.assign(n, -1);
    num_group = n;
  }

  int find_root(int x) {
    return info[x] < 0 ? x : info[x] = find_root(info[x]);
  }

  void unite(int x, int y) {
    // union-by-size
    int rx = find_root(x);
    int ry = find_root(y);
    if (rx == ry)
      return;
    if (info[rx] > info[ry])
      swap(rx, ry);
    info[ry] = rx;
    info[rx] += info[ry];
    num_group--;
  }

  bool is_same_group(int x, int y) { return find_root(x) == find_root(y); }

  int get_group_size(int x) { return -info[find_root(x)]; }

  int get_num_of_groups() { return num_group; }
};

int main() {
  int n, m;
  cin >> n >> m;
  auto uf = UnionFind(n);
  int x, y, z;
  for (int i = 0; i < m; i++) {
    cin >> x >> y >> z;
    x--;
    y--;
    uf.unite(x, y);
  }
  cout << uf.get_num_of_groups() << endl;
}

