int root(int v) {
    if (P[v] < 0) {
        return v;
    } else {
        P[v] = root(P[v]);
        return P[v];
    }
}

bool set_union(int v1, int v2) {
    int root_v1 = root(v1);
    int root_v2 = root(v2);

    if (root_v1 == root_v2) {
        return false;
    }

    if (P[root_v1] < P[root_v2]) {
        swap(root_v1, root_v2);
    }

    P[root_v2] = P[root_v1] + P[root_v2];
    P[root_v1] = root_v2;

    return true;
}

