class UnionFind
{
public:
	explicit UnionFind(int size)
		: mParent(size, -1)
		, mRank(size, 0)
        , mData(size, 0)
		{}
	bool unionSet(int x, int y)
	{
		if ((x = root(x)) == (y = root(y)))
			return false;
		if( mRank[x] < mRank[y] )
		{
			mParent[y] += mParent[x];
			mParent[x] = y;
            unionData( mData[y], mData[x] );
		}
		else
		{
			mParent[x] += mParent[y];
			mParent[y] = x;
			if( mRank[x] == mRank[y] ) ++mRank[x];
            unionData( mData[x], mData[y] );
		}
		return true;
	}
	bool isEqualSet(int x, int y)
	{
		return root(x) == root(y);
	}
	int root(int x)
	{
		return mParent[x] < 0 ? x : mParent[x] = root(mParent[x]);
	}
	int size(int x)
	{
		return -mParent[root(x)];
	}

	void unionData( int& parent, int& child )
	{
			parent += child;
	}
	void setData( int x, int data )
	{
			mData[root(x)] = data;
	}
	int getData( int x )
	{
			return mData[root(x)];
	}

private:
	vector<int> mParent; // = mSize
	vector<int> mRank;
	vector<int> mData;
};

int main()
{
	int n,m;cin>>n>>m;

	UnionFind uf(n);
	REP(i,m)
	{
		int x,y,z;cin>>x>>y>>z;
		uf.unionSet(x-1,y-1);
	}

	vector<int> v( n, 0 );
	int sum = 0;
	REP(i,n)
	{
		int head = uf.root(i);
		if( v[head] == 1 ) continue;
		v[head] = 1;
		++sum;
	}

	cout << sum << endl;
	return 0;
}

