typedef long long int lli;

class UnionFind {
private:
    vector<int> data;

public:
    UnionFind(int size) : data(size, -1) { }

    int root(int x) {
        return (data[x] < 0) ? x : data[x] = root(data[x]);
    }

    bool unite(int x, int y) {
        x = root(x);
        y = root(y);

        if (x != y) {
            if (data[y] < data[x]) swap(x, y);
            data[x] += data[y];
            data[y] = x;
        }
        return x != y;
    }

    bool find(int x, int y) {
        return root(x) == root(y);
    }

    int size(int x) {
        return -data[root(x)];
    }
};

int main() {
    int n, m, x, y, z;

    cin >> n >> m;

    UnionFind uf(n+1);
    for (int i=0; i<m; i++) {
        cin >> x >> y >> z;
        uf.unite(x, y);
    }

    int ans = 0;
    for (int i=1; i<=n; i++) {
        if (uf.root(i) == i) ans++;
    }

    cout << ans << endl;

    return 0;
}

