    return parents.size();
  }

  Abel weight(int x) {
    root(x);
    return diff_weight[x];
  }

  bool issame(int x, int y) {
    return root(x) == root(y);
  }

  // root(y) と root(x) を merge する
  // その際に weight(y) - weight(x) = w を満たすようにする.
  bool merge(int x, int y, int w) {
    w += weight(x); w -= weight(y);
    x = root(x); y = root(y);

    if (x == y) return false;
    if (rank[x] < rank[y]) swap(x, y), w = -w;
    par[y] = x;
    diff_weight[y] = w;
    return true;
  }

  Abel diff(int x, int y) {
    return weight(y) - weight(x);
  }
};

signed main() {
  int N, M; cin >> N >> M;
  UnionFind<int> Tree(N, 0);

  for (int i = 0; i < M; i++) {
    int x, y, z; cin >> x >> y >> z;
    x--; y--;
    if (!Tree.issame(x, y)) {
      Tree.merge(x, y, (z % 2));
    } else {
      if (abs(Tree.diff(x, y)) != (z % 2)) {
        assert(false);
      }
    }
  }


  for (auto x: Tree.par) {
    Parents.insert(x);
  }
  cout << Parents.size() <<  endl;
}

