struct UnionFind
{
	UnionFind(int n) : par(n), rank(n, 0) {
		iota(par.begin(), par.end(), 0);
	}
	int Find(int i)
	{
		if (par[i] == i)
			return i;
		else
			return par[i] = Find(par[i]);
	}
	void Unite(int i, int j)
	{
		i = Find(i);
		j = Find(j);
		if (i == j)
			return;
		if (rank[i] < rank[j])
		{
			par[i] = j;
		}
		else
		{
			par[j] = i;
			if (rank[i] == rank[j])
				++rank[i];
		}
	}
	vector<int> par;
	vector<int> rank;
};

