class UnionFind{
    public:
        vector<int> rank,parent;
        //コンストラクタ
        UnionFind(int n){
            rank.resize(n,0);
            parent.resize(n,0);
            for(int i=0;i<n;i++){
                parent[i]=i;
                rank[i]=0;
            }
        }

        //根を求める(代表元を求める)
        int find_root(int x){
            if(parent[x]==x)
                return x;
            else
                return parent[x] = find_root(parent[x]);
        }

        //xとyの属する集合を併合
        void unite(int x,int y){
            //x,yをそれぞれの属する集合の代表元にする
            x = find_root(x);
            y = find_root(y);
            //代表元が同じならすでに同じ集合
            if(x==y) return;

            if(rank[x]<rank[y]){
                //xよりyの木の高さが高い時はxの親をyにする
                parent[x]=y;
            }else{
                //xよりyの木の高さが低い時はyの親をxにする
                parent[y]=x;
                //xとyの木の高さが等しい時はxの高さが1増える
                if(rank[x]==rank[y]) rank[x]++;
            }
        }

        //xとyが同じ集合に属するか?
        bool same(int x,int y){
            return find_root(x)==find_root(y);
        }
};

