  UnionFind uf_tree(N);

  while (M--) {
    int X, Y, Z; cin >> X >> Y >> Z;
    X--; Y--;
    uf_tree.unite(X, Y);
  }
  cout << uf_tree.size() << endl;
  return 0;
}

