//union find木(グループわけができる)
int par[200005];
int unifind(int n) {
	for (int i = 1; i <= n; i++) {
		par[i] = i;
	}
	return 0;
}
//木の根を求める
int unifind_root(int x) {
	if (par[x] == x) {
		return x;
	}
	else {
		return par[x] = unifind_root(par[x]);
	}
}
//同じグループか判定
bool unifind_same(int x, int y) {
	return unifind_root(x) == unifind_root(y);
}
//グループ併合
int unifind_unite(int x, int y) {
	x = unifind_root(x);
	y = unifind_root(y);
	if (x == y) {
		return 0;
	}
	par[x] = y;
}

int main() {
	map<long long int, long long int>mp;
	//cout << fixed << setprecision(10);
	long long int n, m, u[200000], v[200000], w[200000], memo[200005] = {},res=0;
	long double x = 0;
	string str, str2;
	cin >> n>>m;
	unifind(2 * n);
	for (int i = 1; i <=m; i++) {
		cin >> u[i] >> v[i] >> w[i];
		if (w[i] % 2 == 0) {
			unifind_unite(u[i], v[i]);
			unifind_unite(u[i] + n, v[i] + n);
		}
		else {
			unifind_unite(u[i], v[i] + n);
			unifind_unite(u[i] + n, v[i]);
		}
	}
	for (int i = 1; i <= n; i++) {
		if (memo[unifind_root(i)]==0&&memo[unifind_root(i+n)]==0) {
			res++;
			memo[unifind_root(i+n)]++;
			memo[unifind_root(i+n)]++;
		}
	}
	cout << res;
}

