        v[x].push_back(y);
        v[y].push_back(x);
    }
    priority_queue<pii>pq;
    for(int i=1;i<=n;i++){
        pq.push(MP(edge[i],i));
    }
    memset(edge,0,sizeof edge);
    int cost=0;
    while(!pq.empty()){
        pii t=pq.top();
        pq.pop();
        if(edge[t.ss]==0){
            cost++;
            edge[t.ss]=1;
        }
        for(int i=0;i<v[t.ss].size();i++){
            int next_=v[t.ss][i];
            edge[next_]=1;
        }
    }
    printf("%d\n",cost);
}

