    int root(int x) {
        if( data[x] < 0 ) { return x; }
        return data[x] = root( data[x] );
    }
public:
    UnionFind(int n) :data( vector<int>(n,-1) ) {}
    bool unite(int x, int y) { // 元々同じ素集合ならtrue, 別の集合同士を結合させたならfalse
        x = root(x); y = root(y);
