const int maxn = 1e5+1;

int n, m;

int p[maxn];
bool d[maxn];
bool determined[maxn];
void init(int n)
{
  for (int i = 1; i <= n; ++i)
    {
      p[i] = i; d[i] = false; determined[i] = false;
    }
}
int pa(int x)
{
  if (x != p[x])
    {
      int last_p = p[x];
      p[x] = pa(last_p);
      d[x] = d[x] ^ d[last_p];
    }
  return p[x];  
}
void merge(int from, int to, bool dis)
{
  int from_p = pa(from);
  int to_p = pa(to);
  if (from_p != to_p)
    {
      p[from_p] = to_p;
      d[from_p] = d[from] ^ d[to] ^ dis;
    }
}

int main()
{
  scanf("%d %d", &n, &m);
  init(n);
  vector<int> v;
  for (int i = 1; i <= m; ++i)
