      bool dis = z&1;
      if (x == y) v.pb(x);
      else merge(x, y, dis);
    }
  for (auto e : v) determined[pa(e)] = true;
  int ans = 0;
  for (int i = 1; i <= n; ++i)
    if (pa(i) == i)
      ans += !determined[i];
