// #define DEBUG

void solve(long long N, long long M, std::vector<long long> X, std::vector<long long> Y, std::vector<long long> Z){
    vec<ll> covered(N);
    vec2<int> derives(N);
    vec<bool> fixed(N);
    ll NumFixed = 0;
    ll cost = 0;

    // shift
    for(int i=0; i < M; i++){
        X.at(i)--;
        Y.at(i)--;
    }

    // 下準備
    // derivesをつくる
    for(int i=0; i < M; i++){
        derives.at(X.at(i)).push_back(Y.at(i));
        derives.at(Y.at(i)).push_back(X.at(i));
        covered.at(X.at(i))++;
        covered.at(Y.at(i))++;
    }

    #ifdef DEBUG
    printf("*START: hoge\n");
    for(auto iter: covered){
        cout << iter << " ";
    }
    cout << endl;
    for(int i=0; i < N; i++){
        cout << i << ": ";
        for(auto iter: derives.at(i)){
            cout << iter << ", "; 
        }
        cout << endl;
    }
    printf("*END: hoge\n");
    #endif

    vec<pair<ll, int>> covered2;
    for(int i=0; i < N; i++){
        covered2.push_back(pair<ll, int>(-covered.at(i), i));
    }
    sort(covered2.begin(), covered2.end());

    // solve
    for(auto iter: covered2){
        int pos = iter.second;
        if(fixed.at(pos)){
            continue;
        }

        // posを確定
        fixed.at(pos) = true;
        NumFixed++;
        cost++;

        // はせいして確定
        for(auto iter2: derives.at(pos)){
            if(fixed.at(iter2)){
                continue;
            }
            fixed.at(iter2) = true;
            NumFixed++;
        }
        #ifdef DEBUG
        printf("*START: hogehoge\n");
        printf("Pos %d is fixed\n", pos);
        for(auto iter: fixed){
            cout << iter << " ";
        }
        cout << endl;
        printf("*END: hogehoge\n");
        #endif
    }

    cout << cost << endl;


}

