class unionfind {
  vector<int> v;
  int component_count;

  int size(int n) {
    return -v[root(n)];
  }

  int root(int n) {
    return v[n] < 0 ? n : v[n] = root(v[n]);
  }

public:

  unionfind(int n)
    : v(n, -1), component_count(n) {}

  unionfind(int n, vector<pair<int, int>> vp)
    : unionfind(n)
  {
    unite(vp);
  }

  void unite(int a, int b) {
    int ra = root(a);
    int rb = root(b);
    if (ra != rb) {
      component_count--;
      if (size(ra) < size(rb)) swap(ra, rb);
      v[ra] += v[rb];
      v[rb] = ra;
    }
  }

  void unite(vector<pair<int, int>> v) {
    for (auto&& e : v) {
      unite(e.first, e.second);
    }
  }

  int num_set() {
    return component_count;
  }
};

