typedef pair<int, int> edge;

void evenOfOdd_dfs(vector<edge> *c, vector<int> &dist, int start = 0) {
  dist[start] = 0;
  stack<int> s;
  s.push(start);
  while (!s.empty()) {
    int current = s.top();
    s.pop();
    for (const auto &e : c[current]) {
      if (dist[e.first] == -1) {
        s.push(e.first);
        dist[e.first] = (dist[current] + e.second) % 2;
      }
    }
  }
}

