    y--;
    c[x].push_back(make_pair(y, z));
    c[y].push_back(make_pair(x, z));
  }

  vector<int> dist(n, -1);

  evenOfOdd_dfs(c, dist, 0);

  for (const auto &var : dist) {
    cout << var % 2 << endl;
  }

