int find(int i){
    while(parent[i] != i)
        i = parent[i];
    return i;
}
void merge(int i , int j){
    int a = find(i) , b = find(j);
    if(a == b)
        return ;
    else if(size[a] > size[b]){
        size[a] += size[b];
        parent[j] = a;
    }
    else
    {
        size[b] += size[a];
        parent[i] = b;
    }
}

