typedef long long ll;
#define NODE_MAX 100000
ll par[NODE_MAX],rk[NODE_MAX];
void init(){
  for(int i=0;i<NODE_MAX;i++){
    par[i]=i;
    rk[i]=0;
  }
}
int root(int x){
  if(x==par[x]) return x;
  return par[x]=root(par[x]);
}
void unite(int x,int y){
  x = root(x);
  y = root(y);
  if(x==y) return;

  if(rk[x]<rk[y]){
    par[x] = y;
  }else{
    par[y] = x;
    if(rk[x]==rk[y]) rk[x]++;
  }
}
bool same(int x,int y){
  return root(x)==root(y);
}
int main(){
  ll n,m,cnt=0,rt;
  cin >> n >> m;
  init();
  ll x[n],y[n],z[n];
  bool know[n];
  for(int i=0;i<m;i++){
    know[i]=false;
    cin >> x[i]>>y[i]>>z[i];
    x[i]--;
    y[i]--;
    unite(x[i],y[i]);
  }
  for(int i=0;i<n;i++){
    rt = root(i);
    if(know[rt]==false){
      know[rt]=true;
      cnt++;
    }
  }
  cout << cnt <<endl;
}

