struct Group {
  std::set <int> A;
  std::set <int> B;
};

std::list <Group> pairs;

int go (bool yes_, int a, int b)
{
  std::list<Group>::iterator pair_has_a;
  std::list<Group>::iterator pair_has_b;

  for(auto itr=pairs.begin(); itr != pairs.end(); ++itr) {
    if ( itr->A.count(a) || itr->B.count(a) ) {
      pair_has_a = itr;
      break;
    }
  }

  for(auto itr=pairs.begin(); itr != pairs.end(); ++itr) {
    if ( itr->A.count(b) || itr->B.count(b) ) {
      pair_has_b = itr;
      break;
    }
  }

  if ( pair_has_a == pair_has_b ) {
    bool pair_A = pair_has_a->A.count(a) ? true : false ; // true -> a in A
    bool pair_B = pair_has_b->A.count(b) ? true : false ; // true -> b in A

    // Contradiction : return -1
    if ( (!yes_) && ((pair_A &&  pair_B)||(!pair_A && !pair_B)) )  return -1;
    if (   yes_  && ((pair_A && !pair_B)||(!pair_A &&  pair_B)) ) return -1;

    // Equivalent representation : through
    return 0;
  }

  if ( pair_has_a != pair_has_b ) {
    if ( pair_has_a->B.count(a) ) pair_has_a->A.swap(pair_has_a->B);
    if ( pair_has_b->B.count(b) ) pair_has_b->A.swap(pair_has_b->B);

    if ((!yes_)) pair_has_b->A.swap(pair_has_b->B);

    // merge
    for(auto itr = pair_has_b->A.begin(); itr != pair_has_b->A.end(); ++itr) {
      pair_has_a->A.insert(*itr);
    }
    for(auto itr = pair_has_b->B.begin(); itr != pair_has_b->B.end(); ++itr) {
      pair_has_a->B.insert(*itr);
    }

    // delete
    pairs.erase(pair_has_b);
    return 0;
  }
  return 1;
}


int main (void) {
  int N, M;
