class UnionFindTree {
   private:
    UnionFindTree* parent;

   public:
    UnionFindTree() { parent = this; }
    UnionFindTree* root() {
        UnionFindTree* p = parent;
        while (p != p->parent) p = p->parent;
        return p;
    }
    void unite(UnionFindTree* target) { root()->parent = target->root(); }
    bool isSame(UnionFindTree* target) { return root() == target->root(); }
};

