    DisjointSet ds(n+1);
    rep(i, m) {
        int x, y, z; cin >> x >> y >> z;
        ds.unite(x, y);
    }

    int ans = 0;
    loop(i, 1, n+1) if(i == ds.p[i]) ans++;
    cout << ans << endl;

