    void initialize(ll sz) {
        par.resize(sz);
        siz.assign(sz, 1LL);
        REP(i, sz) par[i] = i;
        node_size = sz;
    }
    ll root(ll x) {
        while(par[x] != x) {
            x = par[x] = par[par[x]];
        }
        return x;
    }
    bool unite(ll x, ll y) {
        x = root(x);
        y = root(y);
        if(x == y) return false;
        if(siz[x] < siz[y]) swap(x, y);
        siz[x] += siz[y];
        par[y] = x;
        return true;
    }
    bool find(ll x, ll y) {
        return root(x) == root(y);
    }
    ll size(ll x) {
        return siz[root(x)];
    }
    map<ll, ll> islands() {
        set<ll> st;
        REP(i, node_size) {
            st.insert(root(i));
        }
        map<ll, ll> ret;
        for(auto &s:st) {
            ret[s] = size(s);
        }
        return ret;
    }
};

void solve() {
    ll N, M;
    cin >> N >> M;
    UF uf(N);
    REP(i, M) {
        ll x, y, z;
        cin >> x >> y >> z;
        uf.unite(x - 1, y - 1);
    }
    out(uf.islands().size());
}

