struct union_find{
    vector<int> par;
    int par_siz;
    union_find(int n) : par(n){
        par_siz = n;
        for(ll i=0;i<n;i++)par[i]=-1; //init
    }
    int root(int x){
        if(par[x]<0)return x;
        else return par[x] = root(par[x]);
    }

    void unite(int p1,int p2){
        int pa1 = root(p1),pa2 = root(p2);
        if(pa1==pa2)return;
        if(par[pa1]>par[pa2]){ // |pa1| < |pa2|
            par[pa2] += par[pa1];
            par[pa1] = pa2;
        }else{ // |pa1| > |pa2|
            par[pa1] += par[pa2];
            par[pa2] = pa1;
        }
        par_siz--;
    }
    int size(int x){ return (-1)*par[root(x)]; }
    int par_size(){return par_siz;}
    bool same(int p1,int p2){ return root(p1) == root(p2); }
};

