class DisjointSet {
public:
	vector<int> rank, p;
	int set_size;

	void link(int x, int y) {
		if (rank[x] > rank[y]) {
			p[y] = x;
		}
		else {
			p[x] = y;
			if (rank[x] == rank[y]) rank[y]++;
		}
	}
	int findSet(int x) {
		if (x != p[x]) p[x] = findSet(p[x]);
		return p[x];
	}

	DisjointSet() { set_size = 0; }
	DisjointSet(int size) {
		rank.resize(size, 0);
		p.resize(size, 0);
		set_size = 0;
		repc(i, 1, size) makeSet(i);
	}
	void makeSet(int x) {
		p[x] = x;
		rank[x] = 0;
		set_size++;
	}
	bool same(int x, int y) {
		return findSet(x) == findSet(y);
	}
	void unite(int x, int y) {
		if (!same(x, y)) set_size--;
		link(findSet(x), findSet(y));
	}
};

