struct UnionFind {
    UnionFind() {}
    UnionFind(int n) {
        resize(n);
    }

    void resize(int n) {
        par.resize(n, -1);
    }

    int root(int x) {
        if (par[x] < 0) return x;
        return par[x] = root(par[x]);
    }

    bool merge(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return false;
        if (par[rx] > par[ry]) swap(rx, ry);
        par[rx] += par[ry];
        par[ry] = rx;
        return true;
    }

    bool is_same(int x, int y) {
        return (root(x) == root(y));
    }

    int size(int x) {
        return -par[root(x)];
    }

private:
    vector<int> par;
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    // std::ifstream in("input.txt");
    // std::cin.rdbuf(in.rdbuf());
    int n, m;
    cin >> n >> m;
    UnionFind uf(n);
    set<int> used;
    rep(i, m) {
        int x, y, z;
        cin >> x >> y >> z;
        x--; y--;
        uf.merge(x, y);
        used.insert(x);
        used.insert(y);
    }
    vector<int> group;
    for (auto u : used) {
        bool f = false;
        rep(ii, sz(group)) {
            if (uf.root(group[ii]) == uf.root(u)) {
                f = true;
                break;
            }
        }
        if (!f) group.push_back(u);
    }
    cout << (sz(group) + (n - sz(used))) << endl;
    return 0;
}

