int typeCount = 0;

void doFloodFill(int p)
{
	typeCount++;	

	std::queue<int> q;
	q.push(p);
	nodes[p].belongsTo = typeCount;

	int curP;

	while (!q.empty())
	{
		curP = q.front();
		q.pop();

		for (int i = 0 ; i < nodes[curP].connects.size() ; i++)
		{
			int newP = nodes[curP].connects[i];
			if (nodes[newP].belongsTo != -1)
				continue;

			nodes[newP].belongsTo = typeCount;
			q.push(newP);
		}
	}
}

