	}

	int u, v, w;
	for (int i = 0 ; i < m ; i++)
	{
		scanf("%d%d%d", &u, &v, &w);
		nodes[u].connects.push_back(v);
		nodes[v].connects.push_back(u);
	}

	for (int i = 1 ; i <= n ; i++)
	{
		if (nodes[i].belongsTo != -1)
			continue;

		doFloodFill(i);
	}

	printf("%d\n", typeCount);

	return 0;
}

