using namespace std;

struct union_find {
    vector<int> par, sz;

    union_find(int n) {
        par.resize(n);
        sz.resize(n);
        for (int i =0; i < n; i++)
            par[i] = i, sz[i] = 0;
    }

    int find(int x) {
        if (par[x] == x)
            return x;
        else 
            return par[x] = find(par[x]);
    }

    void unite(int x, int y) {
        x = find(x), y = find(y);

        if (x == y) return ;

        else if (sz[x] < sz[y])
            par[x] = y;
        else {
            par[y] = x;
            if (sz[x] == sz[y])
                sz[x]++;
        }
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }
};

int main() {
    int n, m;   cin >> n >> m;
    union_find u(n);

    for (int i = 0; i < m; i++) {
        int x, y, z;    cin >> x >> y >> z;
        u.unite(x-1, y-1);
    }

    set<int> s;
    for (int i = 0; i < n; i++) {
        s.insert(u.find(i));
    }

    cout << s.size() << endl;

    return 0;
}

