class DisjointSet{
public:
  vector<int> rank,p;
  vector<int> sz;

  DisjointSet(){}
  DisjointSet(int size){
    rank.resize(size,0);
    p.resize(size,0);
    sz.resize(size,0);
    for(int i=0;i<size;i++) makeSet(i);
  }

  void makeSet(int x){
    p[x]=x;
    rank[x]=0;
    sz[x]=1;
  }

  bool same(int x,int y){
    return findSet(x)==findSet(y);
  }

  void unite(int x,int y){
    link(findSet(x),findSet(y));
  }

  void link(int x,int y){
    if(rank[x]>rank[y]){
      p[y]=x;
      sz[x]+=sz[y];
    }else{
      p[x]=y;
      sz[y]+=sz[x];
      if(rank[x]==rank[y]){
        rank[y]++;
      }
    }
  }

  int findSet(int x){
    if(x!=p[x]){
      p[x]=findSet(p[x]);
    }
    return p[x];
  }

  int findSize(int x){
    return sz[findSet(x)];
  }
};

int main(){
  int N,M;
  cin>>N>>M;

  DisjointSet us(N);
  for(int i=0;i<M;i++){
    int x,y,z;
    cin>>x>>y>>z;

    x--;
    y--;
    if(us.same(x,y)) continue;
    else us.unite(x,y);
  }

  int ans=1;
  for(int i=1;i<N;i++){
    if(us.same(0,i)) continue;

    ans++;
    us.unite(0,i);
  }

  cout<<ans<<endl;

  return 0;
}

