struct uf {
	uf* parent;

	uf() {
		parent = this;
	}
	void connect(uf* v) {
		if (v == this)
		{
			return;
		}
		if (parent == this && v->parent == v)
		{
			v->parent = this;
		}
		else if(parent != this && v->parent == v) {
			v->parent = parent;
		}
		else if (parent == this && v->parent != v) {
			parent = v->parent;
		}
		else if (parent != this && v->parent != v) {
			connect(v->parent);
		}
	}

	bool ind()
	{
		return parent == this;
	}
};

