class Solve
{
  int N;
  vector<vector<int>> V;
  int connected{0};
  vector<bool> visited;

public:
  Solve(int N, vector<vector<int>> V) : N{N}, V{V}, visited(N, false) {}

  void flush()
  {
    count();
    cout << connected << endl;
  }

private:
  void count()
  {
    for (auto i = 0; i < N; ++i)
    {
      if (!visited[i])
      {
        ++connected;
        dfs(i);
      }
    }
  }

  void dfs(int v)
  {
    visited[v] = true;
    for (auto x : V[v])
    {
      if (!visited[x])
      {
        dfs(x);
      }
    }
  }
};

