class UnionFind {
public:
	vector<int> parent;

	UnionFind(int n) : parent(n) {
		for(int i = 0; i < n; i++) {
			parent[i] = i;
		}
	}

	int root(int x) {
		if(parent[x] == x) return x;
		return parent[x] = root(parent[x]);
	}

	void unite(int x, int y) {
		int rx = root(x);
		int ry = root(y);
		if(rx == ry) return;
		parent[rx] = ry;
	}

	bool same(int x, int y) {
		int rx = root(x);
		int ry = root(y);
		return rx == ry;
	}
};

