struct UnionFind{
	vector<int> par;
	int sz;

	UnionFind(int N) : par(N) , sz(N) {
		for(int i=0;i<N;i++) par[i]=i;
	}

	int root(int x){
		if(par[x]==x) return x;
		else{
			return par[x]=root(par[x]); //ここは同時に経路圧縮もやってるらしい
		}
	}

	void unite(int x,int y){
		int rx=root(x);
		int ry=root(y);
		if(rx==ry) return;
		else { par[rx]=ry; sz--; }
	}

	bool same(int x,int y){
		int rx=root(x);
		int ry=root(y);
		return rx==ry;
	}

	int size() { return sz; }
};

int main(){
	int N,M,x,y,z;
	cin >> N>>M;
	UnionFind uf(N);
	for(int i=0;i<M;i++){
		cin >>x>>y>>z; x--; y--;
		uf.unite(x,y);
	}
	cout<<uf.size()<<endl;
}

