typedef pair<int, int> pii;
vector<int> P(100005), S(100005);

void init()
{
    for (int i = 0; i < 100005; ++i)
    {
        P[i] = i;
        S[i] = 1;
    }
}

int find(int i)
{
    if (P[i] == i)
        return i;
    return P[i] = find(P[i]);
}

int Un(int u, int v)
{
    u = find(u);
    v = find(v);
    if (u != v)
    {
        if (S[v] > S[u])
            swap(u, v);
        P[v] = u;
        S[u] += S[v];
        return 1;
    }
    return 0;
}

void solve()
{
    int n, u, v, w, m;
    cin >> n >> m;
    init();
    for (int i = 0; i < m; ++i)
    {
        cin >> u >> v >> w;
        if (Un(u, v))
            n--;
    }
    cout << n;
}

