class UnionFind {
public:
	vector<int> par, sz;
	UnionFind(int n = 1) {
		init(n);
	}
	void init(int n) {
		par.resize(n); sz.resize(n);
		for (int i = 0; i < n; i++)par[i] = i, sz[i] = 1;
	}
	int root(int x) {
		if (par[x] == x)return x;
		else return par[x] = root(par[x]);
	}
	bool same(int x, int y) {
		return root(x) == root(y);
	}
	int size(int x) {
		return sz[root(x)];
	}
	void unite(int x, int y) {
		x = root(x); y = root(y);
		if (x == y)return;
		par[y] = x;
		sz[x] += sz[y];
	}
};

int main() {
	int n, m; cin >> n >> m;
	UnionFind uf(n);

	rep(i, m) {
		int x, y, z; cin >> x >> y >> z;
		x--; y--;
		uf.unite(x, y);
	}

	set<int> aa;
	rep(i, n)aa.insert(uf.par[i]);
	out, sz(aa), out;
}

