// Union-Find
class UnionFind {
private:
	// parents[i] >= 0 なら i の親
	// parents[i] < 0 で、根。abs(parents[i])がその木に属する頂点数
	vector<int> parents;
	int n_root;

public:
	UnionFind();
	UnionFind(int n) {
		parents.assign(n, -1);
		n_root = n;
	}
	~UnionFind() {
		parents.clear();
	};

	int find(int x) {
		if (parents[x] < 0) {
			return x;
		} else {
			return parents[x] = find(parents[x]);
		}
	}

	void unite(int x, int y) {
		x = find(x);
		y = find(y);

		if (x == y) {
			return;
		}

		if (size(x) < size(y)) {
			swap(x, y);
		}

		parents[x] += parents[y];
		parents[y] = x;
		n_root--;
		return ;
	}

	bool same(int x, int y) {
		return find(x) == find(y);
	}

	// xが属する集団のサイズ
	int size(int x) {
		return -parents[find(x)];
	}

	// いくつの集団があるか
	int get_n_root() {
		return n_root;
	}
};

int main() {
	int n, m;
	cin >> n >> m;

	int x, y, z;
	UnionFind uf(n);

	set<int> known;
	for (int i = 0; i < m; i++) {
		cin >> x >> y >> z;
		x--;
		y--;

		uf.unite(x, y);

		if (x == y) {
			known.insert(x);
		}
	}

	set<int> known_root;
	for (auto a: known) {
		known_root.insert(uf.find(a));
	}

	int ans = uf.get_n_root() - known_root.size();
	cout << ans << endl;

	return 0;
}

