#define maxN 100000
#define maxM 100000

class UFT{
public:
  long long int par[maxN]; // 親
  long long int rank[maxN]; // 木の深さ
  long long int degree; // unionの数

  // n要素で初期化
  UFT(long long int n){
    for (long long int i = 0; i < n; i++) {
      par[i] = i;
      rank[i] = 0;
    }
    degree = n;
  }

  // 木の根を求める
  long long int find(long long int x){
    if (par[x] == x){
      return x;
    }
    else{
      return par[x] = find(par[x]);
    }
  }

  // xとyの属する集合を併合
  void unite(long long int x, long long int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (rank[x] < rank[y]) {
      par[x] = y;
    }
    else {
      par[y] = x;
      if (rank[x] == rank[y]) rank[x]++;
      degree --;
    }
  }
};

int main(){
  long long int N, M;
  long long int X, Y, Z;
  long long int res=0;

  cin >> N >> M;
  UFT uft(N);
  for(long long int i=0; i<M; i++){
    cin >> X >> Y >> Z;
    uft.unite(X,Y);
  }
  cout << uft.degree << endl;

}

