struct UF {
  vector<int> vec;
  UF(int size) : vec(size) {
    iota(vec.begin(), vec.end(), 0);
  }
  int root(int a) {
    if (vec[a]==a)
      return a;
    return vec[a] = root(vec[a]);
  }
  void unite(int a, int b) {
    vec[root(b)] = root(a);
  }
};

