        if (z[i] % 2) { // Axi + Ayi は奇数
            uf.unionSet(x[i], y[i] + n);
            uf.unionSet(x[i] + n, y[i]);
        } else {
            uf.unionSet(x[i], y[i]);
            uf.unionSet(x[i] + n, y[i] + n);
        }
    }
