    int py = get_parent_idx(vec, y);
    if (px < py) {
      do {
        int tmp = x;
        x = vec[x];
        vec[tmp] = py;
      } while (x != px);
      vec[x] = py;
    }
    else {
      do {
        int tmp = y;
        y = vec[y];
        vec[tmp] = px;
      } while(y != px);
      vec[y] = px;
    }
  }

  for (int i = 1; i <= n; ++i)
    get_parent_idx(vec, i);

  set<int> s;
  for (int i = 1; i <= n; ++i)
