using namespace std;

enum State {
	UNDEFINED,
	DEFINED,
};

void BFS(vector<set<int>>& u_g, vector<State>& r_t, int search_pos) {
	for (auto itr = u_g[search_pos].begin(); itr != u_g[search_pos].end(); itr++) {
		if (r_t[*itr] == DEFINED) {
			continue;
		}
		else {
			r_t[*itr] = DEFINED;
			BFS(u_g, r_t, *itr);
		}
	}
}

int main() {
	int N, M;
	cin >> N >> M;
	vector<set<int>> union_group(N);
	for (int i = 0; i < M; i++) {
		int X, Y, Z;
		cin >> X >> Y >> Z;
		union_group[X-1].insert(Y-1);
		union_group[Y-1].insert(X-1);
	}
	vector<State> register_table(N, UNDEFINED);

	int ans = 0;

	for (int i = 0; i < N; i++) {
		if (register_table[i] == DEFINED) {
			continue;
		}
		else {
			ans++;
			register_table[i] = DEFINED;
		}
		BFS(union_group, register_table, i);
	}
	cout << ans << endl;
	return 0;
}

