struct listc{
	int to;
	int cost;
};
vector<bool> Visited(100000, false);   //頂点が訪問済みか否かを格納
vector<vector<listc>> LC(100000);
//深さ優先探索(現在位置をiとする)
void DFS(int i)
{
	Visited[i]=true;
	//cout<<i<<endl;

	for(int j=0; j<(int)LC[i].size(); j++){
		if(Visited[LC[i][j].to]) continue;
		DFS(LC[i][j].to);
	}
}

//頂点数n, 枝数mのグラフの入力(重み付き)
void Graph_Input_cost(int n, int m)
{
	for(int i=0; i<m; i++){
		int from, to, cost;
		cin>>from>>to>>cost;
		from--; to--;
		listc e;
		e.to=to; e.cost=cost;
		LC[from].push_back(e);
		//無向グラフの場合以下も追加
		e.to=from; e.cost=cost;
		LC[to].push_back(e);
	}
}
int main(void)
{
	int n, m, ans=0;

	cin>>n>>m;

	Graph_Input_cost(n, m);

	rep(i, n){
		if(!Visited[i]){
			//cout<<"DFS"<<i<<endl;
			ans++;
			DFS(i);
		}
	}
	cout<<ans<<endl;
}

