  for (int i = 0; i < m; i++) {
    scanf("%lld %lld %lld", &x[i], &y[i], &z[i]);
    x[i]--, y[i]--;
  }

  UnionFind uf(n);
  rep(i, 0, m) { uf.unite(x[i], y[i]); }
  map<int, int> cnt;
  ll ans = 0, total = 0;
  rep(i, 0, n) { cnt[uf.find(i)]++; }
  vec<ll> q;
  for (auto p : cnt) q.emplace_back(p.se);
  sort(all(q), greater<int>());
  rep(i, 0, n) {
    if (total == n) break;
    ans++;
    total += q[i];
  }

  put(ans);
  return 0;
}

