const int MAX_N = 1e5+1;

ll par[MAX_N]; // 親
ll size_list[MAX_N]; // iを親とするグループのサイズ
ll depth[MAX_N]; // 木の深さ


// n要素の初期化
void init(ll n){
	REP(i,n){
		par[i] = i;
		depth[i] = 0;
	}
}

// 木の根を求める
ll find(ll x){
	if (par[x]==x){
		return x;
	}
	else{
		return par[x] = find(par[x]);
	}
}

// xとyの属する集合を併合
void unit(ll x, ll y){
	x = find(x);
	y = find(y);
	if (x==y) return;

	if (depth[x]<depth[y]){ // xよりyが深いなら
		size_list[y] += size_list[par[x]];
		par[x] = y; // xの親はy
	}
	else{
		size_list[x] += size_list[par[y]];
		par[y] = x;
		if (depth[x]==depth[y]) depth[x]++;
	}
}

// xとyが同じ集合に属するか否か
bool same(ll x, ll y){
	return find(x) ==find(y);
}

// xのグループの大きさ
ll size(ll x){
	return size_list[par[x]];
}


