class DisjointSet{
  public:
  vector<int> rank,p;
  DisjointSet(){}
  DisjointSet(int size)
  {
    rank.resize(size,0);
    p.resize(size,0);
    for (int i = 0; i < size; i++)
    {
      makeSet(i);
    }
  }
void makeSet(int x)
{
  p[x] = x;
  rank[x] = 0;
}

bool same(int x, int y)
{
  return findSet(x) == findSet(y);
}

void unite(int x, int y)
{
  link(findSet(x),findSet(y));
}
void link(int x, int y)
{
  if(rank[x] > rank[y])
  {
    p[y] = p[x];
  }
  else
  {
    p[x] = p[y];
  }
  if(rank[x] == rank[y])
  {
    rank[y]++;
  }
}
  int findSet(int x)
  {
    if(x != p[x])
    {
      p[x] = findSet(p[x]);
    }
    return p[x];
  }
};

void solve(void)
{
  int N,M;
  cin>>N>>M;
  DisjointSet DS(N);
  for (int i = 0; i < M; i++)
  {
    int X,Y,Z;
    cin>>X>>Y>>Z;
    DS.unite(X,Y);

  }
  set<int> cnt;
  for (int i = 0; i < N; i++)
  {
    cnt.insert(DS.p[i]);
    // DEBUG(DS.p);
  }
  for (int i = 0; i < N; i++)
  {
    DS.same(0,i);
  }

  cout<<cnt.size()<<endl;
  return;
}

