    Union_Find<ll> uf(n);
    map<int, bool> mp;

    rep(i, m) {
        cin >> a[i] >> b[i] >> c[i];
        a[i] --, b[i] --;
        uf.merge(a[i], b[i]);
    }

    rep(i, n) {
        auto t = uf.find(i);
        mp[t] += 1;
    }

    cout << mp.size() << endl;
}

