	}
	return par[a] = find(par[a]);
}

void unite(int a, int b)
{
	if (find(a) == find(b)){
		return;
	}
	par[find(a)] = find(b);

	return;
}

void solv()
{
	int N, M; scanf("%d%d", &N, &M);

	for (int i = 0; i < N; i++){
		par[i] = i;
	}

	for (int i = 0; i < M; i++){
		int x, y, z; scanf("%d%d%d", &x, &y, &z);
		unite(x - 1, y - 1);
	}

	int count[N_MAX];
	fill(count, count + N, 0);
	for (int i = 0; i < N; i++){
		count[find(i)]++;
	}

	int ret = 0;
	for (int i = 0; i < N; i++){
		if (0 != count[i]){
			ret++;
		}
	}

	printf("%d", ret);

	return;
}

