			par[i] = i;
		}
	}

	int root(int x) {//データｘが属する木の根を再帰で得る:root(x)={ｘの木の根}
		while (par[x] != x) {
			x = par[x] = par[par[x]];
		}
		return x;
	}

	bool unite(int x, int y) {
		int rx = root(x);
		int ry = root(y);
		if (rx == ry)return false;//ｘとｙの根が同じ（＝同じ木にある）時はそのまま
		if (siz[rx] < siz[ry])swap(rx, ry);
			siz[rx] += siz[ry];
			par[ry] = rx;
			return true;
	}

	bool same(int x, int y) {
		int rx = root(x);
		int ry = root(y);
		return rx == ry;
	}
	int size(int rx) {
		return siz[root(rx)];
	}

};

