template <int NMAX>
class UnionFind {
private:
  int par[NMAX];  // 親
  int rank[NMAX]; // 木の深さ

public:
  ll N;      // number of nodes
  vll sizes; // node iが親であるgroupの要素数

  // n is the number of nodes
  void init(int n) {
    N = n;
    sizes.resize(N, 1);

    for (int i=0; i<n; i++) {
	par[i] = i;
	rank[i] = 0;
    }
  }

  void unite(int x, int y) {
      x = find(x);
      y = find(y);
      if (x==y) return;

      if (rank[x] < rank[y]) {
  	par[x] = y;
	sizes[y] = sizes[x] + sizes[y]; // xは放置
      } else {
  	par[y] = x;
  	if (rank[x] == rank[y]) rank[x]++;
	sizes[x] = sizes[x] + sizes[y]; // yは放置
      }
  }

  int find(int x) {
      if (par[x] == x) {
  	return x;
      } else {
  	return par[x] = find(par[x]);
      }
  }

  bool same(int x, int y) {
      return find(x) == find(y);
  }
};

