class UnionFind{
private:
    vector<int> data;
public:
    UnionFind(int size) {
        data = vector<int>(size, -1);
    }
    bool unite(int x, int y){
        x = root(x);
        y = root(y);
        if (x != y){
            if (data[y] < data[x]) swap(x,y);
            data[x] += data[y];
            data[y] = x;
        }
        return x != y;
    }
    bool find(int x, int y){
        return root(x) == root(y);
    }
    int root(int x) {
        if (data[x] < 0) {
            return x;
        } else {
            return data[x] = root(data[x]);
        }
    }
    int size(int x){
        return -data[root(x)];
    }
    int count(){
        int cnt = 0;
        for (int i=0;i<data.size();i++){
            if (data[i]<0) cnt++;
        }
        return cnt;
    }
};

