#include <bits/stdc++.h>
using namespace std;

struct UnionFind {
    vector<int> Parent;

    UnionFind(int N) { Parent = vector<int>(N, -1); }

    int root(int A) {
        if (Parent[A] < 0) return A;
        return Parent[A] = root(Parent[A]);
    }

    int size(int A) { return -Parent[root(A)]; }

    bool connect(int A, int B) {
        A = root(A);
        B = root(B);
        if (A == B) {
            return false;
        }

        if (size(A) < size(B)) swap(A, B);

        Parent[A] += Parent[B];
        Parent[B] = A;

        return true;
    }

    bool same(int A, int B) { return root(A) == root(B); }

    int num(int N) {
        set<int> s;
        for (int i = 0; i < N; i++) {
            s.insert(root(i));
        }
        return s.size();
    }
