};

ostream& operator << (ostream& s, BitMatrix A) {
  s << endl;
  rep(i, A.H) {
    rep(j, A.W) {
      s << A[i][j] << ", ";
    }
    s << endl;
  }
  return s;
}

int GaussJordan(BitMatrix* A, bool is_extended = false) {
  int rank = 0;
  rep(col, (*A).W) {
    if (is_extended && col == (*A).W - 1) { break; }
    int pivot = -1;
    for (int row = rank; row < (*A).H; ++row) {
      if ((*A)[row][col]) {
        pivot = row;
        break;
      }
    }
    if (pivot == -1) continue;
    swap((*A)[pivot], (*A)[rank]);
    rep(row, (*A).H) {
      if (row != rank && (*A)[row][col]) {
        (*A)[row] ^= (*A)[rank];
      }
    }
    ++rank;
  }
  return rank;
}

