class union_find_tree
{
    private:
        const int number_of_nodes;
        int number_of_groups;
        int *par;
        int *rank;
    public:
        //int *size_of_group;
        union_find_tree(int n);
        int get_number_of_nodes();
        int get_number_of_groups();
        int root(int x);
        void unite(int x, int y);
        bool same(int x, int y);
};

union_find_tree::union_find_tree(int n) : number_of_nodes(n)
{
    number_of_groups = n;
    par = new int[n];
    rank = new int[n];
    //size_of_group = new int[n];
    for (int i = 0; i < n; i++) {
        par[i] = i;
        rank[i] = 0;
        //size_of_group[i] = 1;
    }
}

int union_find_tree::get_number_of_nodes()
{
    return number_of_nodes;
}

int union_find_tree::get_number_of_groups() {
    return number_of_groups;
}

int union_find_tree::root(int x)
{
    if (par[x] == x) {
        return x;
    } else {
        return par[x] = root(par[x]);
    }
}

void union_find_tree::unite(int x, int y)
{
    x = root(x);
    y = root(y);
    if (x == y) {
        return;
    }
    if (rank[x] < rank[y]) {
        par[x] = y;
        //size_of_group[y] += size_of_group[x];
    } else {
        par[y] = x;
        //size_of_group[x] += size_of_group[y];
        if (rank[x] == rank[y]) {
            rank[x]++;
        }
    }
    number_of_groups--;
}

bool union_find_tree::same(int x, int y) {
    return root(x) == root(y);
}


