struct Edge {
  int to, w;
};

bool check(const vec<Edge, 2>& G, int v, int p, vector<int>& color) {
  vector<int> used;
  queue<int> q;
  q.push(v);
  color[v] = p;
  used.push_back(v);
  bool res = true;
  while (!q.empty()) {
    int v = q.front();
    q.pop();
    for (auto& e : G[v]) {
      int u = e.to;
      int w = e.w;
      int want = (e.w - color[v] + 2) % 2;
      if (color[u] == -1) {
        color[u] = want;
        q.push(u);
        used.push_back(u);
      } else {
        if (color[u] != want) {
          res = false;
          goto end;
        }
      }
    }
  }
end:
  for (int v : used) color[v] = -1;
  return res;
}

void nul(const vec<Edge, 2>& G, int v, vector<int>& color) {
  queue<int> q;
  q.push(v);
  while (!q.empty()) {
    int v = q.front();
    q.pop();
    for (auto& e : G[v]) {
      int u = e.to;
      if (color[u] == -1) {
        color[u] = 2;
        q.push(v);
      }
    }
  }
}

