    X--; Y--;
    u.unite(X, Y);
  }

  int ans = 0;
  rep(i, N) {
    int p = u.find(i);
    if (revealed.at(p)) continue;
    revealed.at(p) = true;
    ans++;
  }
  cout << ans << endl;
  return 0;
}

