public:
  Solve(int n, int m) : n{n}, m{m}, v{ReadGraph(n, m)}, visited(n, false)
  {
  }

  void flush()
  {
    int ans{0};
    for (auto i{0}; i < n; ++i)
    {
      ans += dfs(i);
    }
    cout << ans << endl;
  }

private:
  int dfs(int src)
  {
    if (visited[src])
    {
      return 0;
    }
    visited[src] = true;
    for (auto const &e : v[src])
    {
      dfs(e.dst);
    }
    return 1;
  }
};

