struct UnionFind {
    vector<int> par;
    vector<int> siz;

    UnionFind(int n) : par(n), siz(n, 1) {
        for (int i = 0; i < n; i++) par[i] = i;
    }

    int root (int i) {
        while (par[i] != i) {
            i = par[i] = par[par[i]];
        }
        return i;
    }
    bool marge(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return false;
        if (siz[x] < siz[y]) swap(x, y);
        siz[x] += siz[y];
        par[y] = x;
        return true;
    }

    bool is_same(int x, int y) {
        return root(x) == root(y);
    }

    int size(int i) {
        return siz[root(i)];
    }
};

