            tree.unite(xt - 1, yt - 1);
        } else {
            count--;
        }
    }
    for (int i = 0; i < N; i++) {
        isparent[tree.find(i)] = true;
    }
    for (int i = 0; i < N; i++) {
        if (isparent[i]) count++;
    }
    cout << (N - M > 0 ? N - M : 0) << endl;
    return 0;
}

