class union_find {
private:
  std::vector< int > data_;

public:
  union_find(std::size_t size) : data_(size, -1) {}

  std::size_t size() const {
    return data_.size();
  }

  // x を含む集合の representative を経路圧縮しながら返す
  int get_root(int x) {
    return (data_[x] < 0 ? x : data_[x] = get_root(data_[x]));
  }

  // x が集合の representative なら true を返す
  bool is_root(int x) {
    return x == get_root(x);
  }

  // x と y が同じ集合に含まれるなら true を返す
  bool same(int x, int y) {
    return get_root(x) == get_root(y);
  }

  // x を含む集合と y を含む集合を併合
  void unite(int x, int y) {
    x = get_root(x); y = get_root(y);
    if (x == y) return;

    if (data_[x] > data_[y]) std::swap(x, y);
    data_[x] += data_[y];
    data_[y] = x;
  }

  // x を含む集合の要素数を返す
  int element_count(int x) {
    return -data_[get_root(x)];
  }
};

void solver() {
  int N = input(), M = input();
  union_find uf(N);
  range(i, 0, M) {
    int x = input() - 1, y = input() - 1, z = input();
    uf.unite(x, y);
  }

  int ans = 0;
  range(i, 0, N) {
    if (uf.is_root(i)) ans++;
  }

  cout << ans << endl;
}

signed main(int argc, char *argv[]) {
  solver();
}

