import sys


class UnionFind:
    def __init__(self, n):
        self.par = [i for i in range(n+1)]
        self.rank = [0] * (n+1)

    # 検索
    def find(self, x):
        if self.par[x] == x:
            return x
        else:
            self.par[x] = self.find(self.par[x])
            return self.par[x]

    # 併合
    def union(self, x, y):
        x = self.find(x)
        y = self.find(y)
        if self.rank[x] < self.rank[y]:
            self.par[x] = y
        else:
            self.par[y] = x
        if self.rank[x] == self.rank[y]:
            self.rank[x] += 1

    def same_check(self, x, y):
        return self.find(x) == self.find(y)

    def get_uniq_par(self):
        return list(set(self.par))

def solve(N: int, M: int, X: "List[int]", Y: "List[int]", Z: "List[int]"):
    uni = UnionFind(N)

    for x,y in zip(X,Y):
        uni.union(x-1,y-1)

    print(len(uni.get_uniq_par())-1)

    return


