const int MAX_N = 1e5+29;
int N, M;
int par[MAX_N],ran[MAX_N];

void init()
{
	for(int i=1;i<MAX_N;++i){
		par[i]=i;
		ran[i]=1;
	}
}

int look(int x)
{
	if(par[x]==x) return x;
	return par[x]=look(par[x]);
}

void comb(int x, int y)
{
	int a = look(x),b=look(y);
	if(a!=b){
		if(ran[a]<ran[b]){
			par[a]=b;
		}else{
			par[b]=a;
			if(ran[a]==ran[b])ran[a]++;
		}
	}
}


void solve()
{
	int ans = 0;
	for(int i=1;i<=N;++i)if(par[i]==i)ans++;
	cout << ans << endl;
}

int main()
{
	ios::sync_with_stdio(false);
	init();
	cin >> N >> M;
	int x,y,z;
	for(int i=0;i<M;++i){
		cin >> x >> y >> z;
		comb(x,y);
	}
	solve();
	return 0;
}

