class UnionFind {
  private:
    vector<int> unumber; // 子ノードの場合は親ノードの番号、根ノードの場合は木のノード数*(-1)
  public:
    UnionFind(int N) : unumber(N, -1){} // 各ノードを全て親ノードとして初期化
    int findRoot(int x){ // 根ノードを見つけて返す
        if (unumber[x] < 0) return x;
        return unumber[x] = findRoot(unumber[x]); // 根を張り替えながら再帰的に根ノードを探す
    }
    int unite(int x, int y){ // xとyが含まれる木を結合して、新しい根ノードを返す
        x = findRoot(x);
        y = findRoot(y);
        if (x == y) return x; // 既に同じ木に属しているなら何もしない
        if (unumber[y] < unumber[x]) swap(x, y); // xの木がyの木よりも大きくなるようにする（unumberは負であることに注意）
        // xがyの親ノードになるように連結する
        unumber[x] += unumber[y];
        unumber[y] = x;
        return x;
    }
    bool isSame(int x, int y){return findRoot(x) == findRoot(y);}
    int getSize(int x){return -unumber[findRoot(x)];} // xが含まれる木の大きさを返す
};

