                return;

            if(rank[x] < rank[y]) {
                par[x] = y;
            } else {
                par[y] = x;
                if(rank[x] == rank[y])
                    rank[y]++;
            }

            return;
        }

        int num_cls(int n) {
            map<int,int> dic;

            for(int i = 1;i <= n;i++) {
                dic[par[i]] = 1;
            }

            return dic.size();
        }
};

int main(void) {
    int n,m;
    cin>>n>>m;

    UnionFind uf(n);

    for(int i = 0;i < m;i++) {
        int x,y,z;
        cin>>x>>y>>z;
        uf.merge(x,y);
    }

    cout<<uf.num_cls(n)<<endl;

    return 0;
}

