struct UnionFind {
  vector<ll> par, rank;

  UnionFind(ll N) : par(N), rank(N) {
    rep(i, N){
      par[i] = -1;
      rank[i] = 0;
    }
  }

  ll root(ll x) {
    if (par[x] < 0) return x;
    return par[x] = root(par[x]);
  }

  void unite(ll x, ll y) {
    ll rx = root(x);
    ll ry = root(y);
    if (rx != ry){
      if(rank[rx] > rank[ry]){
        par[rx] += par[ry];
        par[ry] = rx;
      }else{
        par[ry] += par[rx];
        par[rx] = ry;
        if(rank[rx] == rank[ry]) rank[ry]++;
      }
    }
  }

  bool same(ll x, ll y) {
    ll rx = root(x);
    ll ry = root(y);
    return rx == ry;
  }

  ll count(ll x){
    return -par[root(x)];
  }
};

int main(){
  ll N, M;
  cin >> N >> M;
  UnionFind tree(N);
  ll n_eq = 0;
  rep(i, M){
    ll x, y, z;
    cin >> x >> y >> z;
    if(!tree.same(x-1, y-1)) n_eq++;
    tree.unite(x-1, y-1);
  }
  ll ans = N - n_eq;
  cout << ans << endl;
  return 0;
}

