	Graph G(N);
	for (int i = 0; i < M; ++i) {
		int a, b; int c;
		cin >> a >> b; cin >> c;
		a--; b--;
		G[a].push_back(b);
		G[b].push_back(a);
	}

	// 全頂点が訪問済みになるまで探索
	int count = 0;
	seen.assign(N, false);
	for (int v = 0; v < N; ++v) {
		if (seen[v]) continue; // v が探索済みだったらスルー
		dfs(G, v); // v が未探索なら v を始点とした DFS を行う
		++count;
	}
	cout << count << endl;
	return 0;
}

