using namespace std;

struct DSU {
    int n;
    vector<int> ps;
    vector<int> rank;
    int num_components;
    DSU(int n): n(n), ps(n), num_components(n), rank(n) {
        for (int i = 0 ; i < n; ++i) {
            ps[i] = i;
            rank[i] = 0;
        }
    }
    int parent(int i) {
        if (ps[i] == i) {
            return i;
        }
        return ps[i] = parent(ps[i]);
    }
    int merge(int i, int j) {
        i = parent(i);
        j = parent(j);
        if (i != j) {
            if (rank[i] <= rank[j]) {
                swap(i, j);
            }
            if (rank[i] == rank[j]) {
                ++rank[i];
            }
            ps[j] = i;
            --num_components;
            return true;
        }
        return false;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, m;
    cin >> n >> m;
    vector<int> ps(n);
    for (int i = 0; i < n; ++i) {
        ps[i] = i;
    }
    DSU dsu(n);
    for (int i = 0; i < m; ++i) {
        int x, y, z;
        cin >> x >> y >> z;
        --x;
        --y;
        dsu.merge(x, y);
    }
    cout << dsu.num_components << endl;
    return 0;
}

