class UnionFind{
public:
    //親の番号を格納する。親だった場合は-(その集合のサイズ)
    vector<int> Parent;

    //作る時はParentの値を全て-1にする
    //こうするとずべてバラバラになる
    UnionFind(int N){
      Parent = vector<int>(N,-1);
    }

    //Aがどのグループに属しているのか調べる
    int root(int A){
      if(Parent[A]<0) return A;
      return Parent[A] = root(Parent[A]);
    }

    //自分のいるグループの頂点数を調べる
    int size(int A){
      return -Parent[root(A)];//親を取ってきたい
    }

    //AとBをくっつける
    bool connect(int A,int B){
      //AとBを直すつつなぐのではなく、root(A)にroot(B)をくっつける)
      A = root(A);
      B = root(B);
      if(A==B){
        //すでにくっついているからくっつけない
        return false;
      }
      //大きい方(A)に小さい方(B)をくっつけたい
      //大小が逆だったらひっくり返しちゃう
      if(size(A)<size(B)) swap(A,B);

      //Aのサイズを更新する
      Parent[A] += Parent[B];
      //Bの親をAに変更する
      Parent[B] = A;

      return true;
    }
  };

int main(){
  int N,M;cin>>N>>M;
  int i,j,k,l;
  vector<int> A(M),B(M),C(M);
  for(i=0;i<M;i++) {
    cin>>A[i]>>B[i]>>C[i];
  }
  int ans=N;
  UnionFind Uni(N);

  for(i=M-1;i>=0;i--){
    //ans[i-1] = ans[i];
    //繋がってなかったのが繋がった時
    if(Uni.root(A[i]) != Uni.root(B[i])){
      ans -= 1;
      Uni.connect(A[i],B[i]);
      }
    }

  cout<<ans<<endl;
}

