struct UnionFind {
    // parで親のnode値と、サイズを同時に管理する。
    // 根ではないnodeのparは親となるnodeの値が入ってる
    // 根にはサイズ数が入っている。区別できるようにサイズはマイナスの値で入っている
    // そのため、初期値はすべて-1になる(mergeの際にmergeされる側の根に、mergeする方の根が加算される
    vector<int> par;

    UnionFind(int n) : par(n, -1) { }
    void init(int n) { par.assign(n, -1); }

    int root(int x) {
        // 上記の通り,負の値ということは、根である
        if (par[x] < 0) return x;
        return par[x] = root(par[x]);
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        // サイズが大きいほうにマージする
        // 以下は必ずxが大きいほう(サイズはマイナスの値が入ってるので)にするように調整している
        if (par[x] > par[y]) swap(x, y);
        // xのサイズに、yのサイズを加算する
        par[x] += par[y];
        // yの根をxに更新する
        par[y] = x;
        return true;
    }

    bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }

    int size(int x) {
        return -par[root(x)];
    }
};

int main() {
    int n,m; cin >> n >> m;
    UnionFind tree(n);
    vector<int> x(m);
    vector<int> y(m);
    vector<int> z(m);

    rep(i, m) {
        int x,y,z; cin >> x >> y >> z;
        x--;
        y--;
        z--;
        tree.merge(x,y);
    }

    set<int> ans;
    rep(i, n) {
        ans.insert(tree.root(i));
    }

    cout << ans.size() << endl;

    return 0;
}

