//木を駆け上がりrootを探索する
int findroot(int x){
    if(par[x] == x)return x;
    else return par[x] = findroot(par[x]);
}

//結合
void uniteroot(int x, int y){
    x = findroot(x);
    y = findroot(y);
    if( x == y )return; //結合済
    if(rnk[x] < rnk[y])par[x] = y;
    else if(rnk[x] > rnk[y])par[y] = x;
    else {
        par[y] = x;
        rnk[x]++;
    }
}

bool sameroot(int x, int y){
    return findroot(x) == findroot(y);
}

