  for(int i = 0;i < (n << 1);i++){
    par[i] = i;
  }
}
int fin(int u){
  if(par[u] == u) return u;
  return par[u] = fin(par[u]);
}
void uni(int u,int v){
  u = fin(u), v = fin(v);
  if(u == v) return;
  par[u] = v;
}
