    for(int i =1;i<=k;i++){
        lli x ,y ,z;
        cin >> x >> y >> z;
        unionSet(x,y);
    }
    for(int i =1;i<=n;i++){
        ans+=m[i]->inSubset?0:1;
    }
    cout << ans << endl;
}

