    queue<int> que;
    rep(i,N){
    if(dist[i]!=-1) continue;
    else{
    ca++;
    // 初期条件 (頂点 0 を初期ノードとする)
    dist[i] = 0;
    que.push(0); // 0 を橙色頂点にする

    // BFS 開始 (キューが空になるまで探索を行う)
    while (!que.empty()) {
        int v = que.front(); // キューから先頭頂点を取り出す
