struct UnionFind {
    vector<int> data;

    UnionFind(int size) : data(size, -1) {}
    void unite(int x, int y) {
        auto rx = root(x);
        auto ry = root(y);
        if (rx == ry)
            return;

        auto x_size = -data[rx];
        auto y_size = -data[ry];
        if (x_size > y_size) {
            data[rx] = ry;
            data[ry] = -(x_size + y_size);
        } else {
            data[ry] = rx;
            data[rx] = -(x_size + y_size);
        }
    }

    int root(int x) {
        if (data[x] < 0)
            return x;
        data[x] = root(data[x]);
        return data[x];
    }
};

int main() {
