        --x, --y;
        uf.unite(x, y);
    }

    auto group_count = 0;
    auto remains = n;
    for (auto i = 0; i < n; ++i) {
        if (uf.root(i) == i) {
            group_count++;
            remains -= -(uf.data[i]);
        }
    }

    cout << group_count + remains << endl;
    return 0;
}

