int get(int v) {
    if (v == p[v])
        return v;
    return p[v] = get(p[v]);
}

void unite(int u, int v) {
    u = get(u);
    v = get(v);
    if (u == v)
        return;
    if (r[u] < r[v])
        swap(u, v);
    p[v] = u;
    r[u] += r[v];
}

