const int MAX_N = 100010;

int par[MAX_N];
int rank[MAX_N];
int size[MAX_N];

void init(int n) {
  for (int i = 0; i < n; i++) {
    par[i] = i;
    rank[i] = 0;
    size[i] = 1;
  }
}

int find(int x) {
  if (par[x] == x) {
    return x;
  } else {
    return par[x] = find(par[x]);
  }
}

void unite(int x, int y) {
  x = find(x);
  y = find(y);
  if (x == y) return;

  if (rank[x] < rank[y]) {
    par[x] = y;
    size[y] += size[x];
  } else {
    par[y] = x;
    size[x] += size[y];
    if (rank[x] == rank[y]) rank[x]++;
  }
}

bool same(int x, int y) {
  return find(x) == find(y);
}

int getSize(int x) {
  return size[find(x)];
}

using namespace std;
typedef long long ll;

struct Query {
  int x;
  int y;
  int z;

  Query(int x, int y, int z) {
    this->x = x;
    this->y = y;
    this->z = z;
  }
};

int main() {
  int N, M;
  cin >> N >> M;
  init(N + 1);
  vector<Query> query;

  for (int i = 0; i < M; ++i) {
    int x, y, z;
    cin >> x >> y >> z;

    query.push_back(Query(x, y, z));
  }

  for (int i = 0; i < M; ++i) {
    Query q = query[i];

    if (q.x == q.z || q.y == q.z) {
      unite(q.x, q.y);
    }
  }

  int ans = 0;

  bool checked[N + 1];
  memset(checked, false, sizeof(checked));

  for (int i = 1; i <= N; ++i) {
    int parent = find(i);
    if (checked[parent]) {
      checked[i] = true;
      continue;
    }

    int s = getSize(parent);
    if (s <= 1) continue;
    checked[parent] = true;

    ++ans;
  }

  for (int i = 0; i < M; ++i) {
    Query q = query[i];

    int cnt = 0;
    if (checked[q.x]) ++cnt;
    if (checked[q.y]) ++cnt;
    if (checked[q.z]) ++cnt;

    if (cnt <= 1) {
      ans += 2 - cnt;
    }

    checked[q.x] = true;
    checked[q.y] = true;
    checked[q.z] = true;
  }

  for (int i = 1; i <= N; ++i) {
    if (!checked[i]) {
      ++ans;
    }
  }

  cout << ans << endl;

  return 0;
}

