//Union Find Tree
class Union_Find_Tree {
public:
	vector<int> parent;
    vector<int> rank;

    Union_Find_Tree(int N = 1) : parent(N), rank(N,0){
		for (int i = 0; i < N; ++i) parent[i] = i;
	}

	int root(int n) {
		return (parent[n] == n ? n : parent[n] = root(parent[n]));
	}

    bool same(int n, int m) {
		return root(n) == root(m);
	}

	void unite(int n, int m) {
		n = root(n);
		m = root(m);
		if (n == m) return;
		if(rank[n]<rank[m]) {
            parent[n] = m;
        }
        else{
            parent[m] = n;
            if(rank[n] == rank[m]) rank[n]++;
        }
	}
};


int main() {
	int N,M; cin >> N >> M;
	V<int> a(N,-1);
	Union_Find_Tree uf(N);
	V<P<int,int>> edge(N);
	for(int i = 0; i < M; ++i){
		int X,Y,Z; cin >> X >> Y >> Z;
		X--,Y--;
		uf.unite(X,Y);
	}
	V<int> cnt(N,0);
	for(int i = 0; i < N; ++i){
		cnt[uf.root(i)] = 1;
	}
	cout << accumulate(ALL(cnt),0) << endl;

    return 0;
}

