bool prime(ll x)
{
	if (x < 2)
	{
		return false;
	}
	else if (x > 2)
	{
		if (x % 2 == 0)
			return false;
		else
		{
			for (ll i = 3; i <= sqrt(x); i += 2)
			{
				if (x % i == 0)
