ll C(ll n, ll r)
{
	if (r == 0)
		return 1;
	if (n < r)
		return 0;

	/*
     Extra computation saving for large R,
     using property:
     N choose R = N choose (N-R)
    */
	if (r > n / 2)
		return C(n, n - r);

	double res = 1;

	for (int k = 1; k <= r; ++k)
	{
		res *= n - k + 1;
		res /= k;
	}

	return (ll)(res);
}

