struct DSU {
    vector<int> parents;
    vector<int> sizes;

    DSU(int n) {
        parents.resize(n+1);
        for(int i = 1; i <= n; ++i) parents[i] = i;
        sizes.resize(n+1);
        for(int i = 1; i <= n; ++i) sizes[i] = 1;
    }

    int root(int i) {
        while(parents[i] != i) {
            parents[i] = parents[parents[i]];
            i = parents[i];
        }
        return i;
    }

    bool find(int a, int b) {
        return root(a) == root(b);
    }

    void join(int a, int b) {
        int root_a = root(a);
        int root_b = root(b);
        if(root_a == root_b) return;

        if(sizes[root_a] < sizes[root_b]) {
            parents[root_a] = parents[root_b];
            sizes[root_b] += sizes[root_a];
        } else {
            parents[root_b] = parents[root_a];
            sizes[root_a] += sizes[root_b];
        }
    }
};

struct edge {
    int x, y, z;
};

int32_t main() {

    int n, m; cin >> n >> m;

    vector<edge> edges(m);

    for(int i = 0; i < m; ++i) {
        cin >> edges[i].x >> edges[i].y >> edges[i].z;
    }

    DSU dsu(n);

    for(edge e : edges) {
        dsu.join(e.x, e.y);
    }

    unordered_set<int> roots;
    for(int i = 1; i <= n; ++i) {
        roots.insert(dsu.root(i));
    }

    cout << roots.size() << endl;

    return 0;
}

