struct UnionFind
{
	vector<lolo> data;
	UnionFind(lolo size) : data(size, -1) {}
	bool unionSet(lolo x, lolo y)
	{
		x = root(x); y = root(y);
		if ( x != y )
		{
			if ( data[y] < data[x] ) swap(x, y);
			data[x] += data[y]; data[y] = x;
		}
		return x != y;
	}
	bool findSet(lolo x, lolo y)
	{
		return root(x) == root(y);
	}
	lolo root(lolo x)
	{
		return data[x] < 0 ? x : data[x] = root(data[x]);
	}
	lolo size(lolo x)
	{
		return -data[root(x)];
	}
};

