ll findRoot(ll curr) {
  if (curr == parent[curr])
    return curr;
  return (parent[curr] = findRoot(parent[curr]));
}

void union1(ll a, ll b) {
  ll root1 = findRoot(a);
  ll root2 = findRoot(b);
  if (root1 == root2)
    return;

  if (rank1[root1] < rank1[root2]) {
    parent[root1] = root2;
  } else if (rank1[root1] > rank1[root2]) {
    parent[root2] = root1;
  } else {
    parent[root2] = root1;
    rank1[root1]++;
  }
}

