    rep(i,M){
        if(Z[i]%2==0){
            uf.merge(X[i],Y[i]);
            uf.merge(X[i+N],Y[i+N]);
        }
        else{
            uf.merge(X[i],Y[i+N]);
            uf.merge(X[i+N],Y[i]);
        }
    }

    cout << uf.num/2 << endl;



}

