bool start(vector<string> const &c, int y, int sy, int sx, int dy, int dx) {
    vector<pair<ll, ll>> stk;
    stk.push_back({sy, sx});

    vector<vector<bool>> visited(c.size(), vector<bool>(c[0].size(), false));

