struct unionfind {
    vector<i32> p, s;
    i32 g;

    unionfind(i32 n): p(n), s(n, 1), g(n) {
        iota(begin(p), end(p), 0);
    }

    i32 find(i32 n) {
        return p[n] == n ? n : p[n] = find(p[n]);
    }

    void unite(i32 n, i32 m) {
        n = find(n), m = find(m);
        if (n == m) return;
        if (s[n] < s[m]) swap(n, m);
        s[n] += s[m];
        p[m] = n, g--;
    }

    i32 size(i32 n) {
        return s[find(n)];
    }

    bool same(i32 n, i32 m) {
        return find(n) == find(m);
    }
};

