#include <bits/stdc++.h>
using namespace std;
constexpr int MAX = 1e5 + 1;
// const int MAX = 10;
int card[MAX];          // カードに関する連結成分番号を保存.
int connection[MAX];    // 各連結成分 の カード数 を保存.
vector<int> graph[MAX]; // カードの番号を, グラフの頂点に見立てる.

// グラフを幅優先探索する.
// https://ja.wikipedia.org/wiki/幅優先探索
// ※bfsの動作確認用.
// @param s: グラフの探索開始頂点.
// @param l: 連結成分番号(※1以上).
// @return: 特に無し.
void bfs(int s, int l){

    // 1. 空のキュー.
    queue<int> q;

    // 2. 訪問済みフラグ設定.
    // ※スタート地点に, 連結成分番号を指定.
    card[s] = l;
    connection[l]++;

    // 3. 探索地点 s をキュー q に追加.
    q.push(s);
    while(!q.empty()){

        // 4. キューから取り出す.
        int u = q.front();
        q.pop();

        // 5. 取り出した要素を処理.
        for(auto &e : graph[u]){
            // 6. 訪問済であれば, 処理をスキップ.
            if(card[e] > 0)            continue;
            if(card[e] == 0 && e != s) card[e] = card[u], connection[l]++, q.push(e);
        }
    }
    return;
}

int main() {

    // 1. 入力情報取得.
    int N, M;
    scanf("%d %d", &N, &M);

    // 2. グラフ作成.
    for(int i = 0; i < M; i++){
        int x, y, z;
        scanf("%d %d %d", &x, &y, &z);
        x--, y--;
        // x -> y
        graph[x].push_back(y);
        // y -> x
        graph[y].push_back(x);
    }

    // 3. 連結成分に分解.
    int c = 0;
    for(int i = 0; i < N; i++) if(graph[i].size() > 0 && card[i] == 0) c++, bfs(i, c);

    // グラフ連結情報確認.
    // for(int i = 0; i <= N; i++){
    //     printf("card[%d] = %d\n", i, card[i]);
    //     printf("connection[%d] = %d\n", i, connection[i]);
    // }

    // 4. 後処理.
    // -> 各連結成分 ごとに, 魔法 を 1回使用する必要があることと, 
    // 連結成分に含まれないカードは, それぞれ魔法を使用する必要があると見る.
    int ans = N;
    for(int i = 1; i < N; i++){
        if(connection[i] > 0) ans -= connection[i], ans++;
        else                  break;
    }
    printf("%d\n", ans);
    return 0;

}

