using namespace std;



class UnionFind {
	vector<int> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2
	int num;

public:
	UnionFind(int N) : par(N, -1), num(N) { //最初は全てが根であるとして初期化
	}

	int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
		if (par[x] < 0) return x;
		return par[x] = root(par[x]);
	}

	bool merge(int x, int y) { // xとyの木を併合
		int rx = root(x); //xの根をrx
		int ry = root(y); //yの根をry
		if (rx == ry) return false; //xとyの根が同じ(=同じ木にある)時はそのまま
		if (par[ry] < par[rx]) swap(rx, ry);
		par[ry] += par[rx];
		par[rx] = ry;
		num--;
		return true; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
	}

	bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
		int rx = root(x);
		int ry = root(y);
		return rx == ry;
	}

	int getsize(int x) { //集合のサイズを返す
		return -par[root(x)];
	}

	int getnum() { //集合の数を返す
		return num;
	}
};


int main() {
	int n, m;
	cin >> n >> m;
	UnionFind u(n);

	rep(i, m) {
		int x, y, z;
		cin >> x >> y >> z;
		u.merge(x - 1, y - 1);
	}

	cout << u.getnum() << endl;

	return 0;
}

