#define rep(i,N) for(LL i=0;i<N;++i)
typedef long long int LL;

class Union_Find
{
	std::vector<LL>per, rank, cnt;
public:
	void init(LL size)
	{
		rep(i, size)
		{
			per.push_back(i);
			rank.push_back(0);
			cnt.push_back(1);
		}
	}
	LL get_per(LL x)
	{
		if (x == per[x]) return x;
		return per[x] = get_per(per[x]);
	}
	bool is_same_per(LL x, LL y)
	{
		return get_per(x) == get_per(y);
	}
	void unite(LL x, LL y)
	{
		LL x_per = get_per(x), y_per = get_per(y);
		if (x_per == y_per) return;
		if (rank[x_per] < rank[y_per])
		{
			per[x_per] = y_per;
			cnt[y_per] += cnt[x_per];
			cnt[x_per] = 0;
		}
		else
		{
			per[y_per] = x_per;
			cnt[x_per] += cnt[y_per];
			cnt[y_per] = 0;
			if (rank[x_per] == rank[y_per]) ++rank[x_per];
		}
	}
	LL get_cnt(LL x)
	{
		return cnt[get_per(x)];
	}
};

int main()
{
	LL N, M;
	in >> N >> M;
	std::vector<LL>X(M), Y(M), Z(M);
	rep(i, M) in >> X[i] >> Y[i] >> Z[i];

	Union_Find tree;
	tree.init(N + 1);
	rep(i, M) tree.unite(X[i], Y[i]);

	std::set<LL>ans;
	for (LL i = 1; i <= N; ++i) ans.insert(tree.get_per(i));

	out << ans.size() << std::endl;
}

#include <iostream>
