// usi tree
class Segment_Tree {
private:
  ll n=1;
  pll init=pll(-1,-1);
  std::vector<pll> node;
  auto f(pll x,pll y){
    if(x.first>y.first)return x;
    else return y;
  }
public:
  Segment_Tree(std::vector<ll> v){
    ll sz = ((ll)v.size());    
    while(n<sz)n<<=1;
    node.resize(n*2-1,init);
    for(ll i=0;i<sz;++i)node[i+n-1]=pll(v[i],i);
    for(ll i=n-2;i>=0;--i)node[i]=f(node[i*2+1],node[i*2+2]);
  }

  void dec(ll idx){
    idx+=n-1;
    node[idx].first--;
    while(idx){
      idx--;
      idx/=2;
      node[idx]=f(node[idx*2+1],node[idx*2+2]);
    }
  }

  void update(ll idx,ll v){
    idx+=n-1;
    node[idx].first=v;
    while(idx){
      idx--;
      idx/=2;
      node[idx]=f(node[idx*2+1],node[idx*2+2]);
    }
  }

  auto query(ll a,ll b,ll k=0,ll l=0,ll r=-1){
    if(r<0)r=n;
    if(r<=a || b<=l)return init;
    if(a<=l && r<=b)return node[k];
    else{
      auto vl = query(a,b,2*k+1,l,(l+r)/2);
      auto vr = query(a,b,2*k+2,(l+r)/2,r);
      return f(vl,vr);
    }
  }
};
main(){
