class UF {
    private:
        int par[MAX_N];
        int rank[MAX_N];
    public:
        UF(int N) {
            for(int i = 1;i <= N;i++) {
                par[i] = i;
                rank[i] = 0;
            }
        }

        int root(int x) {
            return x == par[x] ? x : par[x] = root(par[x]);
        }

        bool same(int x,int y) {
            return root(x) == root(y);
        }

        void merge(int x,int y) {
            x = root(x);
            y = root(y);
            if(x == y) {
                return;
            }

            if(rank[x] < rank[y]) {
                par[x] = y;
            } else {
                par[y] = x;
                if(rank[x] == rank[y])
                    rank[x]++;
            }

            return;
        }

        int connect(int n) {
            vector<bool> node;
            for(int i = 1;i <= n;i++) {
                node.push_back(false);
            }

            for(int i = 1;i <= n;i++) {
                int u = root(par[i]);
                u--;
                node[u] = true;
            }
            int ans = 0;
            for(int i = 0;i < n;i++) {
                if(node[i])
                    ans++;
            }

            return ans;
        }
};


int main(void) {
    int N,M;

    cin>>N>>M;
    UF uf(N);
    for(int i = 1;i <= M;i++) {
        int x,y,z;
        cin>>x>>y>>z;
        uf.merge(x,y);
    }

    cout<<uf.connect(N)<<endl;

    return 0;
}

