class UnionFind{
    int n;
    vector<int> par;
    vector<int> rank;
    vector<int> sz;

public:
    UnionFind(int n) : n(n), rank(n, 0){
        par.resize(n);
        for(int i=0; i<n; i++)
            par[i] = i;
        sz.resize(n, 1);
    }
    int find(int x){
        if (par[x] == x) return x;
        return par[x] = find(par[x]);
    }
    void unite(int x, int y){
        int x_root = find(x);
        int y_root = find(y);
        if(rank[x_root] > rank[y_root]){
            par[y_root] = x_root;
            sz[x_root] += sz[y_root];
        }else if (rank[x_root] < rank[y_root]){
            par[x_root] = y_root;
            sz[y_root] += sz[x_root];
        }else if (x_root != y_root){
            par[y_root] = x_root;
            sz[x_root] += sz[y_root];
            rank[x_root]++;
        }
    }
    int size(int x){ return sz[find(x)]; }
    bool same(int x, int y){ return find(x) == find(y); }
};

