class unionFind {
public:
  vector<ll> data;

  unionFind(ll size) {
    data.assign(size, -1);
  }

  bool same(ll x, ll y) {
    return find(x)==find(y);
  }

  void unite(ll x, ll y) {
    x=find(x);
    y=find(y);
    if(x==y) return;
    if(data[x]>data[y]) swap(x, y);
    data[x]+=data[y];
    data[y]=x;
  }

  ll find(ll k) {
    if(data[k]<0) return k;
    return data[k]=find(data[k]);
  }

  ll size(ll k) {
    return -data[find(k)];
  }

};



