namespace nyg
{
	const int N=101000;

	int begin[N],next[N*2],to[N*2];

	int n,m,e;

	void add(int x,int y,bool k=1)
	{
		to[++e]=y;
		next[e]=begin[x];
		begin[x]=e;
		if(k)add(y,x,0);
	}

	bool vis[N];
	void dfs(int p)
	{
		if(vis[p])return;
		vis[p]=1;
		for(int i=begin[p];i;i=next[i])
			dfs(to[i]);
	}

	void solve()
	{
		scanf("%d%d",&n,&m);
		for(int i=1,u,v,w;i<=m;i++)
			scanf("%d%d%d",&u,&v,&w),add(u,v);

		int ans=0;
		for(int i=1;i<=n;i++)
			if(!vis[i])ans++,dfs(i);
		printf("%d\n",ans);
	}
}

int main()
{
	nyg::solve();
	return 0;
}

