//UnionFind
//全て添字で扱うこと
struct union_find {
  vll parent;
  vll sizes;

  //初期化
  void init(ll n) {
    for (ll i = 0; i < n; i++) parent.push_back(i);
    for (ll i = 0; i < n; i++) sizes.push_back(1);
    return;
  }

  //頂点nの根
  ll root(ll n) {
    if (parent[n] == n) return n;
    return parent[n] = root(parent[n]);
  }

  //頂点nと間接的に繋がっている頂点の数(自身含む)
  ll size(ll n) {
    return sizes[root(n)];
  }

  //頂点a, bが間接的に繋がっているか判定
  bool is_united(ll a, ll b) {
    return (root(a) == root(b));
  }

  //頂点aを含むグラフに頂点bを含むグラフを結合
  void unite(ll a, ll b) {
    if (is_united(a, b)) return;
    sizes[root(a)] += size(b);
    parent[root(b)] = root(a);
    return;
  }
};

int main() {
  ll n, m;
  cin >> n >> m;

  vector<vll> xyz(m, vll(3));
  for (ll i = 0; i < m; i++) cin >> xyz[i][0] >> xyz[i][1] >> xyz[i][2];

  union_find uf;
  uf.init(n);

  ll ans = n;
  for (ll i = 0; i < m; i++) {
    if (!(uf.is_united(xyz[i][0] - 1, xyz[i][1] - 1))) {
      ans--;
      uf.unite(xyz[i][0] - 1, xyz[i][1] - 1);
    }
  }

  cout << ans << endl;
}

