template <class T>
class UnionFind {
public:
  std::vector<T> par;
  std::vector<T> rank;

  UnionFind(T N)
    : par(N, 0), rank(N, 0) {
    for (T i = 0; i < N; i++) {
      par[i] = i;
      // rank[i] = 0;
    }
  };

  T root(T x) {
    if (par[x] == x) {
      return x;
    } else {
      return par[x] = root(par[x]); // path compression
    }
  }

  bool same(T x, T y) { return (root(x) == root(y)); }

  void unite(T x, T y) {
    T rx = root(x);
    T ry = root(y);
    if (rx == ry)
      return;

    if (rank[rx] < rank[ry]) {
      par[rx] = ry;
    } else {
      par[ry] = rx;
      if (rank[rx] == rank[ry])
        rank[rx]++;
    }
  }

  void show() {
    cout << "index:\t";
    for (uint i = 0; i < par.size(); i++) {
      cout << i << " ";
    }
    cout << "\n";

    cout << "par:\t";
    for (uint i = 0; i < par.size(); i++) {
      cout << par[i] << " ";
    }
    cout << "\n";
  }
};

