class unionfind{
  public:
  int Num;
  vector<int> par; //親の番号
  vector<int> height; //木の高さ(ランク)

  unionfind(int N):
    par(vector<int>(N, 0)), height(vector<int>(N, 0)), Num(N) {}


  //初期化
  void init(){
    REP(i, Num){
      par[i] = i;
      height[i] = 0;
    }
  }

  //xの親番号を返す、再帰処理あり
  int root(int x){
    return par[x] == x ? x : par[x] = root(par[x]);
  }

  //xとyの親番号が同一か判定する
  bool same(int x, int y){
    return root(x) == root(y);
  }

  //xとyのある木を結合する
  void unite(int x, int y){
    x = root(x);
    y = root(y);
    if(x == y) return; //親が同一なら結合済み。

    if(height[x] < height[y]) par[x] = y;
    else {
      par[y] = x;
      if(height[x] == height[y]) height[x]++;
    }
  }
};

int main(){
  int n, m;
  cin>>n>>m;
  unionfind uf(n);
  set<int> s;
  int p;
  uf.init();

  int x[m], y[m], z[m];
  REP(i, m) {
    cin>>x[i]>>y[i]>>z[i];
    --x[i];
    --y[i];
    uf.unite(x[i], y[i]);
  }

  REP(i, n){
    p=uf.root(i);
    //ECHO(p);
    s.insert(p);
  }
  cout<<s.size()<<endl;
  return 0;
}

