		if (d[x] > d[y])swap(x, y);
		d[x] += d[y];
		d[y] = x;
		return true;
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
	int size(int x) {
		return -d[find(x)];
	}
    int operator[](int k){
		return d[k];
    }
};


int main() {
    init();

	int N, M; cin >> N >> M;
	UnionFind uf(N);
	rep(i, 0, M) {
		int x, y, z; cin >> x >> y >> z;
		--x; --y;
		uf.unite(x, y);
	}
	int ans = 0;
	rep(i, 0, N) {
		if (uf[i] < 0)++ans;
	}
	cout << ans << "\n";

    return 0;
}

