    T top() {        if(aquery) return a_q.top();        else return b_q.top();    }
    void pop() {        if(aquery) a_q.pop();        else b_q.pop();    }
    T poll() {        if(aquery) return a_q.poll();        else return b_q.poll();    }
    ll size() {        if(aquery) return a_q.size();        else return b_q.size();    }
};

