template <typename T>
class DisjointSet {
   public:
    map<T, T> p;
    map<T, int> rank;
    DisjointSet() {
        p.clear();
        rank.clear();
    }
    DisjointSet(vector<T> elements) {
        p.clear();
        rank.clear();
        for (int i = 0; i < elements.size(); i++) {
            makeSet(elements[i]);
        }
    }
    void makeSet(T x) {
        p[x] = x;
        rank[x] = 0;
    }
    bool same(T x, T y) { return findSet(x) == findSet(y); }
    void unite(T x, T y) { link(findSet(x), findSet(y)); }
    T findSet(T x) {
        if (x != p[x]) {
            p[x] = findSet(p[x]);
        }
        return p[x];
    }

   private:
    void link(T x, T y) {
        if (rank[x] > rank[y]) {
            p[y] = x;
        } else {
            p[x] = y;
            if (rank[x] == rank[y]) {
                rank[y]++;
            }
        }
    }
};

int main() {
