        cin >> x >> y >> z;
        DS.unite(x, y);
    }
    set<int> p;
    for (int i = 1; i <= N; i++) {
        p.insert(DS.findSet(i));
    }
    int ans = p.size();
    cout << ans << endl;
    return 0;
}

