using namespace std;

bool dfs(const vector<vector<pair<int, int> > > &g, int u, int c, vector<int> &vi)
{
	if (vi[u]) return vi[u] == c;
	vi[u] = c;
	for (int i = 0; i < g[u].size(); i++) {
		int v = g[u][i].first, t = g[u][i].second;
		if (!vi[v]) {
			if (c == 1 && !dfs(g, v, t == 0 ? 1 : 2, vi)) return false;
			if (c == 2 && !dfs(g, v, t == 0 ? 2 : 1, vi)) return false;
		} else {
			if (t == 0 && (c + vi[v]) % 2 == 1) return false;
			if (t == 1 && (c + vi[v]) % 2 == 0) return false;
		}
	}
	return true;
}

int main(int argc, char *argv[])
{
	int n, m;
	cin >> n >> m;
	vector<vector<pair<int, int> > > g(n);
	for (int i = 0; i < m; i++) {
		int x, y, z;
		cin >> x >> y >> z;
		x--; y--;
		g[x].push_back(make_pair(y, z % 2));
		g[y].push_back(make_pair(x, z % 2));
	}

	int ans = 0;

	vector<int> vi(n), vi2(n);
	for (int i = 0; i < n; i++) {
		if (vi[i]) continue;
		bool b1 = dfs(g, i, 1, vi);
		bool b2 = dfs(g, i, 2, vi2);
		if (b1 && b2) ans++;
	}

	cout << ans << endl;

	return 0;
}

