class UnionFind {
public:
  vector<int> parent;

  UnionFind(int n) {
    parent = vector<int>(n,-1);
  }

  int root(int x) {
    if (parent[x] < 0) return x;
    return parent[x] = root(parent[x]);
  }

  int size(int x) {
    return -parent[root(x)];
  }

  bool unite(int x, int y) {
    x = root(x);
    y = root(y);
    if(x == y) return false;
    if(size(x) < size(y)) swap(x,y);
    parent[x] += parent[y];
    parent[y] = x;
  }

  bool isMate(int x, int y) {
    return root(x) == root(y);
  }
};

