struct UnionFind {
  int num;
  vector<int> par, rank;
  UnionFind() {}
  UnionFind(int n) : num(n), par(n, 1), rank(n, 0) { iota(par.begin() ,par.end(), 0); }
  int find(int x) {
    if (x == par[x]) return x;
    return par[x] = find(par[x]);
  }
  bool unite (int x, int y) {
    x = find(x);
    y = find(y);
    if (x==y) return true;
    if (rank[x] < rank[y]) swap(x, y);
    rank[x] += rank[y];
    par[y] = x;
    num--;
  }
  int size(int x) {
    return rank[find(x)];
  }
  int count() const {
    return num;
  }
};


