void solve(long long N, long long M, std::vector<long long> X, std::vector<long long> Y, std::vector<long long> Z){
  map<ll, vector<ll>> m;
  for(ll i=1; i<=N; i++) {
    vector<ll> v;
    m[i] = v;
  }
  for(ll i=0; i<M; i++) {
    m[X[i]].push_back(Y[i]);
    m[Y[i]].push_back(X[i]);
  }
  vector<ll> vis(N+1, 0);
  ll cnt = 0;
  for(ll i=1; i<=N; i++) {
    if(vis[i]) continue;
    cnt++;
    queue<ll> q;
    q.push(i);
    while(!q.empty()) {
      ll x = q.front();
      q.pop();
      vis[x] = 1;
      for(auto suc: m[x]) {
	if(vis[suc]) continue;
	q.push(suc);
      }
    }
  }
  std::cout << cnt << std::endl;
}

