void change(int changed)
{
    ok[changed] = true;
    for (int i = 0; i < relation[changed].size(); i++)
    {
        int p = relation[changed][i].first;
        int q = relation[changed][i].second;

        if (q == -1 && (!ok[p]))
        {
            change(p);
        }
        else if (q != -1)
        {
            if (ok[p] && (!ok[q]))
            {
                change(q);
            }
            else if ((!ok[p]) && ok[q])
            {
                change(p);
            }
        }
    }
}

