	for (int i = 0; i < m; i++){
		cin >> x[i] >> y[i] >> z[i];
		if (z[i] % 2 == 0){
			int a = findrt(x[i]);
			int b = findrt(y[i]);
			if (a != b){
				if (b < a)
					swap(a, b);
				rt[x[i]] = rt[y[i]] = rt[b] = a;
				cnt[a] += cnt[b];
				cnt[b] = 0;
			}			
		}
