ll par[202020];
ll rnk[202020];

void init(ll n){
  for (int i=0;i<n;i++){
    par[i] = i;
    rnk[i] = 0;
  }
}

ll find(ll x){
  if(par[x] == x) return x;
  else{
    par[x] = find(par[x]);
    return par[x];
  }
}

void unite(ll x, ll y){
  x = find(x);
  y = find(y);
  if (x == y) return;

  if (rnk[x] < rnk[y]){
    par[x] = y;
  }
  else{
    par[y] = x;
    if(rnk[x] == rnk[y]) rnk[x]++;
  }
}

bool same(ll x, ll y){
  return find(x) == find(y);
}

