const int MAX_N = 100010;
int parent[MAX_N];

struct XYZ {
    int x, y, z;
};

int find(int n) {
    if (parent[n] == n) {
        return n;
    }
    int p = find(parent[n]);
    parent[n] = p;
    return p;
}
void unite(int a, int b) {
    int pa = find(a);
    int pb = find(b);
    if (pa == pb) {
        return;
    }
    if (pa < pb) {
        parent[pb] = pa;
    } else {
        parent[pa] = pb;
    }
}



int solve(int n, int m, vector<XYZ> xyz) {
    rep(i, MAX_N) {
        parent[i] = i;
    }
    for (auto &v : xyz) {
        unite(v.x, v.y);
    }
    int count[n];
    rep(i, n) {
        count[i] = 0;
    }
    rep(i, n) {
        count[find(i)]++;
    }
    int ans = 0;
    rep(i, n) {
        if (count[i] > 0) {
           ans += 1;
        }
    }
    return ans;
}


