	vector<vector<int>> edges(n, vector<int>());	
	for(int i = 0; i < m; i++) {
		int x, y, z;
		cin >> x >> y >> z;
		edges[x - 1].push_back(y - 1);
		edges[y - 1].push_back(x - 1);
	}

	bool checked[100000];
	for(int i = 0; i < n; i++) checked[i] = false;

	int ans = 0;
	for(int i = 0; i < n; i++) {
		if(!checked[i]) {
			checked[i] = true;
			ans++;
			stack<int> stack;
			stack.push(i);
			while(!stack.empty()) {
				int s = stack.top();
				stack.pop();

				for(int t : edges[s]) {
					if(!checked[t]) {
						checked[t] = true;
						stack.push(t);
					}
				}
			}
		}
	}

	cout << ans << endl;

	return 0;
}

