namespace uf {
    vector<int> par, rank;
    vector<int> memo;
    int num;

    void init(int n) {
        par.resize(n);
        rank.resize(n);
        memo.resize(n);
        for (int i = 0; i < n; i++) {
            par[i] = i;
            rank[i] = 0;
            memo[i] = 1;
        }
        num = n;
    }

    int root(int x) {
        if (par[x] == x) {
            return x;
        } else {
            return par[x] = root(par[x]);
        }
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y)return;
        if (rank[x] < rank[y]) {
            par[x] = y;
            memo[y] += memo[x];
        } else {
            par[y] = x;
            memo[x] += memo[y];
            if (rank[x] == rank[y])rank[x]++;
        }
        num--;
    }

    int size(int x) {
        return memo[root(x)];
    }

    int size() {
        return num;
    }
}

