    v.resize(n, -1);
    component_count = n;
  }

  unionfind(int n, vector<pair<int, int>> vp)
    : unionfind(n)
  {
    unite(vp);
  }

  int unite(int a, int b) {
    int ra = root(a);
    int rb = root(b);
    if (ra == rb) return -1;
    component_count--;
    if (size(ra) < size(rb)) swap(ra, rb);
    v[ra] += v[rb];
    v[rb] = ra;
    return size(ra);
  }

  void unite(vector<pair<int, int>> vp) {
    for (auto&& e : vp) {
      unite(e.first, e.second);
    }
  }
};

int main()
{
  int n, m;
  cin >> n >> m;
  vector<pair<int, int>> vp(m);

  for (int i = 0; i < m; i++) {
    int x, y, z;
    cin >> x >> y >> z;
    vp[i].first = x - 1;
    vp[i].second = y - 1;
  }

  auto uf = unionfind(n, vp);
  cout << uf.component_count << endl;
}

