class UnionFind {  
  public:
  vector<long long> par;
  vector<long long> rank;

  UnionFind(long long N) : par(N + 1), rank(N + 1){
    for(int i = 0; i < N; i++){  
      par[i] = i;
      rank[i] = 1;
    }
  }

  long long root(long long x){  
    if (par[x] == x) return x;
    return par[x] = root(par[x]);
  }

  long long size(long long x){  
    return rank[root(x)]; 
  }

  void unite(long long x, long long y){  
    long long rx = root(x); 
    long long ry = root(y);
    if (rx == ry) return;

    if(rank[rx] < rank[ry]){  
