			a ^= b;
			b ^= a;
			a ^= b;
		}
		uni[a] = uni[a] + uni[b];
		uni[b] = a;
		return true;
	}
	bool isConnect(ll a,ll b) {
		return root(a) == root(b);
	}
	ll size(ll a) {
		return -uni[root(a)];
	}
};

