vector<int> par;
vector<int> RANK;

//初期化,par[i]==iなら根だしRANK=0なら何も繋がってない
void init(int n){
  for(int i=0; i<n; i++){
    par.push_back(i);
    RANK.push_back(0);
  }
  return;
}

//根を返す関数
int root(int x){
  if(par[x]==x){
    return x;
  }
  return par[x]=root(par[x]);//経路圧縮
}

//xとyが同じ集合に属するか否か．
bool same(int x, int y){
  return root(x)==root(y);
}

//xとyの属する集合を併合
void merge(int x, int y){
  x=root(x);
  y=root(y);
  if(x==y) return;
  if(RANK[x]<RANK[y]){
    par[x]=y;//『「元のx」の根』の根を「元のy」の根にする（高い方につなげるので）
  }
  else{
    par[y]=x;
    if(RANK[x]==RANK[y]) RANK[x]++;//根に同じ長さのが増えるから高さが1つ増える
  }
  return;
}

