//各ノードの初期値はそれ自身（自身がノードの根）
UnionFind::UnionFind(int N) : par(N), num_unions(N) {
	for (int i = 0; i < N; i++) {
		par[i] = i;
	}
}

int UnionFind::root(int node) {
	if (par[node] == node) return node;
	else {
		return par[node] = root(par[node]);//経路圧縮
	}
}

void UnionFind::marge(int node_a, int node_b) {
	int root_a = root(node_a);
	int root_b = root(node_b);
	if (root_a == root_b) return;
	else par[root_a] = root_b;
}

int UnionFind::count_unions() {
	int ret = 0;
	for (int i = 0; i < num_unions; i++) {
		if (par[i] == i) ret++;
	}
	return ret;
}

