#include <iostream>
#include <vector>

using namespace std;

struct UnionFind {
    vector<int> t;
    UnionFind(int n): t(n+1,-1) { }

    int root(int x) {
        if(t[x]<0) return x;
        else return t[x]=root(t[x]);
    }

    void merge(int x, int y) {
        x = root(x); y = root(y);
        if(x==y) return;
        if(t[y]>t[x]) swap(x,y);
        t[x] += t[y];
        t[y] = x;
    }

    int size(int x) {
        return -t[root(x)];
    }

};


int main(int argc, char const *argv[])
{
    int n, m; cin >> n >> m;
    UnionFind uF(n);

    int x,y,z;
    for(int i=0;i<m;++i) {
        cin >> x >> y >> z;
        uF.merge(x, y);
    }
    int c=0;
    for(int i=1;i<=n;++i) {
        if(uF.root(i)==i) ++c;
    }
    cout << c << endl;

    return 0;
}

#include<cstdio>
class UnionFind{
private:
    int length, numComponent;
    //parent[x]=xの親の番号 ............. xに親が存在する場合,
    //parent[x]=-(xを含む集合の要素数) ... xが親である場合
    int *parent;
    int *rank;
public:
    UnionFind(int l);
    ~UnionFind();
    int root(int x);
    void unite(int x,int y);
    bool isSameTree(int x,int y);
    int sizeOf(int x);
    int component();
};
UnionFind::UnionFind(int l){
    length=l;
    numComponent=l;
    parent=new int[l];
    for(int i=0;i<l;i++)parent[i]=-1;
    rank=new int[l];
    for(int i=0;i<l;i++)rank[i]=0;
}
UnionFind::~UnionFind(){
    delete[] parent;
    delete[] rank;
}
int UnionFind::root(int x){
    if(parent[x]<0)return x;
    return parent[x]=root(parent[x]);
}
void UnionFind::unite(int x,int y){
    int rx=root(x),ry=root(y);
    if(rx!=ry){
        numComponent--;
        if(rank[rx]>rank[ry]){
            parent[rx]+=parent[ry];
            parent[ry]=rx;
        }
        else{
            if(rank[rx]==rank[ry])rank[ry]++;
            parent[ry]+=parent[rx];
            parent[rx]=ry;
        }
    }
}
bool UnionFind::isSameTree(int x,int y){
    return root(x)==root(y);
}
int UnionFind::component(){
    return numComponent;
}
int UnionFind::sizeOf(int x){
    return -parent[root(x)];
}
int main(){
    int n,m;
    scanf("%d%d",&n,&m);
    UnionFind uf(n);
    for(int i=0;i<m;i++){
        int x,y,z;
        scanf("%d%d%d",&x,&y,&z);
        uf.unite(x-1,y-1);
    }
    printf("%d\n",uf.component());
    return 0;
}

