int ans = 0;
void dfs(int i, int pre, vector<vector<int>> &rel,vector<bool> &checked){
    bool all_checked = true;
    for (int j : rel[i])
    {
        if(!checked[j]) all_checked = false;
    }
    if(all_checked) return;
    for (int j : rel[i])
    {
        if(j == pre) continue;
        checked[j] = true;
        dfs(j,i,rel,checked);
    }    
}

