        cin>> a >> b >> c;
        rel[a-1].push_back(b-1);
        rel[b-1].push_back(a-1);
    }
    int i = 0;
    int sum = 0;
    vector<bool> checked(n,false);
    checked[0] = true;
    bool all_checked = false;
    while (!all_checked)
    {
        dfs(i,-1,rel,checked);
        sum ++;
        bool ok = true;
        for (int j = 0; j < n; j++)
        {
            if(!checked[j]){
                i = j;
                checked[j] = true;
                ok = false;
                break;
            }
        }
        if(ok) all_checked = true;       
    }
    cout << sum << endl; 
}

