int par[100002];  // 親
int Rank[100002]; // 木の深さ
int size[100002]; // 木の要素数
int ans;

void init(int n){
	for(int i=0; i<n; i++){
		par[i] = i;
		Rank[i] = 0;
		size[i] = 1;
	}
}

int find(int x){
	if(par[x] == x){
		return x;
	}else{
		return par[x] = find(par[x]);
	}
}

void unite(int x, int y){
	x = find(x);
	y = find(y);
	if(x == y) return;
	if(Rank[x] < Rank[y]){
		par[x] = y;
		size[y] += size[x];
		ans--;
	}else{
		par[y] = x;
		size[x] += size[y];
		if(Rank[x] == Rank[y]) Rank[x]++;
		ans--;
	}
}

bool same(int x, int y){
	return find(x) == find(y);
}

