void init_DSU() {
	for(int i = 0; i < n; ++i) {
		parent[i] = i;
		cnt[i] = 1;
	}
}

int get_parent(int i) {
	while(parent[i] != i) {
		i = parent[i];
	}

	return i;
}

int connect(int i, int j) {
	i = get_parent(i);
	j = get_parent(j);

	if(i != j) {
		if(cnt[i] > cnt[j]) {
			swap(i, j);
		}

		parent[i] = j;
		cnt[j] += cnt[i];

		return 1;
	} else {
		return 0;
	}
}

