struct UnionFind{
    vector<int> par; //親を示す
    vector<int> siz; //素集合のサイズ

    //コンストラクタ
    UnionFind(int n) : par(n),siz(n,1){
        for(int i=0; i<n; i++) par[i] = i;
    }

    void init(int n){
        par.resize(n);
        siz.resize(n);
        for(int i=0; i<n; i++) par[i] = i;
    }

    int root(int x){
        while(par[x] != x){
            x = par[x] = par[par[x]];
        }
        return x;
    }
    void unite(int x, int y){
        int rx = root(x);
        int ry = root(y);
        if(rx == ry) return;
        if(siz[rx] < siz[ry]) swap(rx, ry);
        //siz[ry]<siz[rx]のときpar[ry]をpar[rx]に結合
        siz[rx] += siz[ry];
        par[ry] = rx;
    }
    bool same(int x, int y){
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
    int size(int x){
        return siz[root(x)];
    }
};
