struct Node {
  int to;
  Node() {}
  explicit Node(int _to) {
    to = _to;
  }
};

void dfs(int v, vector<int> &used, const vector<vector<Node>> &graph) {
  if (used[v]) return;
  used[v] = 1;
  for (auto &e : graph[v]) {
    dfs(e.to, used, graph);
  }
}

int main() {
  int N, M;
  cin >> N >> M;
  vector<vector<Node>> graph(N, vector<Node>());
