    x--;y--;
    graph[x].push_back(Node(y));
    graph[y].push_back(Node(x));
  }
  vector<int> used(N, 0);
  int res = 0;
  for (int i=0; i < N; i++) {
    if (used[i]) continue;
    res++;
    dfs(i, used, graph);
  }
  cout << res << endl;
}

