//DSU Disjoint Set Union
using namespace std;

class DSU {
public:
	vector<int> parent;

	DSU(int _size) : size(_size) {
		rank = vector<int>(size + 1, 1);
		parent = vector<int>(size + 1, 0);
		for(int i = 1; i < size + 1; i++)
		{
			parent[i] = i;
		}
	}

	int find(int i) {
		int r = i;
		while(parent[r] != r)
		{
			r = parent[r];
		}
		int temp;
		while(parent[i] != i)
		{
			temp = parent[i];
			parent[i] = r;
			rank[i] = 2;
			i = temp;
		}
		return parent[i];
	}

	bool Union(int i, int j) {
		int ri = find(i), rj = find(j);
		if(ri == rj) return false;
		if(rank[ri] > rank[rj])
		{
			parent[rj] = ri;
		}
		else if (rank[ri] < rank[rj])
		{
			parent[ri] = rj;
		}
		else
		{
			parent[rj] = ri;
			rank[ri] += 1;
		}
		return true;
	}

private:
	int size;
	vector<int> rank;
};

int main()
{
	int N, M;
	cin >> N >> M;
	vector<int> X(M), Y(M), Z(M);
	for(int i = 0; i < M; i++)
	{
		cin >> X[i] >> Y[i] >> Z[i];
	}

	DSU dsu(N);
	for(int i = 0; i < M; i++)
	{
		dsu.Union(X[i], Y[i]);
	}
	unordered_set<int> s;
	for(int i = 1; i <= N; i++)
	{
		s.insert(dsu.parent[i]);
	}

	cout << s.size() << endl;
	return 1;
}

