    ++cnt[x[i] - 1]; ++cnt[y[i] - 1];
  }

  int unknown = 0;
  int ans = 0;

  for (int i = 0; i < n; ++i){
    if (cnt[i] == 0) ++unknown;
  }

  ans += unknown;

