  for (int i = 0; i < m; ++i) {
    if (uf.size(x[i] - 1) == 1 && uf.size(y[i] - 1) == 1){
      ++ans; uf.unite(x[i] - 1, y[i] - 1);
    } else {
      if (!uf.issame(x[i] - 1, y[i] - 1)){
        uf.unite(x[i] - 1, y[i] - 1);
      }
    }
  }

  print(ans);

  return 0;
}

