int par[100000 + 1];    //親
int trank[100000 + 1];  //木の深さ

//n要素で初期化
void init(int n)
{
    for (int i = 0; i < n; i++) {
        par[i] = i;
        trank[i] = 0;
    }
}

//木の根を求める
int find(int x)
{
    if (par[x] == x) {
        return x;
    } else {
        return par[x] = find(par[x]);
    }
}

//xとyの属する集合を併合
void unite(int x, int y)
{
    x = find(x);
    y = find(y);
    if (x == y)
        return;
    if (trank[x] < trank[y]) {
        par[x] = y;
    } else {
        par[y] = x;
        if (trank[x] == trank[y])
            trank[x]++;
    }
}

//xとyが同じ集合に属するか否か
bool same(int x, int y)
{
    return find(x) == find(y);
}

