int n,m;
int rt[100001], cnt[100001];
vector <int> diff[100001];
int gp[100001];
int findrt(int x){
	if (rt[x] == x)
		return x;
	return rt[x] = findrt(rt[x]);
}

void go(int x, int g, int p, int dist){
	dist % 2 == 0 ? gp[x] = g * 2 : gp[x] = g * 2 + 1;
	for (int i = 0; i < (int) diff[x].size(); i++)
		if (diff[x][i] != p && gp[diff[x][i]] == -1)
			go(diff[x][i], g, x, dist + 1);
}

int main(){
	ios::sync_with_stdio(0);	
	cin >> n >> m;
	for (int i = 1; i <= n; i++){
		rt[i] = i;
		cnt[i] = 1;
		gp[i] = -1;
	}
	int x[100001], y[100001], z[100001];
	for (int i = 0; i < m; i++){
		cin >> x[i] >> y[i] >> z[i];
		if (z[i] % 2 == 0){
			int a = findrt(x[i]);
			int b = findrt(y[i]);
			if (a != b){
				if (b < a)
					swap(a, b);
				rt[x[i]] = rt[y[i]] = rt[b] = a;
				cnt[a] += cnt[b];
				cnt[b] = 0;
			}			
		}
	}
	for (int i = 0; i < m; i++)
		if (z[i] % 2 != 0){
			diff[findrt(x[i])].push_back(y[i]);
			diff[findrt(y[i])].push_back(x[i]);
		}

	int g = 0, ans = 0;
