    while( q.size() ) {

      long long int k = q.front();
      q.pop();
      if ( cnt[k] > 0 ) continue;
      cnt[k]++;
      for ( long long int j = 0; j < v[k].size(); j++ ) {
	long long int l = v[k][j];
	if ( cnt[l] > 0 ) continue;
	q.push( l );
      }

    }

  }

  cout << ans << endl;

  return 0;

}

