	VI x(m), y(m), z(m);
	rep(i, m)in(x[i], y[i], z[i]);

	UnionFind uf(n);
	rep(i, m) {
		uf.unite(x[i] - 1, y[i] - 1);
	}
	set<int> s;
	rep(i, n) {
		s.insert(uf.root(i));
	}
	out(sz(s));
}

