/**
 * @brief  Union-Find木
 * @note   size(x)で頂点xの属しているグループの頂点数を返す
 *         same(x,y)で頂点x,yが同じグループの属しているかのboolを返す
 *         unite(x,y)で頂点x,yの属してるグループを統合する．もともと同じ頂点だったなら何もしない
 */
class UnionFindTree {
  const std::size_t N_;
  std::size_t species_;
  std::vector<std::size_t> parent_;
  std::vector<std::size_t> sz_;

 public:
  explicit UnionFindTree(std::size_t);
  std::size_t root(std::size_t);
  std::size_t size(std::size_t);
  bool same(std::size_t, std::size_t);
  void unite(std::size_t, std::size_t);
  std::size_t sets();
};
/**
 * @brief  コンストラクタ
 * @param  n: グラフの頂点数
 */
UnionFindTree::UnionFindTree(std::size_t n) : N_(n), species_(n) {
  parent_.reserve(N_);
  sz_.reserve(N_);
  for (std::size_t i = 0; i < N_; i++) {
    parent_[i] = i;
    sz_[i] = 1;
  }
}
/**
 * @brief  xの属する木の根っこを見つける
 */
std::size_t UnionFindTree::root(std::size_t x) {
  if (parent_[x] == x) {
    return x;
  }
  return parent_[x] = root(parent_[x]);
}
/**
 * @brief  xの属する木のサイズを返す
 */
std::size_t UnionFindTree::size(std::size_t x) { return sz_[root(x)]; }
/**
 * @brief  頂点x,yが同じ木に属しているかをbooleanで返す
 */
bool UnionFindTree::same(std::size_t x, std::size_t y) { return root(x) == root(y) ? true : false; }
/**
 * @brief  頂点x,yの属する木を統合する
 */
void UnionFindTree::unite(std::size_t x, std::size_t y) {
  x = root(x);
  y = root(y);
  if (x != y) {
    parent_[x] = y;
    sz_[y] += sz_[x];
    species_--;
  }
}
// uftに何種類の集合があるか調べる関数を作りたい。
std::size_t UnionFindTree::sets() { return species_; }

