class UnionFind {
  int n;
  vector<int> par, rk;
public:
  UnionFind(int n) : n(n) {
    par.resize(n);
    rk.resize(n);
    for (int i = 0; i < n; i++) {
      par[i] = i;
      rk[i] = 0;
    }
  }

  int f(int i) {
    if (i == par[i]) return i;
    return par[i] = f(par[i]);
  }

  void unite(int x, int y) {
    x = f(x);
    y = f(y);
    if (rk[x] < rk[y]) {
      par[x] = y;
    } else if (rk[x] > rk[y]) {
      par[y] = x;
    } else {
      par[x] = y;
      rk[y] += 1;
    }
  }
};

