int getComp(vector<int>& comp,int i){
  if(comp[i] != i) comp[i] = getComp(comp,comp[i]);
  return comp[i];
}
void merge(vector<int>& comp,vector<int>& level,int a,int b){
  a = getComp(comp,a);
  b = getComp(comp,b);
  if(level[a] > level[b]) swap(a,b);
  else if(level[a] == level[b]) ++level[b];
  comp[a] = b;
}
