void init(int n)
{
    for(int i=1;i<=n;i++)
    {
        par[i]=i;
        ranka[i]=0;
    }
}
int finda(int x)
{
    if(par[x]==x)
        return x;
    else
        return par[x]=finda(par[x]);
}
void unite(int x,int y)
{
    x=finda(x);
    y=finda(y);
    if(x==y) return;
    if(ranka[x]<ranka[y])
        par[x]=y;
    else{
        par[y]=x;
        if(ranka[x]==ranka[y])
            ranka[x]++;
    }
}

