template <typename T> class DisjointSet {
private:
    T n;
    vector<T> rank, p;

    void link(T x, T y) {
        if (x != y) {
            --n;
            if (rank[x] > rank[y]) {
                p[y] = x;
            } else {
                p[x] = y;
                if (rank[x] == rank[y]) { rank[y]++; }
            }
        }
    }

public:
    DisjointSet() {}
    DisjointSet(const DisjointSet& tree) : n(tree.n), rank(tree.rank), p(tree.p) {}
    DisjointSet(T n) : n(n), rank(n, 0), p(n, 0) {
        rep(i, 0, n) { make_set(i); }
    }

    // Initialize the set of x.
    void make_set(T x) {
        p[x] = x;
        rank[x] = 0;
    }

    // Check if x and y are in the same set.
    bool same(T x, T y) { return find_set(x) == find_set(y); }

    // Unite x and y.
    void unite(T x, T y) { link(find_set(x), find_set(y)); }

    // Find the root node of x.
    T find_set(T x) {
        if (x != p[x]) {
            p[x] = find_set(p[x]);
            rank[x] = 1;
        }
        return p[x];
    }

    T size() { return n; }
};

