int top(int a) {
    return p[a]==a?a:top(p[a]);
}

bool same(int a, int b) {
    return top(a)==top(b);
}

void join(int a, int b) {
    if (num[top(a)] > num[top(b)]) {
        p[top(b)] = top(a);
    } else if (num[top(a)] < num[top(b)]) {
        p[top(a)] = top(b);
    } else {
        p[top(b)] = top(a);
        num[top(a)]++;
    }
}

