class UnionFinder {

public:
  int n;
  vector<int> par;
  vector<int> rank; // to speed up the proccess
  int nUnion; // number of unions

  UnionFinder(int num)
    : n(num), nUnion(n)
  {
    par.resize(n);
    for (int i = 0; i < n; i++) {
      par[i] = i;
    }
    rank.resize(n);
    for (int i = 0; i < n; i++) {
      rank[i] = 0;
    }
  }

  void merge (int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) {
      return;
    }

    if (rank[x] > rank[y]) {
      par[y] = x;
    } else {
      par[x] = y;
      if (rank[x]==rank[y]) {
	rank[y]++;
      }
    }
    nUnion--;
  }

  int root (int x) {
    if (par[x] == x) {
      return x;
    } else {
      return par[x] = root(par[x]); // path compression
    }
  }
};

int main () {
  int N, M;
  cin >> N >> M;
  UnionFinder uf(N);
  for (int i = 0; i < M; i++) {
    int X, Y, Z;
    cin >> X >> Y >> Z;
    uf.merge(X, Y);
  }
  cout<<uf.nUnion<<endl;
  return 0;
}

