struct Relation {
  int x, y, z;
};

int main() {
  int n, m;
  cin >> n >> m;
  vector<Relation> xyz(m);
  for (auto& r : xyz) {
    cin >> r.x >> r.y >> r.z;
  }

  vector<bool> visited(n);
  vector<vector<int>> to(n);
  for (auto& r : xyz) {
    int x = r.x - 1;
    int y = r.y - 1;
    to[x].push_back(y);
    to[y].push_back(x);
  }

  int cost = 0;
  for (int i = 0; i < n; ++i) {
    if (visited[i])
      continue;

    ++cost;
    queue<int> q;
    q.push(i);
    while (!q.empty()) {
      int j = q.front();
      q.pop();
      for (int k : to[j]) {
        if (visited[k])
          continue;
        visited[k] = true;
        q.push(k);
      }
    }
  }
  cout << cost << "\n";

  return 0;
}

