struct DSU {
    int n;
    vector<int> ps;
    int num_components;
    DSU(int n): n(n), ps(n), num_components(n) {
        for (int i = 0 ; i < n; ++i) {
            ps[i] = i;
        }
    }
    int parent(int i) {
        if (ps[i] == i) {
            return i;
        }
        return ps[i] = parent(ps[i]);
    }
    int merge(int i, int j) {
        i = parent(i);
        j = parent(j);
        if (i != j) {
            ps[j] = i;
            --num_components;
