struct UinonFindTree {
private:
  vector<LL> UFT;
public:
  UinonFindTree(LL N) {
    UFT.resize(N);
    for (LL i = 0; i < N; i++) {
      UFT[i] = -1; // 0未満は親である
    }
  }

  LL root(LL i) { // 親を返す
    if (UFT[i] < 0) { // 0未満は親である
      return i;
    }
    else {
      LL j = root(UFT[i]);
      UFT[i] = j;
      return j;
    }
  }

  bool same(LL i, LL j) { // 同じ親であるか
    return (root(i) == root(j));
  }

  void unite(LL i, LL j) // 統合する
  {
    LL root_i = root(i);
    LL root_j = root(j);
    if (root_i != root_j) {
      if (size(root_i) < size(root_j)) { // サイズが大きい方を親とする
        swap(root_i, root_j);
      }
      UFT[root_i] += UFT[root_j];
      UFT[root_j] = root_i;
    }
  }

  LL size(LL i) { // 属する要素数を返す
    return -UFT[root(i)];
  }

  LL get_root_num() { // 親の個数を返す
    set<LL> roots;
    for (LL i = 0; i < UFT.size(); ++i) {
      roots.insert(root(i));
    }
    return (LL)roots.size();
  }

  map<LL, vector<LL>> get_root_child() {
    map<LL, vector<LL>> a;
    for (LL i = 0; i < UFT.size(); ++i) {
      LL j = root(i);
      a[j].push_back(i);
    }
    return a;
  }

  void print() { // 親を表示
    for (LL i = 0; i < UFT.size(); ++i) {
      cerr << root(i) << " ";
    }
    cerr << endl;
  }
};


void func() {

  LL N, M;
  cin >> N >> M;
  UinonFindTree uft(N);

  REP(i, M){
    LL x, y, z;
    cin >> x;
    cin >> y;
    cin >> z;
    x--;
    y--;
    uft.unite(x, y);
  }
  cout << uft.get_root_num();
}

