using namespace std;

void DfsVisit(const int key, const vector<vector<int>> &adjacency,
    vector<bool> &passedMap, map<pair<int, int>, bool> &usedEdgeMap)
{
    passedMap[key] = true;
    for (const int neighbor : adjacency[key])
    {
        if (usedEdgeMap[{key, neighbor}] == false)
        {
            usedEdgeMap[{key, neighbor}] = usedEdgeMap[{neighbor, key}] = true;
        }
        if (passedMap[neighbor] == false)
        {
            DfsVisit(neighbor, adjacency, passedMap, usedEdgeMap);
        }
    }
}

int main()
{
    int N, M;
    cin >> N >> M;
    vector<vector<int>> adjacency(N);
    map<pair<int, int>, bool> usedEdgeMap;
    for (int i = 0; i < M; ++i)
    {
        int X, Y, Z;
        cin >> X >> Y >> Z;
        // Zの値に関係なく，関係性の分かっている２カードをつなぐ
        adjacency[X - 1].push_back(Y - 1);
        adjacency[Y - 1].push_back(X - 1);
        usedEdgeMap[{X - 1, Y - 1}] = usedEdgeMap[{Y - 1, X - 1}] = false;
    }

    vector<bool> passedMap(N);
    for (int i = 0; i < N; ++i)
        passedMap[i] = false;

    // 形成したネットワークの連結部分数を数える
    int count = 0;
    for (int i = 0; i < N; ++i)
    {
        if (passedMap[i] == false)
        {
            DfsVisit(i, adjacency, passedMap, usedEdgeMap);
            ++count;
        }
    }
    cout << count;

    return 0;
}

