struct UnionFind{
    vector<int> par;
    vector<int> rank;
    vector<int> sizes;
    UnionFind(int n): par(n), rank(n), sizes(n){
        for(int i = 0; i < n; i++){
            par[i] = i;
            rank[i] = 0;
            sizes[i] = 1;
        }
    }

    int root(int x){
        if(par[x] == x)
            return x;
        else
            return par[x] = root(par[x]);
    }

    bool same(int x, int y){
        return root(x) == root(y);
    }

    void unite(int x, int y){
        x = root(x);
        y = root(y);
        if(x == y) return;
        else {
            if(rank[x] < rank[y]){
                par[x] = y;
                sizes[y] += sizes[x];
            } else {
                par[y] = x;
                sizes[x] += sizes[y];
                if(rank[x] == rank[y]) rank[x]++;
            }
        }
    }

    int size(int x){
        return sizes[root(x)];
    }
};

int main() {
    int N, M;
    cin >> N >> M;
    UnionFind uni(N+1);

    for(int i = 0; i < M; i++){
        int x, y, z;
        cin >> x >> y >> z;
        if(uni.root(x) != uni.root(y))
            uni.unite(x, y);
    }

