class UnionFind {

private:
    vector<int> parent;
    int num;

public:
    UnionFind(int n)
    {
        parent.resize(n);
        for (int i = 0; i < n; i++) parent[i] = i;
        num = n;
    }

    int root(const int v)
    {
        if (parent[v] == v) return v;
        return parent[v] = root(parent[v]);
    }

    void unite(const int v, const int w)
    {
        int rv = root(v);
        int rw = root(w);
        if (rv != rw) {
            parent[rw] = rv;
            num--;
        }
    }

    bool isSame(const int v, const int w)
    {
        return root(v) == root(w);
    }

    int getNum() { return num; }

};



