struct UnionFind {
#define MAX 100001
    int ElementCount[MAX],Adress[MAX];
    void Init() {rep(i,MAX) ElementCount[i] = 1,Adress[i] = i;}
    void unite(int a ,int b) {
        int a_root = find(a),b_root = find(b);
        if (a_root != b_root) {
            ElementCount[a_root] += ElementCount[b_root];
            Adress[b_root] = a_root;
        }
    }
    int find(int a) {
        if (a == Adress[a]) return Adress[a];
        else {
            Adress[a] = find(Adress[a]);
            return Adress[a];
        }
    }
    int size(int a) {
        int root = find(a);
        return ElementCount[root];
    }
    /*
     * ElementCount : 属するグループの要素数
     * Adress : rootの番号
     * unite : 併合
     * find : aのrootを返す
     * size : aのrootのElementCountを返す
     * */
};


