ll repeat_squaring(ll n, ll p, ll m)
{
	if (p == 0)
		return 1;
	if (p % 2 == 0)
	{
		ll t = repeat_squaring(n, p / 2, m);
		return t * t % m;
	}
	return n * repeat_squaring(n, p - 1, m);
}

class UnionFind
{
public:
	vector<int> par;
	vector<int> rank;
	UnionFind(int N) : par(N)
	{
		par.resize(N);
		par.shrink_to_fit();
		rank.resize(N);
		rank.shrink_to_fit();
		for (int i = 0; i < N; i++)
			par[i] = i, rank[i] = 0;
	}
	int root(int x)
	{
		if (par[x] == x)
			return x;
		return par[x] = root(par[x]);
	}
	void merge(int x, int y)
	{
		x = root(x);
		y = root(y);
		if (x == y)
			return;
		if (rank[x] < rank[y])
			swap(x, y);
		if (rank[x] == rank[y])
			++rank[x];
		par[y] = x;
		return;
	}
	bool is_same(int x, int y)
	{
		return root(x) == root(y);
	}
	size_t size()
	{
		set<int> s;
		for (size_t i = 0; i < par.size(); i++)
		{
			s.insert(root(i));
		}
		return s.size();
	}
};

