bool sameset(ll x, ll y) {
	return findset(x) == findset(y);
}

void mergeset(ll x, ll y) {
	x = findset(x), y = findset(y);
	if (x == y) return;
	if (sz[x] > sz[y]) {
		par[y] = x;
		sz[x] += sz[y];
	}
	else {
		par[x] = y;
		sz[y] += sz[x];
	}
}

