Modl operator/(const LL & a, const Modl & b) { Modl r(a * modinv(b.val, MOD)); return r; }
Modl pow(Modl a, int n) { Modl r(modpow(a, n)); return r; }
Modl pow(Modl a, LL n) { Modl r(modpow(a, n)); return r; }

