int parent[100005], sizee[100005];
void init(int n)
{
	for (int i = 0; i <= n; ++i) {
		sizee[i] = 1;
		parent[i] = i;
	}
}
int find_root(int current)
{
	int temp = current;
	while (current != parent[current]) {
		current = parent[parent[current]];
	}
	return parent[temp] = current;
}
void merge(int a, int b)
{
	if (a != b) {
		if (sizee[a] > sizee[b]) {
			parent[b] = a;
			sizee[a] += sizee[b];
		}
		else {
			parent[a] = b;
			sizee[b] += sizee[a];
		}
	}
}
int main()
{
	ios::sync_with_stdio(0);
	cin.tie(0);
	int n, m;
	cin >> n >> m;
	init(n);
	while (m--) {
		int a, b, c;
		cin >> a >> b >> c;
		merge(find_root(a), find_root(b));
	}
	int ans = 0;
	for (int i = 1; i <= n; ++i)
		ans += parent[i] == i? 1: 0;
	cout << ans << '\n';
	return 0;
}

