           std::vector<long long> Y, std::vector<long long> Z) {

  UnionFindTree uf(N + 1);
  rep(m, M) { uf.unite(X[m], Y[m]); }

  set<ll> parents;
  for (ll n = 1; n <= N; n++) {
    parents.insert(uf.find(n));
  }

  print(parents.size());
