#include <bits/stdc++.h>
using namespace std;

const int MAX=100005;

int state[MAX],N;
vector<int> T[MAX],now(MAX);
stack<int> S;

void DFS(){
    int ans=0,count=0,z=0;
    while(count!=N){
        for(int j=z;j<N;j++){
            if(state[j]==0){
                S.push(j);
                state[j]=1;
                z=j;
                break;
            }
        }
    while(S.size()){
        int a=S.top();
        bool flag=true;
        for(int i=now[a];i<T[a].size();i++){
            if(state[T[a][i]]==0){
                S.push(T[a][i]);
                state[T[a][i]]=1;
                now[a]=i;
                flag=false;
                break;
            }
        }
            if(flag){
                state[a]=2;
                count++;
                S.pop();
            }

        }
        ans++;
    }
    cout<<ans<<endl;
}

int main(){

    int u,k,b,M;
    cin>>N>>M;

    for(int i=0;i<N;i++){
        state[i]=0;
        now[i]=0;
    }

    for(int i=0;i<M;i++){
        cin>>u>>k>>b;
        u--;
        k--;
        T[u].push_back(k);
        T[k].push_back(u);
        }
    for(int i=0;i<M;i++){
        sort(T[i].begin(),T[i].end());
    }
    DFS();
}

