struct UnionFind{
  vector<long long> par;

  UnionFind(int n){
    par.assign(n,-1);
  }

  void unite(long long x, long long y){
    x=root(x);y=root(y);
    if(x==y) return;

    if(par[x]>par[y]){
      swap(x,y);
    }
    par[x]+=par[y];
    par[y]=x;
  }

  long long root(long long x){
    if(par[x]<0){
      return x;
    }else{
      return par[x]=root(par[x]);
    }
  }

  int size(long long x) {
    return -par[root(x)];
  }

  bool same(long long x, long long y){
    return root(x)==root(y);
  }
};

int main(){
  long long n,m,x,y,z,ans=0;
  cin >> n >> m;
  UnionFind uf(n);
  for(int i=0;i<m;i++){
    cin >> x >> y >> z;
    x--;y--;
    uf.unite(x,y);
  }
  map<int, int> mp;
  for(int i=0;i<n;i++){
    if(mp[uf.root(i)]==0){
      mp[uf.root(i)]++;
      ans++;
    }
  }
  cout << ans << endl;
  return 0;
}

