class UniteTree{
	public:
		static const int DEFUALTSIZE=100;
		UniteTree();
		UniteTree(int n);
		~UniteTree();
		void unite(int x,int y);
		int find(int x);
		bool same(int x,int y);
		int size(){return _size;};
	private:
		int* _par;
		int* _rank;
		int _size;
		void init(int n){
			_size=n;
			_par = (int *)malloc(n*sizeof(int));
			_rank = (int *)malloc(n*sizeof(int));
			for(int i=0;i<n;i++){
				_par[i]=i;
				_rank[i]=0;
			}
		}
};


UniteTree::~UniteTree(){
	free(_par);
	free(_rank);
}

UniteTree::UniteTree(){
	init(DEFUALTSIZE);
}

UniteTree::UniteTree(int n){
	init(n);
}

int UniteTree::find(int x){
	if(_par[x]==x){
		return x;
	}else{
		return _par[x]=find(_par[x]);
	}
}

void UniteTree::unite(int x,int y){
	x=find(x);
	y=find(y);
	if(x==y)return;
	if(_rank[x]<_rank[y]){
		_par[x]=y;
	}else{
		_par[y]=x;
		if(_rank[x]==_rank[y])_rank[x]++;
	}
}

bool UniteTree::same(int x,int y){
	return find(x)==find(y);
}


