void init(int n){
    for(int i=0;i<n;i++){
        par[i]=i;
        Rank[i]=0;
        size[i]=1;
    }
}

//木の根を求める
int find(int x){
    if(par[x]==x){
        return x;
    }else{
        return par[x]=find(par[x]);
    }
}

//xとyの属する集合を併合
void unite(int x,int y){
    x=find(x);
    y=find(y);
    if(x==y)    return ;
    if(Rank[x]<Rank[y]){
        par[x]=y;
        size[y]+=size[x];
    }else{
        par[y]=x;
        size[x]+=size[y];
        if(Rank[x]==Rank[y])    Rank[x]++;
    }
}

bool same(int x,int y){
    return find(x)==find(y);
}

