    std::vector<std::vector<int>> graph;
    Graph(int N) : N(N) {
        this->graph.resize(N);
    }

    void add_undirected_edge(const int u, const int v) {
        this->graph.at(u).emplace_back(v);
        this->graph.at(v).emplace_back(u);
    }

    void add_directed_edge(const int from, const int to) {
        this->graph.at(from).emplace_back(to);
    }
};

// uから到達可能な頂点をnoで塗る
void dfs(const int u, const int no, vector<int> &color, const Graph &graph) {
    color[u] = no;
    for (int v : graph.graph[u]) {
        if (color[v] == -1) {
            dfs(v, no, color, graph);
        }
    }
}

// グラフの連結成分数
int num_connected_component(const Graph &graph) {
    vector<int> color(graph.N, -1);

    int no = 0;
    for (int u = 0; u < graph.N; ++u) {
        if (color[u] == -1) {
            dfs(u, no, color, graph);
            no++;
        }
    }

    return no;
}

