template<class T>
class union_find {
  public:
    struct node {
      node *parent = nullptr;
      T data;
    };
    union_find() : _nodes() {}
    node *add(T a) {
      node tmp; tmp.data = a;
      _nodes.push_back(tmp);
      node *ret = &_nodes.back();
      return ret;
    }
    void union_(node *a, node *b) {
      node *ra=a,*rb=b;
      std::list<node *> na,nb;
      while(ra->parent!=nullptr) na.push_back(ra), ra = ra->parent;
      while(rb->parent!=nullptr) nb.push_back(rb), rb = rb->parent;
      for(auto *p: na) p->parent=ra;
      for(auto *p: nb) p->parent=rb;
      if(ra!=rb) {
        rb->parent = ra;
      }
    }
    bool find(node *a, node *b) {
      node *ra=a,*rb=b;
      std::list<node *> na,nb;
      while(ra->parent!=nullptr) na.push_back(ra), ra = ra->parent;
      while(rb->parent!=nullptr) nb.push_back(rb), rb = rb->parent;
      for(auto *p: na) p->parent=ra;
      for(auto *p: nb) p->parent=rb;
      return ra==rb;
    }
    std::list<node *> roots() {
      std::list<node *> rts;
      for(auto p: _nodes) {
        if (p.parent == nullptr) rts.push_back(&p);
      }
      return rts;
    }
  private:
    std::list<node> _nodes;
};

int main() {
  int N,M;cin>>N>>M;
  vector<int> X(M),Y(M),Z(M);
  union_find<int> tree;
  map<int, union_find<int>::node *> tnode;
  for(int i=0;i<N;++i) {
    tnode[i] = tree.add(i);
  }
  for(int i=0;i<M;++i) {
    cin>>X[i]>>Y[i]>>Z[i];
    X[i]--;Y[i]--;
    tree.union_(tnode[X[i]],tnode[Y[i]]);
  }
  auto roots = tree.roots();
  int max_group = roots.size();
  cout << max_group << endl;
}

