class UnionFind
{
public:
  UnionFind(int n)//0~n-1までitemを初期化
  {
    parent=vector<int>(n,-1);//親なら-size
    weight=vector<int>(n,0);
  }
  int root(int a)
  {
    if(parent[a]<0)return a;
    root(parent[a]);
    weight[a]+=weight[parent[a]];
    return parent[a]=root(parent[a]);
  }
  int size(int a)
  {
    return -parent[root(a)];
  }
  bool connect(int a,int b,int cost)
  {
    int A=root(a);
    int B=root(b);
    cost+=weight[a];
    cost-=weight[b];
    if(A==B && cost!=0)return false;
    if(A==B)return true;
    if(size(A)>size(B))
    {
      swap(A,B);
    }
    else cost=-cost;
    weight[A]=cost;
    parent[B]+=parent[A];
    parent[A]=B;
    return true;

  }
private:
  vector<int> parent;
  vector<int> weight;

};
