	}
}

int find(int x) {
	if (x == parent[x]) return x;

	parent[x] = find(parent[x]);
	return parent[x];
}

bool isSame(int x, int y) {
	return find(x) == find(y);
}



void link(int x, int y) {
	if (x == y) return;
	if (parent_rank[x] > parent_rank[y]) {
		parent[y] = x;
		return;
	}
	parent[x] = y;
	if (parent_rank[x] == parent_rank[y]) {
		parent_rank[y]++;
	}
}

void unite(int x, int y) {
	link(find(x),find(y));
}



