	UnionFind tree(n); 

	for (int i = 0; i < m; i++) {
		if (tree.same(a[i][0] - 1, a[i][1] - 1)) {
			island++;
		}
		tree.unite(a[i][0] - 1, a[i][1] -1 );
	}
	int ans = n - m + island;
	cout << ans << endl;
	return 0;

}

