struct UnionFind {
  vector<int> p;
  vector<int> s;
  void init(int n) {
    p.resize(n, -1);
    s.resize(n, 1);
  }
  int find(int n) {
    if(p[n] == -1) return n;
    else return find(p[n]);
  }
  void unite(int a, int b) {
    int pa = find(a);
    int pb = find(b);
    int total = s[pa] + s[pb];
    if(pa == pb) return;
    if(s[pa] < s[pb]) p[pa] = pb;
    else p[pb] = pa;
    s[pa] = total;
    s[pb] = total;
  }
};
