// n要素で初期化
void init(int par[], int rank[], int n){
    for(int i=0;i<n;i++){
        par[i] = i;
        rank[i] = 0;
    }
}

// 木の根を求める
int find(int par[], int x){
    if(par[x] == x){
        return x;
    }else{
        return par[x] = find(par,par[x]);
    }
}

// xとyの属する集合を併合
void unite(int par[], int rank[], int x, int y){
    x = find(par,x);
    y = find(par,y);
    if(x == y) return;

    if(rank[x] < rank[y]){
        par[x] = y;
    }else{
        par[y] = x;
        if(rank[x] == rank[y]) rank[x]++;
    }
}

// xとyが同じ集合に属するか否か
bool same(int par[], int x, int y){
    return find(par,x) == find(par,y);
}

int main() {
    int n,m;
    cin >> n >> m;
    int par[n+1];
    int rank[n+1];

    init(par,rank,n+1);

    rep(i,m){
        int x,y,z;
        cin >> x >> y >> z;
        unite(par,rank,x,y);
    }


    ll ans = 0;

    int count[n+1];
    rep(i,n+1){
        count[i] = find(par,i);
    }
    sort(count,count+(n+1));

    ans++;
    srep(i,2,n+1){
        if(count[i]!=count[i-1])ans++;
    }


    cout << ans << endl;
    return 0;
}

