class UnionFind {
public:
	UnionFind(ll n) {
		par_.resize(n);
		iota(par_.begin(), par_.end(), (ll)0);
		rank_.resize(n, 0);
	}

	//根を求める
	ll find(ll x) {
		return (par_[x] == x ? x : par_[x] = find(par_[x]));
	}

	//xとyの属する集合を併合
	void unite(ll x, ll y) {
		x = find(x);
		y = find(y);
		if (x == y) {
			return;
		}
		if (rank_[x] < rank_[y]) {
			par_[x] = y;
		}
		else {
			par_[y] = x;
			if (rank_[x] == rank_[y]) {
				rank_[x]++;
			}
		}
	}

	//xとyが同じ集合に属するか否かを判定
	bool same(ll x, ll y) {
		return (find(x) == find(y));
	}
private:
	vector<ll> par_, rank_;
};

