class UnionFind{
	int32_t *par;
	int32_t *rank;
	int64_t *movable_size;
private:
	int32_t root(int32_t num){
		if(par[num]==num){
			return num;
		}else{
			return par[num]=root(par[num]);
		}
	}
public:
	UnionFind(const int32_t size){
		par = new int32_t[size];
		rank=new int32_t[size];
		movable_size=new int64_t[size];
		for(int32_t i=0;i<size;i++){
			par[i]=i;
			rank[i]=0;
			movable_size[i]=1;
		}
	}
	bool same(int32_t a,int32_t b){
		return root(a)==root(b);
	}
	void unite(int32_t a,int32_t b){
		if(root(a)==root(b)){
			return;
		}
		a=root(a);
		b=root(b);
		if(rank[a]<rank[b]){
			par[a]=b;
			movable_size[b]=movable_size[a]+movable_size[b];
		}else if(rank[a]==rank[b]){
			par[a]=b;
			rank[b]++;
			movable_size[b]=movable_size[a]+movable_size[b];
		}else{
			par[b]=a;
			movable_size[a]=movable_size[a]+movable_size[b];

		}

	}
	int64_t getSize(int64_t a){
		return movable_size[root(a)];
	}
	virtual ~UnionFind(){
		delete[] par;
		delete[] rank;
	}
};


