	if(par[x] == x){
		return x;
	}else{
		return par[x] = find(par[x]);
	}
}

//x,yの属する集合を併合
void unite(int x,int y){
	x = find(x);
	y = find(y);
	if(x == y)return;

	if(rnk[x] < rnk[y]){
		par[x] = y;
	}else{
		par[y] = x;
		if(rnk[x] == rnk[y])rnk[x]++;
	}
}

