  }
  return ret;
}

class Shakutori {
public:
  // 全体の範囲
  // [0, end)
  // 注目している範囲
  // [tail, head)
  Int head, tail, end = 0;
  bool moveHead() {
    if (head == end) {
      return false;
    }
    head++;
    return true;
  }
  void moveTail() { tail++; }
  bool valid() {
    if (head == tail)
      return true;
    // [tail, head)
    // が解として適当か検証する
    return true;
  }
  void solve() {
    head = tail = 0;
    Int ans = 0;
    while (moveHead()) {
      while (!valid()) {
        moveTail();
      }
      // ここで解を更新する
    }
  }
};

class DisJointSet{
public:
    vector<int> v;//親の添字を入れる
    DisJointSet(int n){//初期化
        v = vector<int>(n);
        rep(i, n)v[i] = i;
    }
    int find(int x){//親を返す
        if(v[x] == x)return x;
        else return v[x] = find(v[x]);
    }
    void unite(int x, int y){//xとyをくっつける
        x = find(x);
        y = find(y);
        if(x == y)return;
        v[x] = y;
    }
    bool same(int x, int y){//xとyが同じ集合かどうか
        return find(x) == find(y);
    }
};

