using namespace std;

int main(){
    int n, m;
    scanf("%d %d", &n, &m);
    vector<vector<int> > nn;
    nn.resize(n);
    for(int i = 0; i < m; ++i){
        int x, y, z;
        scanf("%d %d %d", &x, &y, &z);
        nn.at(x-1).push_back(y-1);
        nn.at(y-1).push_back(x-1);
    }

    vector<bool> visited(n, false);
    int ans = 0;

    for(int i = 1; i < n; ++i){
        if(nn.at(i).size() == 0){
            visited.at(i) = true;
            ans++;
        }
    }

    stack<int> s;
    visited.at(0) = true;
    s.push(0);
    ans++;
    while(!s.empty()){
        while(!s.empty()){
            int x = s.top(); s.pop();
            for(int y : nn.at(x)){
                if(visited.at(y)){ continue; }
                visited.at(y) = true;
                s.push(y);
            }
        }

        for(int i = 0; i < n; ++i){
            if(!visited.at(i)){
                s.push(i);
                visited.at(i) = true;
                ans++;
                break;
            }
        }
    }

    printf("%d\n", ans);
    return 0;
}

