struct union_find {
  std::vector<int> parent, rank;
  std::vector<int> size;

  union_find(int n) : parent(n), rank(n), size(n) {
    for (int i = 0; i < n; i++) {
      parent[i] = i;
      rank[i] = 0;
      size[i] = 1;
    }
  }

  int root(int x) {
    if (parent[x] == x) {
      return x;
    } else {
      parent[x] = root(parent[x]);
      return parent[x];
    }
  }

  bool same(int x, int y) {
    return root(x) == root(y);
  }

  void unite(int x, int y) {
    x = root(x);
    y = root(y);

    if (x == y) {
      return;
    }

    // rank and size only means for root nodes
    if (rank[x] < rank[y]) {
      parent[x] = y;
      size[y] += size[x];
    } else if (rank[x] > rank[y]) {
      parent[y] = x;
      size[x] += size[y];
    } else {
      parent[x] = y;
      rank[y] += 1;
      size[y] += size[x];
    }
  }

  void debug() {
    std::cout << "UNION-FIND --- " << std::endl;
    for (int p : parent) {
      std::cout << p << " ";
    }
    std::cout << std::endl;

    for (int p : rank) {
      std::cout << p << " ";
    }
    std::cout << std::endl;

    for (int p : size) {
      std::cout << p << " ";
    }
    std::cout << std::endl;


    std::cout << "-------------- " << std::endl;
  }
};

using namespace std;

int main() {
  int n, m;
  cin >> n >> m;

  union_find uf(n);

  for (int i = 0; i < m; i++) {
    int x, y, z;
    cin >> x >> y >> z;
    x -= 1;
    y -= 1;
    uf.unite(x, y);
  }

  set<int> roots;

  for (int i = 0; i < n; i++) {
    roots.insert(uf.root(i));
  }

  cout << roots.size() << endl;
  return 0;
}

