class union_find {
public:
  vector<ll> data;

  union_find(){};
  union_find(ll size) { data.assign(size, -1); }

  bool unite(ll x, ll y) {
    x = root(x);
    y = root(y);
    if (x == y) {
      return false;
    }
    if (data[x] > data[y]) {
      swap(x, y);
    }
    data[x] += data[y];
    data[y] = x;
    return true;
  }

  bool same(int x, int y) { return root(x) == root(y); }

  ll root(ll x) {
    if (data[x] < 0) {
      return x;
    } else {
      return data[x] = root(data[x]);
    }
  }

  ll size(ll x) { return (-data[root(x)]); }
};

