using D = tuple<ll, ll>;
void dfs(ll const v, graph<ll> const &g, u_set<ll> &visited,
         function<void(ll)> const &visit) {
  if (visited.find(v) != visited.end()) {
    return;
  }
  visited.insert(v);
  visit(v);
  if (g.find(v) == g.end()) {
    return;
  }
  for (auto &&c : g.at(v)) {
    dfs(c, g, visited, visit);
  }
}
void solve() {
  ll N, M;
  input(N, M);
  auto g = graph<ll>{};
  auto d = u_map<D, ll>{};
  for (auto &&i : range(M)) {
    ll x, y, z;
    input(x, y, z);
    g[x].insert(y);
    g[y].insert(x);
    d[D{x, y}] = z % 2;
  }
  auto visited = u_set<ll>{};
  auto roots = u_map<ll, ll>{};
  for (auto &&i : range(1, N + 1)) {
    if (visited.find(i) == visited.end()) {
      dfs(i, g, visited, [&](auto it) { roots[it] = i; });
    }
  }
  dump(g);
  dump(roots);
  auto counts = u_set<ll>{};
  for (auto &&i : roots) {
    counts.insert(i.second);
  }
  dump(counts);
  print(counts.size());
}
int main() {
