struct UnionFind {
  vector<int> par;
  UnionFind( int n ) {
    par.resize(n);
    init(n);
  }
  void init( int n ) {
    for(int i=0; i<n; ++i )  par[i] = i;
  }
  int root( int a ) {
    int pa = par[a];
    if ( pa == a ) return a;
    return par[a] = root(pa);
  }
  bool merge( int a, int b ) {
    int ra = root(a);
    int rb = root(b);
    if ( ra == rb ) return false;
    par[rb] = ra;
    return true;
  }
  bool isSame( int a, int b) {
    int ra = root(a);
    int rb = root(b);
    if ( ra == rb ) return true;
    else return false;
  }
  int CountRoot( int n ) {
    int cnt = 0;
    for (int i=0; i<n; ++i )
      if ( i == par[i] ) cnt++;
    return cnt;
  }
};

