int find_root(int x){
  int y = root[x];
  if(x == y){
    return x;
  }
  int z = find_root(y);
  root[x] = z;
  return z;
}

void merge(int x,int y){
  int xx = find_root(x);
  int yy = find_root(y);
  if(xx == yy){
    return;
  }
  n_component -= 1;
  if(depth[xx] >= depth[yy]){
    root[yy] = xx;
    depth[xx] += 1;
  } else {
    root[xx] = yy;
    depth[yy] += 1;
  }
  return;
}

