    REP(i, M){
        ll c;
        cin >> A[i] >> B[i] >> c;
        A[i]--;
        B[i]--;
    }

    UnionFind uf(N);

    // 辺を1つずつ足していく
    REP(i, M){


        ll x = A[M-i-1];
        ll y = B[M-i-1];

        // 同じ木に属すなら処理終了
        if(uf.issame(x, y)) continue;

        //最後にマージ処理をする
        uf.merge(x, y);
    }

    map<ll,ll> MAP;

    REP(i, N){
        MAP[uf.root(i)]++;
    }

    cout << MAP.size() << endl;

    return 0;
}

