// Union-Find木
// 初期化 UF(N); Nは要素数
// 結合 unite(x,y); 同じ集合か判定 same(x,y);
// 集合の数を数える count()
struct UF{
  vector<int> par,sizes;
  UF(int N) : par(N),sizes(N, 1){ for(int i=0; i<N; i++) par[i]=i; }

  int find(int x){ return par[x]==x ? x : par[x] = find(par[x]); }

  bool same(int x,int y){ return find(x) == find(y); }

  int size(int x){ return sizes[find(x)]; }

  void unite(int x, int y){
    x = find(x); y = find(y);
    if(x == y) return;
    if(sizes[x] < sizes[y]) swap(x,y);
    par[y] = x;
    sizes[x] += sizes[y];
  }
  int count(){
    int cnt = 0;
    rep(i,sz(par) ) if(par[i] == i) cnt++;
    return cnt;
  }
};

int main(){
  ini(N,M);
  UF uf(N);
  rep(i,M){
    ini(x,y,z);
    x--; y--;
    uf.unite(x,y);
  }
  out(uf.count());
}

