		return n;
	else
		return Search(par[n], par);
}

void uni(const int a, const int b, vector<int> &par, vector<int> &dep) {
	if (dep[a] < dep[b])
		par[a] = b;
	else if (dep[a] > dep[b])
		par[b] = a;
	else {
		par[b] = a;
		dep[a]++;
	}
}

