class UnionFindTree
{
private:
    vector<int> par_;
    vector<int> rank_;

public:
    UnionFindTree(int);
    ~UnionFindTree();
    int root(int);
    bool same(int, int);
    void unite(int, int);
    int numRoot();
};

UnionFindTree::UnionFindTree(int n) : par_(n), rank_(n)
{
    iota(par_.begin(), par_.end(), 0);
}

UnionFindTree::~UnionFindTree()
{
}

int UnionFindTree::root(int x)
{
    return par_[x] == x ? x : par_[x] = root(par_[x]);
}

bool UnionFindTree::same(int x, int y)
{
    return root(x) == root(y);
}

void UnionFindTree::unite(int x, int y)
{
    x = root(x);
    y = root(y);
    if (x == y)
        return;
    else if (rank_[x] < rank_[y])
        par_[x] = y;
    else
    {
        par_[y] = x;
        if (rank_[x] == rank_[y])
            rank_[x]++;
    }
}

int UnionFindTree::numRoot()
{
    int n = 0;
    for (int i = 0; i < par_.size(); i++)
    {
        if(i==root(i))
            n++;
    }
    return n;
}

