class UnionFind{
    public:
    vector<ll> par;
    vector<ll> rank;
    ll numComponent;
    void init(ll n){
        par.resize(n);
        rank.assign(n, 1LL);
        for(ll i=0; i<n; i++)par[i] = i;
        numComponent=n;
    }

    ll findRoot(ll x){
        if(par[x] == x)return x;
        else return par[x] = findRoot(par[x]);
    }

    void unite(ll x, ll y){
        x = findRoot(x);
        y = findRoot(y);
        if(x == y)return;
        if(rank[x] < rank[y])swap(x, y);
        rank[x] += rank[y];
        par[y] = x;
        numComponent--;
        return;
    }

    bool same(ll x, ll y){
        return findRoot(x) == findRoot(y);
    }

    ll size(ll x){
        return rank[findRoot(x)];
    }
};

