struct UnionFind {
    vector<int> parent, height;
    int group;
    UnionFind(int N) {
        parent = vector<int>(N, -1);
        height = vector<int>(N, 1);
        group = N;
    }
    int find(int a) {
        if(parent[a] < 0) return a;
        parent[a] = find(parent[a]);
        return parent[a];
    }
    bool same(int a, int b) {
        return find(a) == find(b);
    }
    int count(int a) {
        return -parent[find(a)];
    }
    void unite(int a, int b) {
        a = find(a); b = find(b);
        if(a == b) return;
        group--;
        if(height[b] < height[a]) swap(a, b);
        if(height[a] == height[b]) height[a]++;
        parent[b] += parent[a];
        parent[a] = b;
    }
};

int main() {
    int n, m; cin >> n >> m;
    UnionFind uf(n);
    rep(i, m) {
        int x, y, z; cin >> x >> y >> z;
        uf.unite(x-1, y-1);
    }
    cout << uf.group << endl;
    return 0;
}

