int parent(int a) {
	if (uf[a] == a) {
		return a;
	}
	uf[a] = parent(uf[a]);
	return uf[a];
}

void link(int a, int b) {
	if (rk[a] < rk[b]) {
		uf[b] = a;
	} else {
		if (rk[a] == rk[b]) {
			rk[a]++;
		}
		uf[a] = b;
	}
}

void unite(int a, int b) {
	link(parent(a), parent(b));
}



