vector<int> depth; // ランク


void init(int n = 1) {
    par.resize(n); depth.resize(n);
    for (int i = 0; i < n; ++i) par[i] = i, depth[i] = 0;
}

int root(int x) {
    if (par[x] == x) {
        return x;
    }
    else {
        int r = root(par[x]);
        return par[x] = r;
    }
}

bool issame(int x, int y) {
    return root(x) == root(y);
}

bool merge(int x, int y) {
    x = root(x); y = root(y);
    if (x == y) return false;
    if (depth[x] < depth[y]) swap(x, y);
    if (depth[x] == depth[y]) ++depth[x];
    par[y] = x;
    return true;
}

