    ld norm() const {return sqrt(x * x + y * y);}
    tuple<ld, ld> get_value(){return make_tuple(x, y);}

    ll which_quadrant() const{
        if (abs(x) < EPS && abs(y) < EPS) return 0;
        if (y > 0) return x > 0 ? 1 : 2;
        return x < 0 ? 3 : 4;
    }

    bool is_zero(){
        fpoint z = {0, 0};
        return z == *this;
    }

};

struct point {
