int main()
{
    int N, M;
    cin >> N >> M;
    vector<vector<int>> adjacency(N);
    for (int i = 0; i < M; ++i)
    {
        int X, Y, Z;
        cin >> X >> Y >> Z;
        // Zの値に関係なく，関係性の分かっている２カードをつなぐ
        adjacency[X - 1].push_back(Y - 1);
        adjacency[Y - 1].push_back(X - 1);
    }

    // 形成したネットワークの連結部分数を数える
    map<int, bool> passedMap;
    for (int i = 0; i < N; ++i)
    {
        passedMap[i] = false;
    }
    int clusterNum = 0;
    for (;;)
    {
        // まだ登場していないノードを探して開始ノードとする
        int origin = -1;
        for (int i = 0; i < N; ++i)
        {
            if (passedMap[i] == false)
            {
                origin = i;
                break;
            }
        }
        // 全てのノードを探索し終えているなら終了
        if (origin == -1)
        {
            break;
        }
        // 開始ノードを含むクラスターを探索
        ++clusterNum;
        passedMap[origin] = true;
        deque<int> keys{ origin };
        for (;;)
        {
            if (keys.empty())
            {
                break;
            }
            int key = keys.front();
            keys.pop_front();
            for (const int neighbor : adjacency[key])
            {
                if (passedMap[neighbor] == false)
                {
                    passedMap[neighbor] = true;
                    keys.push_back(neighbor);
                }
            }
        }
    }
    cout << clusterNum;

    return 0;
}

