#pragma region UnionFind
struct UnionFind
{
	vector<int> par;

	UnionFind(int n) : par(n, -1) {}
	void init(int n) { par.assign(n, -1); }

	int root(int x)
	{
		if (par[x] < 0) return x;
		else return par[x] = root(par[x]);
	}

	bool issame(int x, int y)
	{
		return root(x) == root(y);
	}

	bool merge(int x, int y)
	{
		x = root(x); y = root(y);
		if (x == y) return false;
		if (par[x] > par[y]) swap(x, y);
		par[x] += par[y];
		par[y] = x;
		return true;
	}

	int size(int x)
	{
		return -par[root(x)];
	}
};
#pragma endregion


int main()
{
	int n, m; cin >> n >> m;
	UnionFind uf(n);
	rep(i, 1, m)
	{
		int x, y, z; cin >> x >> y >> z;
		--x, --y;
		uf.merge(x, y);
	}
	set<int> s;
	rep(i, 0, n - 1)
	{
		s.insert(uf.root(i));
	}
	cout << s.size() << endl;
}

