const int maxn = 3e5 + 5;
int fa[maxn], vis[maxn];
int X[maxn], Y[maxn], Z[maxn];
int Find(int x) {
	if (x != fa[x])
		fa[x] = Find(fa[x]);
	return fa[x];
}
void getF(int x, int y) {
	int xx = Find(x), yy = Find(y);
	if (xx != yy)
		fa[xx] = yy;
}
int main() {
	int n, m;
	while (cin >> n >> m) {
		for (int i = 1; i <= n; i++)
			fa[i] = i, vis[i] = 0;
		for (int i = 1; i <= m; i++)
			scanf("%d%d%d", &X[i], &Y[i], &Z[i]);
		for (int i = 1; i <= m; i++)
			getF(X[i], Y[i]);
		int ans = 0;
		for (int i = 1; i <= n; i++) {
			int t = Find(i);
			if (!vis[t])
				ans++, vis[t] = 1;
		}
		printf("%d\n", ans);
	}
}

