vi par,ran;

void init(int n) {
  rep(i,n) {
    par.push_back(i);
    ran.push_back(0);
  }
}

int find(int x) {
  if(par[x]==x) return x;
  return x=find(par[x]);
}

void unite(int x,int y) {
  x=find(x);
  y=find(y);
  if(x==y) return;
  if(ran[x]<ran[y]) par[x]=y;
  else {
    par[y]=x;
    if(ran[x]==ran[y]) ran[x]++;
  }
}

