class DSU
{
public:
    vector<int> f;
    vector<int> cnt;
    DSU(int sz)
    {
        f = vector<int>(sz);
        cnt = vector<int>(sz, 1);
        forn(i, sz) f[i] = i;
    }
    int get(int x)
    {
        return f[x] == x ? x : (f[x] = get(f[x]));
    }
    void merge(int x, int y)
    {
        x = get(x);
        y = get(y);
        if (x != y)
            f[x] = y, cnt[y] += cnt[x];
    }
    bool same(int x, int y)
    {
        return get(x) == get(y);
    }
    int count(int x)
    {
        return cnt[get(x)];
    }
};

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);
	ll n, m;
	cin >> n >> m;
	DSU dsu(n + 1);
	forn(i, m)
	{
		ll x, y, z;
		cin >> x >> y >> z;
		dsu.merge(x, y);
	}
	ll ans = 0;
	ll rmn = n;
	fori(i, 1, n + 1)
	{
		if(dsu.get(i) == i)
		{
			ll cnt = dsu.count(i);
			ans++, rmn -= cnt;
		}
	}
	cout << (ans + rmn) << endl;
	return 0;
}

