struct UnionFind {
    vector<int> parent;
    vector<int> rank;

    void init(int n) {
        parent = vector<int>(n);
        rank = vector<int>(n);

        for(int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    int find(int x) {
        if(parent[x] == x)
            return x;
        else
            return parent[x] = find(parent[x]);
    }

    void unite(int x, int y) {
        int px = find(x);
        int py = find(y);

        if(px == py)
            return;

        if(rank[px] == rank[py]) {
            parent[py] = px;
            rank[px]++;
        }
        else if(rank[px] < rank[py])
            parent[px] = py;
        else
            parent[py] = px;
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }
};

