        parent[i] = i, Rank[i] = 1;
}

int find_parent(int x)
{
    if(parent[x] == x)
    {
        return x;
    }
    return parent[x] = find_parent(parent[x]);
}

void make_union(int x, int  y)
{
    int p = find_parent(x);
    int q = find_parent(y);
    if(p != q)
    {
        if(Rank[p] < Rank[q])
            swap(p,q);
        parent[q] = p;
        Rank[p] += Rank[q];
        n--;
        // Rank[q] += Rank[p];
    }
}

bool isUnion(int x, int y)
{
    return find_parent(x) == find_parent(y);
}

