class Segment_Tree{
  private:
    ll n;
    ll n_;

  public:
    vector<pair<ll, ll>> dat;
    Segment_Tree(ll n__){
      // For simply, the number of component is set to be power of 2
      n = 1;
      n_ = n__;
      while(n < n_) n*=2;

      dat.resize(2*n-1, {-1, 0});
      return;
    };

    ~Segment_Tree(void){
      return;
    };

    //k-th value is changed to a
    void update(ll k, pair<ll, ll> a){
      k += n-1;
      dat[k] = a;
      while(k>0){
        k = (k-1)/2;
        dat[k] = max(dat[k*2+1], dat[k*2+2]);
      }
      return;
    };

    //k-th value is changed to a
    void update2(ll k){
      k += n-1;
      dat[k].first--;
      while(k>0){
        k = (k-1)/2;
        dat[k] = max(dat[k*2+1], dat[k*2+2]);
      }
      return;
    };

    // search the minimum of [a, b)
    // Other values are used for simply
    // From outside, call query(a, b, 0, 0, n)
    // k is the node index, 
    // temporary block is [l, r)
    pair<ll, ll> query(ll a, ll b, ll k, ll l, ll r){
      //if there are no overlap between [a, b) and [l, r)
      if(r<=a || b<=l) return {-1, 0};

      //if [a, b) contains [l, r), return the value of this node
      if(a<=l && r<=b) return dat[k];

      pair<ll, ll> vl = query(a, b, k*2+1, l, (l+r)/2);
      pair<ll, ll> vr = query(a, b, k*2+2, (l+r)/2, r);
      return max(vl, vr);
    };

    // search the minimum of [a, b)
    pair<ll, ll> query(ll a, ll b){
      if(a<0 || n_<b || a==b){
        fprintf(stderr, "Segment_Tree Search Space Error\n");
        exit(0);
      }
      return query(a, b, 0, 0, n);
    };
};


