int parent[100010];

void init(int n) {
	for(int i = 0; i < n; i++) {
		parent[i] = i;
	}
}

int root(int x) {
	if(parent[x] == x) {
		return x;
	}
	return parent[x] = root(parent[x]);
}

bool same(int x, int y) {
	return root(x) == root(y);
}

void unite(int x, int y) {
	x = root(x);
	y = root(y);
	if(x == y) {
		return;
	}
	parent[x] = y;
}

int numGroup(int n) {
	int result = 0;
	for(int i = 0; i < n; i++) {
		if(parent[i] == i) {
			result++;
		}
	}
	return result;
}

