void visit_dfs(vector<int> *c, vector<bool> &visit, int start = 0) {
  visit[start] = 0;
  stack<int> s;
  s.push(start);
  visit[start] = true;
  while (!s.empty()) {
    int current = s.top();
    s.pop();
    for (const auto &e : c[current])
      if (!visit[e]) {
        s.push(e);
        visit[e] = true;
      }
  }
}

