		x = parent(x);
		y = parent(y);
		if(x == y){
			continue;
		}
		if(Rank[x] < Rank[y]){
			Par[x] = y;
		}
		else if(Rank[x] > Rank[y]){
			Par[y] = x;
		}
		else{
			Rank[x]++;
			Par[y] = x;
		}
	}
