class E1Or2 {
public:
	void solve(std::istream& in, std::ostream& out) {
	    int n, m;
	    in >> n >> m;
	    vi x(m), y(m), z(m);

	    ll res = 0;
	    map<int, int> mp;
	    for(int i=0; i<m; i++){
	        in >> x[i] >> y[i] >> z[i];
	        --x[i]; --y[i]; --z[i];
	        mp[x[i]]++; mp[y[i]]++; mp[z[i]]++;
	    }
	    for(int i=0; i<n; i++){
	        if(!mp.count(i)) res++;
	    }

	    vi v(n);
	    for(int i=0; i<m; i++){
	        int s = v[x[i]] + v[y[i]] + v[z[i]];
	        if(s <= 1){
	            if(x[i] == z[i]){
                    v[x[i]] = 1;
                    v[y[i]] = 1;
                    res++;
	            }
	            if(y[i] == z[i]){
                    v[x[i]] = 1;
                    v[y[i]] = 1;
                    res++;
	            }
	        }else{
	            v[x[i]] = 1;
	            v[y[i]] = 1;
	            v[z[i]] = 1;
	        }
	    }

	    for(int i=0; i<m; i++){
            int s = v[x[i]] + v[y[i]] + v[z[i]];
            if(s == 1) res++;
            else if(s == 0) res += 2;
            v[x[i]] = 1;
            v[y[i]] = 1;
            v[z[i]] = 1;
	    }

	    out << res << enl;
	}
};


