const int MAX = 1e5 + 5;
vector<int> adj[MAX];
bool visited[MAX];

void dfs(int x) {
    visited[x] = true;
    for (auto &each : adj[x]) if (!visited[each]) dfs(each);
}

void solve() {
    int n, m;
    cin >> n >> m;
    fori (i, 0, m) {
        int u, v, w;
        cin >> u >> v >> w;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    int ans = 0;
    fori (i, 1, n + 1) {
        if (!visited[i]) {
            dfs(i);
            ans++;
        }
    }
    cout << ans << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    solve();
    return 0;
}

