            }
            par.at(rx) = ry;
            size.at(rx) += size.at(ry);
            return;
        }
    }

    bool same(int x, int y){
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }

    int get_size(int x){
        return size.at(root(x));
    }
};

