class UnionFind {
  vector<int> size_;
  vector<int> parent_;

public:
  UnionFind(int n) {
    size_.reserve(n);
    parent_.reserve(n);
    for (int i = 0; i < n; i++) {
      size_.push_back(1);
      parent_.push_back(i);
    }
  }

  int getSize(int x) { return size_[x]; }

  bool same(int x, int y) { return find(x) == find(y); }

  int find(int x) {
    if (x == parent_[x]) {
      return x;
    }
    return parent_[x] = find(parent_[x]);
  }

  void _union(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) {
      return;
    }
    if (size_[x] < size_[y]) {
      parent_[x] = y;
      size_[y] += size_[x];
    } else if (size_[x] >= size_[y]) {
      parent_[y] = x;
      size_[x] += size_[y];
    }
  }
};

