struct UF{
  vector<int> parent, size_;
  UF(int n){
    rep(i, n){
      parent.push_back(i);
      size_.push_back(1);
    }
  }
  int root(int x){
    if(parent[x] == x) return x;
    return parent[x] = root(parent[x]);
  }
  void unite(int x, int y){
    if(root(x) == root(y)) return;
    else if(root(x) > root(y)){
      size_[root(y)] += size_[root(x)];
      parent[root(x)] = root(y);
      return;
    }
    else{
      size_[root(x)] += size_[root(y)];      
      parent[root(y)] = root(x);
      return;
    }
  }
  bool same(int x, int y){
    return root(x) == root(y);
  }
  int size(int x){
    return size_[root(x)];
  }
};

