    return cnt[root(x)];
  }
  int size() {
    return _size;
  }

private:
  vector<int> par;
  vector<int> rnk;
  vector<int> cnt; // The number of vertices in each connected components.
  int _size; // The number of connected components. Decreases by unite.
};

int main(int argc, char** argv) {
