int num_groups, p[100000], n, m, a, b, c;
int par(int x) { return (p[x]==x)? x:p[x]=par(p[x]); }
bool isSameGroup(int a, int b) { return par(a) == par(b); }
void merge(int a, int b) {
    num_groups -= (!isSameGroup(a, b);
    p[par(a)] = par(b);
}

int main() {
  cin >> n >> m;
  for (int i=0; i<n; i++) p[i] = 1;
  num_groups = n;
  for (int i=0; i<m; i++) {
    cin >> a >> b >> c;
    merge(a-1, b-1);
  }
  cout << num_groups;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD=1000000007;
int MAX_N=1001000;
vector<int> Par(MAX_N);
vector<int> Rank(MAX_N);

void init(int N){
    for(int i=0; i<N; i++){
        Par[i]=i;
        Rank[i]=0;
    }
}

int find(int x){
    if(Par[x]==x){
        return x;
    }
    return Par[x]=find(Par[x]);
}

void unite(int x, int y){
  	int fx=find(x);
  	int fy=find(y);
    if(fx==fy){
        return;
    }
    if(Rank[fx]<Rank[fy]){
        Par[fx]=fy;
    }
    else{
        Par[fy]=fx;
        if(Rank[fx]==Rank[fy]){
            Rank[fx]++;
        }
    }
}

int main(){
    int N, M;
    cin>>N>>M;
  	init(N);
    vector<int> X(M), Y(M), Z(M);
    for(int i=0; i<M; i++){
        cin>>X[i]>>Y[i]>>Z[i];
      	X[i]--;
      	Y[i]--;
    }
    for(int i=0; i<M; i++){
        unite(X[i], Y[i]);
    }
    set<ll> PP;
    for(int i=0; i<N; i++){
        PP.insert(find(i));
      	//cout<<find(i)<<endl;
    }
    cout<<PP.size()<<endl;
  	return 0;
}

