-(Int)rank // https://www.geeksforgeeks.org/program-for-rank-of-matrix/
{
    Matrix *mat = [self copy];
    Int rank = _width;
    for (Int row = 0; row < rank; row++) {
        // Before we visit current row 'row', we make
        // sure that mat[row][0],....mat[row][row-1]
        // are 0.
        // Diagonal element is not zero
        if ([mat valueAtRow:row column:row] != 0) {
            for (int col = 0; col < _height; col++) {
                if (col != row) {
                    // This makes all entries of current
                    // column as 0 except entry 'mat[row][row]'
                    double mult = [mat valueAtRow:col column:row] / [mat valueAtRow:row column:row];
                    for (int i = 0; i < rank; i++) {
                        double a = mult * [mat valueAtRow:row column:i];
                        double b = [mat valueAtRow:col column:i];
                        [mat setValue:b-a atRow:col column:i];
                    }
                }
            }
        }
        // Diagonal element is already zero. Two cases
        // arise:
        // 1) If there is a row below it with non-zero
        //    entry, then swap this row with that row
        //    and process that row
        // 2) If all elements in current column below
        //    mat[r][row] are 0, then remvoe this column
        //    by swapping it with last column and
        //    reducing number of columns by 1.
        else {
            BOOL reduce = YES;
            // Find the non-zero element in current column
            for (Int i = row+1; i < _height;  i++) {
                // Swap the row with non-zero element
                // with this row.
                if ([mat valueAtRow:i column:row] != 0) {
                    [mat exchangeRowAt:row withRowAt:i];
                    reduce = NO;
                    break ;
                }
            }
            // If we did not find any row with non-zero
            // element in current columnm, then all
            // values in this column are 0.
            if (reduce) {
                // Reduce number of columns
                rank--;
                // Copy the last column here
                for (Int i = 0; i < _height; i ++) {
                    double a = [mat valueAtRow:i column:rank];
                    [mat setValue:a atRow:i column:row];
                }
            }
            // Process this row again
            row--;
        }
        // Uncomment these lines to see intermediate results
        // display(mat, R, C);
        // printf("\n");
    }
    return rank;
}
