        NSMutableArray *lines = [StdIO stringsFromStdInSeparatedByCharacter:'\n'];
        NSString *line = [lines shift];
        NSArray *nums = [line componentsSeparatedByString:@" "];
        Int n = [nums firstInteger];
        Int m = [nums secondInteger];
        if (m==1) {
            [StdIO put:"%d", n-1];
            return 0;
        }
        NSMutableArray *rows = [NSMutableArray array];
        for (NSString *line in lines) {
            NSArray *values = [line componentsSeparatedByString:@" "];
            Int x = [values firstInteger];
            Int y = [values secondInteger];
            Int z = [values thirdInteger];
            NSMutableArray *row = [NSMutableArray array];
            for (Int i=0; i<n; i++) {
                if (i==x-1) {
                    [row push:@1];
                } else if (i==y-1) {
                    [row push:@(z%2==0 ? -1 : 1)];
                } else {
                    [row push:@0];
                }
            }
            [rows push: row];
        }
        Matrix *mat = [[Matrix alloc] initWithRows:rows];
        [StdIO put:"%d", n - [mat rank]];
    }
