typedef struct d_t {
    int x, y;
} DATA;

int qsort_data_u(const void *a, const void *b)
{
    return (*(DATA *) a).x - (*(DATA *) b).x;
}

int main(int argc, char *argv[])
{
    int n, m;
    int x, y, z;
    int root[100000];
    DATA d[100000];
    int i, j;
    int ans;

    scanf("%d %d", &n, &m);

    for (i = 0; i < m; i++) {
        scanf("%d %d %d", &x, &y, &z);
        x--;
        y--;
        // x < y (制約)
        d[i].x = x;
        d[i].y = y;
        // zは要らない
    }

    for (i = 0; i < n; i++) {
        root[i] = i;
    }

    qsort(d, m, sizeof(DATA), qsort_data_u);

    // Union
    for (i = 0; i < m; i++) {
        x = d[i].x;
        y = d[i].y;
        if (root[y] != y) {
            for (j = 0; j < i; j++) {
                if (root[j] == root[y]) {root[j] = root[x];}
            }
        }
        root[y] = root[x];
    }

    ans = 0;

    for (i = 0; i < n; i++) {
        if (root[i] == i) {
            ans++;
        }
    }

    printf("%d\n", ans);

    return 0;
}

