#define N 100001

typedef struct UnionFindTree{
  int parent;
  int size;
  bool reveal;
} uft;

uft t[N];
int ans = 0;

void init(int n) {
  for (int i=0; i<n; i++) {
    t[i].parent = i;
    t[i].size = 1;
    t[i].reveal = false;
  }
}

int root(int a) {
  if (t[a].parent == a) return a;
  else return root(t[a].parent);
}

void unite(int a, int b) {
  int ra=root(a), rb=root(b);
  if (t[ra].size < t[rb].size) {
    t[rb].parent = ra;
    t[ra].size += t[rb].size;
  } else {
    t[ra].parent = rb;
    t[rb].size += t[ra].size;  
  }
}

void dfs(int a) {
  if (t[a].reveal == true) return ;
  if (t[a].parent == a) {
    t[a].reveal = true;
    ans++;
    return ;
  }
  dfs(t[a].parent);
  t[a].reveal = true;
  return ;
}

int main() {
  int n, m;
  scanf("%d%d", &n, &m);
  init(n);
  int x, y, z;
  for (int i=0; i<m; i++) {
    scanf("%d%d%d", &x, &y, &z);
    x--;
    y--;
    unite(x, y);
  }
  for (int i=0; i<n; i++) dfs(i);
  printf("%d\n", ans);
  return 0;
}

