int parent[100000], rank[100000];

int find_root(int x) {
  if(parent[x] == x) return x;
  return parent[x] = find_root(parent[x]);
}

void unit(int x, int y) {
  x = find_root(x);
  y = find_root(y);
  if(x == y) return;
  if(rank[x] < rank[y]) {
    parent[x] = y;
  } else {
    parent[y] = x;
    if(rank[x] == rank[y]) rank[x]++;
  }
}

