  }

  for(i = 0; i < m; i++) {
    scanf("%d %d %d", &x, &y, &z);
    x--;
    y--;
    unit(x, y);
  }

  int num_magic = 0;
  for(i = 0; i < n; i++) {
    if(parent[i] == i) num_magic++;
  }

