int find(int x, int par[]){
	if (par[x] == x)return x;
	else return par[x] = find(par[x], par);
}

void unite(int x, int y, int par[]){
	int rx = find(x, par);
	int ry = find(y, par);
	if (rx != ry)par[ry] = rx;
}

