void init(int N){
  for(int i = 0;i < N;i++){
    par[i] = i;
    rank[i] = 0;
  }
}

int root(int x){
  if(x == par[x]) return x;
  return par[x] = root(par[x]);
}

int same(int x,int y){
  if(root(x) == root(y))
    return 1;
  return 0;
}

void unite(int x,int y){
  x = root(x);
  y = root(y);
  if(x == y) return;

  if(rank[x] < rank[y]){
    par[x] = y;
  }else{
    par[y] = x;
    if(rank[x] == rank[y]) rank[x]++;
  }
}

