#define N 100001

typedef struct UnionFindTree{
  int parent;
  bool reveal;
} uft;

uft t[N];
int ans = 0;

void init(int n) {
  for (int i=0; i<n; i++) {
    t[i].parent = i;
    t[i].reveal = false;
  }
}

int root(int a) {
  if (t[a].parent == a) return a;
  else return root(t[a].parent);
}

void unite(int a, int b) {
  int ra=root(a), rb=root(b);
  t[rb].parent = ra;
}

void dfs(int a) {
  if (t[a].reveal == true) return ;
  if (t[a].parent == a) {
    t[a].reveal = true;
    ans++;
    return ;
  }
  dfs(t[a].parent);
  t[a].reveal = true;
  return ;
}

