using namespace std;

struct UnionFind {
    vector<int> par, rank, mem;  // par[i]: iの親番号

    UnionFind(int N) : par(N), rank(N), mem(N) {  // 最初はすべてが根であるとして初期化
        int tree_num = N;
        for(int i=0; i<N; i++) {
            par[i] = i;
            rank[i] = 0;
            mem[i] = 1;
        }
    }

    int root(int x) {
        if(par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    int unite(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        int temp = mem[rx] * mem[ry];
        if(rx == ry) return 0;
        tree_num--;
        if(rank[rx] < rank[ry]) {
            mem[ry] += mem[rx];  mem[rx] = 0;
            par[rx] = ry;
        } else {
            mem[rx] += mem[ry];  mem[ry] = 0;
            par[ry] = rx;
            if(rank[rx] == rank[ry]) {
                rank[rx]++;
            }
        }
        return temp;
    }

    bool same(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};



int main()
{
    int n, m, i, x, y, z;
    scanf("%d%d",&n,&m);
    UnionFind tree(n);
    for(i=0; i<m; i++) {
        scanf("%d%d%d",&x,&y,&z);
        tree.unite(x, y);
    }
    printf("%d",tree.tree_num);
    return 0;
}

