typedef struct List
{
    struct List *next;
    int i;
} list;

void queue(list *p, int i)
{
    if (p->next == NULL)
    {
        p->next = (list *)malloc(sizeof(list));
        (p->next)->i = i;
        (p->next)->next = NULL;
        return ;
    }
    queue(p->next, i);
}

void queue2(list *p, list *q)
{
    if (p->next == NULL)
    {
        while (q->next)
        {
            p->next = (list *)malloc(sizeof(list));
            (p->next)->i = q->i;
            p = p->next;
            q = q->next;
        }
        p->next = NULL;
        return ;
    }
    queue(p->next, q);
}

void input(int *f, list *l, int i)
{
    while (l->next)
    {
        f[l->i] = i;
        l = l->next;
    }
}

