    for (i = 0; i < m; i++)
    {
        if (f[x[i]] + f[y[i]] == 0)
        {
            f[x[i]] = i + 1;
            f[y[i]] = i + 1;
            cnt++;
            l[i].i = x[i];
            l[i].next = (list *)malloc(sizeof(list));
            (l[i].next)->i = y[i];
            (l[i].next)->next = NULL;
        }
        else if (f[x[i]] && !f[y[i]])
        {
            f[y[i]] = f[x[i]];
            cnt++;
            queue(&l[f[x[i]]], y[i]);
        }
        else if (!f[x[i]] && f[y[i]])
        {
            f[x[i]] = f[y[i]];
            cnt++;
            queue(&l[f[x[i]]], x[i]);
        }
        else if (f[x[i]] - f[y[i]])
        {
            cnt++;
            queue2(&l[f[x[i]]], &l[f[y[i]]]);
            input(f, &l[f[x[i]]], f[x[i]]);
        }
    }
    printf("%d", n - cnt);
}

