fun solve(matrix: MutableMap<Int, MutableMap<Int,Int>>,num_nodes:Int) : Int {

    val visited: Array<Boolean> = Array(num_nodes) {
        false
    }
    var count = 0

    while(visited.any { it == false }) {
        count++
        val index_queue: ArrayDeque<Int> = ArrayDeque()
        val root_index = visited.indices.first {visited[it] == false }

        visited[root_index] = true
        index_queue.add(root_index + 1)

        while(! index_queue.isEmpty()) {
            val index = index_queue.poll()
            matrix[index]?.forEach { 
                if(visited[it.key - 1] == false) {
                    index_queue.add(it.key)

                    visited[it.key - 1] = true                    
                }
            }
        }
    }


    return count
}
