    class dsu{
    int connected, par[], sz[];

    dsu(int n){
        par=new int[n];
        sz=new int[n];
        for(int i=0;i<n;i++){
            par[i]=i;
            sz[i]=1;
        }
        connected=n;
    }

    int getPar(int k){
        while(k!=par[k]){
            par[k]=par[par[k]];
            k=par[k];
        }
        return k;
    }

    int getSize(int k){
        return sz[getPar(k)];
    }

    void unite(int u, int v){
        int par1=getPar(u), par2=getPar(v);

        if(par1==par2)
            return;

        connected--;

        if(sz[par1]>sz[par2]){
            int tem=par1;
            par1=par2;
            par2=tem;
        }

        sz[par2]+=sz[par1];
        sz[par1]=0;
        par[par1]=par[par2];
    }
}

