	public static boolean dfs(int node, int parent, ArrayList<HashSet<Integer>> adj, boolean[] visited, boolean[] looped) {
		if(looped[node]) { 
			return looped[node];
		}else if(visited[node]) {
			return looped[node] = true;
		}

		visited[node] = true;
		for(final int next : adj.get(node)) {
			if(next == parent) { continue; }

			if(dfs(next, node, adj, visited, looped)) {
				looped[node] = true;
			}
		}

		return looped[node];
	}

