                	if(!check(aList,input[j][1])){
            			aList.add(input[j][1]);
            		}
                }

              	if(input[i][1] == input[j][1]){
                	if(!check(aList,input[j][0])){
            			aList.add(input[j][0]);
            		}
                }
            }
          }
        }

      	result = result + n - aList.size();
        System.out.println(result);
    } catch (IOException e) {
