            scanner.next();
        }

        System.out.println(unionFind.parents);
    }

    static class UnionFind {
        int parents;
        private int[] parent;

        UnionFind(int n) {
            parents = n;
            parent = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        int root(int n) {
            while (parent[n] != n) {
                n = parent[n] = parent[parent[n]];
            }
            return n;
        }

        void unite(int x, int y) {
            x = root(x);
            y = root(y);
            if (x != y) {
                parents--;
                parent[x] = y;
            }
        }
   }
}

