    private void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        boolean[][] map = new boolean[n + 2][n + 2];
        for (boolean[] a : map) {
            Arrays.fill(a, false);
        }

        Set<Integer> set = new HashSet<>(n);
        for (int i = 1; i <= n; i++) {
            set.add(i);
        }

        for (int i = 0; i < m; i++) {
            int x = in.nextInt();
            int y = in.nextInt();
            in.nextInt();

            set.remove(x);
            set.remove(y);

            map[x][y] = map[y][x] = true;
            map[x][x] = map[y][y] = true;
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (map[i][j]) {
                    map = dfs(i, j, map);
                    count++;
                }
            }
        }

        int ans = set.size();
        out.println(ans + count);
    }

    void dfs(int i, int j, boolean[][] map) {
        if (map[i][j] == false) {
            return;
        }

        map[i][j] = false;

        map =dfs(i + 1, j, map);
        map =dfs(i - 1, j, map);
        map =dfs(i, j + 1, map);
        map =dfs(i, j - 1, map);
    }
}

