                return n;
            } else {
                return par[n] = getRoot(par[n]);
            }
        }

        public void unite(int x, int y) {
            if (!isSame(x, y)) {
                if (par[getRoot(x)] < par[getRoot(y)]) {
                    par[getRoot(x)] += par[getRoot(y)];
                    par[getRoot(y)] = getRoot(x);
                } else {
                    par[getRoot(y)] += par[getRoot(x)];
                    par[getRoot(x)] = getRoot(y);
                }
            }
        }

        public boolean isSame(int x, int y) {
            return getRoot(x) == getRoot(y);
        }


