			ans[i] = i;
		}
//list[i][0]&list[i][1]
		for (int i = 1; i <= list.length - 1; i++) {

			ans[list[i][0]] = Math
					.min(ans[list[i][0]],
							Math.min(ans[list[i][1]],
									Math.min(list[i][0], list[i][1])));
			ans[list[i][1]] = Math
					.min(ans[list[i][0]],
							Math.min(ans[list[i][1]],
									Math.min(list[i][0], list[i][1])));

			ans[list[i][0]] =	Short(ans[list[i][0]],ans);
			ans[list[i][1]] =	Short(ans[list[i][1]],ans);
		}

		return ans;
	}

	static public int Short(int node, int list[]) {
		int next;
		if (list[node] == node) {
			return node;
		} else {
			next = list[node];
			list[node] = Short(next, list);
			return list[node];
		}
	}
