    for (int i = 0; i < N; i++) {
      if (!nodes[i].visited) {
        dfs(nodes[i]);
        cost++;
      }
    }
    System.out.println(cost);
  }

  private static void dfs(Node node) {
    node.visited = true;
    for (Node n : node.neighbors) {
      if (!n.visited) dfs(n);
    }
  }

  private static class Node {
    List<Node> neighbors = new ArrayList<>();
    boolean visited;
  }
}

