  public static int count(ArrayList<int[]> list){
    int result = 0;
    int c = 0;
  	for(int[] val : list){
      	if(val[0] != 0 && val[1] != 0){
          rm(list,val[0]);
          rm(list,val[1]);
          result++;
          c+=2;
          continue;
        }else if(val[0] == 0 && val[1] != 0){
          rm(list,val[1]);
          c++;
          continue;
        }else if(val[0] != 0 && val[1] == 0){
          rm(list,val[0]);
          c++;
          continue;
        }
    }

    result -= c;
    return result;
  }


  public static void rm(ArrayList<int[]> list, int target){
    for(int[] val : list){
      if(val[0] == target){
          val[0] = 0;
      }else if(val[1] == target){
        val[1] = 0;
      }
    }
  }

  public static void print(ArrayList<int[]> list){
	for(int[] val : list){
		System.out.println(val[0] + ":" + val[1]);
    }
    System.out.println("----------------------------");
  }
