public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        OneorTwo solver = new OneorTwo();
        solver.solve(1, in, out);
        out.close();
    }

    static class OneorTwo {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            List<Set<Integer>> list = new ArrayList<>();
            for (int i = 0; i < m; i++) {
                int x = in.nextInt();
                int y = in.nextInt();
                int z = in.nextInt();

                boolean added = false;
                for (Set<Integer> set : list) {
                    if (set.contains(x)) {
                        set.add(y);
                        added = true;
                    }
                    if (set.contains(y)) {
                        set.add(x);
                        added = true;
                    }
                }
                if (!added) {
                    HashSet<Integer> s = new HashSet<>();
                    s.add(x);
                    s.add(y);
                    list.add(s);
                }
            }

            for (Set<Integer> set : list) {
                n -= set.size();
            }
            n += list.size();
            out.print(n);
        }

    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

public class Main {
	Scanner sc = new Scanner(System.in);

	public static void main(String[] args) {
		Main m = new Main();
		m.run();
	}

	void run() {

		int n = sc.nextInt();
		int m = sc.nextInt();

		int u[] = new int[m];
		int v[] = new int[m];
		int w[] = new int[m];

		Map<Integer,List<Integer>> g = new HashMap<Integer,List<Integer>>();

		for(int i = 0; i < m;i++) {
			u[i] = sc.nextInt()-1;
			v[i] = sc.nextInt()-1;
			w[i] = sc.nextInt();

			g.computeIfAbsent(u[i], x -> new ArrayList<Integer>()).add(i);
			g.computeIfAbsent(v[i], x -> new ArrayList<Integer>()).add(i);
		}

		int color = 0;
		int[] res = new int[n];
		Arrays.fill(res, -1);

		for(int i =0 ; i< n;i++) {
			if(res[i] == -1) {				
				res[i] = color;
				coloring(g,res,i,color,u,v,w);
				color++;
			}
		}
		System.out.println(color);
	}


	void coloring(Map<Integer,List<Integer>> g,int[] res, int current,int color, int[]u,int v[],int[] w) {
		for(int nextv : g.getOrDefault(current,new ArrayList<Integer>())) {
			int next = u[nextv]+v[nextv]-current;	
			if(res[next] != -1) {
				continue;
			}
			res[next] = color;
			coloring(g,res,next,color,u,v,w);
		}
	}


}

