	private void oneOrTwo(Scanner scan) {
		int n = scan.nextInt();
		int m = scan.nextInt();

		List<List<Integer>> w = IntStream.range(0, m)
			.mapToObj(i -> IntStream.range(0, 3)
				.map(j -> scan.nextInt())
				.boxed()
				.collect(Collectors.toList()))
			.map(i -> Arrays.asList(i.get(0) - 1, i.get(1) - 1, i.get(2) % 2))
			.collect(Collectors.toList());

		List<Integer> parents = IntStream.range(0, n).boxed().collect(Collectors.toCollection(() -> new ArrayList<>()));

		w.stream().forEach(i -> {
			int leftParent = parents.get(i.get(0));
			while (leftParent != parents.get(leftParent)) {
				leftParent = parents.get(leftParent);
			}

			int rightParent = parents.get(i.get(1));
			while (rightParent != parents.get(rightParent)) {
				rightParent = parents.get(rightParent);
			}

			if (leftParent == rightParent) {
				return;
			}
			parents.set(rightParent, leftParent);
		});

		Set<Integer> grandParents = new HashSet<>();
		for (int i : parents) {
			int index = i;
			while (index != parents.get(index)) {
				index = parents.get(index);
			}
			grandParents.add(index);
		}
		System.out.println(grandParents.size());
	}

