import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Main {
  public static void main(String[] args) throws IOException {
    BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    String[] line1 = br.readLine().split(" ");
    int numOfCard = Integer.parseInt(line1[0]);
    int numOfHint = Integer.parseInt(line1[1]);
    List<Set<Integer>> integerSetList = new ArrayList<>();

    int x;
    int y;
    boolean notFound;
    String[] data;
    for(int i=0; i<numOfHint; i++){
      notFound = true;
      data = br.readLine().split(" ");
      x = Integer.parseInt(data[0]);
      y = Integer.parseInt(data[1]);
      if(i==0){
        integerSetList.add(new HashSet<>());
        integerSetList.get(0).add(x);
        integerSetList.get(0).add(y);
      }else{
        for (Set<Integer> integer : integerSetList) {
          if (integer.contains(x) || integer.contains(y)) {
            integer.add(x);
            integer.add(y);
            notFound = false;
            break;
          }
        }
        if(notFound){
          Set<Integer> newSet = new HashSet<>();
          newSet.add(x);
          newSet.add(y);
          integerSetList.add(newSet);
        }
      }
    }
    int hinted = 0;
    for(Set<Integer> set: integerSetList){
      hinted += set.size();
    }
    int numOfSeries = integerSetList.size();

    System.out.println(numOfCard - hinted + numOfSeries);
  }
}

import java.io.*;
import java.util.*;

class Solver {
  ArrayList<ArrayList<Integer>> edges;
  boolean[] visited;

  private void visit(int index) {
    if (visited[index]) {
      return;
    }

    visited[index] = true;
    for (int next : edges.get(index)) {
      visit(next);
    }
  }

  public int solve(int n, int[] xs, int[] ys, int[] zs) {
    edges = new ArrayList<>();
    for (int i = 0; i <= n; i++) {
      edges.add(new ArrayList<>());
    }

    for (int i = 0; i < xs.length; i++) {
      edges.get(xs[i]).add(ys[i]);
      edges.get(ys[i]).add(xs[i]);
    }

    visited = new boolean[n + 1];
    int count = 0;
    for (int i = 1; i <= n; i++) {
      if (visited[i]) {
        continue;
      }
      visit(i);
      count++;
    }
    return count;
  }
}

public class Main {
  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int m = reader.nextInt();
    int[] xs = new int[m];
    int[] ys = new int[m];
    int[] zs = new int[m];
    for (int i = 0; i < m; i++) {
      xs[i] = reader.nextInt();
      ys[i] = reader.nextInt();
      zs[i] = reader.nextInt();
    }
    out.println(new Solver().solve(n, xs, ys, zs));
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

class ContestReader {
  private BufferedReader reader;
  private StringTokenizer tokenizer;

  ContestReader(InputStream in) {
    reader = new BufferedReader(new InputStreamReader(in));
  }

  public String next() {
    while (tokenizer == null || !tokenizer.hasMoreTokens()) {
      try {
        tokenizer = new java.util.StringTokenizer(reader.readLine());
      } catch (Exception e) {
        throw new RuntimeException(e);
      }
    }
    return tokenizer.nextToken();
  }

  public int nextInt() {
    return Integer.parseInt(next());
  }

  public long nextLong() {
    return Long.parseLong(next());
  }

  public double nextDouble() {
    return Double.parseDouble(next());
  }

  public int[] nextIntArray(int n) {
    int[] array = new int[n];
    for (int i = 0; i < n; i++) {
      array[i] = nextInt();
    }
    return array;
  }

  public long[] nextLongArray(int n) {
    long[] array = new long[n];
    for (int i = 0; i < n; i++) {
      array[i] = nextLong();
    }
    return array;
  }
