import java.util.Scanner;

public class Main {

    static int root(int x, int[] dp) {
        if (dp[x] == x) {
            return x;
        } else {
            return dp[x];
        }
    }

    static void unite(int x, int y, int[] dp) {
        int rx = root(x, dp);
        int ry = root(y, dp);

        if (rx == ry) {
            return;
        }

        dp[rx] = ry;
    }

    public static void main(String[] args) {
        Scanner std = new Scanner(System.in);
