            int x = std.nextInt() - 1;
            int y = std.nextInt() - 1;
            int z = std.nextInt();
//            zs[i] = z;
            unite(x, y, dp);
        }

        long ans = 0;
        for (int i = 0; i < n; i++) {
            int ri = dp[i];
            if (ri == i) {
                ans++;
            }
        }

        System.out.println(ans);
    }
}

