class Unionfind {

	private int[] data;

	public Unionfind(int size) {
		this.data = new int [size];
		clear();
	}

	public void clear() {
		Arrays.fill(data, -1);
	}

	public void union(int x , int y ) {
		if((x = root(x)) != (y = root(y))) {
			if(data[y] < data[x]) {
				final int t = x;
				x = y;
				y = t;
			}
			data[x] += data[y];
			data[y] = x;
		}
	}

	public int root(int x) {
		if(data[x] < 0) {
			return x;
		}
		else {
			return data[x] = root(data[x]);
		}
	}

	public boolean same(int x, int y) {
		return root(x) == root(y);
	}
}

