public class Main {

	public static boolean dfs(int node, int parent, ArrayList<HashSet<Integer>> adj, boolean[] visited, boolean[] looped) {
		if(looped[node]) { 
			return looped[node];
		}else if(visited[node]) {
			return looped[node] = true;
		}

		visited[node] = true;
		for(final int next : adj.get(node)) {
			if(next == parent) { continue; }

			if(dfs(next, node, adj, visited, looped)) {
				looped[node] = true;
			}
		}

		return looped[node];
	}

	public static void main(String[] args) throws IOException {
		try(final Scanner sc = new Scanner(System.in)){
			final int N = sc.nextInt();
			final int M = sc.nextInt();

			ArrayList<HashSet<Integer>> adj = new ArrayList<HashSet<Integer>>();
			for(int i = 0; i < N; i++) { adj.add(new HashSet<Integer>()); }

			for(int i = 0; i < M; i++) {
				final int x = sc.nextInt() - 1;
				final int y = sc.nextInt() - 1;
				final int w = sc.nextInt();

				adj.get(x).add(y);
				adj.get(y).add(x);
			}

			boolean[] visited = new boolean[N];
			boolean[] looped = new boolean[N];

			dfs(0, -1, adj, visited, looped);

			int count = N;
			for(final boolean loop : looped) {
				count -= loop ? 1 : 0;
			}

			System.out.println(count - 1);
		}
	}

	public static class Scanner implements Closeable {
		private BufferedReader br;
		private StringTokenizer tok;

		public Scanner(InputStream is) throws IOException {
			br = new BufferedReader(new InputStreamReader(is));
		}

		private void getLine() throws IOException {
			while(!hasNext()){
				tok = new StringTokenizer(br.readLine());
			}
		}

		private boolean hasNext() {
			return tok != null && tok.hasMoreTokens();
		}

		public String next() throws IOException {
			getLine();
			return tok.nextToken();
		}

		public int nextInt() throws IOException {
			return Integer.parseInt(next());
		}

		public long nextLong() throws IOException {
			return Long.parseLong(next());
		}

		public double nextDouble() throws IOException {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) throws IOException {
			final int[] ret = new int[n];
