public class Main {

	static int parent[];
    static int rank[];
    static int[] cycle;
    static void init(int n)
    {
        parent= new int[n+1];
        rank= new int[n+1];
        cycle = new int[n+1];
        for(int i=1;i<n+1;i++){
            parent[i]=i;
            cycle[i] = 1;
        }

    }

    static void union(int x , int y)
    {
        int Px= FindParent(x);
        int Py= FindParent(y);

        if(Px!=Py)
        {
        	if(rank[Px]<rank[Py])
        	{
        		int s = Px;
        		Px = Py;
        		Py = s;
        	}
        	rank[Px]++;
        	parent[Py] = Px;
        	cycle[Px]+=cycle[Py];
        }
        else
        {
        	cycle[Px]++;
        }

    }

    static int FindParent(int i)
    {
        if(parent[i]==i) 
        	return i;

        else{
            int result= FindParent(parent[i]);
            parent[i]= result;
            return result;
        }
    }



