	public class UnionFindTree {

		int[] parent; //インデックスにとノードを対応させ、そのルートノードのインデックスを格納
		int[] rank; //parentと同様に、木の高さを格納
		int[] size; //木の要素の数を格納。最新はparentのindexに
		int group;

		public UnionFindTree(int n) {
			this.parent = new int[n];
			this.rank = new int[n];
			this.size = new int[n];
			group = n;

			for (int i = 0; i < n; i++) {
				makeSet(i);
			}
		}

		public void makeSet(int i) {
			parent[i] = i;
			rank[i] = 0; //集合の高さ
			size[i] = 1;
		}

		public void unite(int x, int y) {
			int xRoot = find(x);
			int yRoot = find(y);
			if (xRoot == yRoot)
				return;
			group--;
			//xが属する木の方が大きい場合
			if (rank[xRoot] > rank[yRoot]) {
				parent[yRoot] = xRoot; //yの親をxに更新
				size[xRoot] += size[yRoot];

			} else if (rank[xRoot] < rank[yRoot]) {
				parent[xRoot] = yRoot;
				size[yRoot] += size[xRoot];
			} else {
				parent[yRoot] = xRoot;
				rank[xRoot]++; //同じ高さの木がルートの子として着くから大きさ++;
				size[xRoot] += size[yRoot];
			}
		}

		//引数の属する木のルートのidを返す
		public int find(int i) {
			if (i != parent[i]) {
				parent[i] = find(parent[i]);
			}
			return parent[i];
		}

		//同じ木に属しているか
		public boolean same(int x, int y) {
			return find(x) == find(y);
		}

		// via Oland https://atcoder.jp/contests/abc120/submissions/4452920
		public int size(int i) {
			return size[find(i)];
		}

		public int getGroup() {
			return group;
		}
	}

