/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author Ribhav
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        E1Or2 solver = new E1Or2();
        solver.solve(1, in, out);
        out.close();
    }

    static class E1Or2 {
        public void solve(int testNumber, FastReader s, PrintWriter out) {
            int n = s.nextInt();
            int m = s.nextInt();
            boolean[] known = new boolean[n + 1];
            int ans = 0;
            for (int i = 0; i < m; i++) {
                int x = s.nextInt();
                int y = s.nextInt();
                int z = s.nextInt();
                if (known[x] && known[y]) {
                    continue;
                }

                if (known[x] || known[y]) {
                    known[x] = known[y] = true;
                    continue;
                }

                known[x] = known[y] = true;
                ans++;
            }

            for (int i = 1; i <= n; i++) {
                if (!known[i]) {
                    ans++;
                }
            }
            out.println(ans);
        }

    }

    static class FastReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private FastReader.SpaceCharFilter filter;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

import java.util.Arrays;
import java.util.Scanner;
import java.util.stream.IntStream;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int M = sc.nextInt();
        int[] X = new int[M];
        int[] Y = new int[M];
        int[] Z = new int[M];
        for (int i = 0; i < M; ++i) {
            X[i] = sc.nextInt() - 1;
            Y[i] = sc.nextInt() - 1;
            Z[i] = sc.nextInt();
        }

        System.out.println(solve(N, X, Y, Z));

        sc.close();
    }

    static int solve(int N, int[] X, int[] Y, int[] Z) {
        int[] parents = new int[N];
        Arrays.fill(parents, -1);

        for (int i = 0; i < X.length; ++i) {
            int rootX = findRoot(parents, X[i]);
            int rootY = findRoot(parents, Y[i]);
            if (rootX != rootY) {
                parents[rootY] = rootX;
            }
        }

        return (int) IntStream.range(0, N).map(i -> findRoot(parents, i)).distinct().count();
    }

    static int findRoot(int[] parents, int node) {
        int root = node;
        while (parents[root] != -1) {
            root = parents[root];
        }

        int p = node;
        while (p != root) {
            int next = parents[p];
            parents[p] = root;

            p = next;
        }

        return root;
    }
}

