class UnionFind{
    int[] par;
    int[] size;

    public UnionFind(int n){
        par = new int[n];
        for(int i=0; i<n; i++){
            par[i] = i;
        }
        size = new int[n];
        Arrays.fill(size, 1);
    }

    public int find(int x){
        if(par[x] == x){
            return x;
        }else{
            par[x] = find(par[x]);
            return par[x];
        }
    }

    public boolean unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x==y) return false;

        if(size[x]<size[y]){
            int tmp = x;
            x = y;
            y = tmp;
        }
        size[x] += size[y];
        par[y] = x;
        return true;
    }

    public boolean same(int x, int y){
        return find(x)==find(y);
    }

    public int size(int x){
        return size[find(x)];
    }
}

