            int[] size;
            int group;

            public UnionFindTree(int n) {
                this.parent = new int[n];
                this.rank = new int[n];
                this.size = new int[n];
                group = n;

                for (int i = 0; i < n; i++) {
                    makeSet(i);
                }
            }

            public void makeSet(int i) {
                parent[i] = i;
                rank[i] = 0; //集合の高さ
                size[i] = 1;
            }

            public void unite(int x, int y) {
                int xRoot = find(x);
                int yRoot = find(y);
                if (xRoot == yRoot) return;
                group--;
                //xが属する木の方が大きい場合
                if (rank[xRoot] > rank[yRoot]) {
                    parent[yRoot] = xRoot; //yの親をxに更新
                    size[xRoot] += size[yRoot];

                } else if (rank[xRoot] < rank[yRoot]) {
                    parent[xRoot] = yRoot;
                    size[yRoot] += size[xRoot];
                } else {
                    parent[yRoot] = xRoot;
                    rank[xRoot]++; //同じ高さの木がルートの子として着くから大きさ++;
                    size[xRoot] += size[yRoot];
                }
            }

            public int find(int i) {
                if (i != parent[i]) {
                    parent[i] = find(parent[i]);
                }
                return parent[i];
            }

            public int groups() {
                return group;
            }

        }

    }

    static class FastScanner implements Closeable {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            } else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (buflen <= 0) {
                    return false;
                }
            }
            return true;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            else return -1;
        }

        private static boolean isPrintableChar(int c) {
            return 33 <= c && c <= 126;
        }

        public boolean hasNext() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
            return hasNextByte();
        }

        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) {
                throw new NumberFormatException();
            }
            while (true) {
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                } else if (b == -1 || !isPrintableChar(b)) {
                    return minus ? -n : n;
                } else {
                    throw new NumberFormatException();
                }
                b = readByte();
            }
        }

        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }

        public void close() {
            try {
                in.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

    }
}

import java.util.Scanner;

public class Main {

    static int root(int x, int[] dp) {
        if (dp[x] == x) {
            return x;
        }

        return root(dp[x], dp);
    }

    static void unite(int x, int y, int[] dp) {
        int rx = root(x, dp);
        int ry = root(y, dp);

        if (rx == ry) {
            return;
        }

        dp[rx] = ry;
    }

    public static void main(String[] args) {
        Scanner std = new Scanner(System.in);
        int n = std.nextInt();
        int m = std.nextInt();
        int[] dp = new int[n];
        int[] zs = new int[n];

        for (int i = 0; i < n; i++) {
            dp[i] = i;
        }

        for (int i = 0; i < m; i++) {
            int x = std.nextInt() - 1;
            int y = std.nextInt() - 1;
            int z = std.nextInt();
            zs[i] = z;
            unite(x, y, dp);
        }

        long ans = 0;
        for (int i = 0; i < n; i++) {
            int ri = dp[i];
            if (ri == i) {
                ans++;
            }
        }

        System.out.println(ans);
    }
}

