class Graph {
	Map<String, ArrayList<String>> edge;
	Map<String, Integer> vertex;

	public Graph() {
		//点,<辺が伸びている先>
		edge = new HashMap<String, ArrayList<String>>();
		//点,点の次数
		vertex = new HashMap<String, Integer>();
	}

	//点の追加
	public void add(String a) {
		if (!edge.containsKey(a)) {
			ArrayList<String> cont = new ArrayList<>();
			edge.put(a, cont);
			vertex.put(a, 1);
		}
	}

	//双方向点の追加
	public void add(String a, String b) {
		if (edge.containsKey(a)) {
			edge.get(a).add(b);
			vertex.put(a, vertex.get(a) + 1);
		} else {
			ArrayList<String> cont = new ArrayList<>();
			cont.add(b);
			edge.put(a, cont);
			vertex.put(a, 1);
		}
		if (edge.containsKey(b)) {
			edge.get(b).add(a);
			vertex.put(b, vertex.get(b) + 1);
		} else {
			ArrayList<String> cont = new ArrayList<>();
			cont.add(a);
			edge.put(b, cont);
			vertex.put(b, 1);
		}
	}

	//a→bの片方向
	public void unadd(String a, String b) {
		if (edge.containsKey(a)) {
			edge.get(a).add(b);
			vertex.put(a, vertex.get(a) + 1);
		} else {
			ArrayList<String> cont = new ArrayList<>();
			cont.add(b);
			edge.put(a, cont);
			vertex.put(a, 1);
		}
		if (!edge.containsKey(b)) {
			ArrayList<String> cont = new ArrayList<>();
			edge.put(b, cont);
		}
	}

