     * @param i
     * @param n
     * @return
     */
    private int recursiveC(int i, int n) {
        if (i >= n) {
            return 0;
        }
        return recursiveC(i * 2, n) + 1;
    }

    private void solveD() {
        int n = nextInt();

        int[] u = new int[n - 1];
        int[] v = new int[n - 1];
        int[] w = new int[n - 1];

        /*
         * 辺のMapを作成
         */
        Map<Integer, List<Edge>> wk = new TreeMap<Integer, List<Edge>>();

        for (int i = 0; i < n - 1; i++) {
            Edge e = null;
            List<Edge> tmp = null;

            u[i] = nextInt() - 1;
            v[i] = nextInt() - 1;
            w[i] = nextInt();
            /*
             * コストは偶奇以外不要なのでmodしたけど別にしなくてもよかったよね。。。
             */
            int cost = w[i] % 2;
            e = new Edge();
            e.from = u[i];
            e.to = v[i];
            e.cost = cost;
            tmp = wk.getOrDefault(e.from, new ArrayList<Edge>());
            tmp.add(e);
            wk.put(e.from, tmp);

            e = new Edge();
            e.from = v[i];
            e.to = u[i];
            e.cost = cost;
            tmp = wk.getOrDefault(e.from, new ArrayList<Edge>());
            tmp.add(e);
            wk.put(e.from, tmp);
        }
        /*
         * BFS用のQueue
         */
        Deque<Edge> ek = new ArrayDeque<Edge>();
        /*
         * tree探索するための最初のqueの選択
         * なんでもよいわけではなくて、子が一つのものを選択
         * 頂点がN個で辺がN-1個なので、必ずこの条件にあてはまるものがいる。
         * while()の中で最初のqueueだけは自分の行き先を全て見ていないので。
         * まぁ、while()に入る前に位置0のedgeを全てqueueに入れておけば良いだけな気はしている。
         */
        for (List<Edge> edges : wk.values()) {
            if (edges.size() == 1) {
                ek.addLast(edges.get(0));
                break;
            }
        }
        //		ek.addLast(wk.get(0).get(0));
        int[] res = new int[n];
        //色の格納用
        res[0] = 0;
        while (!ek.isEmpty()) {
            Edge e = ek.removeLast();
            /*
             * costの偶奇で塗る色を決定
             */
            if (e.cost % 2 == 0) {
                //偶数ならfromもtoも同じ色
                res[e.to] = res[e.from];
            } else {
                //奇数ならfromと違う色にtoを塗る必要がある
                res[e.to] = 1 - res[e.from];
            }
            //toに子がいるのかの探索
            List<Edge> edges = wk.get(e.to);
            for (Edge edge : edges) {
                /*
                 * 親↔子が循環しないように
                 */
                if (e.from == edge.to) {
                    continue;
                }
                /*
                 * 探索対象なのでQueueにadd
                 */
                ek.addLast(edge);
            }
        }

        for (int resN : res) {
            out.println(resN);
        }

    }

