class UnionFind {
	int[] par;
	int[] rank;

	UnionFind(int n) {
		par = new int[n];
		rank = new int[n];
		for (int i = 0; i < n; i++) {
			par[i] = i;
			rank[i] = 0;
		}
	}

	int root(int x) {
		if (par[x] == x) {
			return x;
		}
		else {
			par[x] = root(par[x]);
			return par[x];
		}
	}

	boolean same(int x, int y) {
		return root(x) == root(y);
	}

	void unit(int x, int y) {
		x = root(x);
		y = root(y);
		if (x == y) return;

		if (rank[x] < rank[y]) {
			par[x] = y;
		}
		else {
			par[y] = x;
			if (rank[x] == rank[y]) rank[x]++;
		}
	}
}

