class UnionFind {

    int length;
    int[] parent;
    int[] deep;
    int rootX, rootY;

    public UnionFind(int length) {
        this.length = length;
        parent = new int[length];
        for (int i = 0; i < length; i++) {
            parent[i] = i;
        }
        deep = new int[length];
    }

    public int getRoot(int x) {
        if (parent[x] == x) {
            return x;
        } else {
            return parent[x] = getRoot(parent[x]);
        }
    }

    public void makeSame(int x, int y) {
        rootX = getRoot(x);
        rootY = getRoot(y);
        if (rootX == rootY) {
            return;
        } else if (deep[rootX] > deep[rootY]) {
            parent[rootY] = parent[rootX];
        } else {
            parent[rootX] = parent[rootY];
            if (deep[rootX] == deep[rootY]) {
                deep[rootY]++;
            }
        }
        length--;
    }

    public boolean isSame(int x, int y) {
        return getRoot(x) == getRoot(y);
    }
}

import java.util.Scanner;

class Main {
    public static class UnionFind {

        private int[] parent;

        public UnionFind(int n) {
            // 親の番号を格納する。
            // 自分自身が親だった場合は-(その集合のサイズ)を格納する。
            this.parent = new int[n];

            for (int i = 0; i < n; i++) {
                // 最初の時点では親は自分自身
                // 集合のサイズは１
                this.parent[i] = -1;
            }
        }

        // aがどのグループに属しているか調べる。
        public int root(int a) {
            if (this.parent[a] < 0) {
                return a;
            } else {
                // 再帰的に親をたどる。
                return this.parent[a] = this.root(this.parent[a]);
            }
        }

        // aの集合のサイズを返す
        public int size(int a) {
            return -this.parent[this.root(a)];
        }

        // aとbをつなぐ。
        // 大きい方(a)に小さい方(b)をつなぐ感じ。
        public boolean connect(int a, int b) {
            // 親同士をつなぐ。
            a = this.root(a);
            b = this.root(b);

            // すでにくっついている場合
            if (a == b) {
                return false;
            }

            if (this.size(a) < this.size(b)) {
                int r = a;
                a = b;
                b = r;
            }

            this.parent[a] += this.parent[b];
            this.parent[b] = a;

            return true;
        }
    }

