        		if(!V[x].vst) {
        			flg = true;
        			V[x].dfs((mode+1)%3);
        		}
        	}
        	if(!flg) {
        		if(mode == 0) {
            		num2++;
            	} else if(mode == 1) {
            		num3++;
            	} else {
            		num1++;
            	}
        	}
        }
    }

    static void debug(long... args) {
