class elem{
	int data;
	int rank;
}

class disj{
	elem[] arr;

	disj(int n){
		arr=new elem[n];

		for(int i=0;i<n;i++) {
			arr[i]=new elem();
			arr[i].data=i;
			arr[i].rank=1;
		}
	}

	int find(int x) {
		if(arr[x].data==x) {
			return x;
		}
		else {
			return arr[x].data=find(arr[x].data);
		}
	}

	void union(int a,int b){
		unify(find(a),find(b));
	}

	void unify(int a,int b){
		if(arr[a].rank>arr[b].rank) {
			arr[b].data=a;
		}
		else {
			arr[a].data=b;

			if(arr[a].rank==arr[b].rank) {
				arr[b].rank+=1;
			}
		}
	}
}


/** Class for buffered reading int and double values */
class Rot {
	static BufferedReader reader;
