    class UFT {
        int size;
        int[] a;

        UFT(int size) {
            this.size = size;
            a = new int[size];
            for (int i = 0; i < size; i++) {
                a[i] = i;
            }
        }

        int find(int x) {
            if (a[x] == x) return x;
            return a[x] = find(a[x]);
        }

        void unite(int x, int y) {
            int u = find(x);
            int v = find(y);
            if (u == v) return;
            a[u] = v;
        }

        boolean same(int x, int y) {
            return find(x) == find(y);
        }
