public class Main {

    static int N, M;
    static int[] X, Y, Z;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        M = sc.nextInt();

        X = new int[M];
        Y = new int[M];
        Z = new int[M];
        for (int i = 0; i < M; i++) {
            X[i] = sc.nextInt()-1;
            Y[i] = sc.nextInt()-1;
            Z[i] = sc.nextInt();
        }
        System.out.println(solve());
    }

    static int solve() {
        UnionFind uf = new UnionFind(N);
        for (int i = 0; i < M; i++) {
            uf.unite(X[i], Y[i]);
        }

        Set<Integer> group = new HashSet<>();
        for (int i = 0; i < N; i++) {
            group.add( uf.root(i) );
        }
        return group.size();
    }

    static class UnionFind {

        private final int[] parent;
        private final int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        public int root(int i) {
            if( parent[i] == i ) {
                return i;
            } else {
                return parent[i] = root(parent[i]);
            }
        }

        public int unite(int i, int j) {
            int ri = root(i);
            int rj = root(j);
            if( ri == rj ) return ri;

            if( rank[ri] < rank[rj] ) {
                parent[ri] = rj;
                return rj;

            } else {
                parent[rj] = ri;
                if( rank[ri] == rank[rj] ) {
                    rank[ri]++;
                }
                return ri;
            }
        }

        public boolean isSame(int a, int b) {
            return root(a) == root(b);
        }
    }

