        // 1, 1, 1 => 1 is even
        Iterator<int[]> it = data.iterator();
        while (it.hasNext()) {
            int[] d = it.next();
            int c1 = check1(d);
            if (c1 != -1) {
                known[c1-1] = 2;
                it.remove();
            } else if (same(d)) {
                known[d[0]-1] = 2;
                it.remove();
            }
        }

        Set<Integer> hasData = new HashSet<>();
