             */
            if (e.cost % 2 == 0) {
                //偶数ならfromもtoも同じ色
                res[e.to] = res[e.from];
            } else {
                //奇数ならfromと違う色にtoを塗る必要がある
                res[e.to] = 1 - res[e.from];
            }
            //toに子がいるのかの探索
            List<Edge> edges = wk.get(e.to);
            for (Edge edge : edges) {
                /*
