        public int getRoot(int n) {
            if (par[n] == n) {
                return n;
            } else {
                return par[n] = getRoot(par[n]);
            }
        }

        public void unite(int x, int y) {
            if (!isSame(x, y)) {
                par[x] = y;
            }
        }

        public boolean isSame(int x, int y) {
            return getRoot(x) == getRoot(y);
        }


