    public static class UnionFind {
        int[] par;

        UnionFind(int n) {
            par = new int[n];
            for (int i = 0; i < n; i++) {
                par[i] = i;
            }
        }

        int root(int x) {
            if (par[x] == x) return x;
            return root(par[x]);
        }

        void unite(int x, int y) {
            int rx = root(x);
            int ry = root(y);
            if (rx == ry) return;
            par[ry] = rx;
        }

        boolean same(int x, int y) {
            int rx = root(x);
            int ry = root(y);
            return rx == ry;
        }

        int connectedComponent() {
            Set<Integer> set = new HashSet<Integer>();
            for (int p : par) {
                set.add(p);
