	class UnionFindTree{
		int n;
		int[] par;
		int[] rank;
		UnionFindTree(int n){
			this.n = n;
			par = new int[n];
			rank = new int[n];
			for(int i = 0; i < n; i++) {
				par[i] = i;
				rank[i] = 0;
			}
		}
		int find(int x) {
			if(par[x] == x) {
				return x;
			}
			else {
				return par[x] = find(par[x]);
			}
		}

