    static class UnionFindTree {
        int[] parents;

        public UnionFindTree(int n) {
            parents = new int[n];
            for (int i = 0; i < n; i++) {
                parents[i] = i;
            }
        }

        public int find(int x) {
            if (parents[x] == x) {
                return x;
            } else {
                return parents[x] = find(parents[x]);
            }
        }

        public void unite(int x, int y) {
            int xx = find(x);
            int yy = find(y);
            parents[xx] = yy;
        }

