class UnionFind{
	int[] par;
	public UnionFind(int size)
	{
		par=new int[size];
		Arrays.fill(par, -1);
	}
	public int root(int x)
	{
		if(par[x]<0)
		{
			return x;
		}
		int z=root(par[x]);
		par[x]=z;
		return z;

	}
	public boolean same(int a,int b)
	{
		return (root(a)==root(b));
	}
	public void unite(int a,int b)
	{
		if(!same(a,b)) {
			int ra=root(a);
			int rb=root(b);
			//right now both ra and rb ==-1

			if(par[ra]<par[rb])
			{
				par[ra]+=par[rb];
				par[rb]=ra;
			}else {
				par[rb]+=par[ra];
				par[ra]=rb;
			}
		}
	}
	public int size(int a)
	{
		return -par[root(a)];
	}

}

