		for(int i=0;i<m;i++) {
			input1 = sc.nextInt();
			input2 = sc.nextInt();
			sc.nextLine();

			if(roots[input1] == 0) {
				roots[input1] = input2;
			}else {
				if(roots[input2] == 0) {
					roots[input2] = input1;
				}else {
					int root1 = calc.searchRoot(roots,input1);
					if(root1 != calc.searchRoot(roots,input2)) {
						roots[root1] = input2;
					}
				}
			}
		}

		int count = 0;
