    static class E1Or2 {
        int[] rep;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt(), m = in.nextInt();
            rep = new int[n];
            for (int i = 0; i < n; i++) {
                rep[i] = i;
            }

            for (int i = 0; i < m; i++) {
                int x = in.nextInt(), y = in.nextInt(), z = in.nextInt();
                x--;
                y--;
                union(x, y);
            }


            for (int i = 0; i < n; i++) {
                rep(i);
            }


            HashSet<Integer> distinct = new HashSet<>();
            for (int r : rep) {
                distinct.add(r);
            }

            out.println(distinct.size());
        }

        int rep(int x) {
            if (rep[x] == x) {
                return x;
            }

            int r = rep(rep[x]);
            rep[x] = r;
            return r;
        }

        void union(int x, int y) {
            if (Math.random() < 0.5) {
                rep[rep(x)] = rep(y);
            } else {
                rep[rep(y)] = rep(x);
            }
        }

