	class UnionFind {
		int gcnt; // グループ数
		int[] par; // [子番号] = 親番号(親の場合、メンバ数のマイナス値)
					// [1]=3 [2]=-1 [3]=-2  なら　１　と　３　は　同じグループ

		public UnionFind(int n) {
			gcnt = n;
			par = new int[n];
			Arrays.fill(par, -1); // 全部が親で、メンバ数を　１　とする
		}

		// 親の番号を返す（この中で親に直接つなぎ変えている）
		int root(int x) {
			if (par[x] < 0)
				return x; // 親の場合はマイナスが入っている
			else
				return par[x] = root(par[x]);
		}

		// 同じグループなら true を返す
		boolean same(int x, int y) {
			return root(x) == root(y);
		}

		// グループ数を返す
		int groupCnt() {
			return gcnt;
		}

		// メンバ数を返す
		int size(int x) {
			return -par[root(x)];
		}

		// メンバのリストを返す
		List<Integer> member(int x) {
			List<Integer> ans = new ArrayList<>();
			int root = root(x);
			for (int i = 0; i < par.length; i++) {
				if (root(i) == root) {
					ans.add(i);
				}
			}
			return ans;
		}

		// 同じ親につなげる
		void connect(int x, int y) {
			int xP = root(x); // 親を取得する
			int yP = root(y); // 親を取得する
			if (xP == yP)
				return; // 同じなので処理しない
			if (size(xP) > size(yP)) { // メンバ数が多い方にくっつける
				par[xP] += par[yP]; //   メンバ数を更新する
				par[yP] = xP; //   親番号を設定する
			} else {
				par[yP] += par[xP];
				par[xP] = yP;
			}
			gcnt--;
		}

		void dump(PrintWriter out) {
			for (int i = 0; i < par.length; i++) {
				out.println("par[" + i + "] = " + par[i]);
			}
			out.println("");
		}
	}
