class UnionFind{
    private int[] p, rank;
    public UnionFind(int n){
        p = new int[n];
        rank = new int[n];
        for(int i = 0; i < n; i++)
            p[i] = i;
    }
    public int findSet(int i){
        if(p[i] == i)
            return i;
        else
            return findSet(p[i]);
    }
    public boolean isSameSet(int i, int j){
        return findSet(i) == findSet(j);
    }
    public void unionSet(int i, int j){
        if(!isSameSet(i, j)){
            int x = findSet(i), y = findSet(j);
            if(rank[x] > rank[y])
                p[y] = x;
            else{
                p[x] = y;
                if(rank[x] == rank[y])
                    rank[y]++;
            }
        }
    }
}
public class Main {
