        {
            int[] V = ReadInts();
            int N = V[0], M = V[1];
            var infos = new int[M][];
            for (int i = 0; i < M; ++i) { infos[i] = ReadInts(); }
            Console.WriteLine(Solve(N, M, infos));
        }
    }
