    class UnionFind
    {
        public int N;
        public int[] Parents;
        public int[] Rank;
        public UnionFind(int n)
        {
            this.N = n;
            this.Parents = Enumerable.Repeat(-1, N).ToArray();
            this.Rank = new int[N];
        }
        public int Find(int x)
        {
            var p = this.Parents[x];
            if (p < 0) return x;
            p = Find(p);
            this.Parents[x] = p;
            return p;
        }
        public bool IsSame(int x, int y)
        {
            return Find(x) == Find(y);
        }
        public void Union(int x, int y)
        {
            x = Find(x);
            y = Find(y);
            if (x == y) return;
            if (this.Rank[x] < this.Rank[y])
            {
                var tmp = x;
                x = y;
                y = tmp;
            }
            if (this.Rank[x] == this.Rank[y]) this.Rank[x]++;
            this.Parents[x] += this.Parents[y];
            this.Parents[y] = x;
        }
        public int Size(int x)
        {
            x = Find(x);
            return -this.Parents[x];
        }
    }
