    class UnionFind
    {
        private int[] Parents;
        int N;
        public UnionFind(int n)
        {
            N = n;
            Parents = Enumerable.Repeat(-1, n).ToArray();
        }
        public int Find(int a)
        {
            if (Parents[a] < 0) return a;
            var p = Find(Parents[a]);
            Parents[a] = p;
            return p;
        }
        public bool Same(int a, int b)
        {
            a = Find(a);
            b = Find(b);
            return a == b;
        }
        public void Union(int a, int b)
        {
            a = Find(a);
            b = Find(b);
            if (a == b) return;
            Parents[a] += Parents[b];
            Parents[b] = a;
        }
    }
