	class UnionFindForest {
		public class Node {
			public int value { get; set; }
			public Node parent { get; set; }
			public Node root {
				get {
					var path = new Queue<Node>();
					var res = this;
					while(res.parent!=res) {
						path.Enqueue(res);
						res=res.parent;
					}
					while(path.Any())
						path.Dequeue().parent=res;
					return res;
				}
			}
			public int rank { get; private set; }    //meanful iff this is root
			public void rankIncrement() => rank++;
			public Node(int thisValue) {
				value=thisValue;
				parent=this;
				rank=1;
			}
		}

		private readonly Dictionary<int, Node> phoneBook = new Dictionary<int, Node>();
		public UnionFindForest(int N) {
			for(int i = 0; i<N; i++) Add(i);
		}
		public void Union(int x, int y) => Union(phoneBook[x], phoneBook[y]);
		public void Union(Node X, Node Y) {
			var RX = X.root;
			var RY = Y.root;
			switch(RX.rank.CompareTo(RY.rank)) {
				case 1:
					RY.parent=RX;
					break;
				case -1:
					RX.parent=RY;
					break;
				default:
					RX.parent=RY;
					RY.rankIncrement();
					break;
			}
		}
		public bool Find(int x, int y) => Find(phoneBook[x], phoneBook[y]);
		public bool Find(Node X, Node Y) => X.root==Y.root;
		public void Add(int id) {
			var N = new Node(id);
			phoneBook.Add(id, N);
		}
		public Dictionary<Node, int> TallyDegrees() {
			var Roots = new Dictionary<Node, int>();
			foreach(var node in phoneBook.Values) {
				var R = node.root;
				if(Roots.Keys.Contains(R))
					Roots[R]++;
				else
					Roots.Add(R, 1);
			}
			return Roots;
		}
		public int[] Degrees() {
			var D = TallyDegrees();
			var res = new int[phoneBook.Count];
			for(int i = 0; i<phoneBook.Count; i++)
				res[i]=D[phoneBook[i]];
			return res;
		}
		public int TreeCount() {
			var D = TallyDegrees();
			return D.Count;
		}
	}
}

