public class UnionFind
{
    public readonly int[] leaders;
    private readonly int[] ranks;

    public UnionFind(int count)
    {
        ClustersCount = count;
        leaders = new int[count];
        for (var i = 0; i < count; i++)
            leaders[i] = i;
        ranks = new int[count];
    }

    public int ClustersCount { get; private set; }

    public void Union(int x, int y)
    {
        var from = Find(x);
        var to = Find(y);

        if (from == to)
            return;

        ClustersCount--;

        var rfrom = ranks[from];
        var rto = ranks[to];

        if (rfrom == rto)
        {
            leaders[from] = to;
            ranks[to]++;
        }
        else if (rfrom < rto)
        {
            leaders[from] = to;
        }
        else
        {
            leaders[to] = from;
        }
    }

    public int Find(int i)
    {
        var prev = i;

        var leader = leaders[prev];
        while (leader != prev)
        {
            prev = leader;
            leader = leaders[leader];
        }

        leaders[i] = leader;

        return leader;
    }
}

