class UnionFindTree
{
    int[] parent;

    public UnionFindTree(int n)
    {
        parent = new int[n + 1];

        for (int i = 0; i <= n; ++i)
        {
            parent[i] = i;
        }
    }

    public int Root(int x)
    {
        // これ、再帰で回してスタックオーバーフロー出ない？（デフォルトで１MB）
        // （↑子供それぞれの親の値は、このRoot関数を呼んだときに総親の値に書き換えられるので、絶対大丈夫）
        if (parent[x] == x) { return x; }
        return parent[x] = Root(parent[x]);
    }

    public void Unite(int x, int y)
    {
        int rootX = Root(x);
        int rootY = Root(y);
        if (rootX != rootY)
        {
            parent[rootX] = rootY;
        }
    }

    public bool Same(int x, int y)
    {
        return Root(x) == Root(y);
    }
}

