    class UnionFind
    {
        private int[] graph;
        private int[] rank;
        private int count;
        public UnionFind(int capacity)
        {
            graph = new int[capacity];
            rank = new int[capacity];
            for (int i = 0; i < capacity; i++)
            {
                graph[i] = i;
                rank[i] = 0;
            }

            count = capacity;
        }

        public void Unite(int first, int second)
        {
            var rootX = graph[first];
            var rootY = graph[second];
            if (rootX == rootY)
            {
                return;
            }
            if (rank[rootX] < rank[rootY])
            {
                graph[rootX] = rootY;
            }
            else
            {
                graph[rootY] = rootX;
                if (rank[rootX] == rank[rootY])
                {
                    rank[rootX]++;
                }
            }

            count--;
        }
        public bool Same(int first, int second)
        {
            return Root(first) == Root(second);
        }
        public int Root(int x)
        {
            if (graph[x] == x)
            {
                return x;
            }
            else
            {
                graph[x] = Root(graph[x]);
                return graph[x];
            }
        }

        public int Count()
        {
            return count;
        }
    }


    private static int UpperBound<T>(this IEnumerable<T> list, T item) where T : IComparable<T> => UpperBound(list.ToList(), item);
    private static int LowerBound<T>(this IEnumerable<T> list, T item) where T : IComparable<T> => LowerBound(list.ToList(), item);

    private static int UpperBound<T>(this List<T> list, T item) where T : IComparable<T>
    {
        return list.BinarySearch(item, -1, list.Count, (first, second) => first.CompareTo(second) > 0);
    }

    private static int LowerBound<T>(this List<T> list, T item) where T : IComparable<T>
    {
        return list.BinarySearch(item, -1, list.Count, (first, second) => first.CompareTo(second) >= 0);
    }

    private static int BinarySearch<T>(this List<T> list, T item, int left, int right, Func<T, T, bool> isOkPredicate)
    {
        while (Math.Abs(right - left) > 1)
        {
            var mid = left + (right - left) / 2;
            if (isOkPredicate(list[mid], item))
            {
                right = mid;
            }
            else
            {
                left = mid;
            }
        }
        return right;
    }


