    void calc()
    {
        int N = cin.nextInt();
        int M = cin.nextInt();
        int[] X, Y, Z;
        X = new int[M];
        Y = new int[M];
        Z = new int[M];

        for (int i = 0; i < M; i++)
        {
            X[i] = cin.nextInt() - 1;
            Y[i] = cin.nextInt() - 1;
            Z[i] = cin.nextInt();
        }

        init(N);
        for (int i = 0; i < M; i++)
        {
            connect(X[i], Y[i]);
        }

        int ans = 0;
        for (int i = 0; i < N; i++)
        {
            if (root(i) == i) ans++;
        }
        Console.WriteLine(ans);

    }

    int[] uni;
    void init(int N)
    {
        uni = new int[N];
        for (int i = 0; i < N; i++)
        {
            uni[i] = -1;
        }
    }

    int root(int a)
    {
        if (uni[a] < 0) return a;
        else return uni[a] = root(uni[a]);
    }

    bool connect(int a, int b)
    {
        a = root(a);
        b = root(b);
        if (a == b) return false;
        if (uni[a] > uni[b]) swap(ref a, ref b);
        uni[a] += uni[b];
        uni[b] = a;
        return true;
    }

    void swap<T>(ref T a, ref T b)
    {
        T c = a;
        a = b;
        b = c;
    }  
}


