        class UnionFind
        {
            public List<int> Par;
            public List<int> Sizes;

            public UnionFind(int n)
            {
                Par = new List<int>();
                Sizes = new List<int>();
                for (int i = 0; i < n; i++)
                {
                    Par.Add(i);
                    Sizes.Add(1);
                }
            }

            public int Find(int x)
            {
                if (x == Par[x]) return x;
                Par[x] = Find(Par[x]);
                return Par[x];
            }

            public void Unite(int x, int y)
            {
                x = Find(x);
                y = Find(y);
                if (x == y) return;

                if (Sizes[x] < Sizes[y])
                {
                    int temp = x;
                    x = y;
                    y = temp;
                }

                Par[y] = x;
                Sizes[x] += Sizes[y];
                Sizes[y] = 0;
            }

            public bool Same(int x, int y)
            {
                return Find(x) == Find(y);
            }

            public int Size(int x)
            {
                return Sizes[Find(x)];
            }
        }
    }


