        line = Console.ReadLine();
        String[] words = line.Split(' ');
        int N = int.Parse(words[0]);
        int M = int.Parse(words[1]);
        List<Tuple<int, int>> list = new List<Tuple<int, int>>();

        bool[] count_NG = new bool[N];
        for (int i = 0; i < N; i++) count_NG[i] = false;

        int X, Y, Z;
        int count = 0;
        for(int i = 0; i < M; i++)
        {
            line = Console.ReadLine();
            words = line.Split(' ');
            X = int.Parse(words[0]) - 1;
            Y = int.Parse(words[1]) - 1;
            Z = int.Parse(words[2]);//使わない
            list.Add(new Tuple<int,int>(X, Y));
            count_NG[X] = true;
            count_NG[Y] = true;
        }

        for (int i = 0; i < N; i++)
        {
            if (!count_NG[i])
            {
                count++;
            }
        }

        //ルートが何個できるか、検証する
        find f = new find();
        f.found_list = new bool[M];
        f.found_card = new bool[N];
        for (int i = 0; i < M; i++) f.found_list[i] = false;
        for (int i = 0; i < N; i++) f.found_card[i] = false;
        //できたルートの数だけ、足す
        count += f.GetRoute(list, N);

        Console.WriteLine(count);
    }

    public class find
    {
        public bool[] found_list;
        public bool[] found_card;
        //now:今見ているリストの番号 now_card:今見ているカードの番号
        public int GetRoute(List<Tuple<int, int>> list,int N)
        {
            int route_count = 0;
            for(int i = 0; i < list.Count; i++)
            {
                if (!found_list[i])
                {
                    //まだ見てないリスト
                    route_count++;
                    found_list[i] = true;
                    found_card[list[i].Item1] = true;
                    found_card[list[i].Item2] = true;
                    int count = 1;
                    int left_limit = i + 1;//探索の左端
                    while (count > 0)
                    {
                        count = 0;
                        for (int j = left_limit; j < list.Count; j++)
                        {
                            if (!found_list[j] && (found_card[list[j].Item1] || found_card[list[j].Item2]))
                            {
                                found_card[list[j].Item1] = true;
                                found_card[list[j].Item2] = true;
                                found_list[j] = true;
                                count++;
                                left_limit = j + 1;
                            }
                        }
                    }
                    for (int j = 0; j < N; j++) found_card[j] = false;
                }
            }
            return route_count;
        }
    }
}

