    class UnionFind{
        public UnionFind(int n){
            this.parent = new int[n];
            for(int i=0;i<n;i++){
                parent[i] = i;
            }
        }

        public int[] parent;

        public int root(int x){
            if(parent[x]==x){return x;}
            return root(parent[x]);
        }

        public bool Unite(int x, int y){
            int rx = root(x);
            int ry = root(y);
            if(rx==ry){return false;}
            parent[ry] = rx;
            return true;
        }
        public void Merge(int x, int y){Unite(x,y);}

        public bool SameParent(int x, int y){
            if(root(x)==root(y)){return true;}
            return false;
        }
    }
}

