                huta[i] = new Hutatu(x, y);
                //       if (Ns[x] < Ns[y]) { Ns[y] = Ns[x]; }
           //     else { Ns[x] = Ns[y]; } 
            }

       //     huta = sort(huta.ToArray(), 0, huta.Length - 1);
            Array.Sort(huta);
            for (int i = 0; i < M; i++)
            {
                if (huta[i].y > Ns[huta[i].x]) { Ns[huta[i].x-1] = Ns[huta[i].y-1];
                    continue;
                }
                Ns[huta[i].y-1] = Ns[huta[i].x-1];
            }
            int count = 0;
            for (int i = 0; i < N; i++)
            {
                if (Ns[i] != i) { count++; }
            }
            Console.WriteLine(N-count);

        }
        static Hutatu[] sort(Hutatu[] huta,int start,int end)
        {
            if (end - start <= 0) { return huta; }

            Hutatu pibot = huta[(start + end) / 2];
            int l = start, r = end;
            while (true)
            {
                while (huta[l] < pibot && l <= end)
                {
                    l++;
                }
                while (huta[r] > pibot && r >= start)
                {
                    r--;
                }
                if (l >= r) { break; }


                var tmp = huta[r].copy();
                huta[r] = huta[l].copy();
                huta[l] = tmp;
            }
            sort(huta, start, r - 1);
            sort(huta, r + 1, end);
            return huta;
        }

    }
