class UnionFind

 

{

 

// 親要素のインデックスを保持する

 

// 親要素が存在しない(自身がルートである)とき、マイナスでグループの要素数を持つ

 

public long[] Parents { get; set; }

 

public UnionFind(long n)

 

{

 

this.Parents = new long[n];

 

for (int i = 0; i < n; i++)

 

{

 

// 初期状態ではそれぞれが別のグループ(ルートは自分自身)

 

// ルートなのでマイナスで要素数(1個)を保持する

 

this.Parents[i] = -1;

 

}

 

}

 

 

 

// 要素xのルート要素はどれか

 

public long Find(long x)

 

{

 

// 親がマイナスの場合は自分自身がルート

 

if (this.Parents[x] < 0) return x;

 

// ルートが見つかるまで再帰的に探す

 

// 見つかったルートにつなぎかえる

 

this.Parents[x] = Find(this.Parents[x]);

 

return this.Parents[x];

 

}

 

 

 

// 要素xの属するグループの要素数を取得する

 

public long Size(long x)

 

{

 

// ルート要素を取得して、サイズを取得して返す

 

return -this.Parents[this.Find(x)];

 

}

 

 

 

// 要素x, yが同じグループかどうか判定する

 

public bool Same(long x, long y)

 

{

 

return this.Find(x) == this.Find(y);

 

}

 

 

 

// 要素x, yが属するグループを同じグループにまとめる

 

public bool Union(long x, long y)

 

{

 

// x, y のルート

 

x = this.Find(x);

 

y = this.Find(y);

 

// すでに同じグループの場合処理しない

 

if (x == y) return false;

 

 

 

// 要素数が少ないグループを多いほうに書き換えたい

 

if (this.Size(x) < this.Size(y))

 

{

 

var tmp = x;

 

x = y;

 

y = tmp;

 

}

 

// まとめる先のグループの要素数を更新

 

this.Parents[x] += this.Parents[y];

 

// まとめられるグループのルートの親を書き換え

 

this.Parents[y] = x;

 

return true;

 

}

 

}







public class PriorityQueue<T> : IEnumerable<T> { private readonly List<T> _data = new List<T>(); private readonly IComparer<T> _comparer; private readonly bool _isDescending; public PriorityQueue(IComparer<T> comparer, bool isDescending = true) { _comparer = comparer; _isDescending = isDescending; } public PriorityQueue(Comparison<T> comparison, bool isDescending = true) : this(Comparer<T>.Create(comparison), isDescending) { } public PriorityQueue(bool isDescending = true) : this(Comparer<T>.Default, isDescending) { } public void Enqueue(T item) { _data.Add(item); var childIndex = _data.Count - 1; while (childIndex > 0) { var parentIndex = (childIndex - 1) / 2; if (Compare(_data[childIndex], _data[parentIndex]) >= 0) break; Swap(childIndex, parentIndex); childIndex = parentIndex; } } public T Dequeue() { var lastIndex = _data.Count - 1; var firstItem = _data[0]; _data[0] = _data[lastIndex]; _data.RemoveAt(lastIndex--); var parentIndex = 0; while (true) { var childIndex = parentIndex * 2 + 1; if (childIndex > lastIndex) break; var rightChild = childIndex + 1; if (rightChild <= lastIndex && Compare(_data[rightChild], _data[childIndex]) < 0) childIndex = rightChild; if (Compare(_data[parentIndex], _data[childIndex]) <= 0) break; Swap(parentIndex, childIndex); parentIndex = childIndex; } return firstItem; } public T Peek() { return _data[0]; } private void Swap(int a, int b) { var tmp = _data[a]; _data[a] = _data[b]; _data[b] = tmp; } private int Compare(T a, T b) { return _isDescending ? _comparer.Compare(b, a) : _comparer.Compare(a, b); } public int Count => _data.Count; public IEnumerator<T> GetEnumerator() { return _data.GetEnumerator(); } IEnumerator IEnumerable.GetEnumerator() => GetEnumerator(); }

