    static void Main()
    {
        var nm = Console.ReadLine().ToIntArray();
        int N = nm[0];
        int M = nm[1];

        var infoList = Enumerable.Range(0, M).Select(n => Console.ReadLine().ToIntArray())
            .Select(arr => new { X = arr[0] - 1, Y = arr[1] - 1, Z = arr[2] })
            .OrderBy(itm => Math.Min(itm.X, itm.Y))
            .ToList();

        var infoHashSet = infoList.ToHashSet();
        var already = new HashSet<int>();
        var ans = 0;
        for(int i = 0; i < N; i++)
        {
            if (already.Contains(i)) continue;

            Queue<int> q = new Queue<int>();
            q.Enqueue(i);
            while(q.Any())
            {
                var val = q.Dequeue();
                already.Add(val);
                foreach (var itm in infoHashSet.ToArray())
                {
                    if (itm.X == val)
                    {
                        q.Enqueue(itm.Y);
                        infoHashSet.Remove(itm);
                    }
                    else if (itm.Y == val)
                    {
                        q.Enqueue(itm.X);
                        infoHashSet.Remove(itm);
                    }                    
                }
            }
            ans++;
        }
        Console.WriteLine(ans);

    }
}

