    class UnionFind
    {
        private int N;
        public int[] parents; //親の番号を格納. 親の場合は-(メンバサイズ)

        public UnionFind(int n)
        {
            parents = new int[n];
            for (int i = 0; i < n; i++) parents[i] = -1;
            N = n;
        }

        //グループのボスを取得
        public int Root(int x)
        {
            if (parents[x] < 0) return x;
            parents[x] = Root(parents[x]); //次からはボスに直結するように構造を変える
            return parents[x];
        }

        //グループのメンバ数
        public int Size(int x)
        {
            int r = Root(x);
            return -parents[r];
        }

        public bool Unite(int x, int y)
        {
            x = Root(x);
            y = Root(y);
            if (x == y) return false;
            //メンバサイズが大きい方をボスとして合併
            if (Size(x) < Size(y))
            {
                parents[y] += parents[x];
                parents[x] = y;
            }
            else
            {
                parents[x] += parents[y];
                parents[y] = x;
            }
            return true;
        }
    }

}

