    class Program
    {
        static void Main(string[] args)
        {
            var nums = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToList();
            var card = Enumerable.Repeat(-1, nums[0]).ToList();

            foreach (var i in Enumerable.Range(0, nums[1]))
            {
                var info = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToList();
                var x = info[0] - 1;
                var y = info[1] - 1;

                // どちらかがペア登録されていれば、同じグループとして登録する
                var pairId = Math.Max(card[x], card[y]);

                // どちらもまだペア登録されていないなら、新しいグループ番号を割り当てる
                if (pairId < 0)
                {
                    pairId = i;
                }

                // いずれかが分かればOKなペアとして記録する
                card[x] = pairId;
                card[y] = pairId;
            }

            var sum = 0;
            sum += card.Count(x => x < 0);
            sum += card.Distinct().Count(x => x >= 0);

            Console.WriteLine(sum);
        }
    }
