                {
                    X = tmp[0] - 1,
                    Y = tmp[1] - 1,
                    IsEvenTotal = tmp[2] % 2 == 0
                };
                infos.Add(info);
            }

            foreach (var info in infos)
            {
                count[info.X]++;
                count[info.Y]++;

                HashSet<int> xHash = null;
                HashSet<int> yHash = null;

                foreach (var hash in hashs)
                {
                    if (hash.Contains(info.X))
                    {
                        xHash = hash;
                    }
                    if (hash.Contains(info.Y))
                    {
                        yHash = hash;
                    }
                }

                if (xHash == null && yHash == null)
                {
                    var newHash = new HashSet<int>();
                    newHash.Add(info.X);
                    newHash.Add(info.Y);
