            count_NG[X] = true;
            count_NG[Y] = true;
        }

        for (int i = 0; i < N; i++)
        {
            if (!count_NG[i])
            {
                count++;
            }
        }

        //ルートが何個できるか、検証する
        find f = new find();
        f.found_card = new bool[N];
        for (int i = 0; i < N; i++) f.found_card[i] = false;
        //できたルートの数だけ、足す
        count += f.GetRoute(list, N);

        Console.WriteLine(count);
    }

    public class find
    {
        public bool[] found_card;
        //now:今見ているリストの番号 now_card:今見ているカードの番号
        public int GetRoute(List<Tuple<int, int>> list,int N)
        {
            int route_count = 0;
            for(int i = 0; i < list.Count; i++)
            {
                //まだ見てないリスト
                route_count++;
                found_card[list[i].Item1] = true;
                found_card[list[i].Item2] = true;
                list.RemoveAt(i);
                for (int j = 0; j < list.Count; j++)
                {
                    if (found_card[list[j].Item1] || found_card[list[j].Item2])
                    {
                        found_card[list[j].Item1] = true;
                        found_card[list[j].Item2] = true;
                        list.RemoveAt(j);
                        j = -1;
                    }
                }
            }
            return route_count;
        }
    }
