public class UnionFind
{
	public int N { get; private set; } = 0;
	private int[] par = null;
	private int[] rank = null;
	private int[] weight = null;

	public UnionFind(int n)
	{
		if(n <= 0)
			throw new Exception();
		N = n;
		par = new int[N];
		rank = new int[N];
		weight = new int[N];
		for(int i = 0; i < N; i++)
		{
			par[i] = i;
			rank[i] = 0;
			weight[i] = 1;
		}
	}

	public int find(int x)
	{
		if(par[x] == x)
		{
			return x;			
		}
		else
		{
			return (par[x] = find(par[x]));
		}
	}

	public void unite(int x, int y)
	{
		x = find(x);
		y = find(y);
		if(x == y)
			return;

		if(rank[x] < rank[y])
		{
			par[x] = y;
		}
		else
		{
			par[y] = x;
			if(rank[x] == rank[y])
				rank[x]++;			
		}
		int tmp = weight[x] + weight[y];
		weight[x] = tmp;
		weight[y] = tmp;
	}

	public bool same(int x, int y)
	{
		return (find(x) == find(y));
	}

	public int GetWeight(int x)
	{
		return weight[x];
	}
}


