        {
            if (!f.found_card[i])
            {
                count++;
            }
        }
        Console.WriteLine(count);
    }

    public class find
    {
        public bool[] found_card;
        //now:今見ているリストの番号 now_card:今見ているカードの番号
        public int GetRoute(List<Tuple<int, int>> list,int N)
        {
            int route_count = 0;
            for(int i = 0; i < list.Count;)
            {
                //まだ見てないリスト
                route_count++;
                found_card[list[i].Item1] = true;
                found_card[list[i].Item2] = true;
