class UnionFind
{
    int[] nodes;

    public int Count { get; private set; }

    public UnionFind(int size)
    {
        this.nodes = Enumerable.Repeat(-1, size).ToArray();
        Count = size;
    }

    public int Find(int x)
    {
        var p = nodes[x];
        if (p < 0)
        {
            return x;
        }

        return nodes[x] = Find(p);
    }

    public void Unite(int x, int y)
    {
        var p = Find(x);
        var q = Find(y);
        if (p == q)
        {
            return;
        }

        var r = nodes[p];
        var s = nodes[q];
        if (r > s)
        {
            p += q;
            q = p - q;
            p -= q;
        }
        nodes[p] += nodes[q];
        nodes[q] = p;
        Count--;
    }

    public bool Union(int x, int y)
        => Find(x) == Find(y);

    public int GetSize(int x)
        => -nodes[Find(x)];

    public int GetDensity()
        => nodes.Count(x => x < 0);
}

