        class UnionFind
        {
            int[] par;
            internal UnionFind(int n)
            {
                par = new int[n + 1];
                for (int i = 0; i < n + 1; i++)
                {
                    par[i] = i;
                }
            }

            internal int Root(int x)
            {
                if (par[x] == x) return x;
                return Root(par[x]);
            }

            internal void Unite(int x, int y)
            {
                var rx = Root(x);
                var ry = Root(y);
                if (rx == ry) return;
                par[rx] = ry;
            }

            internal bool Same(int x, int y)
            {
                return Root(x) == Root(y);
            }

            internal int Count()
            {
                var hs = new HashSet<int>();
                for (int i = 1; i < par.Length; i++)
                {
                    hs.Add(Root(i));
                }
                return hs.Count;
            }
