    static string[] ReadLines(int n) => Enumerable.Range(0, n).Select(s => Console.ReadLine()).ToArray();

    static void Main()
    {
        var nm = Console.ReadLine().ToIntArray();
        int N = nm[0];
        int M = nm[1];

        var infoList = Enumerable.Range(0, M).Select(n => Console.ReadLine().ToIntArray())
            .Select(arr => new { X = arr[0] - 1, Y = arr[1] - 1, Z = arr[2] })
            .OrderBy(itm => Math.Min(itm.X, itm.Y))
            .ToList();

        //地点iから行ける箇所を取れるようにしておく。
        var ways = Enumerable.Range(0, N).Select(n => new List<int>()).ToArray();
        foreach(var info in infoList)
        {
            ways[info.X].Add(info.Y);
            ways[info.Y].Add(info.X);
        }

        int ans = 0;
        HashSet<int> already = new HashSet<int>();
        for(int i = 0; i < N; i++)
        {
            if (already.Contains(i)) continue;

            Queue<int> q = new Queue<int>();
            q.Enqueue(i);

            while(q.Any())
            {
                var val = q.Dequeue();
                already.Add(val);
                foreach(var next in ways[val])
                {
                    if (already.Contains(next)) continue;

                    q.Enqueue(next);
                }
            }

            ans += 1;
        }

        Console.WriteLine(ans);

    }
}

