    class Program
    {
        public List<int> ScanInts(int count) => Enumerable.Range(0, count).Select(_ => ScanInt).ToList();
        public List<int> ScanInts(long count) => ScanInts((int)count);
        public List<long> ScanLongs(int count) => Enumerable.Range(0, count).Select(_ => Scan).ToList();
        public List<long> ScanLongs(long count) => ScanLongs((int)count);
        public int ScanInt => int.Parse(Str);
        public long Scan => long.Parse(Str);
        public double ScanDouble => (double)Scan;

        StringBuilder sb = new StringBuilder();

        public string Str => ScanStr();
        public string ScanStr()
        {
            sb.Clear();

            int r = 0;
            bool? b = null;
            do
            {
                r = Console.Read();
                b = IsBreak(r);
            } while (b == true);

            if (b == null)
                throw new Exception("input error: unexpected end of stream");

            do
            {
                sb.Append((char)r);
                r = Console.Read();
                b = IsBreak(r);
            } while (b == false);

            return sb.ToString();
        }

        bool? IsBreak(int c)
        {
            switch (c)
            {
                case -1:
                    return null;
                case (int)' ':
                case (int)'\n':
                case (int)'\r':
                    return true;
                default:
                    return false;
            }
        }

        public IEnumerable<int> Loop(int count) => Enumerable.Range(0, count);
        public IEnumerable<int> Loop(int from, int to) => Enumerable.Range(from, to - from + 1);

        public IEnumerable<long> Loop(long count) => Loop(0, count - 1);
        public IEnumerable<long> Loop(long from, long to)
        {
            for (long i = from; i <= to; i++)
                yield return i;
        }

        public string YesNo(bool isYes) => isYes ? "Yes" : "No";

        public HashSet<T> ToHashSet<T>(IEnumerable<T> ts) => new HashSet<T>(ts);

        void DFS(long v, ref HashSet<long> used, ref Dictionary<long, Tuple<long, long>[]> edgeTable)
        {
            if (used.Contains(v))
                return;

            used.Add(v);

            if (edgeTable.ContainsKey(v) == false)
                return;

            foreach (var e in edgeTable[v])
                DFS(e.Item2, ref used, ref edgeTable);
        }

        public IEnumerable<string> Solve()
        {
            var n = Scan;
            var m = Scan;
            var xs = new List<long>();
            var ys = new List<long>();
            var zs = new List<long>();

            foreach (var i in Loop(m))
            {
                xs.Add(Scan - 1);
                ys.Add(Scan - 1);
                zs.Add(Scan);
            }

            List<Tuple<long, long>> edges = new List<Tuple<long, long>>();
            foreach (int i in Loop(m))
            {
                edges.Add(new Tuple<long, long>(xs[i], ys[i]));
                edges.Add(new Tuple<long, long>(ys[i], xs[i]));
            }

            var edgeTable = edges.GroupBy(x => x.Item1).ToDictionary(x => x.Key, x => x.ToArray());

            var used = new HashSet<long>();

            var res = 0L;
            foreach (var i in Loop(n))
            {
                if (used.Contains(i))
                    continue;

                res++;
                DFS(i, ref used, ref edgeTable);
            }

            yield return res.ToString();
        }
    }
}

