                else if (tmp[c.xi] != null && tmp[c.yi] != null)
                {
                    if (tmp[c.xi].Count < tmp[c.yi].Count)
                    {
                        tmp[c.yi].AddRange(tmp[c.xi]);
                        foreach (var t in tmp[c.xi])
                        {
                            if (t != c.xi)
                                tmp[t] = tmp[c.yi];
                        }
                        tmp[c.xi] = tmp[c.yi];
                    }
                    else
                    {
                        tmp[c.xi].AddRange(tmp[c.yi]);
                        foreach (var t in tmp[c.yi])
                        {
                            if (t != c.yi)
                                tmp[t] = tmp[c.xi];
                        }
                        tmp[c.yi] = tmp[c.xi];
                    }
                }
                else if (tmp[c.xi] != null)
                {
                    tmp[c.yi] = tmp[c.xi];
                    tmp[c.xi].Add(c.yi);
                }
                else
                {
                    tmp[c.xi] = tmp[c.yi];
                    tmp[c.xi].Add(c.xi);
                }
            }

            var count = 0;
            var setOfList = new HashSet<List<int>>();
            foreach (var list in tmp)
            {
                if (list == null)
                    ++count;
                else if (setOfList.Add(list))
                    ++count;
            }

            return count;

        }

