     class UnionFind
    {
        public List<int> Parent;
        public UnionFind(int n)
        {
            //親の番号をそれぞれ格納する。自分が親なら、-(サイズ)
            this.Parent = Enumerable.Repeat(-1, n).ToList();
        }

        public int Size(int a)
        {
            if (Parent[a] < 0)return -Parent[a];
            else return -Parent[Root(a)];
        }

        public int Root(int a)
        {
            if (Parent[a] < 0) return a;
            else
            {
                int root = Root(Parent[a]);
                Parent[a] = root;
                return root;
            }
        }

        public bool Connect(int a, int b)
        {
            a = Root(a);
            b = Root(b);
            if (a == b) return false;
            else
            {
                //a > bにする
                if (a < b)
                {
                    int tmp = a;
                    a = b;
                    b = tmp;
                }
                //bの親をaにして、aのsizeにbのぶんを足す
                Parent[a] += Parent[b];
                Parent[b] = a;
                return true;
            }
        }
    }
}

