namespace SolutionCS
{
    class Program
    {
        class IntUnionFind
        {
            // 親の要素を指す配列
            int[] rootArray;

            // 初期化(最大要素数指定する)
            public IntUnionFind(int max_element)
            {
                rootArray = new int[max_element];
                for (int i = 0; i < rootArray.Length; i++)
                {
                    rootArray[i] = i;       // 自分自身を指す=root
                }
            }

            public bool IsRoot(int element)
            {
                return rootArray[element] == element;
            }

            // 要素の根を返す
            public int Root(int element)
            {
                // 要素インデックス=親の要素インデックスなら親、そうでないなら親をたどる
                if (rootArray[element] != element)
                {
                    // 根を取得
                    int r = Root(rootArray[element]);
                    // 根を付け替え
                    rootArray[element] = r;
                    // 根を返す
                    return r;
                }

                // 根を返す
                return element;
            }

            // 同じ根かどうかを返す
            public bool IsSameRoot(int element1, int element2)
            {
                return (Root(element1) == Root(element2));
            }

            // 要素を結合
            public void Unite(int element1, int element2)
            {
                int root1 = Root(element1);
                int root2 = Root(element2);

                if (root1 == root2)
                {
                    return;
                }

                rootArray[root1] = root2;
            }
        }


        static void Main(string[] args)
        {
            string[] inS = Console.ReadLine().Split(' ');
            int N = int.Parse(inS[0]);
            int M = int.Parse(inS[1]);

            IntUnionFind uf = new IntUnionFind(N);

            for (int i = 0; i < M; i++)
            {
                string[] inP = Console.ReadLine().Split(' ');
                int e0 = int.Parse(inP[0]) - 1;
                int e1 = int.Parse(inP[1]) - 1;

                uf.Unite(e0, e1);
            }

            int result = 0;

            for (int i = 0; i < N; i++)
            {
                if (uf.IsRoot(i))
                {
                    result++;
                }
            }

            Console.WriteLine("{0}", result);
        }
    }
}

