class Tree
  def initialize(size)
    @size = size
    @parents = size.times.map { |i| i }
  end

  def union(x, y)
    ry = root(y)
    @parents[ry] = root(x)
  end

  def root(x)
    arr = []
    while !root?(x)
      arr << x
      x = @parents[x]
    end
    arr.each { |idx| @parents[idx] = x }
    x
  end

  def root?(x)
    @parents[x] == x
  end

  def group_size
    s = 0
    0.upto(@size-1) do |i|
      s += 1 if root?(i)
    end
    s
  end
end

