type tree struct {
	parent int
}

func update(x, i int, trees []tree) int {
	if i == trees[i].parent {
		if x < i {
			trees[i].parent = x
			return x
		}
		return i
	}
	trees[i].parent = update(x, trees[i].parent, trees)
	return trees[i].parent
}

func root(i int, trees []tree) int {
	if i == trees[i].parent {
		return i
	}
	return root(trees[i].parent, trees)
}

