			units[x] = unit{
				isRoot:   true,
				root:     x,
				children: []int{x, y},
			}
			units[y] = unit{
				root: x,
			}
		} else if ok1 {
			units[y] = unit{
				root: v1.root,
			}
			root := units[v1.root]
			root.children = append(root.children, y)
			units[v1.root] = root
		} else {
			units[x] = unit{
