	root     int
	children []int
}

type unitArr map[int]*unit

func (u unitArr) merge(i, j int) {
	u[u[j].root].isRoot = false
	for _, k := range u[j].children {
		u[k].root = u[i].root
	}
	u[i].children = append(u[i].children, u[j].children...)

}

func (u unitArr) find(i, j int) {
	if u[i].root != u[j].root {
		if len(u[i].children) > len(u[j].children) {
			u.merge(i, j)
		} else {
			u.merge(j, i)
		}
	}
}

