func root(teams []int, i int) int {
	if teams[i] == i {
		return i
	}
	return root(teams, teams[i])
}

func merge(teams []int, x, y int) {
	if x < y {
		teams[y] = root(teams, x)
	} else {
		teams[x] = root(teams, y)
	}
}

