type tree struct {
	parent int
}

func update(x, i int, trees []tree) {
	if i == trees[i].parent {
		return
	}
	update(x, trees[i].parent, trees)
	trees[i].parent = x
}

func root(i int, trees []tree) int {
	if i == trees[i].parent {
		return i
	}
	return root(trees[i].parent, trees)
}

