var uni []int

func root(a int) int {
	if uni[a] < 0 {
		return a
	}
	uni[a] = root(uni[a])
	return uni[a]
}

func connect(a, b int) bool {
	a = root(a)
	b = root(b)
	if a == b {
		return false
	}
	if uni[a] > uni[b] {
		a, b = b, a
	}
	uni[a] = uni[a] + uni[b]
	uni[b] = a
	return true
}

func isConnect(a, b int) bool {
	return root(a) == root(b)
}

func size(a int) int {
	return -uni[root(a)]
}

