	"strconv"
)

func wordScanner() *bufio.Scanner {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)
	return sc
}

func get_int(sc *bufio.Scanner) int {
	sc.Scan()
	i, err := strconv.Atoi(sc.Text())
	if err != nil {
		panic(err)
	}
	return i
}

func root(teams []int, i int) int {
	if teams[i] == i {
		return i
	}
	return root(teams, teams[i])
}

func merge(teams []int, x, y int) {
	if x < y {
		teams[y] = root(teams, x)
	} else {
		teams[x] = root(teams, y)
	}
}

func main() {
	var n, m int
	fmt.Scan(&n, &m)

	xs := make([]int, m)
	ys := make([]int, m)
	zs := make([]int, m)
	sc := wordScanner()
	for i := range xs {
		xs[i] = get_int(sc)
		ys[i] = get_int(sc)
		zs[i] = get_int(sc)
	}

	teams := make([]int, n)
	for i := range teams {
		teams[i] = i
	}

	for i, x := range xs {
		y := ys[i]
		merge(teams, x-1, y-1)
	}

	cntr := make(map[int]bool)
	for i := range teams {
		cntr[root(teams, i)] = true
	}
	fmt.Println(len(cntr))
}

