func main() {
    var n, m int
    fmt.Scan(&n, &m)

    mp = make(map[int]map[int]bool)
    chk = make(map[int]bool)

    for i := 0; i < m; i++ {
        var x, y, z int
        fmt.Scan(&x, &y, &z)
        x--
        y--
        if _, ok := mp[x]; !ok {
            mp[x] = make(map[int]bool)
        }
        mp[x][y] = true
        if _, ok := mp[y]; !ok {
            mp[y] = make(map[int]bool)
        }
        mp[y][x] = true
    }

    var sum int
    for i := 0; i < n; i++ {
        sum += search(i)
    }
    fmt.Println(sum)
}

func search(pos int) int {
    if b, ok := chk[pos]; ok && b {
        return 0
    }
    chk[pos] = true
    for k, _ := range mp[pos] {
        search(k)
    }
    return 1
}

