class DisjointSet {
	parents: number[]
	components: number
	constructor(readonly size: number) {
		this.parents = new Array(size).fill(null).map((value, index) => index);
		this.components = size;
	}
	find(index: number): number {
		if (index != this.parents[index])
			this.parents[index] = this.find(this.parents[index]);
		return this.parents[index]
	}
	union(index1: number, index2: number): void {
		let parent1 = this.find(index1),
			parent2 = this.find(index2);
		if (parent1 != parent2) {
			this.parents[parent1] = parent2;
			this.components -= 1;
		}
	}
}


