class UnionFind{
  treeset: {parent?:number, size:number}[];
  constructor(size: number){
      this.treeset=new Array(size);
      for(let i=0;i<size;i++){
        this.treeset[i]={size:1};
      }
  }
  union(x:number, y:number){
      const rootX=this.find(x);
      const rootY=this.find(y);
      if(rootX!=null && rootX==rootY){
          return;
      }else{
          const sizeX=this._size(x);
          const sizeY=this._size(y);
          if(sizeX>sizeY){
              this.treeset[rootY].parent = rootX;
              this.treeset[rootX].size += this.treeset[rootY].size;
          }else{
              this.treeset[rootX].parent = rootY;
              this.treeset[rootY].size += this.treeset[rootX].size;
          }
      }
  }
  //x should be root
  _size(x:number){
      return this.treeset[x].size;
  }
  size(x:number){
      return this._size(this.find(x));
  }
  print(){
    for(let i=0;i<this.treeset.length;i++)
      console.log("i:%d parent:%d size:%d", i, this.treeset[i].parent, this.treeset[i].size);
      console.log();
    }
  find(x:number):number{
      let parent = this.treeset[x].parent;
      if(parent==null){
          return x;
      }else{
        const root = this.find(parent);
        this.treeset[x].parent=root;
        return root;
      }
  }
}

