struct UnionFind
{
	private long   num;
	private long[] ps;

	public this( long n )
	{
		num = n;
		ps = new long[]( n );
		ps[] = -1;
	}

	public long root( long x )
	{
		return ( ps[ x ] < 0 ) ? x : ( ps[ x ] = root( ps[ x ] ) );
	}

	public bool same( long x, long y )
	{
		return root( x ) == root( y );
	}

	public void unite( long x, long y )
	{
		x = root( x );
		y = root( y );
		if( x == y ) return;
		if( ps[ x ] < ps[ y ] ){ ps[ x ] += ps[ y ]; ps[ y ] = x; }
		else                   { ps[ y ] += ps[ x ]; ps[ x ] = y; }
		num--;
	}

	public long rootnum()
	{
		return num;
	}
}

