class UnionFind {
private:
  uint[] rank;
  uint[] par;
  uint size;

public:
  this(uint size) {
    rank = repeat(0u).take(size).array;
    par = iota(size).array;
    this.size = size;
  }

  uint length() {
    return size;
  }

  uint getRoot(uint n) {
    return par[n] = (par[n] == n ? n : getRoot(par[n]));
  }

  bool unite(uint n1, uint n2) {
    n1 = getRoot(n1);
    n2 = getRoot(n2);
    if (n1 == n2) return false;

    bool t = rank[n1] < rank[n2];
    par[t ? n1 : n2] = t ? n2 : n1;
    if (rank[n1] == rank[n2]) rank[n1]++;
    return true;
  }

  bool haveSameRoot(uint n1, uint n2) {
    return getRoot(n1) == getRoot(n2);
  }

  uint countRoots() {
    uint roots = 0;
    par.each!((i, v){ if (getRoot(v) == i) roots++; });
    return roots;
  }
}

