    par: seq[int]
    rank: seq[int]

proc newUnionFindTree(n: int): UnionFindTree =
  result = UnionFindTree()
  newSeq(result.par, n)
  newSeq(result.rank, n)
  for i in 0..<n:
    result.par[i] = i
    result.rank[i] = 0

proc find(t:var UnionFindTree, x:int): int =
  if x != t.par[x]:
    t.par[x] = t.find(t.par[x])
  t.par[x]

