  let
    x = t.find(x)
    y = t.find(y)
  if x == y:
    return
  if t.rank[x] < t.rank[y]:
    t.par[x] = y
  else:
    t.par[y] = x
    if t.rank[x] == t.rank[y]:
      inc(t.rank[x])

