class Graph:

    def __init__(self, num_of_vertexes):
        self.v = num_of_vertexes
        self.e = [[] for i in range(num_of_vertexes)]

    def dfs(self, tmp, v, visited):
        visited[v] = True
        tmp.append(v)
        for i in self.e[v]:
            if visited[i] == False:
                tmp = self.dfs(tmp, i, visited)
        return tmp

    def addEdge(self, v, w):
        self.e[v].append(w)
        self.e[w].append(v)

    def connComponents(self):
        ret = []
        visited = []
        for i in range(self.v):
            visited.append(False)
        for v in range(self.v):
            if visited[v] == False:
                tmp = []
                ret.append(self.dfs(tmp, v, visited))
        return ret

