def dsMakeSet(ds, x):
    ds[x] = x


def dsFind(ds, x):
    if ds[x] == x:
        return x

    while ds[x] != x:
        x = ds[x]

    ds[x] = x
    return x


def dsUnion(ds, x, y):
    xRoot = dsFind(ds, x)
    yRoot = dsFind(ds, y)

    if xRoot != yRoot:
        ds[yRoot] = xRoot
        return True

    return False


