class Graph:
    def __init__(self, n_vertices, edge_list, directed=True):
        self.n_vertices = n_vertices
        self.edge_list = edge_list
        self.directed = directed
        self.n_component = None

        self.V = [Vertex(i) for i in range(n_vertices)]
        self.E = []

        if directed:
            for i, e in enumerate(edge_list):
                tail, head = self.V[e[0]], self.V[e[1]]
                edge = Edge((tail, head), i)
                self.E.append(edge)
                tail.incident.append(edge)
                tail.out_neighbor.append(head)
                head.in_neighbor.append(tail)
            self.n_edges = len(self.E)

        else:
            i = 0
            for e in edge_list:
                tail, head = self.V[e[0]], self.V[e[1]]
                edge = Edge((tail, head), i)
                self.E.append(edge)
                tail.incident.append(edge)
                tail.out_neighbor.append(head)
                head.in_neighbor.append(tail)
                i += 1

                edge = Edge((head, tail), i)
                self.E.append(edge)
                head.incident.append(edge)
                head.out_neighbor.append(tail)
                tail.in_neighbor.append(head)
                i += 1
            self.n_edges = len(self.E)//2

    def __str__(self):
        return "a graph with {0} vertices and {1} edges".format(self.n_vertices, self.n_edges)

    def underlying_graph(self):
        if self.directed:
            return Graph(self.n_vertices, self.edge_list, directed=False)
        else:
            return self

    def indeg(self, v):
        return len(v.in_neighbor)

    def outdeg(self, v):
        return len(v.out_neighbor)

    def set_vertex_value(self, value_dict):
        for v_name, val_list in value_dict.items():
            for i, v in enumerate(self.V):
                v.set_value(v_name, val_list[i])

    def calc_component(self):
        # find the component of a graph by DFS.
        g = self.underlying_graph()
        comp = [None]*self.n_vertices
        counter = 0

        while None in comp:
            idx = comp.index(None)
            for i in g.DFS(idx):
                comp[i] = counter
            counter += 1

        self.n_components = counter

        return comp

    def DFS(self, init_idx=0):
        init = {'DFS': initialize(None, self.n_vertices),
                'DFS order': initialize(None, self.n_vertices)}
        self.set_vertex_value(init)

        s = self.V[init_idx]
        length = 0

        stck = []
        stck.append((s, length))
        visited = []
        finished = []
        counter = 0

        while stck:
            v, l = stck.pop()

            if v['DFS'] is not None:
                continue
            visited.append(v.idx)
            v['DFS'] = l
            v['DFS order'] = counter
            counter += 1

            all_visited = True
            for u in v.out_neighbor:
                if u['DFS'] is None:
                    all_visited = False
                    stck.append((u, l+1))

            if all_visited:
                finished.append(visited.pop())

        while len(visited) != 0:
            finished.append(visited.pop())

        return finished

