        # 親の場合は -{その集合のサイズ}
        self.parent = [-1 for _ in range(N)]

    def root(self, A):
        if self.parent[A] < 0:
            return A
        self.parent[A] = self.root(self.parent[A])
        return self.parent[A]

    def size(self, A):
        return -self.parent[self.root(A)]

