def dfs(init) :
	queue = [init]
	p[init] = 0

	while queue :
		x_ = queue.pop(0)
		visited[x_] = True

		for y_, z_ in relation[x_] :
			if visited[y_] :
				if (z_ & 1) ^ p[x_] != p[y_] :
					return False
			else :
				p[y_] = (z_ & 1) ^ p[x_]
				queue.append(y_)

	return True

def calc() :
	# 閉路ごと実行
	res = 0
	for i in range(1, N + 1) :
		if len(relation[i]) and not visited[i] :
			res += 1
			if not dfs(i) :
				return -1

	return res + visited.count(False) - 1

