def solve(string):
    n, m, *xyz = map(int, string.split())
    t = [-1] * (n + 1)
    for x, y, z in zip(*[iter(xyz)] * 3):

        def search(x, y):
            tmp = [y]
            curr = x
            while curr != -1:
                tmp.append(curr)
                curr = t[curr]
            root = tmp.pop()
            for _t in tmp:
                t[_t] = root

        search(x, y)
    return str(t[1:].count(-1))


