class Node:
    def __init__(self, index):
        self._index = index
        self._connections = []

    @property
    def index(self):
        return self._index

    @property
    def connections(self):
        return self._connections

    def addConnection(self, node):
        self._connections.append(node)

    @staticmethod
    def checkKnown(node, knownList):
        if knownList[node.index] == False:
            knownList[node.index] = True
            for connectioon in node.connections:
                Node.checkKnown(connectioon, knownList)
        else:
            return

