class MergeFind:
    def __init__(self, N):
        self.par = list(range(N))
        self.num_sets = N

    def root(self, x):
        if self.par[x] == x:
            return x
        else:
            self.par[x] = self.root(self.par[x])
            return self.par[x]

    def unite(self, x, y):
        rx = self.root(x)
        ry = self.root(y)
        if rx == ry:
            return
        else:
            self.par[rx] = ry
            self.num_sets -= 1

    def same(self, x, y):
        return self.root(x) == self.root(y)

    def get_num_sets(self):
        return self.num_sets

