class Union_Tree:
    def __init__(self, N):
        self.group_num = [i for i in range(N)]
        self.childs = [[] for i in range(N)]

    def change_group(self, _from, num):
        self.group_num[_from] = num
        for child in self.childs[_from]:
            self.group_num[child] = num
        self.childs[num].extend(self.childs[_from])
        self.childs[_from].clear()

    def unite(self, a, b):
        a_par = self.group_num[a]
        b_par = self.group_num[b]
        if len(self.childs[a_par]) >= len(self.childs[b_par]):
            # bの親グループをaのグループに統合
            self.change_group(b_par, a_par)
        else:
            self.change_group(a_par, b_par)



