class union_find():
    def __init__(self, id):
        self.parent = None
        self.id = id

    def root(self):
        if not self.parent:
            return self
        else:
            return self.parent.root()

    def union(self, target):
        sr = self.root().id
        tr = target.root().id
        if sr == tr:
            return
        elif sr > tr:
            self.root().parent = target.root()
        else:
            target.root().parent = self.root()


