def graph_connected_component(nodes, nd_edges):
    # 無向グラフを想定、edgesを両向きにはやす
    edge_table = {n:[] for n in nodes}
    for e in nd_edges:
        edge_table[e[0]].append(e[1])
        edge_table[e[1]].append(e[0])

    result = [-1] * (len(nodes) + 1)
    count = 0
    color = 0
    while count < len(nodes):
        node_q = deque()
        color += 1

        # まだ見ていないnodeを基点にしてcomponentを構成
        for node in nodes:
            if result[node] == -1:
                node_q.appendleft(node)
                break

        # qがある = 連結先があるので探索
        while len(node_q) > 0:
            curr = node_q.pop()
            result[curr] = color
            count += 1

            # 連結先のうち、まだ未探索nodeをqにつむ
            next_nodes = edge_table[curr]
            for node in next_nodes:
                if result[node] == -1:
                    node_q.appendleft(node)

    return result


