def count_graph(edges, n):
    unvisited = set(range(n))
    c = 0

    while unvisited:
        f = first(unvisited)
        unvisited.remove(f)
        c += 1

        q = deque()
        q.append(f)
        while q:
            u = q.popleft()
            for v in edges[u]:
                if v in unvisited:
                    q.append(v)
                    unvisited.remove(v)

    return c

