class UnionFindTree:
    """Tested https://atc001.contest.atcoder.jp/tasks/unionfind_a
    """

    def __init__(self, size: int):
        self.size = size

        # all are root at first
        self._par = [i for i in range(size)]

    def find(self, x: int) -> int:
        if self._par[x] == x:  # root
            return x
        else:
            self._par[x] = self.find(self._par[x])  # path compression
            return self._par[x]

    def same(self, x: int, y: int) -> bool:
        return self.find(x) == self.find(y)

    def union(self, x: int, y: int):
        x = self.find(x)
        y = self.find(y)
        if x != y:
            self._par[x] = y


