	val = 0
	parent = None
	height = 0
	size = 1
	def __init__(self, val, parent=None, height=0, size=1):
		self.val = val
		if parent is None:
			self.parent = self
		else:
			self.parent = parent
		self.height = height
		self.size = size

class UnionFindTree:
	elemnts = []

	def __init__(self, n):
		self.elemnts = [Element(val=i) for i in range(n)]

	def root(self, x:int) -> Element:
		if self.elemnts[x].parent is self.elemnts[x]:
			return self.elemnts[x]
		return self.root(self.elemnts[x].parent.val)

	def same(self, x:int, y:int) -> bool:
		rx = self.root(x)
		ry = self.root(y)
		return rx is ry

	def unite(self, x:int, y:int):
		rx = self.root(x)
		ry = self.root(y)
		if rx == ry:
			return
		if rx.height < ry.height:
			rx.parent = ry
			ry.size += ry.height
		else:
			ry.parent = rx
			rx.size += ry.size
			if rx.height == ry.height:
				rx.height += 1

