fn dfs(graph: &Vec<Vec<usize>>, seen: &mut Vec<bool>, v: usize) {
    seen[v] = true;
    for next in graph[v].iter() {
        if !seen[*next] {
            dfs(graph, seen, *next);
        }
    }
