// IO
use std::io::*;
struct IO<R: Read, W: Write, E: Write> {
    Read: R,
    Write: BufWriter<W>,
    Error: BufWriter<E>,
}
impl<R: Read, W: Write, E: Write> IO<R, W, E> {
    fn new(r: R, w: W, e: E) -> IO<R, W, E> {
        IO {
            Read: r,
            Write: BufWriter::new(w),
            Error: BufWriter::new(e),
        }
    }
    fn read<T>(&mut self) -> T
    where
        T: std::str::FromStr,
    {
        let next: String = self
            .Read
            .by_ref()
            .bytes()
            .map(|c| c.unwrap() as char)
            .skip_while(|c| c.is_whitespace())
            .take_while(|c| !c.is_whitespace())
            .collect();
        next.parse().ok().unwrap()
    }
    fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
    fn chari(&mut self) -> Vec<i64> {
        self.chars()
            .iter()
            .map(|&c| (c as u8 - b'0') as i64)
            .collect::<Vec<i64>>()
    }
    fn readn<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read::<T>()).collect::<Vec<_>>()
    }
    fn readmat<T: std::str::FromStr>(&mut self, n: usize, m: usize) -> Vec<Vec<T>> {
        (0..n).map(|_| self.readn(m)).collect()
    }
    fn write<S: ToString>(&mut self, val: S) {
        self.Write.write(val.to_string().as_bytes());
    }
    fn writeln<S: ToString>(&mut self, val: S) {
        self.Write.write(val.to_string().as_bytes());
        self.Write.write(b"\n");
    }
    fn debug<S: std::fmt::Debug>(&mut self, val: S) {
        writeln!(self.Error, "(debug) {:?}", &val);
    }
    fn debug2<S: std::fmt::Debug, T: std::fmt::Debug>(&mut self, val1: S, val2: T) {
        writeln!(self.Error, "(debug2) {:?} -> {:?}", val1, val2);
    }
    fn debug3<S: std::fmt::Debug, T: std::fmt::Debug, U: std::fmt::Debug>(
        &mut self,
        val1: S,
        val2: T,
        val3: U,
    ) {
        writeln!(
            self.Error,
            "(debug3) {:?} -> {:?} -> {:?}",
            val1, val2, val3
        );
    }
}

use std::io::stdin;

fn solve(matrix: Vec<Vec<Option<u64>>>,num_node: u32) -> u32 {
    assert_eq!(matrix.len(), matrix[0].len());

    // let num_node = matrix.len();

    let mut visited: Vec<bool> = vec![false; num_node as usize];
    let mut count = 0;

    while let Some(root_index) = (0..num_node as usize).find(|&i| !visited[i]) {
        count += 1;
        let mut index_stack: Vec<u32> = Vec::new();
        visited[root_index] = true;
        index_stack.push(root_index as u32);

        while let Some(index) = index_stack.pop() {
            let indices: Vec<usize> = visited
                .iter()
                .enumerate()
                .filter(|&(_, &c)| !c)
                .map(|(i, _)| i)
                .collect();

            for i in indices.into_iter() {
                if let Some(_) = matrix[index as usize][i] {
                    if !visited[i] {
                        index_stack.push(i as u32);
                        visited[i] = true;
                    }
                }
            }
        }
    }
    return visited.iter().filter(|&&c| !c).count() as u32 + count;
}

fn main() {
