fn solve() {
    input! {
        n: usize,
        m: usize,
        sets: [(usize,usize,usize);m]
    }

    let edges = sets.iter().map(|set| (set.0, set.1)).collect();
    let mut adj_list: Vec<Vec<usize>> = vec![Vec::new(); n];
    for &(x, y) in &edges {
        adj_list[x as usize - 1].push(y - 1);
        adj_list[y as usize - 1].push(x - 1);
    }
    //println!("{:?}", adj_list);

    let nodes = topological_sort(n, edges);
    //println!("{:?}", nodes);
    let mut detected = vec![false; n];

    let mut ans = 0;
    for &n in &nodes {
        if detected[n - 1] {
            continue;
        } else {
            ans += 1;
            detected[n - 1] = true;

            let mut stack: VecDeque<usize> = VecDeque::new();
            for &j in &adj_list[n - 1] {
                stack.push_back(j);
            }

            while stack.len() > 0 {
                let target = stack.pop_back().unwrap();
                if detected[target] {
                    continue;
                }
                for &j in &adj_list[target] {
                    stack.push_back(j);
                }

                detected[target] = true;
            }
        }
    }

    println!("{}", ans);
}

