fn solve() {
    let (n,m) = get!(usize, usize);
    let xyz = get!(usize, usize, usize; m);

    let mut nodes = vec![Vec::new(); n+1];
    for (x,y,_) in xyz {
        nodes[x].push(y);
        nodes[y].push(x);
    }

    let mut queue = VecDeque::new();
    let mut visited = BTreeSet::new();

    let mut count = 0;
    for i in 1..n+1 {
        if visited.contains(&i) {
            continue;
        }
        count += 1;
        queue.push_back(i);
        visited.insert(i);
        while let Some(node) = queue.pop_front() {
            for &next in &nodes[node] {
                if visited.contains(&next) {
                    continue;
                }
                visited.insert(next);
                queue.push_back(next);
            }
        }
    }
    println!("{}", count);
}

