fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let (n, m) = i.read();

    let mut uf = UnionFind::new(n);
    let mut ans = n;

    for _ in 0..m {
        let (x, y, _z) = i.read::<(usize, usize, usize)>();
