//単一視点から目的のノードまでの最短距離、ただし全ての辺の重みが等しいグラフに限る
fn bfs(n: usize, g: &Vec<Vec<usize>>, start: usize, visit: &mut Vec<bool>) {
    let mut q = std::collections::VecDeque::new();

    //init
    visit[start] = true;
    q.push_back(start);

    while let Some(now) = q.pop_front() {
        for &e in &g[now] {
            if !visit[e] {
                visit[e] = true;
                q.push_back(e);
            }
        }
    }
}

use proconio::{fastout, input};
struct UnionFind{
    par : Vec<usize>,
    n_tree : usize,
}

impl UnionFind{
    pub fn new(n: usize) -> Self{
        let par : Vec<usize>= (0..n).collect();
        UnionFind{
            par,
            n_tree: n,
        }
    }

    pub fn root(&mut self,x : usize) -> usize{
        if self.par[x] == x{
            return x;
        }

        self.par[x] = self.root(self.par[x]);
        self.par[x]
    }

    pub fn unite(&mut self, x: usize, y: usize){
        let rx = self.root(x);
        let ry = self.root(y);

        if rx == ry{
            return;
        }
        self.n_tree -= 1;
        self.par[rx] = ry;
    }

    pub fn same(&mut self, x: usize, y: usize) -> bool{
        self.root(x) == self.root(y)
    }

    pub fn num_tree(&self) -> usize{
        self.n_tree
    }

}

#[fastout]
fn main() {
    input! {
        n: usize,
        m: usize,
        tu : [(usize,usize,usize);m],
    }

    let mut uf = UnionFind::new(n);

    for e in &tu{
        let x = e.0 - 1;
        let y = e.1 - 1;

        uf.unite(x, y);
    }

    println!("{}",uf.num_tree());
}

use proconio::input;
use proconio::marker::Usize1;
use std::collections::HashSet;

struct UnionFind {
    parent: Vec<usize>,
    rank: Vec<i32>,
}

impl UnionFind {
    fn new(n: usize) -> Self {
        UnionFind {
            parent: (0..n).map(|i| i).collect(),
            rank: vec![0; n],
        }
    }

    fn find(&mut self, n: usize) -> usize {
        if self.parent[n] == n {
            return n;
        };
        self.parent[n] = self.find(self.parent[n]);
        self.parent[n]
    }

    fn same(&mut self, n: usize, m: usize) -> bool {
        self.find(n) == self.find(m)
    }

    fn unit(&mut self, n: usize, m: usize) {
        let n = self.find(n);
        let m = self.find(m);
        if n == m {
            return;
        }
        if self.rank[n] > self.rank[m] {
            self.parent[m] = n;
        } else {
            self.parent[n] = m;
            if self.rank[n] == self.rank[m] {
                self.rank[n] += self.rank[m];
            }
        }
    }
}

fn main()
{
    input! {
    n:usize,
    m:usize,
    v:[(Usize1,Usize1,i32);m],
    }

    let mut uf = UnionFind::new(n);
    for &(a, b, _) in v.iter() {
        uf.unit(a, b);
    }

    let mut id: HashSet<usize> = (0..n).into_iter().map(|i| uf.find(i)).collect();
    println!("{}", id.iter().count());
}

