#[fastout]
fn main() {
    input!{
        (n, m): (usize, usize),
        xyz: [(usize, usize, usize); m]
    };

    let mut links: Vec<Vec<usize>> = vec![Vec::new(); n];
    for (a, b, c) in xyz {
        links[a-1].push(b-1);
        links[b-1].push(a-1);
    }

    let mut ans = 0;
    let mut used = vec![false; n];
    for i in 0..n {
        if !used[i] {
            ans += 1;
            let mut que: VecDeque<usize> = VecDeque::new();
            que.push_back(i);
            while !que.is_empty() {
                let from = match que.back() {
                    Some(x) => *x,
                    None => 0 as usize,
                };
                que.pop_back();
                if used[from] {
                    continue;
                }
                used[from] = true;
                for to in links[from].iter() {
                    if !used[*to] {
                        que.push_back(*to);
                    }
                }
            }
        }
    }
    println!("{}", ans);
}

use std::io::*;

mod disjoint_set {
    pub struct DisjointSet {
        parent: Vec<usize>,
        size: Vec<usize>,
    }
    impl DisjointSet {
        pub fn new(n: usize) -> DisjointSet {
            DisjointSet {
                parent: (0..n).collect(),
                size: vec![1; n],
            }
        }
        pub fn root(&mut self, x: usize) -> usize {
            if x == self.parent[x] {
                x
            } else {
                let tmp = self.parent[x];
                self.parent[x] = self.root(tmp);
                self.parent[x]
            }
        }
        pub fn merge(&mut self, x: usize, y: usize) {
            let x = self.root(x);
            let y = self.root(y);
            if x == y {
                return;
            }
            if self.size[x] > self.size[y] {
                self.size[x] += self.size[y];
                self.parent[y] = x;
            } else {
                self.size[y] += self.size[x];
                self.parent[x] = y;
            }
        }
    }
}

