type Graph = Vec<Edges>;
#[allow(dead_code)]
fn graph_new(n: usize) -> Graph {
    vec![vec![]; n]
}
#[allow(dead_code)]
fn add_bi_edge(graph: &mut Graph, index: &mut usize, src: usize, dest: usize, weight: Weight) {
    graph[src].push(Edge::new(*index, src, dest, weight));
    graph[dest].push(Edge::new(*index, dest, src, weight));
    *index += 1;
}
#[allow(dead_code)]
fn add_uni_edge(graph: &mut Graph, index: &mut usize, src: usize, dest: usize, weight: Weight) {
    graph[src].push(Edge::new(*index, src, dest, weight));
    *index += 1;
}

fn dfs(g: &Graph, from: usize, visit: &mut Vec<bool>) {
    if visit[from] {
        return;
    }
    visit[from] = true;
    for e in g[from].iter() {
        dfs(g, e.dest, visit);
    }
}

fn main() {
    let n = read::<usize>();
    let m = read::<usize>();
    let mut g = graph_new(n);
    let mut index = 0;
    for _i in 0..m {
        let x = read::<usize>() - 1;
        let y = read::<usize>() - 1;
        let z = read::<Weight>();
        add_bi_edge(&mut g, &mut index, x, y, z);
    }
    let mut visit = vec![false; n];
    let mut ans = 0;
    for i in 0..n {
        if visit[i] {
            continue;
        }
        dfs(&g, i, &mut visit);
        ans += 1;
    }
    println!("{}", ans);
}

