fn input<T>() -> T
where
    T: std::str::FromStr,
{
    let stdin = std::io::stdin();
    let token: String = stdin
        .lock()
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}

fn main() {
    let n: usize = input();
    let m: usize = input();
    let xyz: Vec<(usize, usize, i64)> = (0..m)
        .map(|_| {
            let x = input();
            let y = input();
            let z = input();
            (x, y, z)
        })
        .collect();

    let mut uf = UnionFind::new(n);
    for (x, y, _) in xyz {
        uf.union(x - 1, y - 1);
    }

    let mut v = vec![0; n];
    for i in 0..n {
        v[i] = uf.find(i);
    }
    v.sort();
    v.dedup();
    println!("{}", v.len());
}

struct UnionFind {
    parent: Vec<usize>,
    size: Vec<usize>,
}

impl UnionFind {
    fn new(n: usize) -> UnionFind {
        let mut p = vec![0; n];
        for i in 0..n {
            p[i] = i;
        }
        UnionFind {
            parent: p,
            size: vec![1; n],
        }
    }

    fn find(&mut self, x: usize) -> usize {
        if self.parent[x] == x {
            x
        } else {
            let p = self.parent[x];
            self.parent[x] = self.find(p);
            self.parent[x]
        }
    }

    fn union(&mut self, x: usize, y: usize) {
        let mut x = self.find(x);
        let mut y = self.find(y);

        if x != y {
            if self.size[x] < self.size[y] {
                let t = x;
                y = x;
                x = t;
            }

            self.parent[y] = x;
            self.size[x] += self.size[y];
        }
    }
}

