    }

    pub fn unite(&mut self, i: usize, j: usize) {
        let root_i = self.find(i);
        let root_j = self.find(j);
        if root_i == root_j {
            return
        }

        if self.tree[root_i].size < self.tree[root_j].size {
            self.tree[root_i].size += self.tree[root_j].size;
            self.tree[root_j].parent = Some(root_i);
        } else {
            self.tree[root_j].size += self.tree[root_i].size;
            self.tree[root_i].parent = Some(root_j);
        }

    }

    pub fn find(&mut self, i: usize) -> usize {
        match self.tree[i].parent {
            Some(p) => {
                let root = self.find(p);
                self.tree[i].parent = Some(root);
                root
            },
            None => i
        }
    }

    pub fn equiv(&mut self, i: usize, j: usize) -> bool {
        self.find(i) == self.find(j)
    }

    pub fn size(&mut self, i: usize) -> usize {
        let root = self.find(i);
        self.tree[root].size
    }
}

