fn dfs(adj: &[Vec<usize>]) -> usize {
    let mut num = 0;
    let mut stack = vec![];
    let mut used = vec![false; adj.len()];
    for i in 0..adj.len() {
        if used[i] {
            continue;
        }
        num += 1;
        stack.push(i);
        while stack.len() > 0 {
            let crt = stack.pop().unwrap();
            if used[crt] {
                continue;
            }
            used[crt] = true;
            for &nxt in adj[crt].iter() {
                if used[nxt] {
                    continue;
                }
                stack.push(nxt);
            }
        }
    }
    num
}

