    let mut visited = vec![false; 2 * n];

    for &(x, y, z) in &relations {
        if z % 2 == 0 {
            graph[x - 1].push(y - 1);
            graph[y - 1].push(x - 1);
            graph[n + y - 1].push(n + x - 1);
            graph[n + x - 1].push(n + y - 1);
        } else {
            graph[x - 1].push(n + y - 1);
            graph[n + y - 1].push(x - 1);
            graph[y - 1].push(n + x - 1);
            graph[n + x - 1].push(y - 1);
        }
    }
    let mut ans = 0;
    for i in 0..2 * n {
        if !visited[i] {
            ans += 1;
            dfs(i, &graph, &mut visited);
        }
    }
    println!("{}", ans / 2);
}

