fn dfs(pos: usize, graph: &Vec<Vec<usize>>, visited: &mut Vec<bool>) {
    visited[pos] = true;
    for &n in &graph[pos] {
        if !visited[n] {
            dfs(n, graph, visited);
        }
    }
}

fn main() {
    input! {
        n: usize,
        m: usize,
        relations: [(usize, usize, usize); m],
    }

    let mut graph = vec![vec![]; 2 * n];
    let mut visited = vec![false; 2 * n];

    for &(x, y, z) in &relations {
        if z % 2 == 0 {
            graph[x - 1].push(y - 1);
            graph[y - 1].push(x - 1);
            graph[n + y - 1].push(n + x - 1);
            graph[n + x - 1].push(n + y - 1);
        } else {
            graph[x - 1].push(n + y - 1);
            graph[y - 1].push(n + x - 1);
        }
    }
    let mut ans = 0;
    for i in 0..2 * n {
        if !visited[i] {
            ans += 1;
            dfs(i, &graph, &mut visited);
        }
    }
    println!("{}", ans / 2);
}

use std::collections::HashMap;
use std::io::stdin;

fn solve(matrix: HashMap<u32, HashMap<u32, u64>>, num_node: u32) -> u32 {
    let mut visited: Vec<bool> = vec![false; num_node as usize];
    let mut count = 0;

    while let Some(root_index) = (0..num_node as usize).find(|&i| !visited[i]) {
        count += 1;
        let mut index_stack: Vec<u32> = Vec::new();
        visited[root_index] = true;
        index_stack.push(root_index as u32 + 1);

        while let Some(index) = index_stack.pop() {
            if let Some(col) = matrix.get(&(index)).map(|it| it.iter()) {
                for (&i, _) in col {
                    if !visited[i as usize - 1] {
                        index_stack.push(i);
                        visited[i as usize - 1] = true;
                    }
                }
            }
        }
    }
    return visited.iter().filter(|&&c| !c).count() as u32 + count;
}

fn main() {
    let mut input = String::new();
    let _ = stdin().read_line(&mut input).unwrap();
    let n_m = input
        .trim()
        .split(" ")
        .map(|s| s.to_string().parse::<u32>().unwrap())
        .collect::<Vec<u32>>();

    let num_node = n_m[0];
    let m = n_m[1];

    let mut graph: HashMap<u32, HashMap<u32, u64>> = HashMap::new();

    for (x, y, z) in (1..(m + 1)).map(|_| {
        let mut input = String::new();
        let _ = stdin().read_line(&mut input).unwrap();
        let input: Vec<String> = input.trim().split(" ").map(|s| s.to_string()).collect();
        assert_eq!(3, input.len());
        (
            input[0].parse::<u32>().unwrap(),
            input[1].parse::<u32>().unwrap(),
            input[2].parse::<u64>().unwrap(),
        )
    }) {
        if let Some(col) = graph.get_mut(&x) {
            col.insert(y, z);
        } else {
            let mut map = HashMap::new();
            map.insert(y, z);
            graph.insert(x, map);
        }

        if let Some(col) = graph.get_mut(&y) {
            col.insert(x, z);
        } else {
            let mut map = HashMap::new();
            map.insert(x, z);
            graph.insert(y, map);
        }
    }
    println!("{}", solve(graph, num_node));
}

use std::cmp::*;
use std::io::*;

mod disjoint_set {
    pub struct DisjointSet {
        parent: Vec<usize>,
        size: Vec<usize>,
    }
    impl DisjointSet {
        pub fn new(n: usize) -> DisjointSet {
            DisjointSet {
                parent: (0..n).collect(),
                size: vec![1; n],
            }
        }
        pub fn root(&mut self, x: usize) -> usize {
            if x == self.parent[x] {
                x
            } else {
                let tmp = self.parent[x];
                self.parent[x] = self.root(tmp);
                self.parent[x]
            }
        }
        pub fn merge(&mut self, x: usize, y: usize) {
            let x = self.root(x);
            let y = self.root(y);
            if x == y {
                return;
            }
            if self.size[x] > self.size[y] {
                self.size[x] += self.size[y];
                self.parent[y] = x;
            } else {
                self.size[y] += self.size[x];
                self.parent[x] = y;
            }
        }
    }
}

fn main() {
    let mut s: String = String::new();
    std::io::stdin().read_to_string(&mut s).ok();
    let mut itr = s.trim().split_whitespace();
    let n: usize = itr.next().unwrap().parse().unwrap();
    let m: usize = itr.next().unwrap().parse().unwrap();

    let mut ds = disjoint_set::DisjointSet::new(n);
    for _ in 0..m {
        let x: usize = itr.next().unwrap().parse::<usize>().unwrap() - 1;
        let y: usize = itr.next().unwrap().parse::<usize>().unwrap() - 1;
        let z: usize = itr.next().unwrap().parse().unwrap();
        ds.merge(x, y);
    }
    let mut ans = 0;
    let mut used = vec![false; n];
    for i in 0..n {
        if !used[ds.root(i)] {
            ans += 1;
            used[ds.root(i)] = true;
        }
    }
    println!("{}", ans);
}

