use std::io::*;
use std::str::FromStr;
use std::collections::VecDeque;

fn main() {
    let n: usize = read();
    let m: usize = read();

    let mut po = vec![Vec::new(); n];
    for i in 0..m {
        let x: usize = read();
        let y: usize = read();
        let _: usize = read();
        po[x-1].push(y-1);
        po[y-1].push(x-1);
    }

    let mut ans = n;
    let mut used = vec![false; n];
    for i in 0..n {
        if used[i] {
            continue;
        }
        let mut que: VecDeque<usize> = VecDeque::new();
        que.push_back(i);
        used[i] = true;
        loop {
            if que.is_empty() {
                break;
            }
            let q = que.pop_front().unwrap();
            for i in &po[q] {
                if !used[*i] {
                    ans -= 1;
                    used[*i] = true;
