struct UnionFind {
    parent: Vec<usize>,
    size: Vec<usize>,
}

impl UnionFind {
    fn new(n : usize)-> UnionFind {
        let mut par = Vec::with_capacity(n);
        for i in 0..n {
            par.push(i);
        }
        UnionFind {
            parent: par,
            size: vec![1; n]
        }
    }

    fn union(&mut self, l: usize, r: usize) {
        let mut lp = self.get_par(l);
        let mut rp = self.get_par(r);

        if lp != rp {
            self.parent[lp] = rp;
            self.size[rp] += self.size[lp];
        }

    }

    fn get_par(&mut self, tar: usize) -> usize {
        let mut par = tar;
        while self.parent[par] != par {
            par = self.parent[par];
        }
        self.parent[tar] = par;
        par
    }

    fn get_par_size(&mut self, tar: usize) -> usize {
        let par = self.get_par(tar);
        self.size[tar]
    }

    fn is_parent(&self, x: usize) -> bool {
        self.parent[x] == x
    }
}

