struct UnionFind {
    forest: Vec<usize>
}


impl UnionFind {
    pub fn new(n: usize) -> UnionFind {
        UnionFind { forest: (0..n).collect() }
    }


    fn group(&mut self, mut i: usize) -> usize {
        let mut path = vec![];
        while self.forest[i] != i {
            path.push(i);
            i = self.forest[i]
        }
        for p in path { self.forest[p] = i }
        i
    }


    fn merge(&mut self, edges: Vec<(usize, usize)>) {
        for (l, r) in edges {
            let gl = self.group(l);
            let gr = self.group(r);
            if gl != gr {
                self.forest[gl] = gr
            }
        }
    }


    fn count(&mut self) -> usize {
        let mut cnt = 0;
        for i in 0..self.forest.len() {
            if self.forest[i] == i {
                cnt += 1
            }
        }
        cnt
    }
}



