use std::collections::HashMap;

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|s| s.parse().ok().unwrap())
        .collect()
}

fn main() {
    let input = read_vec::<usize>();
    let (n, m) = (input[0], input[1]);
    let mut map = HashMap::new();
    for _ in 0..m {
        let input = read_vec::<usize>();
        let (x, y) = (input[0]-1, input[1]-1);
        map.entry(x).or_insert_with(|| vec![]).push(y);
        map.entry(y).or_insert_with(|| vec![]).push(x);
    }
    let mut used = vec![false; n];


    let mut count = 0;
    for i in 0..n {
        if used[i] {
            continue;
        }
        count += 1;
        dfs(i, &map, &mut used);
    }

    println!("{}", count);
}

fn dfs(index: usize, map: &HashMap<usize, Vec<usize>>, used: &mut Vec<bool>) {
    used[index] = true;
    if let Some(val) = map.get(&index) {
        for &key in val.iter() {
            if used[key] {
                continue;
            }
            dfs(key, map, used);
        }
    }
}

