fn main() {
    input! {
        n: usize, // ノード数
        m: usize, // ノード数
        edges: [(usize1, usize1, usize); m], // usize1 は 1-origin to 0-origin変換を行う
    }

    let mut edgemap = HashMap::new();

    for (n0, n1, l) in edges {
        edgemap.entry(n0).or_insert(vec![]).push((n1, l));
        edgemap.entry(n1).or_insert(vec![]).push((n0, l));
    }

    let mut visit = HashSet::new();
    let mut q = VecDeque::new();
    let mut ans = 0;

    for i in 0..n {
        if visit.contains(&i) {
            continue;
        }
        ans += 1;
        q.push_back(i);
        while q.len() > 0 {
            let n = q.pop_front().unwrap();
            visit.insert(n);
            match edgemap.get(&n) {
                Some(nexts) => {
                    for &(nx, _) in nexts {
                        if !visit.contains(&nx) {
                            q.push_back(nx);
                        }
                    }
                }
                None => {}
            }
        }
    }

    println!("{}", ans);
}

