use std::collections::HashMap;
use std::io::stdin;

fn solve(matrix: HashMap<u32, HashMap<u32, u64>>, num_node: u32) -> u32 {
    let mut visited: Vec<bool> = vec![false; num_node as usize];
    let mut count = 0;

    while let Some(root_index) = (0..num_node as usize).find(|&i| !visited[i]) {
        count += 1;
        let mut index_stack: Vec<u32> = Vec::new();
        visited[root_index] = true;
        index_stack.push(root_index as u32 + 1);

        while let Some(index) = index_stack.pop() {
            if let Some(col) = matrix.get(&(index)).map(|it| it.iter()) {
                for (&i, _) in col {
                    if !visited[i as usize - 1] {
                        index_stack.push(i);
                        visited[i as usize - 1] = true;
                    }
                }
            }
        }
    }
    return visited.iter().filter(|&&c| !c).count() as u32 + count;
}

