        graph[x].push(y);
        graph[y].push(x);
    }
    let mut count = 0;
    let mut dist = vec![false; n];

    for i in 0..n {
        if dist[i] {continue; }
        dist[i] = true;
        count += 1;
        let mut queue = VecDeque::new();
