//単一視点から目的のノードまでの最短距離、ただし全ての辺の重みが等しいグラフに限る
fn bfs(n: usize, g: &Vec<Vec<usize>>, start: usize, visit: &mut Vec<bool>) {
    let mut q = std::collections::VecDeque::new();

    //init
    visit[start] = true;
    q.push_back(start);

    while let Some(now) = q.pop_front() {
        for &e in &g[now] {
            if !visit[e] {
                visit[e] = true;
                q.push_back(e);
            }
        }
    }
}

use std::collections::{HashMap, HashSet, VecDeque};

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
    ($($r:tt)*) => {
        #[allow(unused_mut)]
        let mut s = {
            use std::io::Read;
            let mut s = String::new();
            std::io::stdin().read_to_string(&mut s).unwrap();
            s
        };
        let mut iter = s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
}

macro_rules! input_inner {
    ($iter:expr) => {};
    ($iter:expr, ) => {};
    ($iter:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($iter, $t);
        input_inner!{$iter $($r)*}
    };
}

macro_rules! read_value {
    ($iter:expr, ( $($t:tt),* )) => {
        ( $(read_value!($iter, $t)),* )
    };
    ($iter:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
    };
    ($iter:expr, chars) => {
        read_value!($iter, String).chars().collect::<Vec<char>>()
    };
    ($iter:expr, usize1) => {
        read_value!($iter, usize) - 1
    };
    ($iter:expr, $t:ty) => {
        $iter.next().unwrap().parse::<$t>().expect("Parse error")
    };
}

fn main() {
    input! {
        n: usize, // ノード数
        m: usize, // ノード数
        edges: [(usize1, usize1, usize); m], // usize1 は 1-origin to 0-origin変換を行う
    }

    let mut edgemap = HashMap::new();

    for (n0, n1, l) in edges {
        edgemap.entry(n0).or_insert(vec![]).push((n1, l));
        edgemap.entry(n1).or_insert(vec![]).push((n0, l));
    }

    let mut visit = HashSet::new();
    let mut q = VecDeque::new();
    let mut ans = 0;

    for i in 0..n {
        if visit.contains(&i) {
            continue;
        }
        ans += 1;
        q.push_back(i);
        while q.len() > 0 {
            let n = q.pop_front().unwrap();
            visit.insert(n);
            let nexts = edgemap.get(&n).unwrap();
            for &(nx, _) in nexts {
                if !visit.contains(&nx) {
                    q.push_back(nx);
                }
            }
        }
    }

    println!("{}", ans);
}

