fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize, m: usize);
    let mut uf = UnionFind::new(n);
    for _ in 0..m {
        parse!(it, x: u1, y: u1, z: usize);
        uf.union(x, y);
    }
    let ps: HashSet<usize> = (0..n).map(|i| uf.root(i)).collect();
    println!("{}", ps.len());
}

